(10407101, 104071, 'P32-C7-L1-O01', null, 1, 'أن يشرح الطالب تجربة راذرفورد مع صفيحة الذهب', 'أن يشرح الطالب تجربة راذرفورد لقذف صفيحة رقيقة من الذهب بجسيمات ألفا.', '[]'::jsonb, 'أن يشرح الطالب تجربة راذرفورد لقذف صفيحة رقيقة من الذهب بجسيمات ألفا.', 'إضافة علامة الترقيم، وتحديد التجربة بمصطلحات الكتاب (قذف صفيحة رقيقة جدًّا من الذهب بحزمة من جسيمات ألفا).', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["تجربة راذرفورد","جسيمات ألفا","صفيحة الذهب الرقيقة","نموذج تومسون"]'::jsonb, null, '[192,193,216]'::jsonb, 'مغطى', 'ص192: «أجريت تجربة راذرفورد باستخدام مركبات مشعة تصدر أشعة نافذة… فقد قذف راذرفورد حزمة من جسيمات ألفا على صفيحة رقيقة جدًّا من الذهب» مع الشكل 7–1 وتوقعه المبني على نموذج تومسون؛ ص193 الشكل 7–2؛ ص216 سؤال 24، وص221 اختبار مقنن 1.', null, 'approved', '2026-11-24'::timestamptz),
(10407102, 104071, 'P32-C7-L1-O02', null, 2, 'أن يذكر الطالب نتائج تجربة راذرفورد مع صفيحة الذهب', 'أن يذكر الطالب نتائج تجربة راذرفورد مع صفيحة الذهب الرقيقة، وما استنتجه منها.', '[]'::jsonb, 'أن يذكر الطالب نتائج تجربة راذرفورد مع صفيحة الذهب الرقيقة، وما استنتجه منها.', 'إضافة الاستنتاج إلى النتائج كما يعرضهما الكتاب معًا، وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["نتائج تجربة راذرفورد","انحراف جسيمات ألفا","النواة"]'::jsonb, null, '[192,193,215]'::jsonb, 'مغطى', 'ص192: «عبرَ معظم جسيمات α خلال صفيحة الذهب دون انحراف أو مع انحراف قليل… إلا أن بعضها ارتدّ بزوايا كبيرة جدًّا (تزيد على 90°)»؛ ص193 الشكل 7–2: «جسيم واحد من كل 1000 يرتد بزاوية كبيرة» واستنتاج تركّز الشحنة في النواة؛ ص215 المفاهيم الرئيسة.', null, 'approved', '2026-11-24'::timestamptz),
(10407103, 104071, 'P32-C7-L1-O03', null, 3, 'أن يذكر الطالب سبب استخدام راذرفورد شاشة مطلية بطبقة من كبريتات الزنك في تجربته مع صفيحة الذهب', 'أن يذكر الطالب سبب استخدام راذرفورد شاشة مطلية بطبقة من كبريتات الزنك في تجربته مع صفيحة الذهب.', '[]'::jsonb, 'أن يذكر الطالب سبب استخدام راذرفورد شاشة مطلية بطبقة من كبريتات الزنك في تجربته مع صفيحة الذهب.', 'إضافة علامة الترقيم فقط؛ والمصطلح «كبريتات الزنك» مطابق للكتاب. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["كبريتات الزنك","الكشف عن جسيمات ألفا","الومضات الضوئية"]'::jsonb, null, '[192]'::jsonb, 'مغطى', 'ص192: «ويمكن الكشف عن هذه الجسيمات في تجربة راذرفورد بواسطة ومضات ضوئية تنبعث عندما تصطدم الجسيمات مع شاشة مطلية بطبقة من كبريتات الزنك». التغطية جملة واحدة لكنها صريحة.', null, 'approved', '2026-11-24'::timestamptz),
(10407104, 104071, 'P32-C7-L1-O04', null, 4, 'أن يذكر الطالب وظيفة جهاز المطياف', 'أن يذكر الطالب وظيفة جهاز المطياف، ويصف مكوناته الرئيسة.', '[]'::jsonb, 'أن يذكر الطالب وظيفة جهاز المطياف، ويصف مكوناته الرئيسة.', 'إضافة علامة الترقيم، وإضافة مكونات المطياف (الشق، والمنشور أو محزوز الحيود، والكاشف) كما يعرضها الشكل 7–5a. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["المطياف","المنشور","محزوز الحيود","الشق"]'::jsonb, null, '[194,195]'::jsonb, 'مغطى', 'ص194: «ويمكن دراسة طيف الانبعاث بتفصيل أكبر باستخدام جهاز يسمى المطياف… فإن الضوء في منشور المطياف يعبر خلال الشق، ثم يتشتت… فيكوّن المطياف صورة الشق عند مواقع مختلفة لكل طول موجي» والشكل 7–5a؛ ص195 الشكل 7–7a.', null, 'approved', '2026-11-24'::timestamptz),
(10407105, 104071, 'P32-C7-L1-O05', null, 5, 'أن يقارن الطالب بين الطيف المنبعث من غاز والطيف المنبعث من جسم ساخن', 'أن يقارن الطالب بين طيف الانبعاث المستمر المنبعث من جسم ساخن وطيف الانبعاث الخطي المنبعث من غاز.', '[]'::jsonb, 'أن يقارن الطالب بين طيف الانبعاث المستمر المنبعث من جسم ساخن وطيف الانبعاث الخطي المنبعث من غاز.', 'إضافة علامة الترقيم، واستخدام مصطلحي الكتاب «طيف الانبعاث المستمر» و«طيف الانبعاث الخطي» كما في أهداف الدرس ص191.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["طيف الانبعاث المستمر","طيف الانبعاث الخطي","الجسم الساخن"]'::jsonb, null, '[191,194,204,207]'::jsonb, 'مغطى', 'ص191 أهداف الدرس: «تقارن بين طيف الانبعاث المستمر وطيف الانبعاث الخطي»؛ ص194: «إن الطيف المنبعث عن جسم ساخن… هو حزمة متصلة من ألوان الطيف… لكن طيف الغاز يكون سلسلة من الخطوط المنفصلة»؛ ص204 سؤال 10؛ ص207.', null, 'approved', '2026-11-24'::timestamptz),
(10407106, 104071, 'P32-C7-L1-O06', null, 6, 'أن يذكر الطالب استخدامات طيف الانبعاث', 'أن يذكر الطالب استخدامات طيف الانبعاث.', '[]'::jsonb, 'أن يذكر الطالب استخدامات طيف الانبعاث.', 'إضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["طيف الانبعاث","تحديد نوع غاز مجهول","تحليل خليط الغازات"]'::jsonb, null, '[194,215]'::jsonb, 'مغطى', 'ص194: «يعدّ طيف الانبعاث أيضًا وسيلة تحليلية مفيدة، فيمكن استخدامه لتحديد نوع عينة غاز مجهولة… ويمكن كذلك استخدام طيف الانبعاث لتحليل خليط من الغازات… يمكن تحديد التركيب النسبي للمادة»؛ ص215 المفاهيم الرئيسة.', null, 'approved', '2026-11-24'::timestamptz),
(10407107, 104071, 'P32-C7-L1-O07', null, 7, 'أن يوضح الطالب طيف الامتصاص', 'أن يعرّف الطالب طيف الامتصاص للغاز.', '[]'::jsonb, 'أن يعرّف الطالب طيف الامتصاص للغاز.', '«يوضح طيف الامتصاص» غير محدد، والمقصود التعريف لأنه من مفردات الدرس، فحُوّل إلى «يعرّف»، مع إضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["طيف الامتصاص"]'::jsonb, null, '[191,195,215]'::jsonb, 'مغطى', 'ص191 من مفردات الدرس؛ ص195: «ومجموعة الأطوال الموجية الممتصة بواسطة الغاز تسمى طيف الامتصاص للغاز»؛ ص215 المفردات.', null, 'approved', '2026-11-24'::timestamptz),
(10407108, 104071, 'P32-C7-L1-O08', null, 8, 'أن يوضح الطالب سبب وجود بعض الخطوط المعتمة في طيف ضوء الشمس', 'أن يفسّر الطالب سبب ظهور خطوط معتمة (خطوط فرنهوفر) في طيف ضوء الشمس.', '[]'::jsonb, 'أن يفسّر الطالب سبب ظهور خطوط معتمة (خطوط فرنهوفر) في طيف ضوء الشمس.', '«يوضح سبب» إلى «يفسّر سبب» لأنه سؤال تعليل، وإضافة مصطلح الكتاب «خطوط فرنهوفر».', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["خطوط فرنهوفر","الغلاف الغازي للشمس","طيف الامتصاص"]'::jsonb, null, '[195]'::jsonb, 'مغطى', 'ص195: «لاحظ جوزيف فون فرنهوفر وجود بعض الخطوط المعتمة تتخلل طيف ضوء الشمس… وقد علل ذلك بأن ضوء الشمس يعبر خلال الغلاف الغازي المحيط بالشمس، وتمتص هذه الغازات أطوالًا موجية مميزة محددة» والشكل 7–6.', null, 'approved', '2026-11-24'::timestamptz),
(10407109, 104071, 'P32-C7-L1-O09', null, 9, 'أن يوضح الطالب كيف يمكن تحديد مكونات الغلاف الشمسي', 'أن يوضّح الطالب كيف يمكن تحديد مكونات الغلاف الشمسي.', '[]'::jsonb, 'أن يوضّح الطالب كيف يمكن تحديد مكونات الغلاف الشمسي.', 'تشكيل «يوضّح» وإضافة علامة الترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الغلاف الشمسي","طيف الامتصاص","طيف الانبعاث"]'::jsonb, null, '[195,196]'::jsonb, 'مغطى', 'ص195: «وقد أمكن تحديد مكونات الغلاف الشمسي بمقارنة الخطوط المفقودة في الطيف المرئي مع طيف الانبعاث المعلوم للعناصر المختلفة، وتم كذلك تحديد مكونات العديد من النجوم»؛ ص196: التحليل الطيفي «الأداة المتوافرة الوحيدة حاليًّا لدراسة مكونات النجوم».', null, 'approved', '2026-11-24'::timestamptz),
(10407110, 104071, 'P32-C7-L1-O10', null, 10, 'أن يشرح الطالب كيف ينتج طيف الامتصاص للغازات', 'أن يشرح الطالب كيف ينتج طيف الامتصاص لغاز، ولماذا تقع خطوطه المعتمة عند الأطوال الموجية نفسها لخطوط طيف انبعاثه.', '[]'::jsonb, 'أن يشرح الطالب كيف ينتج طيف الامتصاص لغاز، ولماذا تقع خطوطه المعتمة عند الأطوال الموجية نفسها لخطوط طيف انبعاثه.', 'إضافة علامة الترقيم وإكمال المضمون بما يركّز عليه الكتاب (تطابق خطوط الامتصاص والانبعاث للغاز نفسه).', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["طيف الامتصاص","طيف الانبعاث","الضوء الأبيض","بخار الصوديوم"]'::jsonb, null, '[195,204,215,216]'::jsonb, 'مغطى', 'ص195: «تستطيع مشاهدة طيف الامتصاص بتمرير ضوء أبيض خلال عينة غاز ومطياف… الشكل 7–7a… فإن العناصر الغازية الباردة تمتص الأطوال الموجية نفسها التي تبعثها عندما تثار»؛ ص204 سؤال 13؛ ص215؛ ص216 سؤال 25.', null, 'approved', '2026-11-24'::timestamptz),
(10407111, 104071, 'P32-C7-L1-O11', null, 11, 'أن يذكر الطالب الاستخدامات الصناعية للتحليل الطيفي', 'أن يذكر الطالب الاستخدامات الصناعية للتحليل الطيفي.', '[]'::jsonb, 'أن يذكر الطالب الاستخدامات الصناعية للتحليل الطيفي.', 'إضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["التحليل الطيفي","مصانع الحديد","معالجة الفلزات"]'::jsonb, null, '[196]'::jsonb, 'مغطى', 'ص196: «التحليل الطيفي… تقوم مصانع الحديد مثلًا بإعادة معالجة كميات كبيرة من حديد الخردة… فيتم التحديد الدقيق لهذه التراكيب في دقائق بالتحليل الطيفي… وتقوم محطات معالجة الفلزات – ومنها الألومنيوم والزنك ومعادن أخرى – بتطبيق الطريقة نفسها».', null, 'approved', '2026-11-24'::timestamptz),
(10407112, 104071, 'P32-C7-L1-O12', null, 12, 'أن يوضح الطالب سبب دراسة الطيف الذري لذرة الهيدروجين بدقة', 'أن يوضّح الطالب سبب دراسة طيف ذرة الهيدروجين بدقة.', '[]'::jsonb, 'أن يوضّح الطالب سبب دراسة طيف ذرة الهيدروجين بدقة.', 'حذف التكرار في «الطيف الذري لذرة الهيدروجين»، وتشكيل «يوضّح»، وإضافة علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["طيف ذرة الهيدروجين","خطوط الطيف المرئي للهيدروجين"]'::jsonb, null, '[196]'::jsonb, 'مغطى', 'ص196: «وتمت دراسة الهيدروجين بدقة؛ لأنه العنصر الأخف، وله أبسط طيف؛ حيث يتكون الطيف المرئي للهيدروجين من أربعة خطوط» والشكل 7–8.', null, 'approved', '2026-11-24'::timestamptz),
(10407113, 104071, 'P32-C7-L1-O13', null, 13, 'أن يذكر الطالب سلبيات نموذج راذرفورد', 'أن يوضّح الطالب سلبيات النموذج النووي (نموذج الكواكب) الذي اقترحه راذرفورد.', '[]'::jsonb, 'أن يوضّح الطالب سلبيات النموذج النووي (نموذج الكواكب) الذي اقترحه راذرفورد.', 'استخدام عنوان الكتاب «سلبيات النموذج النووي (نموذج الكواكب)»، و«يذكر» إلى «يوضّح» لأن السلبيات تحتاج تعليلًا بقوانين الكهرومغناطيسية (الإلكترون المتسارع يشع طاقة فيسقط في النواة، ويُتوقع إشعاعه عند كل الأطوال الموجية).', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النموذج النووي","نموذج الكواكب","الإلكترون المتسارع","الإشعاع الكهرومغناطيسي"]'::jsonb, null, '[196,216]'::jsonb, 'مغطى', 'ص196: «سلبيات النموذج النووي (نموذج الكواكب) يتسارع الإلكترون في مستواه… فإن الإلكترونات المتسارعة تشع طاقة… حتى يسقط في النواة خلال 10⁻⁹ s… لكن… الضوء المنبعث من الذرات يُشع عند أطوال موجية محددة فقط»؛ ص216 سؤال 26.', null, 'approved', '2026-11-24'::timestamptz),
(10407114, 104071, 'P32-C7-L1-O14', null, 14, 'أن يعرف الطالب مستوى الطاقة – حالة الاستقرار – حالة الاثارة – الطاقة الصفرية – طاقة التأين', 'أن يعرّف الطالب: مستوى الطاقة، وحالة الاستقرار، وحالة الإثارة، والطاقة الصفرية، وطاقة التأين.', '[]'::jsonb, 'أن يعرّف الطالب: مستوى الطاقة، وحالة الاستقرار، وحالة الإثارة، والطاقة الصفرية، وطاقة التأين.', '«يعرف» الغامضة إلى «يعرّف»، وتصحيح «الاثارة» إلى «الإثارة»، واستبدال الشرطات بواو العطف وعلامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["مستوى الطاقة","حالة الاستقرار","حالة الإثارة","الطاقة الصفرية","طاقة التأين"]'::jsonb, null, '[197,200,204,215]'::jsonb, 'مغطى', 'ص197: «يسمى مستوى طاقة… يقال إنها في حالة استقرار… وهذه الحالة تسمى حالة الإثارة»؛ ص200: «وطاقة مستوى اللانهاية يمكن اعتبارها صفرًا، وتسمى الطاقة الصفرية»؛ ص204: «وطاقة تأين الذرة هي الطاقة اللازمة لتحرير إلكترون بصورة كاملة من الذرة»؛ ص215 المفردات.', null, 'approved', '2026-11-24'::timestamptz),
(10407115, 104071, 'P32-C7-L1-O15', null, 15, 'أن يوضح الطالب ما الذي يحدد طاقة الذرة', 'أن يوضّح الطالب العوامل التي تحدد طاقة الذرة (طاقة حركة الإلكترونات، وطاقة الوضع الناتجة عن قوة التجاذب بين الإلكترونات والنواة).', '[]'::jsonb, 'أن يوضّح الطالب العوامل التي تحدد طاقة الذرة (طاقة حركة الإلكترونات، وطاقة الوضع الناتجة عن قوة التجاذب بين الإلكترونات والنواة).', 'صياغة السؤال «ما الذي يحدد» هدفًا واضحًا، وإضافة مكونات طاقة الذرة كما في الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["طاقة الذرة","طاقة الحركة","طاقة الوضع"]'::jsonb, null, '[197]'::jsonb, 'مغطى', 'ص197: «طاقة الذرة ما الذي يحدد طاقة الذرة؟ طاقة الذرة تساوي مجموع طاقة حركة الإلكترونات وطاقة الوضع الناتجة عن قوة التجاذب بين الإلكترونات والنواة».', null, 'approved', '2026-11-24'::timestamptz),
(10407116, 104071, 'P32-C7-L1-O16', null, 16, 'أن يوضح الطالب سبب أن طاقة الإلكترون في المستويات القريبة من النواة أقل من طاقة الإلكترون في المستويات البعيدة عن النواة', 'أن يفسّر الطالب سبب أن طاقة الإلكترون في المستويات القريبة من النواة أقل من طاقته في المستويات البعيدة عنها.', '[]'::jsonb, 'أن يفسّر الطالب سبب أن طاقة الإلكترون في المستويات القريبة من النواة أقل من طاقته في المستويات البعيدة عنها.', '«يوضح سبب» إلى «يفسّر سبب» لأنه تعليل، وحذف التكرار في آخر الجملة، وإضافة علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["طاقة الإلكترون","مستويات الطاقة","الشغل"]'::jsonb, null, '[197]'::jsonb, 'مغطى', 'ص197: «وطاقة الإلكترون في المستويات القريبة من النواة أقل من طاقة الإلكترون في المستويات البعيدة عنها؛ لأنه يجب أن يبذل شغل لنقل الإلكترونات بعيدًا عن النواة».', null, 'approved', '2026-11-24'::timestamptz),
(10407117, 104071, 'P32-C7-L1-O17', null, 17, 'أن يصف الطالب نموذج بور للذرة', 'أن يصف الطالب نموذج بور للذرة وافتراضاته (استقرار الإلكترون في مداره دون إشعاع، وتكمية مستويات الطاقة، وانبعاث الفوتون أو امتصاصه عند الانتقال بين المستويات).', '[]'::jsonb, 'أن يصف الطالب نموذج بور للذرة وافتراضاته (استقرار الإلكترون في مداره دون إشعاع، وتكمية مستويات الطاقة، وانبعاث الفوتون أو امتصاصه عند الانتقال بين المستويات).', 'إضافة الافتراضات التي يعرضها الكتاب ويسأل عنها (سؤال 27: «ما الافتراضات الثلاثة التي قدمها بور؟»)، وإضافة علامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["نموذج بور","تكمية الطاقة","المدار المستقر","انبعاث الفوتون"]'::jsonb, null, '[197,198,215,216]'::jsonb, 'مغطى', 'ص197: «فافترض أن الإلكترونات في المدار المستقر لا تشع طاقة رغم أنها تتسارع… أي أنه اعتبر أن مستويات الطاقة في الذرة مكمّاة… يعرف نموذج الذرة… بنموذج بور للذرة… اقترح بور أن طاقة كهرومغناطيسية تنبعث عندما تتغير حالة الذرة» والشكلان 7–9 و7–10؛ ص198؛ ص215؛ ص216 سؤالا 27 و29.', null, 'approved', '2026-11-24'::timestamptz),
(10407118, 104071, 'P32-C7-L1-O18', null, 18, 'أن يذكر الطالب عيوب نموذج بور للذرة', 'أن يذكر الطالب عيوب نموذج بور للذرة.', '[]'::jsonb, 'أن يذكر الطالب عيوب نموذج بور للذرة.', 'إضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["نموذج بور","حدود نموذج بور","طيف الهيليوم"]'::jsonb, null, '[198,203]'::jsonb, 'مغطى', 'ص198: «لكن – لسوء الحظ – فقد طبّق هذا النموذج على ذرة الهيدروجين فقط، ولم يكن باستطاعته توقع طيف الهيليوم… إضافة إلى ذلك لم يقدم النموذج تفسيرًا جيدًا لبعض المسائل، مثل لماذا يمكن تطبيق قوانين الكهرومغناطيسية في كل مكان إلا داخل الذرة»؛ ص203 مسألة تحفيز (ذرة النيون).', null, 'approved', '2026-11-24'::timestamptz),
(10407119, 104071, 'P32-C7-L1-O19', null, 19, 'أن يحل الطالب مسائل على نصف قطر المستوى ومعادلات مستويات الطاقة', 'أن يحل الطالب مسائل حسابية على معادلة نصف قطر مستوى إلكترون ذرة الهيدروجين ومعادلة طاقة ذرة الهيدروجين.', '[]'::jsonb, 'أن يحل الطالب مسائل حسابية على معادلة نصف قطر مستوى إلكترون ذرة الهيدروجين ومعادلة طاقة ذرة الهيدروجين.', 'استخدام اسمي المعادلتين كما في الكتاب، وإضافة «حسابية» وعلامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["نصف قطر مستوى إلكترون ذرة الهيدروجين","طاقة ذرة الهيدروجين","نصف قطر بور"]'::jsonb, null, '[199,201,202,218,219]'::jsonb, 'مغطى', 'ص199: «rₙ = h²n²/4π²kmq²… r₁ = 5.3×10⁻¹¹ m = 0.053 nm» و«Eₙ = −13.6 eV × 1/n²»؛ ص201 مثال 1؛ ص202 مسائل تدريبية 1–5؛ ص204 سؤال 12؛ ص218 مسائل 51 و56؛ ص219 سؤال 63.', null, 'approved', '2026-11-24'::timestamptz),
(10407120, 104071, 'P32-C7-L1-O20', null, 20, 'أن يوضح الطالب سبب أن طاقة الذرة في نموذج بور ذات قيمة سالبة', 'أن يفسّر الطالب سبب أن طاقة الذرة في نموذج بور ذات قيمة سالبة.', '[]'::jsonb, 'أن يفسّر الطالب سبب أن طاقة الذرة في نموذج بور ذات قيمة سالبة.', '«يوضح سبب» إلى «يفسّر سبب» لأنه تعليل، وإضافة علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الطاقة الصفرية","تأين الذرة","طاقة الذرة السالبة"]'::jsonb, null, '[200]'::jsonb, 'مغطى', 'ص200: «الطاقة وانتقال الإلكترون ربما تتساءل لماذا تكون طاقة الذرة في نموذج بور ذات قيمة سالبة… ولأنه يجب بذل شغل لتأيين الذرة فإن طاقة الذرة مع الإلكترون الدائر فيها يجب أن يكون أقل من صفر».', null, 'approved', '2026-11-24'::timestamptz),
(10407121, 104071, 'P32-C7-L1-O21', null, 21, 'أن يذكر الطالب سلاسل طيف الانبعاث لذرة الهيدروجين', 'أن يذكر الطالب سلاسل طيف الانبعاث لذرة الهيدروجين (ليمان، وبالمر، وباشن)، ومستوى الطاقة الذي ينتهي إليه الانتقال في كل منها، ومنطقة الطيف الكهرومغناطيسي التي تقع فيها.', '[]'::jsonb, 'أن يذكر الطالب سلاسل طيف الانبعاث لذرة الهيدروجين (ليمان، وبالمر، وباشن)، ومستوى الطاقة الذي ينتهي إليه الانتقال في كل منها، ومنطقة الطيف الكهرومغناطيسي التي تقع فيها.', 'تسمية السلاسل وتحديد ما يُطلب عن كل سلسلة كما في الشكل 7–12، وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["سلسلة ليمان","سلسلة بالمر","سلسلة باشن","الأشعة فوق البنفسجية","الأشعة تحت الحمراء"]'::jsonb, null, '[200,221]'::jsonb, 'مغطى', 'ص200: «حيث تنبعث الأشعة فوق البنفسجية عندما ينتقل إلكترون من مستوى حالة الإثارة إلى مستوى الطاقة الأول، وتنتج الخطوط الأربعة المرئية… إلى مستوى الطاقة n = 2» والشكل 7–12 (سلسلة بالمر – مرئي، سلسلة ليمان – فوق البنفسجية، سلسلة باشن – تحت الحمراء)؛ ص221 اختبار مقنن 5 و6.', null, 'approved', '2026-11-24'::timestamptz),
(10407122, 104071, 'P32-C7-L1-O22', null, 22, 'أن يذكر الطالب مميزات نموذج بور', 'أن يذكر الطالب مميزات نموذج بور (نجاحاته في حساب أطوال موجات طيف ذرة الهيدروجين وطاقة تأينها، وتوضيح بعض الخصائص الكيميائية للعناصر).', '[]'::jsonb, 'أن يذكر الطالب مميزات نموذج بور (نجاحاته في حساب أطوال موجات طيف ذرة الهيدروجين وطاقة تأينها، وتوضيح بعض الخصائص الكيميائية للعناصر).', 'تحديد المميزات كما وردت في الكتاب، وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["نموذج بور","طاقة التأين","طيف ذرة الهيدروجين"]'::jsonb, null, '[198,204]'::jsonb, 'مغطى', 'ص198: «استخدم بور نظريته لحساب الأطوال الموجية للضوء المنبعث من ذرة الهيدروجين، فكانت الحسابات متوافقة جدًّا مع قيم مقيسة… فإنه يصف مستويات الطاقة… بصورة جيدة»؛ ص204: «كان بور وطلبته قادرين على حساب طاقة التأين لذرة الهيدروجين… وقدم نموذج بور أيضًا توضيحًا لبعض الخصائص الكيميائية للعناصر».', null, 'approved', '2026-11-24'::timestamptz),
(10407123, 104071, 'P32-C7-L1-O23', null, 23, 'أن يحسب الطالب طاقة الفوتون المنبعث أو الممتص عند انتقال الإلكترون بين مستويين للطاقة، وتردده وطوله الموجي، باستخدام العلاقتين E فوتون = hf = ΔE ذرة وλ = hc/ΔE.', 'أن يحسب الطالب طاقة الفوتون المنبعث أو الممتص عند انتقال الإلكترون بين مستويين للطاقة، وتردده وطوله الموجي، باستخدام العلاقتين E فوتون = hf = ΔE ذرة وλ = hc/ΔE.', '[]'::jsonb, 'أن يحسب الطالب طاقة الفوتون المنبعث أو الممتص عند انتقال الإلكترون بين مستويين للطاقة، وتردده وطوله الموجي، باستخدام العلاقتين E فوتون = hf = ΔE ذرة وλ = hc/ΔE.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["طاقة الفوتون المنبعث","ΔE = Ef − Ei","الطول الموجي للفوتون","hc = 1240 eV.nm"]'::jsonb, null, '[198,202,203,217,218]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص198: «طاقة الفوتون المنبعث E فوتون = hf أو E فوتون = ΔE ذرة»؛ ص202 مثال 2 (λ = hc/ΔE = 1240 eV.nm/10.2 eV = 122 nm)؛ ص203 مسائل تدريبية 6–8؛ ص217 مسائل 39 و43–46؛ ص218 مسائل 50 و52–55؛ ص221 اختبار مقنن 2 و3 و6 و7.', null, 'approved', '2026-11-24'::timestamptz),
(10407124, 104071, 'P32-C7-L1-O24', null, 24, 'أن يصف الطالب النموذج النووي للذرة (تركّز الشحنة الموجبة وأكثر من 99.9% من كتلة الذرة في النواة، وأن قطر الذرة أكبر من قطر النواة بنحو 10000 مرة، فمعظم حجم الذرة فراغ).', 'أن يصف الطالب النموذج النووي للذرة (تركّز الشحنة الموجبة وأكثر من 99.9% من كتلة الذرة في النواة، وأن قطر الذرة أكبر من قطر النواة بنحو 10000 مرة، فمعظم حجم الذرة فراغ).', '[]'::jsonb, 'أن يصف الطالب النموذج النووي للذرة (تركّز الشحنة الموجبة وأكثر من 99.9% من كتلة الذرة في النواة، وأن قطر الذرة أكبر من قطر النواة بنحو 10000 مرة، فمعظم حجم الذرة فراغ).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["النموذج النووي","النواة","نموذج تومسون"]'::jsonb, null, '[191,192,193,204]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص191 أهداف الدرس؛ ص192 «النموذج النووي» ونموذج تومسون؛ ص193: «لذلك سمي نموذجه النموذج النووي… أن الشحنة الموجبة للذرة وأكثر من 99.9% من كتلة الذرة موجودة في النواة… ولأن قطر الذرة أكبر 10000 مرة تقريبًا من قطر النواة فإن معظم حجم الذرة يكون فراغًا»؛ ص204 سؤال 9.', null, 'approved', '2026-11-24'::timestamptz),
(10407125, 104071, 'P32-C7-L1-O25', null, 25, 'أن يعرّف الطالب طيف الانبعاث الذري، ويصف كيفية الحصول عليه باستخدام أنبوب تفريغ الغاز.', 'أن يعرّف الطالب طيف الانبعاث الذري، ويصف كيفية الحصول عليه باستخدام أنبوب تفريغ الغاز.', '[]'::jsonb, 'أن يعرّف الطالب طيف الانبعاث الذري، ويصف كيفية الحصول عليه باستخدام أنبوب تفريغ الغاز.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["طيف الانبعاث الذري","أنبوب تفريغ الغاز"]'::jsonb, null, '[193,194,216]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص193: «أن مجموعة الأطوال الموجية الكهرومغناطيسية التي تنبعث من الذرة تسمى طيف الانبعاث الذري… يمكن استخدام ذرات عينة غاز لتبعث ضوءًا في أنبوب تفريغ الغاز» والشكل 7–4؛ ص194: «حيث يحتوي أنبوب تفريغ الغاز على غاز ذي ضغط منخفض… ويتوهج الغاز عند تطبيق فرق جهد عالٍ»؛ ص216 سؤال 28.', null, 'approved', '2026-11-24'::timestamptz),
(10407126, 104071, 'P32-C7-L1-O26', null, 26, 'أن يعرّف الطالب عدد الكم الرئيس n، ويوضّح أن نصف قطر المستوى يزداد بزيادة n² وأن الطاقة تعتمد على 1/n².', 'أن يعرّف الطالب عدد الكم الرئيس n، ويوضّح أن نصف قطر المستوى يزداد بزيادة n² وأن الطاقة تعتمد على 1/n².', '[]'::jsonb, 'أن يعرّف الطالب عدد الكم الرئيس n، ويوضّح أن نصف قطر المستوى يزداد بزيادة n² وأن الطاقة تعتمد على 1/n².', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["عدد الكم الرئيس","تكمية نصف القطر","تكمية الطاقة"]'::jsonb, null, '[191,199,215]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص191 من مفردات الدرس؛ ص199: «ويسمى العدد الصحيح n الذي يظهر في المعادلات عدد الكم الرئيس… فإن نصف القطر r يزداد بزيادة مربع n، بينما تعتمد الطاقة E على 1/n²»؛ ص215 المفردات.', null, 'approved', '2026-11-24'::timestamptz),
(10407127, 104071, 'P32-C7-L1-O27', null, 27, 'أن يوضّح الطالب كيف طوّر بور نموذجه بتطبيق قانون نيوتن الثاني وقانون كولوم على الإلكترون، وافتراض تكمية الزخم الزاوي (mvr = nh/2π).', 'أن يوضّح الطالب كيف طوّر بور نموذجه بتطبيق قانون نيوتن الثاني وقانون كولوم على الإلكترون، وافتراض تكمية الزخم الزاوي (mvr = nh/2π).', '[]'::jsonb, 'أن يوضّح الطالب كيف طوّر بور نموذجه بتطبيق قانون نيوتن الثاني وقانون كولوم على الإلكترون، وافتراض تكمية الزخم الزاوي (mvr = nh/2π).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["قانون نيوتن الثاني","قانون كولوم","الزخم الزاوي","تكمية الزخم الزاوي"]'::jsonb, null, '[198,199,218]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص198 «تطوّر نموذج بور»: kq²/r² = mv²/r؛ ص199: «ثم افترض أن الزخم الزاوي للإلكترون له قيم محددة… اقترح بور أن mvr = nh/2π»؛ ص218 سؤال 56 (القوة الكهربائية والتسارع المركزي والسرعة الدورانية للإلكترون).', null, 'approved', '2026-11-24'::timestamptz),
(10407128, 104071, 'P32-C7-L1-O28', null, 28, 'أن يقدّر الطالب حجم جسم لا يمكن رؤيته باستخدام الاحتمالات في نموذج محاكٍ لتجربة صفيحة الذهب، ويحسب نسبة الخطأ المئوية.', 'أن يقدّر الطالب حجم جسم لا يمكن رؤيته باستخدام الاحتمالات في نموذج محاكٍ لتجربة صفيحة الذهب، ويحسب نسبة الخطأ المئوية.', '[]'::jsonb, 'أن يقدّر الطالب حجم جسم لا يمكن رؤيته باستخدام الاحتمالات في نموذج محاكٍ لتجربة صفيحة الذهب، ويحسب نسبة الخطأ المئوية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["الاحتمالات","نسبة الخطأ المئوية","تجربة صفيحة الذهب"]'::jsonb, null, '[212,213]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص212–213 مختبر الفيزياء «إيجاد حجم الذرة»: «كيف يمكن استخدام الاحتمالات لتحديد حجم جسم لا يمكن رؤيته؟» مع خطوات الحساب وتحليل الخطأ.', null, 'approved', '2026-11-24'::timestamptz),
(10407201, 104072, 'P32-C7-L2-O01', null, 1, 'أن يذكر الطالب أوجه القصور في نموذج بور.', 'أن يصف الطالب أوجه القصور في نموذج بور الذري (تعارض افتراضاته مع النظرية الكهرومغناطيسية ومع مبدأ عدم التحديد لهيزنبرج).', '[]'::jsonb, 'أن يصف الطالب أوجه القصور في نموذج بور الذري (تعارض افتراضاته مع النظرية الكهرومغناطيسية ومع مبدأ عدم التحديد لهيزنبرج).', '«يذكر» إلى «يصف» كما في أهداف الدرس ص205، وتحديد أوجه القصور كما في الكتاب، وحذف النقطة قبل القوس.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["نموذج بور","النظرية الكهرومغناطيسية","مبدأ عدم التحديد لهيزنبرج"]'::jsonb, null, '[205,211,219]'::jsonb, 'مغطى', 'ص205 أهداف الدرس «تصف أوجه القصور في نموذج بور الذري»، والنص: «فالنظرية الكهرومغناطيسية مثلًا تتطلب أن تبعث الجسيمات المتسارعة طاقة، مما يؤدي إلى انهيار سريع للذرة… إن الإلكترون الدائر له مستوى محدد بنصف قطر معين تتعارض مع مبدأ عدم التحديد لهيزنبرج»؛ ص211 سؤالا 18 و19.', null, 'approved', '2026-11-24'::timestamptz),
(10407202, 104072, 'P32-C7-L2-O02', null, 2, 'أن يعرف الطالب النموذج الكمي.', 'أن يعرّف الطالب النموذج الكمي للذرة.', '[]'::jsonb, 'أن يعرّف الطالب النموذج الكمي للذرة.', '«يعرف» الغامضة إلى «يعرّف»، وإكمال المصطلح «النموذج الكمي للذرة»، وحذف النقطة الزائدة. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["النموذج الكمي"]'::jsonb, null, '[205,215]'::jsonb, 'مغطى', 'ص205 من مفردات الدرس، والنص: «لذا فإن النموذج الكمي يتوقع احتمالية وجود الإلكترون في منطقة محددة فقط»؛ ص215 المفردات.', null, 'approved', '2026-11-24'::timestamptz),
(10407203, 104072, 'P32-C7-L2-O03', null, 3, 'أن يصف الطالب النموذج الكمي للذرة', 'أن يصف الطالب النموذج الكمي للذرة، ويقارنه بنموذج بور.', '[]'::jsonb, 'أن يصف الطالب النموذج الكمي للذرة، ويقارنه بنموذج بور.', 'إضافة المقارنة بنموذج بور لأن الكتاب يعرض النموذج الكمي في مقابل نموذج بور (المسافة الأكثر احتمالية تساوي نصف قطر بور) ويسأل عنها (سؤال 41)، وإضافة علامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النموذج الكمي","نظرية شرودنجر","مبدأ عدم التحديد","الاحتمالية"]'::jsonb, null, '[205,206,215,217,221]'::jsonb, 'مغطى', 'ص205: «استخدم العالم النمساوي إيرين شرودنجر… نموذج موجة دي برولي للوصول إلى نظرية الكم للذرة… لذا فإن النموذج الكمي يتوقع احتمالية وجود الإلكترون… أن المسافة الأكثر احتمالية بين الإلكترون والنواة لذرة الهيدروجين هي نصف القطر نفسه الذي تم توقعه من خلال نموذج بور»؛ ص206 الشكل 7–14؛ ص215؛ ص217 سؤال 41؛ ص221 اختبار مقنن 4.', null, 'approved', '2026-11-24'::timestamptz),
(10407204, 104072, 'P32-C7-L2-O04', null, 4, 'أن يعرف الطالب السحابة الالكترونية', 'أن يعرّف الطالب السحابة الإلكترونية.', '[]'::jsonb, 'أن يعرّف الطالب السحابة الإلكترونية.', '«يعرف» الغامضة إلى «يعرّف»، وتصحيح «الالكترونية» إلى «الإلكترونية»، وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["السحابة الإلكترونية"]'::jsonb, null, '[206,215]'::jsonb, 'مغطى', 'ص206: «والمنطقة ذات الاحتمالية العالية لوجود الإلكترون فيها تسمى سحابة إلكترونية» والشكل 7–14؛ ص215 المفردات.', null, 'approved', '2026-11-24'::timestamptz),
(10407205, 104072, 'P32-C7-L2-O05', null, 5, 'أن يوضح الطالب المقصود بميكانيكا الكم', 'أن يوضّح الطالب المقصود بميكانيكا الكم.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بميكانيكا الكم.', 'تشكيل «يوضّح» وإضافة علامة الترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["ميكانيكا الكم"]'::jsonb, null, '[206,215]'::jsonb, 'مغطى', 'ص206: «فإن ميكانيكا الكم – وهي دراسة خصائص المادة باستخدام خصائصها الموجية –»؛ ص215 المفردات.', null, 'approved', '2026-11-24'::timestamptz),
(10407206, 104072, 'P32-C7-L2-O06', null, 6, 'أن يعدد الطالب النجاحات التي حققتها ميكانيكا الكم', 'أن يعدّد الطالب النجاحات التي حققتها ميكانيكا الكم.', '[]'::jsonb, 'أن يعدّد الطالب النجاحات التي حققتها ميكانيكا الكم.', 'تشكيل «يعدّد» وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["ميكانيكا الكم","تراكيب الجزيئات","الليزر"]'::jsonb, null, '[206,215]'::jsonb, 'مغطى', 'ص206: «قد حققت نجاحًا هائلًا في توقع الكثير من المعلومات التفصيلية لتركيب الذرة… تمكنت من جعل تراكيب بعض الجزيئات قابلة للحساب… استطاع الكيميائيون تحضير جزيئات جديدة… لتحليل تفاصيل امتصاص وانبعاث الضوء… تم تطوير مصدر جديد للضوء»؛ ص215: «نجحت ميكانيكا الكم إلى حدٍّ كبير في تحديد خصائص الذرات والجزيئات والمواد الصلبة».', null, 'approved', '2026-11-24'::timestamptz),
(10407207, 104072, 'P32-C7-L2-O07', null, 7, 'أن يقارن الطالب بين الضوء المترابط والضوء الغير مترابط', 'أن يقارن الطالب بين الضوء المترابط والضوء غير المترابط.', '[]'::jsonb, 'أن يقارن الطالب بين الضوء المترابط والضوء غير المترابط.', 'تصحيح «الغير مترابط» إلى «غير المترابط» (لا تدخل «أل» على «غير» المضافة)، وإضافة علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الضوء المترابط","الضوء غير المترابط","الطور"]'::jsonb, null, '[207,215]'::jsonb, 'مغطى', 'ص207: «ويشار إلى أن موجات الضوء المترابطة تكون ضوءًا مترابطًا، بينما تنتج موجات الضوء المختلفة في الطور ضوءًا غير مترابط» والشكل 7–15؛ ص215 المفردات.', null, 'approved', '2026-11-24'::timestamptz),
(10407208, 104072, 'P32-C7-L2-O08', null, 8, 'أن يذكر الطالب طرق اثارت الذرات', 'أن يذكر الطالب طرائق إثارة الذرات.', '[]'::jsonb, 'أن يذكر الطالب طرائق إثارة الذرات.', 'تصحيح «اثارت» إلى «إثارة»، و«طرق» إلى «طرائق» كما يكتبها الكتاب، وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الإثارة الحرارية","تصادم الإلكترون","التصادم مع الفوتونات"]'::jsonb, null, '[207]'::jsonb, 'مغطى', 'ص207: «وقد درست حتى الآن طريقتين يمكن أن تثار الذرات بهما، وهما: الإثارة الحرارية، وتصادم الإلكترون. لكن يمكن للذرات أن تثار أيضًا نتيجة تصادمها مع فوتونات ذات طاقة محددة».', null, 'approved', '2026-11-24'::timestamptz),
(10407209, 104072, 'P32-C7-L2-O09', null, 9, 'أن يقارن الطالب بين الانبعاث التلقائي والانبعاث المحفز', 'أن يقارن الطالب بين الانبعاث التلقائي والانبعاث المحفز.', '[]'::jsonb, 'أن يقارن الطالب بين الانبعاث التلقائي والانبعاث المحفز.', 'إضافة علامة الترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الانبعاث التلقائي","الانبعاث المحفز"]'::jsonb, null, '[208,215]'::jsonb, 'مغطى', 'ص208: «تعود الذرة بعد وقت قصير عادة إلى حالتها المستقرة باعثة فوتونًا… وهذه العملية تسمى الانبعاث التلقائي… فبيّن حينها أن هذه الحالة للذرة تسمى الانبعاث المحفز» والشكل 7–16 (a وb)؛ ص215.', null, 'approved', '2026-11-24'::timestamptz),
(10407210, 104072, 'P32-C7-L2-O10', null, 10, 'أن يذكر الطالب شروط الانبعاث المحفز', 'أن يذكر الطالب شروط حدوث الانبعاث المحفز.', '[]'::jsonb, 'أن يذكر الطالب شروط حدوث الانبعاث المحفز.', 'إضافة «حدوث» للدقة، وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الانبعاث المحفز","الذرات المثارة"]'::jsonb, null, '[208]'::jsonb, 'مغطى', 'ص208: «هذه العملية محددة بالشروط التالية حتى تحدث. أولًا: يجب أن تكون هناك ذرات أخرى مثارة. ثانيًا: يجب أن تبقى الذرات مثارة لفترة زمنية كافية حتى يحدث التصادم. ثالثًا: يجب السيطرة على الفوتونات وتوجيهها».', null, 'approved', '2026-11-24'::timestamptz),
(10407211, 104072, 'P32-C7-L2-O11', null, 11, 'أن يعرف الطالب الليزر', 'أن يعرّف الطالب الليزر.', '[]'::jsonb, 'أن يعرّف الطالب الليزر.', '«يعرف» الغامضة إلى «يعرّف»، وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الليزر","تضخيم الضوء بواسطة الانبعاث المحرّض للإشعاع","الذرة الليزرية"]'::jsonb, null, '[208,215,216]'::jsonb, 'مغطى', 'ص208: «في عام 1959م تم ابتكار أداة تسمى ليزر، وقد حققت جميع الشروط اللازمة لإنتاج ضوء مترابط. وكلمة ليزر هي اختصار للعبارة "تضخيم الضوء بواسطة الانبعاث المحرّض للإشعاع"»؛ ص215 المفردات؛ ص216 سؤال 32 (الميزر).', null, 'approved', '2026-11-24'::timestamptz),
(10407212, 104072, 'P32-C7-L2-O12', null, 12, 'أن يوضح الطالب كيف تثار ذرات الليزر', 'أن يوضّح الطالب طرائق إثارة (ضخ) ذرات الليزر.', '[]'::jsonb, 'أن يوضّح الطالب طرائق إثارة (ضخ) ذرات الليزر.', 'تحويل «كيف تثار» إلى صيغة هدف، وإضافة مصطلح الكتاب «الضخ»، وتشكيل «يوضّح» وإضافة علامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["ضخ الذرات","الومضة الضوئية","ليزر هيليوم–نيون"]'::jsonb, null, '[208,211]'::jsonb, 'مغطى', 'ص208: «إثارة الذرة الذرات في الليزر يمكن أن تثار أو تضخ… حيث يمكن لومضة كثيفة من الضوء ذات طول موجي أقصر من الليزر أن تستخدم لضخ الذرات… كما يمكن للذرات الليزرية أن تثار نتيجة التصادم مع ذرات أخرى. ففي أجهزة ليزر هيليوم–نيون…» والشكل 7–17؛ ص211 سؤال 17.', null, 'approved', '2026-11-24'::timestamptz),
(10407213, 104072, 'P32-C7-L2-O13', null, 13, 'أن يوضح الطالب سبب ان ضوء الليزر مترابط', 'أن يفسّر الطالب سبب أن ضوء الليزر مترابط.', '[]'::jsonb, 'أن يفسّر الطالب سبب أن ضوء الليزر مترابط.', '«يوضح سبب» إلى «يفسّر سبب» لأنه تعليل، وتصحيح همزة «أن»، وإضافة علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["ضوء الليزر","الضوء المترابط","الانبعاث المحفز"]'::jsonb, null, '[209]'::jsonb, 'مغطى', 'ص209: «ولأن جميع فوتونات الإثارة تنبعث في الطور نفسه مع الفوتونات التي تصطدم بالذرات فإن ضوء الليزر يكون مترابطًا».', null, 'approved', '2026-11-24'::timestamptz),
(10407214, 104072, 'P32-C7-L2-O14', null, 14, 'أن يوضح الطالب سبب ان ضوء الليزر له الطول الموجي نفسه', 'أن يفسّر الطالب سبب أن لضوء الليزر الطول الموجي نفسه (أحادي اللون).', '[]'::jsonb, 'أن يفسّر الطالب سبب أن لضوء الليزر الطول الموجي نفسه (أحادي اللون).', '«يوضح سبب» إلى «يفسّر سبب»، وتصحيح همزة «أن» وتركيب الجملة («أن لضوء الليزر» بدل «ان ضوء الليزر له»)، وإضافة مصطلح الكتاب «أحادي اللون».', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["ضوء الليزر","أحادي اللون","مستويات الطاقة"]'::jsonb, null, '[209]'::jsonb, 'مغطى', 'ص209: «وكذلك فإن ضوء الليزر له الطول الموجي نفسه (أحادي اللون) بسبب انتقال الإلكترونات بين زوج واحد فقط من مستويات الطاقة، وفي نوع واحد من الذرات».', null, 'approved', '2026-11-24'::timestamptz),
(10407215, 104072, 'P32-C7-L2-O15', null, 15, 'أن يوضح الطالب تطبيقات الليزر', 'أن يوضّح الطالب تطبيقات الليزر، ويربط كل تطبيق بخاصية ضوء الليزر التي يعتمد عليها.', '[]'::jsonb, 'أن يوضّح الطالب تطبيقات الليزر، ويربط كل تطبيق بخاصية ضوء الليزر التي يعتمد عليها.', 'تشكيل «يوضّح»، وإضافة الربط بالخصائص لأن الكتاب يعرض التطبيقات معللة بخصائص الليزر (حزم ضيقة لا تتشتت، طول موجي أحادي، طاقة مركّزة، طبيعة مترابطة).', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["تطبيقات الليزر","الألياف البصرية","الهولوجرام","جراحة العين بالليزر"]'::jsonb, null, '[210,211,216]'::jsonb, 'مغطى', 'ص210 «تطبيقات الليزر»: مشغل القرص المدمج CD وDVD، واختبار استقامة الأنفاق والأنابيب، وقياس بعد القمر، واتصالات الألياف البصرية، وصندوق جراحة العين؛ ص211: أجهزة المطياف، والطب (قرنية العين والجراحة)، وقطع المعادن وتلحيمها، والهولوجرام؛ ص216 سؤال 33.', null, 'approved', '2026-11-24'::timestamptz),
(10407216, 104072, 'P32-C7-L2-O16', null, 16, 'أن يفسّر الطالب شرط استقرار مستويات الإلكترون في الذرة باستخدام موجات دي برولي (nλ = 2πr).', 'أن يفسّر الطالب شرط استقرار مستويات الإلكترون في الذرة باستخدام موجات دي برولي (nλ = 2πr).', '[]'::jsonb, 'أن يفسّر الطالب شرط استقرار مستويات الإلكترون في الذرة باستخدام موجات دي برولي (nλ = 2πr).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["طول موجة دي برولي","محيط المستوى","الحالة المستقرة"]'::jsonb, null, '[205,221]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص205: «تم حساب طول موجة دي برولي لجسيم زخمه mv بالمعادلة λ = h/mv… nλ = 2πr… لذلك فإن محيط مستوى بور 2πr يساوي العدد الصحيح n مضروبًا في طول موجة دي برولي» والشكل 7–13 (n = 3 وn = 5 مستقران، وn = 2.9 غير مستقر)؛ ص221 اختبار مقنن 4 (D).', null, 'approved', '2026-11-24'::timestamptz),
(10407217, 104072, 'P32-C7-L2-O17', null, 17, 'أن يصف الطالب كيف يُنتَج شعاع الليزر في أنبوب تحصر طرفيه مرآتان متوازيتان إحداهما جزئية الانعكاس.', 'أن يصف الطالب كيف يُنتَج شعاع الليزر في أنبوب تحصر طرفيه مرآتان متوازيتان إحداهما جزئية الانعكاس.', '[]'::jsonb, 'أن يصف الطالب كيف يُنتَج شعاع الليزر في أنبوب تحصر طرفيه مرآتان متوازيتان إحداهما جزئية الانعكاس.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["إنتاج الليزر","المرآة الجزئية الانعكاس","الانبعاث المحفز"]'::jsonb, null, '[209,211]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص209 «إنتاج الليزر»: «طريق حصر تلك الذرات في أنبوب زجاجي على طرفيه المتقابلين مرايا مستوية متوازية… إحدى هذه المرايا عاكسة بمقدار يزيد على 99.9%… بينما المرآة الأخرى… تسمح لـ 1%… ثم تخرج الفوتونات من الأنبوب خلال المرآة الجزئية الانعكاس منتجة شعاع ليزر»؛ ص211 سؤال 20.', null, 'approved', '2026-11-24'::timestamptz),
(10407218, 104072, 'P32-C7-L2-O18', null, 18, 'أن يصف الطالب خصائص ضوء الليزر (أحادي اللون، ومترابط، وموجّه، وذو طاقة عالية).', 'أن يصف الطالب خصائص ضوء الليزر (أحادي اللون، ومترابط، وموجّه، وذو طاقة عالية).', '[]'::jsonb, 'أن يصف الطالب خصائص ضوء الليزر (أحادي اللون، ومترابط، وموجّه، وذو طاقة عالية).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["خصائص ضوء الليزر","أحادي اللون","مترابط","موجّه"]'::jsonb, null, '[205,209,210,211,215]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص205 أهداف الدرس؛ ص209: «فإن ضوء الليزر لا ينحرف مهما ابتعد عن مصدره… فإن الضوء يكون عالي الكثافة»؛ ص210: «وحزمة أشعة الليزر ضيّقة وموجهة بدقة كبيرة»؛ ص211 سؤال 21: «ما الخصائص الأربعة لضوء الليزر»؛ ص215: «ضوءًا أحادي اللون ومترابطًا وموجهًا وذا طاقة عالية».', null, 'approved', '2026-11-24'::timestamptz),
(10407219, 104072, 'P32-C7-L2-O19', null, 19, 'أن يستخدم الطالب الجدول 7–1 لمصادر الليزر الشائعة لتحديد الطول الموجي ونوع الليزر (نبضي أو مستمر)، ويحسب فرق الطاقة بين مستويات الطاقة الليزرية من الطول الموجي.', 'أن يستخدم الطالب الجدول 7–1 لمصادر الليزر الشائعة لتحديد الطول الموجي ونوع الليزر (نبضي أو مستمر)، ويحسب فرق الطاقة بين مستويات الطاقة الليزرية من الطول الموجي.', '[]'::jsonb, 'أن يستخدم الطالب الجدول 7–1 لمصادر الليزر الشائعة لتحديد الطول الموجي ونوع الليزر (نبضي أو مستمر)، ويحسب فرق الطاقة بين مستويات الطاقة الليزرية من الطول الموجي.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["مصادر الليزر","ليزر نبضي","ليزر مستمر","فرق الطاقة"]'::jsonb, null, '[210,211,218]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص210 الجدول 7–1 «مصادر الليزر الشائعة» (الوسط، الطول الموجي، النوع)؛ ص211 سؤال 16؛ ص218 مسائل 57–61 (ليزرات زرنيخات الجاليوم، GaInNi، ثاني أكسيد الكربون، HeNe).', null, 'approved', '2026-11-24'::timestamptz),
(10408101, 104081, 'P32-C8-L1-O01', null, 1, 'ان يوضح الطالب طريقة عمل انابيب التفريغ', 'أن يصف الطالب وظيفة أنابيب التفريغ وعيوبها التي أدت إلى استبدالها بأدوات الحالة الصلبة.', '[]'::jsonb, 'أن يصف الطالب وظيفة أنابيب التفريغ وعيوبها التي أدت إلى استبدالها بأدوات الحالة الصلبة.', 'همزة «أن»؛ والكتاب لا يشرح آلية عمل أنابيب التفريغ تفصيلًا، بل يذكر وظيفتها (تدفق الإلكترونات خلال الفراغ لتكبير الإشارات الضعيفة وضبطها) وعيوبها (قدرة كبيرة، فتائل تسخين، حرارة، عمر قصير)، فعُدّلت الصياغة لتطابق المحتوى.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["أنابيب التفريغ","أدوات الحالة الصلبة"]'::jsonb, null, '[223,224]'::jsonb, 'مغطى جزئيًا', 'ص223: «يعود الفضل في عمل جميع الأدوات الإلكترونية إلى أنابيب التفريغ… حيث تدفق الإلكترونات خلال الفراغ… لتكبير الإشارات الكهربائية الضعيفة وضبطها» مع ذكر حاجتها إلى قدرة كبيرة وفتائل تسخين واستبدالها خلال سنة إلى خمس سنوات؛ ولا يوجد شرح لتركيبها الداخلي، لذا التغطية جزئية لصيغة «طريقة العمل».', null, 'approved', '2026-11-24'::timestamptz),
(10408102, 104081, 'P32-C8-L1-O02', null, 2, 'ان يعرف الطالب أشباه الموصلات', 'أن يعرّف الطالب أشباه الموصلات، ويذكر أمثلة عليها مثل السليكون والجرمانيوم.', '[]'::jsonb, 'أن يعرّف الطالب أشباه الموصلات، ويذكر أمثلة عليها مثل السليكون والجرمانيوم.', 'همزة «أن»، و«يعرف» الغامضة إلى «يعرّف»، وإضافة الأمثلة كما وردت في الكتاب. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["أشباه الموصلات","السليكون","الجرمانيوم"]'::jsonb, null, '[223,228]'::jsonb, 'مغطى', 'ص223: «وصُنعت هذه الأدوات من مواد تعرف بأشباه الموصلات، ومنها: السليكون والجرمانيوم» (مفردة مظللة)، وص228 عنوان «أشباه الموصلات».', null, 'approved', '2026-11-24'::timestamptz),
(10408103, 104081, 'P32-C8-L1-O03', null, 3, 'ان يوضح الطالب مميزات الادوات الالكترونية المصنوعة من اشباه الموصلات', 'أن يوضّح الطالب مميزات الأدوات الإلكترونية المصنوعة من أشباه الموصلات مقارنةً بأنابيب التفريغ.', '[]'::jsonb, 'أن يوضّح الطالب مميزات الأدوات الإلكترونية المصنوعة من أشباه الموصلات مقارنةً بأنابيب التفريغ.', 'همزة «أن»، وتصحيح «الادوات، الالكترونية، اشباه»، وإضافة أساس المقارنة كما في الكتاب.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["أدوات أشباه الموصلات","أنابيب التفريغ"]'::jsonb, null, '[223,224]'::jsonb, 'مغطى', 'ص224: «تعمل الأدوات المصنوعة من أشباه الموصلات بقدرة كهربائية صغيرة… لا تحتوي على فتائل… صغيرة جدًا، ولا تولّد حرارة كبيرة، وتكلفة صناعتها قليلة، ويقدّر عمرها الافتراضي بعشرين عامًا أو أكثر».', null, 'approved', '2026-11-24'::timestamptz),
(10408104, 104081, 'P32-C8-L1-O04', null, 4, 'ان يوضح الطالب نظرية الاحزمة للمواد الصلبة', 'أن يوضّح الطالب نظرية الأحزمة للمواد الصلبة (حزمة التكافؤ، وحزمة التوصيل، وفجوة الطاقة الممنوعة).', '[]'::jsonb, 'أن يوضّح الطالب نظرية الأحزمة للمواد الصلبة (حزمة التكافؤ، وحزمة التوصيل، وفجوة الطاقة الممنوعة).', 'همزة «أن»، وتصحيح «الاحزمة»، وتحديد مكونات النظرية كما في الكتاب.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["نظرية الأحزمة","حزمة التكافؤ","حزمة التوصيل","فجوة الطاقة الممنوعة"]'::jsonb, null, '[224,225]'::jsonb, 'مغطى', 'ص224 «نظرية الأحزمة للمواد الصلبة» والشكل 8-1 (تجزؤ مستويات الطاقة عند تقارب ذرتين ثم أربع ثم ذرات عديدة وتكوّن حزمة التكافؤ وحزمة التوصيل وفجوة الطاقة)، وص225 تعريف نظرية الأحزمة (مفردة مظللة).', null, 'approved', '2026-11-24'::timestamptz),
(10408105, 104081, 'P32-C8-L1-O05', null, 5, 'ان يذكر الطالب الهدف من نظرية الاحزمة للمواد الصلبة', 'أن يذكر الطالب الهدف من استخدام نظرية الأحزمة للمواد الصلبة.', '[]'::jsonb, 'أن يذكر الطالب الهدف من استخدام نظرية الأحزمة للمواد الصلبة.', 'همزة «أن»، وتصحيح «الاحزمة». مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["نظرية الأحزمة","التوصيل الكهربائي"]'::jsonb, null, '[225]'::jsonb, 'مغطى', 'ص225: «ويسمى هذا الوصف… نظرية الأحزمة للمواد الصلبة، ويمكن استخدامها من أجل فهم أفضل للتوصيل الكهربائي».', null, 'approved', '2026-11-24'::timestamptz),
(10408106, 104081, 'P32-C8-L1-O06', null, 6, 'ان يقارن الطالب بين فجوات الطاقة في عدة مواد ؟', 'أن يقارن الطالب بين مقادير فجوة الطاقة الممنوعة في عدة مواد (الماس، والسليكون، والجرمانيوم، والعوازل) ويربطها بقدرتها على التوصيل.', '[]'::jsonb, 'أن يقارن الطالب بين مقادير فجوة الطاقة الممنوعة في عدة مواد (الماس، والسليكون، والجرمانيوم، والعوازل) ويربطها بقدرتها على التوصيل.', 'همزة «أن»، وحذف علامة الاستفهام الخاطئة في آخر الهدف، وتحديد المواد التي يقارن بينها الكتاب، واستخدام مصطلح الكتاب «فجوة الطاقة الممنوعة».', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["فجوة الطاقة الممنوعة","الماس","السليكون","الجرمانيوم"]'::jsonb, null, '[225,227,228]'::jsonb, 'مغطى', 'ص225 الشكل 8-2 (مقارنة فجوة الطاقة بين السليكون البلوري 1.1 eV والكربون البلوري/الماس 5.5 eV) وفجوة الجرمانيوم 0.7 eV؛ ص227 العوازل 5 eV على الأقل؛ ص228 الشكل 8-5 (عازل 5 eV وشبه موصل 1 eV)؛ أسئلة 18، 19 ص234 وسؤال 44 ص246.', null, 'approved', '2026-11-24'::timestamptz),
(10408107, 104081, 'P32-C8-L1-O07', null, 7, 'ان يصف الطالب الموصلات وفق نظرية الاحزمة للمواد الصلبة', 'أن يصف الطالب الموصلات الكهربائية وفق نظرية الأحزمة للمواد الصلبة.', '[]'::jsonb, 'أن يصف الطالب الموصلات الكهربائية وفق نظرية الأحزمة للمواد الصلبة.', 'همزة «أن»، وتصحيح «الاحزمة»، واستخدام مصطلح الكتاب «الموصلات الكهربائية».', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الموصلات الكهربائية","حزمة التوصيل المملوءة جزئيًا"]'::jsonb, null, '[225,226]'::jsonb, 'مغطى', 'ص225 الشكل 8-3 (في المادة جيدة التوصيل تكون حزمة التوصيل مملوءة جزئيًا)، وص226 عنوان «الموصلات الكهربائية» والشكل 8-4.', null, 'approved', '2026-11-24'::timestamptz),
(10408108, 104081, 'P32-C8-L1-O08', null, 8, 'ان يحل الطالب مسائل حسابية على كثافة الالكترونات الحرة في موصل', 'أن يحسب الطالب عدد الإلكترونات الحرة في وحدة الحجم (free e⁻/cm³) لموصل بمعلومية كثافته وكتلته الذرية وعدد الإلكترونات الحرة لكل ذرة.', '[]'::jsonb, 'أن يحسب الطالب عدد الإلكترونات الحرة في وحدة الحجم (free e⁻/cm³) لموصل بمعلومية كثافته وكتلته الذرية وعدد الإلكترونات الحرة لكل ذرة.', 'همزة «أن»، وتصحيح «الالكترونات»، وتحديد المعطيات والمطلوب كما في المثال 1 بدل العبارة العامة «مسائل حسابية على».', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["كثافة الإلكترونات الحرة","عدد أفوجادرو","الكتلة الذرية"]'::jsonb, null, '[226,227,247]'::jsonb, 'مغطى', 'ص226–227 المثال 1 «كثافة الإلكترونات الحرة في موصل» (النحاس 8.49×10²² free e⁻/cm³) والمسائل التدريبية 1–5؛ ص247 سؤال 52 (الصوديوم).', null, 'approved', '2026-11-24'::timestamptz),
