(10409305, 104093, 'P32-C9-L3-O05', null, 5, 'ان يقارن الطالب بين الجسيم وضديده', 'أن يقارن الطالب بين الجسيم وضديده.', '[]'::jsonb, 'أن يقارن الطالب بين الجسيم وضديده.', 'همزة «أن»، وإضافة علامة الترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["ضديد المادة","البوزترون","ضديد البروتون","الفناء"]'::jsonb, null, '[272,274,282]'::jsonb, 'مغطى', 'ص272 «ضديد المادة»: «والإلكترون الموجب الذي يسمى بوزترون مثال على ضديد الجسيم. وللإلكترون والبوزترون نفس الكتلة ومقدار الشحنة، ومع ذلك فإن إشارتي شحنتيهما متعاكستان»؛ ص274 «حفظ الجسيم»: «يتماثل ضديد الجسيمات مع الجسيمات إلا في نوع الشحنة»؛ ص282 سؤال 58.', null, 'approved', '2026-11-24'::timestamptz),
(10409306, 104093, 'P32-C9-L3-O06', null, 6, 'ان يفسر الطالب تولد بعض الجسيمات في التفاعلات النووية.', 'أن يفسّر الطالب تولّد بعض الجسيمات في التفاعلات النووية (مثل النيوترينو في اضمحلال بيتا، وزوج الإلكترون–البوزترون في إنتاج الزوج).', '[]'::jsonb, 'أن يفسّر الطالب تولّد بعض الجسيمات في التفاعلات النووية (مثل النيوترينو في اضمحلال بيتا، وزوج الإلكترون–البوزترون في إنتاج الزوج).', 'همزة «أن»، وتشكيل «يفسّر»، وتحديد الحالات التي يفسرها الكتاب لأن الصياغة الأصلية عامة.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النيوترينو","إنتاج الزوج","حفظ الطاقة"]'::jsonb, null, '[272,274,275]'::jsonb, 'مغطى', 'ص272: «والحقيقة أن المدى الواسع لطاقات الإلكترونات المنبعثة خلال اضمحلال بيتا نبهت… إلى وجود جسيم آخر يمكن أن يشارك في التفاعل النووي؛ حيث يحمل جزءًا من الطاقة… النيوترينو»؛ ص274: «أي أن الطاقة يمكن أن تتحول مباشرةً إلى مادة»؛ ص275.', null, 'approved', '2026-11-24'::timestamptz),
(10409307, 104093, 'P32-C9-L3-O07', null, 7, 'ان يذكر الطالب بعض الأمثلة على جسيمات تتولد في التفاعلات النووية', 'أن يذكر الطالب بعض الأمثلة على جسيمات تتولد في التفاعلات النووية.', '[]'::jsonb, 'أن يذكر الطالب بعض الأمثلة على جسيمات تتولد في التفاعلات النووية.', 'همزة «أن»، وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["النيوترينو","البوزترون","الميون","البيون","ضديد البروتون"]'::jsonb, null, '[265,272,274]'::jsonb, 'مغطى', 'ص265: «ويمكن للأنوية المشعة أن تبعث جسيمات ألفا، وجسيمات بيتا، وإشعاع جاما. بالإضافة إلى النيوترينو، وضديد نيوترينو، والبوزترونات»؛ ص272 الميون والبيون؛ ص274 ضديد البروتون.', null, 'approved', '2026-11-24'::timestamptz),
(10409308, 104093, 'P32-C9-L3-O08', null, 8, 'ان يوضح الطالب المقصود بالنموذج المعياري ، الكواركات ، اللبتونات .', 'أن يوضّح الطالب المقصود بكل من: النموذج المعياري، والكواركات، واللبتونات.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بكل من: النموذج المعياري، والكواركات، واللبتونات.', 'همزة «أن»، وتشكيل «يوضّح»، وضبط العطف والترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النموذج المعياري","الكواركات","اللبتونات","الهادرونات"]'::jsonb, null, '[272,273,281]'::jsonb, 'مغطى', 'ص272: «ويعتقد العلماء الآن وجود ثلاث عائلات من الجسيمات الأولية وفقًا للنموذج المعياري هي: الكواركات، واللبتونات، وحاملات القوى (البوزونات)»؛ ص273 الجدول 9–3: «عائلة الكواركات… عائلة اللبتونات… مثل: الإلكترون، والميون، والتاو»؛ ص281.', null, 'approved', '2026-11-24'::timestamptz),
(10409309, 104093, 'P32-C9-L3-O09', null, 9, 'ان يوضح الطالب المقصود بحاملات القوة.', 'أن يوضّح الطالب المقصود بحاملات القوة، ويفسّر دورها في نقل القوى الأساسية.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بحاملات القوة، ويفسّر دورها في نقل القوى الأساسية.', 'همزة «أن»، وتشكيل «يوضّح»، وإضافة «يفسّر دورها» كما في هدف الدرس «وتفسر دور حاملات القوة».', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["حاملات القوة","الفوتونات","الجلونات","البوزونات الضعيفة","الجرافيتون"]'::jsonb, null, '[269,273,281]'::jsonb, 'مغطى', 'ص269 أهداف الدرس؛ ص273: «عائلة حاملات القوى (force carriers) وتسمى كذلك البوزونات: وهي جسيمات تنقل القوى الأساسية، فمثلًا تحمل الفوتونات القوة الكهرومغناطيسية، وتحمل الجلونات الثمانية القوى النووية القوية، أما البوزونات الثلاثة الضعيفة فهي التي تحمل القوة النووية الضعيفة، والجرافيتون حامل قوة الجاذبية»؛ ص281.', null, 'approved', '2026-11-24'::timestamptz),
(10409310, 104093, 'P32-C9-L3-O10', null, 10, 'ان يوضح الطالب تركيب كل من البروتون والنيوترون وفق نموذج الكواركات', 'أن يوضّح الطالب تركيب كل من البروتون والنيوترون وفق نموذج الكواركات، ويحسب شحنة كل منهما من شحنات كواركاته.', '[]'::jsonb, 'أن يوضّح الطالب تركيب كل من البروتون والنيوترون وفق نموذج الكواركات، ويحسب شحنة كل منهما من شحنات كواركاته.', 'همزة «أن»، وتشكيل «يوضّح»، وإضافة حساب الشحنة لأنه جزء من عرض الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الكوارك العلوي","الكوارك السفلي","p = uud","n = udd"]'::jsonb, null, '[272,273,284]'::jsonb, 'مغطى', 'ص272 الشكل 9–16؛ ص273 «البروتونات والنيوترونات»: «فيتكون البروتون من اثنين من الكواركات العلوية (+2/3 e) وكوارك سفلي واحد (−1/3 e)… p = uud… بينما يتكون النيوترون من كوارك واحد علوي واثنين من الكواركات السفلية n = udd؛ فشحنة النيوترون صفر»؛ ص284 سؤال 82.', null, 'approved', '2026-11-24'::timestamptz),
(10409311, 104093, 'P32-C9-L3-O11', null, 11, 'ان يحسب الطالب الطاقة الناتجة من فناء جسيم.', 'أن يحسب الطالب الطاقة الناتجة من فناء جسيم وضديده باستخدام العلاقة E = mc².', '[]'::jsonb, 'أن يحسب الطالب الطاقة الناتجة من فناء جسيم وضديده باستخدام العلاقة E = mc².', 'همزة «أن»، وحذف النقطة الزائدة، وإضافة «وضديده» لأن الفناء يحدث لزوج الجسيم وضديده كما يوضح الكتاب، وإضافة العلاقة.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["الفناء","E = mc²","1.02 MeV"]'::jsonb, null, '[274,275,286]'::jsonb, 'مغطى', 'ص274 «التحولات بين الكتلة والطاقة»: «يمكن حساب كمية الطاقة التي تتولد نتيجة فناء جسيم باستخدام معادلة أينشتاين… E = 1.02×10⁶ eV أو 1.02 MeV»؛ ص275 مسائل تدريبية 35–38؛ ص286 اختبار مقنن 8.', null, 'approved', '2026-11-24'::timestamptz),
(10409312, 104093, 'P32-C9-L3-O12', null, 12, 'ان يوضح الطالب المقصود بإنتاج الزوج .', 'أن يوضّح الطالب المقصود بإنتاج الزوج، ويحدد أقل طاقة لازمة لحدوثه.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بإنتاج الزوج، ويحدد أقل طاقة لازمة لحدوثه.', 'همزة «أن»، وتشكيل «يوضّح»، وحذف المسافة قبل النقطة، وإضافة شرط الطاقة الدنيا (1.02 MeV) الذي يركّز عليه الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["إنتاج الزوج","حفظ الشحنة","حجرة الفقاعة"]'::jsonb, null, '[274,277,281]'::jsonb, 'مغطى', 'ص274: «فإذا عبر شعاع جاما بطاقة 1.02 MeV على الأقل بالقرب من نواة فقد ينتج زوج من البوزترون والإلكترون… يسمى تحوّل الطاقة إلى زوج الجسيمات "مادة وضديد المادة" إنتاج الزوج» والشكل 9–17؛ ص277 سؤال 41؛ ص281.', null, 'approved', '2026-11-24'::timestamptz),
(10409313, 104093, 'P32-C9-L3-O13', null, 13, 'ان يفسر الطالب اضمحلال بيتا والتفاعل الضعيف', 'أن يفسّر الطالب اضمحلال بيتا بنموذج الكواركات، ودور القوة النووية الضعيفة فيه.', '[]'::jsonb, 'أن يفسّر الطالب اضمحلال بيتا بنموذج الكواركات، ودور القوة النووية الضعيفة فيه.', 'همزة «أن»، وتشكيل «يفسّر»، واستخدام مصطلح الكتاب «القوة النووية الضعيفة» (عنوان القسم «اضمحلال بيتا والتفاعل الضعيف»)، وإضافة نموذج الكواركات (d → u + W⁻).', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["اضمحلال بيتا","القوة النووية الضعيفة","البوزون W","ضديد النيوترينو"]'::jsonb, null, '[275,276,277]'::jsonb, 'مغطى', 'ص275 «اضمحلال بيتا والتفاعل الضعيف»: «¹₀n → ¹₁p + ⁰₋₁e + ⁰₀ν̄… إن وجود انحلال بيتا يشير إلى أنه يجب أن يكون هناك تفاعل آخر، وهو القوة النووية الضعيفة»؛ ص276 «نموذج الكوارك لاضمحلال بيتا» والشكل 9–18؛ ص277 سؤال 43.', null, 'approved', '2026-11-24'::timestamptz),
(10409314, 104093, 'P32-C9-L3-O14', null, 14, 'ان يوضح الطالب المقصود باختبار النموذج المعياري.', 'أن يوضّح الطالب كيف يُختبر النموذج المعياري (اكتشاف بوزون هيجز)، وحدوده في تفسير كتل الجسيمات ووجود ثلاث عائلات.', '[]'::jsonb, 'أن يوضّح الطالب كيف يُختبر النموذج المعياري (اكتشاف بوزون هيجز)، وحدوده في تفسير كتل الجسيمات ووجود ثلاث عائلات.', 'همزة «أن»، وتشكيل «يوضّح»، و«المقصود باختبار» صياغة غير واضحة، فحُدّد المضمون كما في قسم «اختبار النموذج المعياري».', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النموذج المعياري","بوزون هيجز","عائلات الجسيمات"]'::jsonb, null, '[276,277]'::jsonb, 'مغطى', 'ص276 «اختبار النموذج المعياري»: «إن بوزون هيجز الذي يفترض أنه جسيم يحدد كتل اللبتونات والكواركات، أعلن عن اكتشافه في… سيرن CERN عام 2012… فالنموذج المعياري ليس نظرية؛ لأنه لا يفسر كتل الجسيمات، ولا يفسر لماذا توجد ثلاث عائلات»؛ ص277 سؤال 42.', null, 'approved', '2026-11-24'::timestamptz),
(10409315, 104093, 'P32-C9-L3-O15', null, 15, 'ان يوضح الطالب القوى الأربعة في الكون', 'أن يوضّح الطالب القوى الأساسية الأربع في الكون (القوية، والضعيفة، والكهرومغناطيسية، والتجاذب)، وأوجه الاختلاف والتماثل بينها.', '[]'::jsonb, 'أن يوضّح الطالب القوى الأساسية الأربع في الكون (القوية، والضعيفة، والكهرومغناطيسية، والتجاذب)، وأوجه الاختلاف والتماثل بينها.', 'همزة «أن»، وتشكيل «يوضّح»، وتصحيح «القوى الأربعة» إلى «القوى الأربع» (المعدود «قوة» مؤنث)، وتسمية القوى كما في الكتاب.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["القوة النووية القوية","القوة النووية الضعيفة","القوة الكهرومغناطيسية","قوة التجاذب","القوة الكهربائية الضعيفة"]'::jsonb, null, '[273,276,277,282]'::jsonb, 'مغطى', 'ص276 «لماذا توجد أربع قوى؟»: «إن الاختلافات بين التفاعلات الرئيسة الأربعة واضحة… والقوى الكهربائية تؤثر في مدى واسع؛ لأن كتلة الفوتونات صفر، بينما القوى الضعيفة تؤثر في مسافات قصيرة»؛ ص277: «كانت القوى الكهرومغناطيسية والقوى الضعيفة متحدتين في قوة واحدة تسمى قوة كهربائية ضعيفة»؛ ص282 سؤال 56.', null, 'approved', '2026-11-24'::timestamptz),
(10409316, 104093, 'P32-C9-L3-O16', null, 16, 'أن يصف الطالب طريقة عمل عداد جايجر–مولر وحجرة الغيمة وحجرة الفقاعة في الكشف عن الجسيمات المشحونة، ويفسّر عدم ترك الجسيمات المتعادلة مسارات فيها.', 'أن يصف الطالب طريقة عمل عداد جايجر–مولر وحجرة الغيمة وحجرة الفقاعة في الكشف عن الجسيمات المشحونة، ويفسّر عدم ترك الجسيمات المتعادلة مسارات فيها.', '[]'::jsonb, 'أن يصف الطالب طريقة عمل عداد جايجر–مولر وحجرة الغيمة وحجرة الفقاعة في الكشف عن الجسيمات المشحونة، ويفسّر عدم ترك الجسيمات المتعادلة مسارات فيها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["عداد جايجر–مولر","حجرة الغيمة","حجرة الفقاعة","التأين"]'::jsonb, null, '[271,278,281,284,286]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص271 «عداد جايجر» و«مسارات التكاثف» (حجرة غيمة ولسون، وحجرة الفقاعة، وحجرات السلك) و«الجسيمات المتعادلة كهربائيًّا لا تغادر المسارات؛ لأنها لا تُحدث تفريغًا»؛ ص278 مختبر الفيزياء؛ ص281؛ ص284 سؤال 84؛ ص286 اختبار مقنن 9.', null, 'approved', '2026-11-24'::timestamptz),
(10409317, 104093, 'P32-C9-L3-O17', null, 17, 'أن يصنّف الطالب الهادرونات إلى باريونات وميزونات، ويحسب شحنة جسيم من تركيبه من الكواركات وضديداتها.', 'أن يصنّف الطالب الهادرونات إلى باريونات وميزونات، ويحسب شحنة جسيم من تركيبه من الكواركات وضديداتها.', '[]'::jsonb, 'أن يصنّف الطالب الهادرونات إلى باريونات وميزونات، ويحسب شحنة جسيم من تركيبه من الكواركات وضديداتها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["الهادرونات","الباريونات","الميزونات","ضديد الكوارك"]'::jsonb, null, '[272,273,274,284]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص273: «تتحد الكواركات لتشكل الهادرونات التي تنقسم إلى مجموعتين فرعيتين، هما مجموعة الباريونات مثل: البروتونات والنيوترونات، ومجموعة الميزونات مثل البيونات المكونة من كوارك وضديده»؛ ص274 شحنة ضديد البروتون ūūd̄؛ ص284 أسئلة 79–82.', null, 'approved', '2026-11-24'::timestamptz),
(10409318, 104093, 'P32-C9-L3-O18', null, 18, 'أن يصمم الطالب تجربة لاستكشاف العلاقة بين البعد عن مصدر إشعاع بيتا وجاما وشدة الإشعاع المقيس باستخدام عداد جايجر، ويمثّل النتائج بيانيًّا.', 'أن يصمم الطالب تجربة لاستكشاف العلاقة بين البعد عن مصدر إشعاع بيتا وجاما وشدة الإشعاع المقيس باستخدام عداد جايجر، ويمثّل النتائج بيانيًّا.', '[]'::jsonb, 'أن يصمم الطالب تجربة لاستكشاف العلاقة بين البعد عن مصدر إشعاع بيتا وجاما وشدة الإشعاع المقيس باستخدام عداد جايجر، ويمثّل النتائج بيانيًّا.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["عداد جايجر","الإشعاع الخلفي","شدة الإشعاع","1/d²"]'::jsonb, null, '[278,279]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص278–279 مختبر الفيزياء «صمّم تجربتك: استكشاف الإشعاع»: «ما العلاقة بين المسافة من مصدر إشعاع جاما وبيتا وشدة الإشعاع؟» مع طرح الإشعاع الخلفي وتمثيل معدل الإشعاع المصحح مقابل 1/d².', null, 'approved', '2026-11-24'::timestamptz)
