select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد مراجعة الأهداف الرسمية', 'مالك المشروع', '2026-11-24'::timestamptz
from public.objectives o where o.code like 'P32-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = false
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد الأهداف المضافة من الكتاب المدرسي', 'مالك المشروع', '2026-11-24'::timestamptz
from public.objectives o where o.code like 'P32-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = true
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يوصف المغناطيس بأنه «مستقطب». ما المقصود بذلك؟', null, null, '["يحمل شحنة كهربائية موجبة عند أحد طرفيه وشحنة سالبة عند الآخر","له قطبان متميزان متعاكسان؛ أحدهما شمالي والآخر جنوبي","يجذب جميع الفلزات القريبة منه مهما كان نوعها","له قطب واحد يمكن فصله عن بقية أجزاء المغناطيس"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 72 — الخصائص العامة للمغانط (المستقطب)'),
('mcq', 2, 'عُلّق مغناطيس بخيط تعليقًا حرًّا، ثم قُرّب منه مغناطيس آخر كما في الشكل الآتي. ماذا يحدث للمغناطيس المعلّق؟', null, '[{"src":"qimg/phys32/c3l1-o01-hang.svg","alt":"مغناطيس معلّق أفقيًا بخيط: طرفه الأيسر قطب جنوبي S (أزرق) وطرفه الأيمن قطب شمالي N (أحمر). وعلى يمينه مغناطيس آخر طرفه الأيسر قطب شمالي N وطرفه الأيمن قطب جنوبي S، وتحته سهم نحو اليسار مكتوب عنده «يُقرَّب»؛ أي أن القطب الشمالي للمغناطيس الثاني يُقرَّب من القطب الشمالي للمغناطيس المعلّق."}]'::jsonb, '["يبتعد عن المغناطيس المقرَّب؛ لأن القطبين المتقابلين متشابهان","ينجذب نحو المغناطيس المقرَّب؛ لأن القطبين المتقابلين مختلفان","يبقى ساكنًا؛ لأن القوى المغناطيسية لا تؤثر إلا عند تلامس القطبين","ينجذب نحو المغناطيس المقرَّب؛ لأن القطبين المتقابلين متشابهان"]'::jsonb, 'فهم', 'تفسير ظاهرة من شكل', 'سهل', 'الكتاب ص 72 — الخصائص العامة للمغانط (الشكل 2b-3)'),
('mcq', 3, 'يبين الشكل الآتي خمسة مغانط على شكل أقراص مثقوبة مرقّمة من 1 إلى 5، تطفو بعضها فوق بعض حول ساق رأسية دون أن يتلامس أي قرصين، والقطب الشمالي للقرص العلوي 1 متجه إلى أعلى. ما نوع القطب المتجه إلى أعلى في القرص 2 ثم في القرص 3؟', null, '[{"src":"qimg/phys32/c3l1-o01-rings.svg","alt":"ساق رأسية تمر عبر خمسة أقراص مغناطيسية أفقية مرقّمة من الأعلى إلى الأسفل 1، 2، 3، 4، 5، بينها فراغات متساوية فلا يتلامس أي قرصين. وفوق الوجه العلوي للقرص 1 الحرف N، مع عبارة «الوجه العلوي للقرص 1»."}]'::jsonb, '["الشمالي في القرص 2، والشمالي في القرص 3","الشمالي في القرص 2، والجنوبي في القرص 3","الجنوبي في القرص 2، والشمالي في القرص 3","الجنوبي في القرص 2، والجنوبي في القرص 3"]'::jsonb, 'تطبيق', 'تطبيق قاعدة التنافر', 'متوسط', 'الكتاب ص 75 — مسائل تدريبية (المسألة 2)'),
('mcq', 4, 'قُرّب الطرف X لقضيب مغناطيسي من القطب الشمالي لمغناطيس آخر فتنافرا. ما نوع القطب X، وإلى أيّ اتجاه يشير لو عُلّق القضيب بخيط من منتصفه تعليقًا حرًّا أفقيًا؟', null, null, '["جنوبي، ويشير نحو الشمال الجغرافي للأرض","شمالي، ويشير نحو الجنوب الجغرافي للأرض","جنوبي، ويشير نحو الجنوب الجغرافي للأرض","شمالي، ويشير نحو الشمال الجغرافي للأرض"]'::jsonb, 'فهم', 'تفسير مصطلح', 'متوسط', 'الكتاب ص 72 — الخصائص العامة للمغانط (الشكل 2-3)'),
('mcq', 5, 'ثلاثة قضبان مغناطيسية. لوحظ أن الطرف P للمغناطيس الأول يتنافر مع الطرف Q للمغناطيس الثاني، وأن الطرف Q يتجاذب مع الطرف R للمغناطيس الثالث، وأن R قطب شمالي. ما نوع القطب P؟', null, null, '["شمالي؛ لأن Q شمالي والأقطاب المتشابهة تتنافر","جنوبي؛ لأن Q جنوبي والأقطاب المتشابهة تتنافر","شمالي؛ لأن Q جنوبي والأقطاب المختلفة تتنافر","جنوبي؛ لأن Q شمالي والأقطاب المختلفة تتنافر"]'::jsonb, 'تحليل', 'استدلال متسلسل', 'صعب', 'الكتاب ص 72 وص 96 — قاعدة التنافر والتجاذب (السؤال 32)'),
('mcq', 6, 'أيّ الأجسام الآتية ينجذب إلى المغناطيس؟', null, null, '["ساق من الألومنيوم","قطعة نقدية من النحاس","مسمار من الحديد","ساق من الزجاج"]'::jsonb, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 73 — كيف تؤثر المغانط في المواد الأخرى'),
('mcq', 7, 'قرّب طالب القطب الشمالي لمغناطيس من أحد طرفي ساق فلزية فانجذب الطرف إليه، ثم قرّب القطب الجنوبي من الطرف نفسه فانجذب أيضًا. ما الاستنتاج الصحيح؟', null, null, '["الساق مغناطيس دائم، وطرفها المختبَر قطب شمالي","الساق مغناطيس دائم، وطرفها المختبَر قطب جنوبي","الساق مغناطيس دائم، في طرفها المختبَر قطبان معًا","الساق غير ممغنطة، ومادتها مما يجذبه المغناطيس كالحديد"]'::jsonb, 'تحليل', 'استنتاج من ملاحظة', 'صعب', 'الكتاب ص 73 — كيف تؤثر المغانط في المواد الأخرى'),
('essay', 1, '(a) اكتب قاعدة التنافر والتجاذب المغناطيسي. (b) وضّح لماذا يوصف المغناطيس بأنه مستقطب. (c) اذكر جسمين ينجذبان إلى المغناطيس وجسمًا لا ينجذب إليه.', null, null, null, 'فهم', 'وصف خصائص', 'متوسط', 'الكتاب ص 72–73 وص 96 (السؤال 32)'),
('essay', 2, 'يبين الشكل الآتي مغناطيسين أطرافهما مرقّمة 1 و2 و3 و4، والطرف 1 قطب شمالي. عند تقريب الطرف 2 من الطرف 3 تنافرا. (a) حدّد نوع القطب في كل من الأطراف 2 و3 و4. (b) ماذا يحدث عند تقريب الطرف 1 من الطرف 4؟ (c) ماذا يحدث عند تقريب الطرف 1 من الطرف 3؟ فسّر كل إجابة.', null, '[{"src":"qimg/phys32/c3l1-o01-e-pair.svg","alt":"مغناطيسان أفقيان متجاوران. المغناطيس الأول على اليسار: طرفه الأيسر مرقّم 1 ومكتوب عليه N (أحمر)، وطرفه الأيمن مرقّم 2 بلون رمادي بلا حرف. المغناطيس الثاني على اليمين رمادي كله: طرفه الأيسر مرقّم 3 وطرفه الأيمن مرقّم 4، بلا حروف. الطرف 2 يقابل الطرف 3."}]'::jsonb, null, 'تطبيق', 'تحديد أقطاب', 'متوسط', 'الكتاب ص 72 وص 75 — مسائل تدريبية (المسألة 1)'),
('essay', 3, 'لديك قضيب مغناطيسي مُحيت الحروف عن طرفيه، وقضيب مغناطيسي آخر معلوم القطبين، وخيط. (a) صف طريقتين مختلفتين لتحديد القطب الشمالي للقضيب المجهول. (b) وضّح لماذا يُعدّ تنافر طرف القضيب المجهول مع أحد قطبي القضيب المعلوم دليلًا حاسمًا على نوع ذلك الطرف، في حين لا يُعدّ التجاذب دليلًا حاسمًا.', null, null, null, 'تحليل', 'تصميم طريقة وتعليل', 'صعب', 'الكتاب ص 72–73 — الخصائص العامة للمغانط')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C3-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'المغناطيس المستقطب له قطبان متميزان متعاكسان: القطب الشمالي (الباحث عن الشمال الجغرافي) والقطب الجنوبي (الباحث عن الجنوب الجغرافي).', '["الاستقطاب المغناطيسي يعني وجود قطبين مغناطيسيين، لا شحنتين كهربائيتين؛ فهذا خلط بين المغناطيسية والكهرباء الساكنة.","","المغناطيس لا يجذب كل الفلزات؛ فهو يجذب الحديد ونحوه ولا يجذب النحاس أو الألومنيوم، وهذا ليس معنى الاستقطاب.","لا يوجد قطب مغناطيسي مفرد؛ فلكل مغناطيس قطبان دائمًا ولا يمكن فصل أحدهما عن الآخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-28T06:03:18.305Z"}'::jsonb),
('mcq', 2, 0, 'القطب المقابل في المغناطيس المعلّق شمالي، والقطب المقرَّب منه شمالي أيضًا، والأقطاب المتشابهة تتنافر؛ لذا يبتعد المغناطيس المعلّق.', '["","القطبان المتقابلان كلاهما شمالي (متشابهان) لا مختلفان؛ فالقوة تنافر.","القوى المغناطيسية تؤثر عن بعد، وتحدث قبل تلامس المغناطيسين.","الأقطاب المتشابهة تتنافر ولا تتجاذب؛ فهذا عكس قاعدة التجاذب والتنافر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.305Z"}'::jsonb),
('mcq', 3, 2, 'الأقراص تطفو، أي أن كل وجهين متقابلين يتنافران فهما قطبان متشابهان. القرص 1 وجهه العلوي شمالي فوجهه السفلي جنوبي؛ لذا يكون الوجه العلوي للقرص 2 جنوبيًا ووجهه السفلي شماليًا، فيكون الوجه العلوي للقرص 3 شماليًا. أي أن الأقطاب العلوية تتناوب.', '["لو كانت الأقراص كلها بالاتجاه نفسه لتقابل في كل مرة قطب جنوبي مع قطب شمالي فتجاذبت الأقراص والتصقت ولم تطفُ.","هذا عكس الترتيب الصحيح؛ فالوجه السفلي للقرص 1 جنوبي، فيجب أن يقابله وجه جنوبي في القرص 2 حتى يتنافرا.","","إذا كان الوجه العلوي للقرصين 2 و3 جنوبيًا فإن الوجه السفلي للقرص 2 (شمالي) يقابل الوجه العلوي للقرص 3 (جنوبي) فيتجاذبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-28T06:03:18.306Z"}'::jsonb),
('mcq', 4, 3, 'تنافر X مع قطب شمالي يعني أنه قطب شمالي؛ لأن الأقطاب المتشابهة تتنافر. والقطب الشمالي هو الطرف الباحث عن الشمال الجغرافي للأرض؛ فعند تعليق القضيب تعليقًا حرًّا يستقر في اتجاه شمال–جنوب ويشير X نحو الشمال الجغرافي.', '["التنافر يحدث بين قطبين متشابهين، فـ X شمالي لا جنوبي؛ والقطب الجنوبي يشير نحو الجنوب الجغرافي لا الشمالي.","X شمالي فعلًا، لكن القطب الشمالي هو الطرف الباحث عن الشمال الجغرافي لا الجنوب.","التنافر مع قطب شمالي يعني أن X شمالي لا جنوبي، والقطب الشمالي يشير نحو الشمال الجغرافي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.306Z"}'::jsonb),
('mcq', 5, 1, 'Q يتجاذب مع R الشمالي، والأقطاب المختلفة تتجاذب، فـ Q قطب جنوبي. وP يتنافر مع Q، والأقطاب المتشابهة تتنافر، فـ P قطب جنوبي.', '["Q لا يمكن أن يكون شماليًا لأنه يتجاذب مع R الشمالي، والقطبان الشماليان يتنافران.","","الأقطاب المختلفة تتجاذب ولا تتنافر؛ فهذا عكس القاعدة.","Q جنوبي لا شمالي، والأقطاب المختلفة تتجاذب لا تتنافر؛ ففي البديل خطآن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.307Z"}'::jsonb),
('mcq', 6, 2, 'المغانط تجذب أجسامًا فلزية مثل المسامير والدبابيس ومشابك الورق المصنوعة من الحديد، أما الألومنيوم والنحاس والزجاج فلا تنجذب إليه.', '["ليس كل فلز ينجذب إلى المغناطيس؛ فالألومنيوم لا ينجذب إليه، ولذلك لا يصلح قلبًا لمغناطيس كهربائي.","النحاس فلز لكنه لا ينجذب إلى المغناطيس؛ فالانجذاب ليس صفة لكل الفلزات.","","الزجاج مادة لا تتأثر بالمغناطيس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.307Z"}'::jsonb),
('mcq', 7, 3, 'أي طرف من المغناطيس يجذب أي طرف لقطعة حديد غير ممغنطة؛ لأن المغناطيس يحفّزها لتصبح مستقطبة. فلو كانت الساق مغناطيسًا لتنافر طرفها مع أحد القطبين. لذا فالساق غير ممغنطة.', '["لو كان الطرف قطبًا شماليًا لتنافر مع القطب الشمالي للمغناطيس لا أن ينجذب إليه.","لو كان الطرف قطبًا جنوبيًا لتنافر مع القطب الجنوبي للمغناطيس.","لا يجتمع قطبان في طرف واحد؛ فلكل مغناطيس قطبان متميزان في طرفين متعاكسين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.307Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) الأقطاب المغناطيسية المتشابهة تتنافر، والأقطاب المغناطيسية المختلفة تتجاذب. (b) لأن للمغناطيس قطبين متميزين متعاكسين: قطبًا شماليًا يبحث عن الشمال الجغرافي للأرض، وقطبًا جنوبيًا يبحث عن الجنوب الجغرافي، ولجميع المغانط قطبان مختلفان. (c) ينجذب إليه مثلًا: مسمار حديدي، ومشبك ورق (أو دبوس)، ولا ينجذب إليه مثلًا: قطعة نحاس أو ألومنيوم أو زجاج.', '["الأقطاب المتشابهة تتنافر","الأقطاب المختلفة تتجاذب","للمغناطيس قطبان متميزان متعاكسان (شمالي وجنوبي)","مثالان صحيحان لأجسام تنجذب ومثال لجسم لا ينجذب"]'::jsonb, '[]'::jsonb, '[{"element":"قاعدة التنافر","marks":1},{"element":"قاعدة التجاذب","marks":1},{"element":"معنى الاستقطاب","marks":1},{"element":"الأمثلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"القاعدة كاملة ومعنى الاستقطاب والأمثلة صحيحة"},{"level":"2–3 درجات","description":"القاعدة صحيحة مع نقص في معنى الاستقطاب أو الأمثلة"},{"level":"1 درجة","description":"شطر واحد صحيح من القاعدة أو مثال صحيح فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["عكس القاعدة (المتشابهة تتجاذب)","تفسير الاستقطاب بوجود شحنتين كهربائيتين","عدّ كل الفلزات مما ينجذب إلى المغناطيس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-28T06:03:18.308Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الطرف 2 قطب جنوبي؛ لأن للمغناطيس قطبين متعاكسين والطرف 1 شمالي. والطرف 3 قطب جنوبي؛ لأنه تنافر مع الطرف 2 الجنوبي والأقطاب المتشابهة تتنافر. والطرف 4 قطب شمالي؛ لأنه الطرف المقابل للطرف 3 في المغناطيس الثاني. (b) يتنافران؛ لأن الطرفين 1 و4 كليهما شمالي. (c) يتجاذبان؛ لأن الطرف 1 شمالي والطرف 3 جنوبي، والأقطاب المختلفة تتجاذب.', '["الطرف 2 جنوبي","الطرف 3 جنوبي بسبب التنافر مع 2","الطرف 4 شمالي","1 و4 يتنافران","1 و3 يتجاذبان"]'::jsonb, '[]'::jsonb, '[{"element":"نوع الطرف 2","marks":1},{"element":"نوع الطرف 3 مع التعليل","marks":1},{"element":"نوع الطرف 4","marks":1},{"element":"الحالة (b)","marks":1},{"element":"الحالة (c)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الأقطاب الثلاثة والحالتان صحيحة مع التعليل"},{"level":"3–4 درجات","description":"الأقطاب صحيحة مع خطأ في إحدى الحالتين أو نقص في التعليل"},{"level":"1–2 درجة","description":"تحديد صحيح لقطب أو قطبين فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["عدّ الطرف 3 شماليًا لظنّ أن التنافر يحدث بين الأقطاب المختلفة","نسيان أن طرفي المغناطيس الواحد متعاكسان","الحكم على الحالتين دون الرجوع إلى نوع القطبين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.308Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) الطريقة الأولى: نعلّق القضيب المجهول بخيط من منتصفه تعليقًا حرًّا أفقيًا، فيستقر في اتجاه شمال–جنوب، والطرف الذي يشير إلى الشمال الجغرافي هو القطب الشمالي. الطريقة الثانية: نقرّب القطب الشمالي للقضيب المعلوم من أحد طرفي القضيب المجهول؛ فإذا تنافرا كان هذا الطرف شماليًا، وإذا تجاذبا نجرّب الطرف الآخر حتى نحصل على تنافر. (b) التنافر لا يحدث إلا بين قطبين متشابهين، فهو يحدد نوع الطرف بيقين. أما التجاذب فيحدث بين قطبين مختلفين، ويحدث أيضًا بين أي قطب وقطعة حديد غير ممغنطة؛ فلا يكفي وحده لمعرفة نوع القطب.', '["طريقة التعليق الحر وتحديد الطرف المتجه للشمال الجغرافي","طريقة التقريب من قطب معلوم وملاحظة التنافر","التنافر يحدث فقط بين قطبين متشابهين","التجاذب يحدث بين قطبين مختلفين أو بين قطب وجسم حديدي غير ممغنط"]'::jsonb, '[]'::jsonb, '[{"element":"الطريقة الأولى","marks":1},{"element":"الطريقة الثانية","marks":1},{"element":"تعليل حسم التنافر","marks":1},{"element":"تعليل عدم حسم التجاذب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"طريقتان صحيحتان وتعليل كامل للتنافر والتجاذب"},{"level":"2–3 درجات","description":"طريقتان صحيحتان مع تعليل ناقص، أو طريقة واحدة مع تعليل كامل"},{"level":"1 درجة","description":"طريقة واحدة صحيحة دون تعليل"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الاعتماد على التجاذب وحده لتحديد القطب","تعليق القضيب من أحد طرفيه بدل منتصفه","الخلط بين الطرف المتجه للشمال وتسميته قطبًا جنوبيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.309Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
