from (values
('mcq', 1, 'أيّ المواد الآتية يصبح مغناطيسًا مؤقتًا عند ملامسة مغناطيس، ثم يفقد كل جاذبيته للأجسام الفلزية الأخرى مباشرة عند إبعاد المغناطيس؟', null, null, '["سبيكة من الحديد والألومنيوم والنيكل والكوبالت","الحديد المطاوع القليل الكربون","سبيكة من العناصر الترابية النادرة كالنيوديميوم","قضيب من النحاس الخالص"]'::jsonb, 'تذكر', 'تمييز', 'سهل', 'الكتاب ص 73 — كيف تؤثر المغانط في المواد الأخرى'),
('mcq', 2, 'يلامس القطب الشمالي لمغناطيس دائم رأسَ مسمار حديدي كما في الشكل الآتي. ما نوع القطب المغناطيسي الذي يتكوّن عند الطرف المدبب A للمسمار؟', null, '[{"src":"qimg/phys32/c3l1-o02-nail.svg","alt":"قضيب مغناطيسي أفقي طرفه الأيسر S (أزرق) وطرفه الأيمن N (أحمر) ومكتوب فوقه «مغناطيس دائم». يتدلى من أسفل الطرف الأيمن N مسمار حديدي رأسي، رأسه العريض يلامس القطب الشمالي، وطرفه المدبب في الأسفل مكتوب عنده الحرف A."}]'::jsonb, '["جنوبي؛ لأن رأس المسمار الملامس للقطب الشمالي يصبح شماليًا","جنوبي؛ لأن الطرف المدبب للمسمار يكون قطبًا جنوبيًا دائمًا","لا قطبية له؛ لأن المسمار لا يتمغنط إلا إذا مرّ فيه تيار","شمالي؛ لأن رأس المسمار الملامس للقطب الشمالي يصبح جنوبيًا"]'::jsonb, 'فهم', 'تحديد قطبية بالحث', 'متوسط', 'الكتاب ص 73 — كيف تؤثر المغانط في المواد الأخرى وص 75 (المسألة 3)'),
('mcq', 3, 'لامس مسمار حديدي قطب مغناطيس، ثم لامس الطرفُ الآخر للمسمار قطعًا حديدية صغيرة فانجذبت إليه. ما سبب انجذاب القطع الحديدية إلى المسمار؟', null, null, '["أصبح المسمار مغناطيسًا بالحث، فحفّز القطع الحديدية لتصبح مستقطبة","انتقلت مغناطيسية المغناطيس كلها إلى المسمار ففقد المغناطيس قطبيه","اكتسب المسمار شحنة كهربائية من المغناطيس فجذب القطع الحديدية","القطع تنجذب إلى المغناطيس نفسه، أما المسمار فلا يتأثر بالمغناطيس"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'سهل', 'الكتاب ص 73 — كيف تؤثر المغانط في المواد الأخرى (الشكل 3-3)'),
('mcq', 4, 'ما المقصود بأن قطعة الحديد «تمغنطت بالحث»؟', null, null, '["اكتسبت شحنة كهربائية عند دلكها بقطعة صوف فأصبحت تجذب القصاصات","أصبحت مستقطبة (مغناطيسًا) بتأثير المجال المغناطيسي لمغناطيس قريب منها","انتقل إليها أحد قطبي المغناطيس فأصبح المغناطيس بقطب واحد","أصبحت مغناطيسًا دائمًا بعد تسخينها إلى درجة حرارة مرتفعة"]'::jsonb, 'فهم', 'تفسير مصطلح', 'متوسط', 'الكتاب ص 73–75 — المغنطة بالحث'),
('mcq', 5, 'أيّ الطرق الآتية تعطي مغناطيسًا مؤقتًا يمكن تشغيله وإيقافه بسهولة؟', null, null, '["دلك ساق زجاجية بقطعة من الحرير","وضع قضيب من النحاس بجوار مغناطيس قوي","لفّ سلك معزول حول قضيب من الحديد المطاوع وتمرير تيار فيه","تسخين قضيب حديدي ثم تبريده بعيدًا عن أي مغناطيس"]'::jsonb, 'تطبيق', 'اختيار طريقة', 'سهل', 'الكتاب ص 71 وص 77 — المغناطيس الكهربائي والقلب الحديدي'),
('mcq', 6, 'قطعة حديد غير ممغنطة تنجذب إلى المغناطيس سواء قُرّب منها قطبه الشمالي أم قطبه الجنوبي. ما التفسير الصحيح لذلك؟', null, null, '["يتكوّن في طرف القطعة القريب من المغناطيس قطب مخالف للقطب المقرَّب أيًّا كان نوعه","يتكوّن في طرف القطعة القريب من المغناطيس قطب مشابه للقطب المقرَّب أيًّا كان نوعه","قطعة الحديد مغناطيس دائم قطباه ضعيفان فلا يظهر التنافر","يحمل الحديد شحنة كهربائية فيجذبه أي قطب للمغناطيس"]'::jsonb, 'تحليل', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 73 وص 75 — القوى المؤثرة في الأجسام الموضوعة في مجالات مغناطيسية'),
('mcq', 7, 'عند رش برادة الحديد حول مغناطيس، تدور قطع البرادة حتى تصبح موازية للمجال المغناطيسي مثل إبرة البوصلة. ما سبب ذلك؟', null, null, '["تحمل قطع البرادة شحنات كهربائية فيجذبها المغناطيس","تحتوي قطع البرادة على أقطاب مفردة تنجذب إلى القطبين","تصبح كل قطعة من البرادة مغناطيسًا صغيرًا بالحث","تتأثر قطع البرادة بالجاذبية الأرضية أكثر من تأثرها بالمغناطيس"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 74 — تمثيل المجال ببرادة الحديد'),
('essay', 1, 'وضّح كيف تجعل مسمارًا حديديًا مغناطيسًا مؤقتًا باستخدام مغناطيس دائم، ثم: (a) كيف تتحقق من أن المسمار أصبح مغناطيسًا؟ (b) ماذا يحدث لمغناطيسية المسمار عند إبعاد المغناطيس؟ (c) ما الفرق في السلوك لو استُعملت قطعة من الحديد المطاوع بدل المسمار؟', null, null, null, 'فهم', 'شرح طريقة', 'متوسط', 'الكتاب ص 73 — كيف تؤثر المغانط في المواد الأخرى والشكل 3-3'),
('essay', 2, 'يلامس القطب الجنوبي لمغناطيس رأسي رأسَ مسمار من الحديد المطاوع عند P، ويتدلى من الطرف المدبب Q للمسمار دبوس حديدي صغير طرفه السفلي R، كما في الشكل الآتي. (a) حدّد نوع القطب المتكوّن عند كل من P وQ. (b) حدّد نوع القطب عند الطرف العلوي للدبوس وعند R. (c) ماذا يحدث للدبوس عند إبعاد المغناطيس عن المسمار؟ ولماذا؟', null, '[{"src":"qimg/phys32/c3l1-o02-chain.svg","alt":"قضيب مغناطيسي رأسي: نصفه العلوي قطب شمالي N (أحمر) ونصفه السفلي قطب جنوبي S (أزرق). يلامس أسفلَ القطب الجنوبي رأسُ مسمار رأسي، ونقطة التلامس عند رأس المسمار مكتوب عندها P. والطرف المدبب السفلي للمسمار مكتوب عنده Q. ويتدلى من Q دبوس صغير رأسي، طرفه السفلي مكتوب عنده R. وبجانب المسمار كلمة «مسمار» وبجانب الدبوس كلمة «دبوس»."}]'::jsonb, null, 'تطبيق', 'تحديد أقطاب بالحث', 'صعب', 'الكتاب ص 73 — كيف تؤثر المغانط في المواد الأخرى وص 75 (المسألة 3)'),
('essay', 3, 'ربط طالب مسمارًا من منتصفه بخيط، ثم أدخله في ملف متصل بمصدر جهد وشغّل المصدر، ثم فصل المصدر وأخرج المسمار وعلّقه بالخيط تعليقًا حرًّا أفقيًا. (a) توقّع سلوك المسمار المعلّق. (b) اذكر دليلين يمكن أن يستعملهما الطالب للتأكد من أن المسمار أصبح ممغنطًا. (c) فسّر كيف تمغنط المسمار مع أنه لم يلامس أي مغناطيس، ولماذا تكون هذه المغنطة مؤقتة.', null, null, null, 'تحليل', 'تفسير تجربة', 'صعب', 'الكتاب ص 78 — تجربة المجالات المغناطيسية الثلاثية الأبعاد')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
