from (values
('mcq', 1, 1, 'الحديد المطاوع (حديد يحتوي على القليل من الكربون) مغناطيس مؤقت؛ فهو يتمغنط بوجود المغناطيس ويفقد كل جاذبيته للأجسام الأخرى مباشرة عند إبعاده.', '["سبيكة الحديد مع الألومنيوم والنيكل والكوبالت تُصنع منها المغانط الدائمة لا المؤقتة.","","العناصر الترابية النادرة كالنيوديميوم تنتج مغانط دائمة قوية جدًّا مقارنة بأحجامها.","النحاس لا ينجذب إلى المغناطيس ولا يتمغنط أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.309Z"}'::jsonb),
('mcq', 2, 3, 'يحفّز المغناطيس المسمار ليصبح مستقطبًا: يتكوّن عند الرأس الملامس للقطب الشمالي قطب جنوبي (فينجذب المسمار)، فيكون الطرف الآخر A قطبًا شماليًا. أي أن قطبية المسمار تعتمد على قطبية المغناطيس.', '["الطرف الملامس يكتسب قطبًا مخالفًا لقطب المغناطيس لا مشابهًا له؛ ولو كان مشابهًا لتنافرا ولما انجذب المسمار.","قطبية طرفي المسمار تعتمد على قطبية المغناطيس الملامس، لا على شكل الطرف.","المسمار يتمغنط بالحث عند وضعه في المجال المغناطيسي لمغناطيس دائم دون حاجة إلى تيار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-28T06:03:18.311Z"}'::jsonb),
('mcq', 3, 0, 'المغناطيس يحفّز المسمار الملامس له ليصبح مستقطبًا، فيصبح المسمار نفسه مغناطيسًا بالحث، وهو بدوره يحفّز القطع الحديدية الصغيرة لتصبح مستقطبة فتنجذب إليه.', '["","المغناطيس لا يفقد قطبيه عند مغنطة المسمار؛ فهو يحفّز المسمار ليصبح مستقطبًا ويبقى هو مغناطيسًا.","التأثير هنا مغناطيسي لا كهربائي؛ فالمسمار تمغنط بالحث ولم يُشحن.","المسمار نفسه يصبح مغناطيسًا عند ملامسة المغناطيس، ولذلك يجذب القطع الحديدية عند طرفه الآخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-28T06:03:18.311Z"}'::jsonb),
('mcq', 4, 1, 'التمغنط بالحث هو أن يحفّز المغناطيس قطعة الحديد الموضوعة في مجاله لتصبح مستقطبة (لها قطبان)، كما تصبح كل قطعة من برادة الحديد مغناطيسًا بالحث.', '["هذا وصف للشحن الكهربائي بالدلك (الكهرباء الساكنة)، لا للمغنطة.","","المغناطيس لا يفقد أحد قطبيه ولا ينقله؛ فلا يوجد مغناطيس بقطب واحد.","التسخين يُضعف المغناطيس ولا يمغنط الحديد، والمغنطة بالحث تحتاج إلى مجال مغناطيسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-28T06:03:18.311Z"}'::jsonb),
('mcq', 5, 2, 'المجال المغناطيسي للملف الذي يسري فيه تيار يولّد مغناطيسية مؤقتة في قلب الحديد المطاوع، فيعمل مغناطيسًا عند سريان التيار ويفقد مغناطيسيته عند قطعه.', '["دلك الزجاج يشحنه كهربائيًا ولا يكوّن مغناطيسًا.","النحاس لا يتمغنط بوجود مغناطيس.","","التسخين والتبريد بعيدًا عن أي مجال مغناطيسي لا يمغنط الحديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.311Z"}'::jsonb),
('mcq', 6, 0, 'عند وضع قطعة الحديد في مجال المغناطيس تتمغنط بالحث؛ فيصبح طرفها القريب من القطب الشمالي قطبًا جنوبيًا، وطرفها القريب من القطب الجنوبي قطبًا شماليًا. فيكون الطرفان المتقابلان مختلفين دائمًا، والأقطاب المختلفة تتجاذب.', '["","لو تكوّن قطب مشابه للقطب المقرَّب لتنافرا ولما انجذبت القطعة.","لو كانت القطعة مغناطيسًا دائمًا لتنافر أحد طرفيها مع أحد القطبين مهما كان ضعيفًا.","الحديد غير مشحون، والتجاذب هنا مغناطيسي ناتج عن المغنطة بالحث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-28T06:03:18.312Z"}'::jsonb),
('mcq', 7, 2, 'كل قطعة صغيرة من برادة الحديد تصبح مغناطيسًا بالحث عند وضعها في مجال المغناطيس، فتدور كإبرة البوصلة حتى توازي المجال.', '["برادة الحديد غير مشحونة كهربائيًا، وتأثرها بالمغناطيس مغناطيسي لا كهربائي.","لا توجد أقطاب مغناطيسية مفردة؛ فكل قطعة ممغنطة لها قطبان.","","الجاذبية الأرضية لا تجعل البرادة موازية لخطوط المجال؛ فالترتيب ناتج عن تمغنطها بالحث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-28T06:03:18.312Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نلمس المسمار بأحد قطبي المغناطيس الدائم (أو نضعه قريبًا منه) فيحفّزه المغناطيس ليصبح مستقطبًا، فيصبح المسمار نفسه مغناطيسًا بالحث. (a) نقرّب من المسمار قطعًا حديدية صغيرة أو مشابك ورق فيجذبها وهو ما زال ملامسًا للمغناطيس. (b) عند إبعاد المغناطيس يفقد المسمار بعضًا من مغناطيسيته، فتسقط بعض الأجسام، ولا يطول جذبه للأجسام الفلزية الأخرى. (c) الحديد المطاوع يفقد كل جاذبيته للأجسام الأخرى مباشرة عند إبعاد المغناطيس؛ لأنه مغناطيس مؤقت، أما المسمار فيحتوي على معادن أخرى تتيح له الاحتفاظ ببعض مغناطيسيته مدة قصيرة.', '["ملامسة المسمار لقطب المغناطيس فيتمغنط بالحث","التحقق بجذب قطع حديدية صغيرة","يفقد المسمار بعض مغناطيسيته عند إبعاد المغناطيس","الحديد المطاوع يفقد كل جاذبيته مباشرة"]'::jsonb, '[]'::jsonb, '[{"element":"طريقة المغنطة","marks":1},{"element":"طريقة التحقق","marks":1},{"element":"ما يحدث عند الإبعاد","marks":1},{"element":"سلوك الحديد المطاوع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الطريقة والتحقق وما يحدث بعد الإبعاد والمقارنة كلها صحيحة"},{"level":"2–3 درجات","description":"عنصران أو ثلاثة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن المسمار يبقى مغناطيسًا بالقوة نفسها بعد إبعاد المغناطيس","الاعتقاد بأن المغنطة تحتاج إلى تيار كهربائي دائمًا","عدّ الحديد المطاوع مغناطيسًا دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.312Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) يتكوّن عند P قطب شمالي؛ لأنه يلامس القطب الجنوبي للمغناطيس، والأقطاب المختلفة تتجاذب. ويتكوّن عند Q قطب جنوبي؛ لأن المسمار أصبح مستقطبًا وطرفاه متعاكسان. (b) الطرف العلوي للدبوس الملامس لـ Q (جنوبي) يصبح قطبًا شماليًا، وR يصبح قطبًا جنوبيًا؛ فالدبوس يتمغنط بالحث أيضًا. (c) يسقط الدبوس مباشرة؛ لأن الحديد المطاوع مغناطيس مؤقت يفقد مغناطيسيته وجاذبيته للأجسام الأخرى فور إبعاد المغناطيس.', '["P شمالي","Q جنوبي","الطرف العلوي للدبوس شمالي وR جنوبي","يسقط الدبوس لأن الحديد المطاوع يفقد مغناطيسيته فورًا"]'::jsonb, '[]'::jsonb, '[{"element":"القطب عند P","marks":1},{"element":"القطب عند Q","marks":1},{"element":"قطبا الدبوس","marks":1},{"element":"ما يحدث عند الإبعاد مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأقطاب كلها صحيحة مع تعليل سقوط الدبوس"},{"level":"2–3 درجات","description":"أقطاب المسمار صحيحة مع خطأ في الدبوس أو في التعليل"},{"level":"1 درجة","description":"قطب واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جعل P جنوبيًا كقطب المغناطيس الملامس له","نسيان أن الدبوس يتمغنط بالحث أيضًا","القول إن الدبوس يبقى معلقًا لأن المسمار يحتفظ بمغناطيسيته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-28T06:03:18.312Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) يستقر المسمار المعلّق في اتجاه شمال–جنوب تقريبًا كإبرة البوصلة، ويتنافر أحد طرفيه مع أحد قطبي مغناطيس يُقرَّب منه. (b) من الأدلة: أنه يستقر في اتجاه شمال–جنوب عند تعليقه تعليقًا حرًّا؛ وأن أحد طرفيه يتنافر مع قطب مغناطيس معلوم (التنافر دليل حاسم)؛ وأنه يجذب مشابك ورق صغيرة. (c) الملف الذي يسري فيه تيار يولّد مجالًا مغناطيسيًا، وهذا المجال يحفّز المسمار الموجود داخله ليصبح مستقطبًا كما يفعل المغناطيس الدائم عند تقريبه من قطعة حديد؛ فتمغنط بالحث. وتكون المغنطة مؤقتة لأن المسمار يفقد مغناطيسيته (كلها أو معظمها) بعد زوال المجال الخارجي.', '["يستقر المسمار في اتجاه شمال–جنوب","دليلان صحيحان (الاتجاه شمال–جنوب، التنافر مع قطب معلوم، جذب المشابك)","مجال الملف يمغنط المسمار بالحث","المغنطة تزول بزوال المجال الخارجي"]'::jsonb, '[]'::jsonb, '[{"element":"التوقع","marks":1},{"element":"الدليلان","marks":2},{"element":"تفسير التمغنط بمجال الملف","marks":1},{"element":"تعليل كون المغنطة مؤقتة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التوقع والدليلان والتفسير والتعليل كلها صحيحة"},{"level":"3–4 درجات","description":"التفسير صحيح مع نقص في الأدلة أو التعليل"},{"level":"1–2 درجة","description":"التوقع أو دليل واحد صحيح فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الاعتقاد بأن المسمار لا يتمغنط إلا بملامسة مغناطيس","عدّ التجاذب مع قطب مغناطيس دليلًا حاسمًا على المغنطة","القول إن المسمار يبقى ممغنطًا للأبد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-28T06:03:18.313Z"}'::jsonb)
