from (values
('mcq', 1, 3, 'المجالات المغناطيسية كميات متجهة توجد في المنطقة التي تؤثر فيها القوة المغناطيسية حول المغناطيس.', '["هذا تعريف التدفق المغناطيسي، والمجال المغناطيسي كمية متجهة لا قياسية.","المجال يوجد حول المغناطيس في كل المنطقة التي تؤثر فيها القوة المغناطيسية، لا داخله فقط.","المجال ليس هو القوة نفسها، والقوى المغناطيسية تؤثر قبل التلامس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-28T06:03:18.313Z"}'::jsonb),
('mcq', 2, 0, 'يسمى عدد خطوط المجال المغناطيسي التي تخترق السطح التدفق المغناطيسي.', '["","المنطقة المغناطيسية مجموعة من الذرات تترتب مجالاتها المغناطيسية في الاتجاه نفسه، لا عدد خطوط تخترق سطحًا.","شدة التيار الكهربائي معدل تدفق الشحنة الكهربائية، لا عدد خطوط المجال المغناطيسي.","القطب المغناطيسي طرف المغناطيس الذي تخرج منه خطوط المجال أو تدخل إليه، لا عدد الخطوط التي تخترق سطحًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.313Z"}'::jsonb),
('mcq', 3, 1, 'يسمى المغناطيس الذي ينشأ عن سريان تيار كهربائي في ملف المغناطيس الكهربائي.', '["المغناطيس الدائم يحتفظ بمغناطيسيته دون حاجة إلى تيار كهربائي.","","المغانط الطبيعية صخور مغناطيسية توجد في الطبيعة، ولا تنشأ عن تيار كهربائي.","المنطقة المغناطيسية مجموعة صغيرة جدًّا من الذرات المتجاورة المترتبة مجالاتها في الاتجاه نفسه، لا مغناطيس ينشأ عن تيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.314Z"}'::jsonb),
('mcq', 4, 2, 'التدفق عبر وحدة المساحة يتناسب طرديًا مع شدة المجال المغناطيسي؛ فكلما ازداد عدد خطوط المجال التي تخترق وحدة المساحة كان المجال أقوى.', '["ازدياد عدد الخطوط عبر وحدة المساحة يعني مجالًا أقوى لا أضعف؛ فالعلاقة طردية.","التناسب طردي مع شدة المجال نفسها، لا مع مربعها.","","خطوط المجال تزوّدنا بمقياس لشدة المجال؛ فالتدفق عبر وحدة المساحة مرتبط بها مباشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-28T06:03:18.314Z"}'::jsonb),
('mcq', 5, 0, 'يخترق السطحَ X القريب من القطب عددٌ من خطوط المجال أكبر مما يخترق السطح Y، فالتدفق عبره أكبر. وبما أن المساحتين متساويتان فالتدفق عبر وحدة المساحة عند X أكبر، أي أن المجال عند X أقوى.', '["","Y بعيد عن القطبين ويخترقه عدد أقل من الخطوط؛ فتدفقه أقل ومجاله أضعف.","التدفق عبر وحدة المساحة يتناسب طرديًا مع شدة المجال؛ فالسطح ذو التدفق الأكبر (مع تساوي المساحتين) يكون عنده المجال أقوى.","التدفق يعتمد على عدد الخطوط التي تخترق السطح لا على مساحته وحدها؛ والخطوط أكثف عند X."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.314Z"}'::jsonb),
('mcq', 6, 1, 'معظم التدفق المغناطيسي يتركّز عند القطبين؛ حيث يكون المجال المغناطيسي عندهما أكبر ما يمكن، وتكون خطوط المجال أكثر تقاربًا.', '["منتصف القضيب ليس موضع تركّز الخطوط؛ فالخطوط تخرج من القطب الشمالي وتدخل في القطب الجنوبي.","","الخطوط تتباعد كلما ابتعدنا عن المغناطيس؛ فالتدفق عبر وحدة المساحة هناك أقل.","كثافة الخطوط تختلف من منطقة إلى أخرى؛ فهي أكبر عند القطبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.314Z"}'::jsonb),
('mcq', 7, 3, 'الملف الذي يسري فيه تيار يصبح له مجال مغناطيسي يشبه مجال المغناطيس الدائم، فيتنافر أحد طرفيه مع القطب المماثل له ويتجاذب الطرف الآخر؛ أي أنه مغناطيس له قطبان شمالي وجنوبي، ويسمى المغناطيس الكهربائي.', '["النحاس لا ينجذب إلى المغانط، والتنافر الذي حدث لا يفسره التجاذب.","التأثير هنا مغناطيسي لا كهربائي؛ فالتنافر والتجاذب حدثا مع قطبي مغناطيس.","لا توجد أقطاب مغناطيسية مفردة؛ فطرفا الملف قطبان متعاكسان لمغناطيس واحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.314Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) المجال المغناطيسي: كمية متجهة توجد في المنطقة التي تؤثر فيها القوة المغناطيسية حول المغناطيس. (b) التدفق المغناطيسي: عدد خطوط المجال المغناطيسي التي تخترق السطح. (c) المغناطيس الكهربائي: المغناطيس الذي ينشأ عن سريان تيار كهربائي في ملف. (d) التدفق عبر وحدة المساحة يتناسب طرديًا مع شدة المجال المغناطيسي.', '["المجال: كمية متجهة في المنطقة التي تؤثر فيها القوة المغناطيسية","التدفق: عدد خطوط المجال التي تخترق السطح","المغناطيس الكهربائي: ينشأ عن سريان تيار في ملف","التدفق لكل وحدة مساحة يتناسب طرديًا مع شدة المجال"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المجال المغناطيسي","marks":1},{"element":"تعريف التدفق المغناطيسي","marks":1},{"element":"تعريف المغناطيس الكهربائي","marks":1},{"element":"العلاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريفات الثلاثة والعلاقة صحيحة"},{"level":"2–3 درجات","description":"تعريفان أو ثلاثة صحيحة دون العلاقة"},{"level":"1 درجة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"لا تعريف صحيح"}]'::jsonb, '["الخلط بين المجال والتدفق","وصف المجال المغناطيسي بأنه كمية قياسية","تعريف المغناطيس الكهربائي بأنه مغناطيس يجذب الشحنات الكهربائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-28T06:03:18.315Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) كل مجال منها يصف المنطقة التي تؤثر فيها قوة معيّنة؛ فمجال الجاذبية منطقة تؤثر فيها قوة الجاذبية، والمجال الكهربائي منطقة تؤثر فيها القوة الكهربائية، والمجال المغناطيسي منطقة تؤثر فيها القوة المغناطيسية. (b) المجالات الثلاثة كميات متجهة لها مقدار واتجاه. (c) مجال الجاذبية يؤثر في الكتل، والمجال الكهربائي يؤثر في الشحنات الكهربائية، والمجال المغناطيسي يؤثر في المغانط الأخرى والمواد المغناطيسية (كالحديد). (d) خطوط المجالين الكهربائي والمغناطيسي خطوط وهمية تساعدنا على تصور المجال، وتزودنا بمقياس لشدته.', '["التعريف المشترك: منطقة تؤثر فيها قوة","المجالات كميات متجهة","ما يتأثر بكل مجال","الخطوط وهمية وتدل على الشدة"]'::jsonb, '[]'::jsonb, '[{"element":"أوجه التشابه في التعريف","marks":1},{"element":"نوع الكمية","marks":1},{"element":"ما يتأثر بكل مجال","marks":1},{"element":"طبيعة الخطوط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المقارنة كاملة في البنود الأربعة"},{"level":"2–3 درجات","description":"بندان أو ثلاثة صحيحة"},{"level":"1 درجة","description":"بند واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن المجال المغناطيسي يؤثر في الشحنات الساكنة","عدّ خطوط المجال خطوطًا حقيقية","وصف أحد المجالات بأنه كمية قياسية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-28T06:03:18.315Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) لأن التيار الكهربائي المار في الملف يولّد حوله مجالًا مغناطيسيًا يشبه مجال المغناطيس الدائم، والمغناطيس الذي ينشأ عن سريان تيار كهربائي في ملف يسمى المغناطيس الكهربائي. (b) عند تقريب أحد طرفي الملف من مغناطيس معلّق يتنافر مع القطب المماثل له ويتجاذب مع القطب المخالف، أي أن للملف قطبين شماليًا وجنوبيًا؛ وتترتب برادة الحديد حوله بنمط يشبه نمط مجال القضيب المغناطيسي؛ ويجذب الأجسام الحديدية. (c) مغناطيسيته تزول عند قطع التيار (ويمكن التحكم في قوته بتغيير التيار)، أما المغناطيس الدائم فيحتفظ بمغناطيسيته دون تيار.', '["التيار يولّد مجالًا مغناطيسيًا حول الملف","ملاحظة أولى صحيحة (قطبان يتنافران ويتجاذبان)","ملاحظة ثانية صحيحة (نمط برادة الحديد أو جذب الحديد)","الفرق: يزول بزوال التيار"]'::jsonb, '[]'::jsonb, '[{"element":"سبب التسمية","marks":1},{"element":"الملاحظة الأولى","marks":1},{"element":"الملاحظة الثانية","marks":1},{"element":"الفرق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعليل والملاحظتان والفرق صحيحة"},{"level":"2–3 درجات","description":"التعليل مع ملاحظة واحدة أو دون الفرق"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الملف مغناطيس لأنه مصنوع من فلز","عدّ جذب الملف لأجسام صغيرة دليلًا على شحنة كهربائية","الاعتقاد بأن مغناطيسية الملف تبقى بعد قطع التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.315Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C3-L1-O03') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L1-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'كيف يُعرَّف اتجاه خط المجال المغناطيسي عند نقطة ما؟', null, null, '["الاتجاه الذي يشير إليه القطب الجنوبي لإبرة بوصلة توضع عند النقطة","الاتجاه الذي يشير إليه القطب الشمالي لإبرة بوصلة توضع عند النقطة","الاتجاه من النقطة نحو أقرب قطب للمغناطيس أيًّا كان نوعه","اتجاه الشمال الجغرافي للأرض عند النقطة دائمًا"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 74 — اتجاه خطوط المجال المغناطيسي'),
('mcq', 2, 'وُضعت بوصلة عند النقطة P فوق منتصف قضيب مغناطيسي تمامًا كما في الشكل الآتي. إلى أي اتجاه يشير القطب الشمالي لإبرة البوصلة؟', null, '[{"src":"qimg/phys32/c3l1-o04-above.svg","alt":"قضيب مغناطيسي أفقي طرفه الأيسر N (أحمر) وطرفه الأيمن S (أزرق). فوق منتصف القضيب تمامًا دائرة بوصلة فارغة بلا إبرة مكتوب بجانبها الحرف P."}]'::jsonb, '["نحو اليسار، موازيًا للقضيب وباتجاه قطبه الشمالي","نحو أعلى الصفحة، مبتعدًا عن القضيب عموديًا عليه","نحو اليمين، موازيًا للقضيب وباتجاه قطبه الجنوبي","نحو أسفل الصفحة، متجهًا إلى منتصف القضيب عموديًا عليه"]'::jsonb, 'فهم', 'تحديد اتجاه من شكل', 'متوسط', 'الكتاب ص 74 — اتجاه خطوط المجال المغناطيسي (الشكل 5-3)'),
('mcq', 3, 'يبين الشكل الآتي قضيبًا مغناطيسيًا مجهول القطبين X وY، وبوصلتين عند طرفيه، والقطب الشمالي (الأحمر) لكل من الإبرتين يشير نحو اليسار. أيّ الطرفين هو القطب الجنوبي للمغناطيس؟', null, '[{"src":"qimg/phys32/c3l1-o04-two.svg","alt":"قضيب مغناطيسي أفقي رمادي طرفه الأيسر مكتوب عليه X وطرفه الأيمن Y، وحوله خطوط مجال خضراء بلا أسهم. على يسار الطرف X بوصلة قطب إبرتها الشمالي (الأحمر) يشير نحو اليسار مبتعدًا عن المغناطيس، وعلى يمين الطرف Y بوصلة قطب إبرتها الشمالي (الأحمر) يشير نحو اليسار متجهًا نحو المغناطيس."}]'::jsonb, '["X؛ لأن الإبرة القريبة منه تشير مبتعدة عن المغناطيس","X؛ لأن الإبرتين كلتيهما تشيران نحو اليسار حيث يقع X","لا يمكن تحديده؛ لأن الإبرتين تشيران إلى الاتجاه نفسه","Y؛ لأن الإبرة القريبة منه تشير نحو المغناطيس"]'::jsonb, 'فهم', 'تحديد قطب من استجابة البوصلة', 'متوسط', 'الكتاب ص 74 وص 98 (السؤال 61)'),
('mcq', 4, 'يبين الشكل الآتي خطوط المجال المغناطيسي واتجاهاتها حول قضيب مغناطيسي طرفاه مرقّمان 1 و2. أيّ الطرفين هو القطب الشمالي؟', null, '[{"src":"qimg/phys32/c3l1-o04-arrows.svg","alt":"قضيب مغناطيسي أفقي رمادي طرفه الأيسر مرقّم 1 وطرفه الأيمن مرقّم 2، وحوله خطوط مجال خضراء عليها أسهم: الأسهم على الخطوط تتجه مبتعدة عن الطرف 2 وتنحني حول القضيب ثم تتجه نحو الطرف 1 وتدخل فيه؛ والخط الأفقي على يمين القضيب سهمه يتجه نحو اليمين، والخط الأفقي على يساره سهمه يتجه نحو اليمين نحو الطرف 1."}]'::jsonb, '["الطرف 2؛ لأن خطوط المجال تخرج منه","الطرف 1؛ لأن خطوط المجال تدخل إليه","الطرف 2؛ لأن خطوط المجال تدخل إليه","الطرف 1؛ لأن خطوط المجال تخرج منه"]'::jsonb, 'فهم', 'قراءة شكل', 'سهل', 'الكتاب ص 74 وص 98 (السؤال 60)'),
('mcq', 5, 'قُرّب القطبان الشماليان لمغناطيسين أحدهما من الآخر. أيّ العبارات الآتية تصف خطوط المجال المغناطيسي في المنطقة بينهما؟', null, null, '["تخرج من أحد القطبين وتتجه مباشرة لتدخل في القطب الآخر","تدخل في القطبين كليهما قادمة من المنطقة الواقعة بينهما","تخرج من القطبين كليهما وتنحرف مبتعدة دون أن تتصل بين القطبين","تتقاطع في منتصف المسافة بين القطبين ثم تكمل طريقها"]'::jsonb, 'فهم', 'وصف نمط مجال', 'متوسط', 'الكتاب ص 75 — الشكل 6-3'),
('mcq', 6, 'وُضع مغناطيسان على استقامة واحدة بحيث يقابل القطب الشمالي لأحدهما القطب الجنوبي للآخر، ووُضعت بوصلة عند النقطة P في منتصف المسافة بينهما كما في الشكل الآتي. إلى أين يشير القطب الشمالي لإبرة البوصلة؟', null, '[{"src":"qimg/phys32/c3l1-o04-gap.svg","alt":"مغناطيسان أفقيان على خط واحد. المغناطيس الأيسر: طرفه الأيسر S (أزرق) وطرفه الأيمن N (أحمر). المغناطيس الأيمن: طرفه الأيسر S (أزرق) وطرفه الأيمن N (أحمر). بين المغناطيسين، في منتصف المسافة بين N للأيسر وS للأيمن، دائرة بوصلة فارغة بلا إبرة وتحتها الحرف P."}]'::jsonb, '["نحو اليسار، باتجاه القطب الشمالي للمغناطيس الأيسر","نحو أعلى الصفحة، عموديًا على المغناطيسين","لا تستقر الإبرة في اتجاه محدد لانعدام المجال عند P","نحو اليمين، باتجاه القطب الجنوبي للمغناطيس الأيمن"]'::jsonb, 'تطبيق', 'تحديد اتجاه من شكل', 'متوسط', 'الكتاب ص 75 — الشكل 6b-3'),
('mcq', 7, 'وُضعت بوصلة على التوالي في المواضع A وB وC وD حول قضيب مغناطيسي كما في الشكل الآتي. في أيّ المواضع يشير القطب الشمالي لإبرة البوصلة نحو القضيب؟', null, '[{"src":"qimg/phys32/c3l1-o04-four.svg","alt":"قضيب مغناطيسي أفقي طرفه الأيسر S (أزرق) وطرفه الأيمن N (أحمر). حوله أربع دوائر بوصلة فارغة بلا إبر: A على يسار الطرف S، وC على يمين الطرف N، وB فوق منتصف القضيب، وD تحت منتصف القضيب."}]'::jsonb, '["الموضع A","الموضع B","الموضع C","الموضع D"]'::jsonb, 'تحليل', 'تحليل مواضع', 'صعب', 'الكتاب ص 74 — اتجاه خطوط المجال المغناطيسي والتجربة الاستهلالية ص 71'),
('essay', 1, 'ارسم قضيبًا مغناطيسيًا صغيرًا، وبيّن عليه خطوط المجال المغناطيسي حوله، واستعمل الأسهم لتحديد اتجاه الخطوط. ثم وضّح: (a) القاعدة التي اعتمدت عليها في رسم الأسهم. (b) كيف يمكن التحقق من اتجاه الخطوط عمليًا. (c) أين رسمت الخطوط أكثر تقاربًا، ولماذا؟', null, null, null, 'تطبيق', 'رسم وتفسير', 'متوسط', 'الكتاب ص 74 وص 96 (السؤال 35)'),
('essay', 2, 'يبين الشكل الآتي زوجين من المغانط. (a) في الزوج (a): صف شكل خطوط المجال في المنطقة بين القطبين المتقابلين، وحدّد اتجاهها. (b) في الزوج (b): صف شكل خطوط المجال بين القطبين المتقابلين وحدّد اتجاهها. (c) ماذا يدل عليه الاختلاف بين النمطين بشأن القوة بين المغناطيسين في كل زوج؟', null, '[{"src":"qimg/phys32/c3l1-o04-e-pairs.svg","alt":"زوجان من المغانط الأفقية. الزوج (a) في الأعلى: المغناطيس الأيسر طرفه الأيسر N وطرفه الأيمن S، والمغناطيس الأيمن طرفه الأيسر S وطرفه الأيمن N؛ فيتقابل قطبان جنوبيان. الزوج (b) في الأسفل: المغناطيس الأيسر طرفه الأيسر S وطرفه الأيمن N، والمغناطيس الأيمن طرفه الأيسر S وطرفه الأيمن N؛ فيتقابل القطب N للأيسر مع القطب S للأيمن."}]'::jsonb, null, 'تطبيق', 'وصف أنماط المجال', 'صعب', 'الكتاب ص 75 (الشكل 6-3) وص 96 (السؤال 36)'),
('essay', 3, 'وضع طالب قضيبين مغناطيسيين أفقيين على خط واحد بينهما فراغ، والقطب الشمالي لكل منهما نحو اليسار، ثم حرّك بوصلة في مواضع كثيرة حولهما، ورسم في كل موضع سهمًا في الاتجاه الذي يشير إليه الطرف الأحمر (الشمالي) لإبرة البوصلة. (a) نحو أيّ قطب يشير الطرف الأحمر للإبرة عندما تكون البوصلة قرب أحد القطبين؟ ومن أيّ قطب يبتعد؟ (b) لماذا لا تشير بعض الأسهم نحو أي من القطبين ولا مبتعدة عنه؟ (c) ماذا يمثل المخطط الذي حصل عليه الطالب؟', null, null, null, 'تحليل', 'تحليل تجربة', 'صعب', 'الكتاب ص 71 — التجربة الاستهلالية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C3-L1-O04') and x.type = v.type and x.number = v.number);
