from (values
('mcq', 1, 1, 'يُعرَّف اتجاه خط المجال المغناطيسي بأنه الاتجاه الذي يشير إليه القطب الشمالي لإبرة البوصلة عند وضعها في المجال المغناطيسي.', '["التعريف مبني على القطب الشمالي للإبرة لا الجنوبي؛ والقطب الجنوبي يشير إلى عكس اتجاه المجال.","","الخطوط تخرج من القطب الشمالي وتدخل في الجنوبي؛ فالاتجاه لا يكون دائمًا نحو أقرب قطب.","قرب المغناطيس يتحدد اتجاه الإبرة بمجال المغناطيس، فلا تشير بالضرورة إلى الشمال الجغرافي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.316Z"}'::jsonb),
('mcq', 2, 2, 'خطوط المجال خارج المغناطيس تخرج من القطب الشمالي (اليسار) وتدخل في القطب الجنوبي (اليمين)، وفوق منتصف القضيب تكون موازية له. لذا يشير القطب الشمالي للإبرة نحو اليمين، أي نحو القطب الجنوبي.', '["القطب الشمالي للإبرة يتبع اتجاه المجال من N إلى S، فلا يشير نحو القطب الشمالي للمغناطيس.","فوق منتصف القضيب تكون الخطوط موازية له لا عمودية عليه.","","منتصف القضيب ليس قطبًا؛ والخطوط عند P موازية للقضيب ومتجهة من N إلى S."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-28T06:03:18.316Z"}'::jsonb),
('mcq', 3, 3, 'القطب الشمالي للإبرة يشير في اتجاه المجال، والمجال يخرج من القطب الشمالي ويدخل في الجنوبي. عند Y تشير الإبرة نحو اليسار أي نحو المغناطيس، فالمجال يدخل فيه، فـ Y قطب جنوبي. وعند X تشير الإبرة مبتعدة عن المغناطيس، فالمجال يخرج منه، فـ X قطب شمالي.', '["ابتعاد الإبرة عن الطرف X يعني أن المجال يخرج منه، فهو قطب شمالي لا جنوبي.","اتجاه الإبرتين وحده لا يحدد القطب؛ المهم هل تشير الإبرة نحو الطرف أم مبتعدة عنه.","الإبرتان تشيران إلى الاتجاه نفسه لكن إحداهما نحو المغناطيس والأخرى مبتعدة عنه، وهذا يكفي للتحديد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.317Z"}'::jsonb),
('mcq', 4, 0, 'تكون خطوط المجال المغناطيسي خارجة من القطب الشمالي وداخلة إلى القطب الجنوبي. والأسهم في الشكل تخرج من الطرف 2 وتدخل في الطرف 1، فالطرف 2 هو القطب الشمالي.', '["","الخطوط تدخل في القطب الجنوبي لا الشمالي؛ فالطرف 1 قطب جنوبي.","الأسهم تبين أن الخطوط تخرج من الطرف 2 لا تدخل إليه.","الأسهم تبين أن الخطوط تدخل في الطرف 1 لا تخرج منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.317Z"}'::jsonb),
('mcq', 5, 2, 'بين قطبين متشابهين لا تشكّل الخطوط مسارات متصلة بين القطبين؛ فالخطوط تخرج من كل قطب شمالي ثم تنحرف مبتعدة عن الخطوط الخارجة من القطب الآخر.', '["الخطوط تتجه مباشرة من قطب إلى آخر فقط بين قطبين مختلفين.","الخطوط تخرج من القطب الشمالي ولا تدخل فيه؛ فهذا وصف قطبين جنوبيين متقابلين.","","لا تتصل الخطوط بين القطبين المتشابهين، بل تنحرف مبتعدة؛ ولا تتقاطع خطوط المجال في نقطة ثم تكمل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.317Z"}'::jsonb),
('mcq', 6, 3, 'بين قطبين مختلفين تتجه خطوط المجال مباشرة من القطب الشمالي للمغناطيس الأيسر إلى القطب الجنوبي للمغناطيس الأيمن، فيكون المجال عند P نحو اليمين، ويشير القطب الشمالي للإبرة نحو اليمين.', '["المجال يخرج من القطب الشمالي فلا تشير الإبرة نحوه؛ بل تشير مبتعدة عنه نحو اليمين.","الخطوط بين القطبين المختلفين تتجه مباشرة من أحدهما إلى الآخر، فتكون أفقية عند P.","المجال بين قطبين مختلفين لا ينعدم، بل يتجه من N إلى S؛ والانعدام قد يحدث بين قطبين متشابهين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-28T06:03:18.318Z"}'::jsonb),
('mcq', 7, 0, 'الخطوط خارج المغناطيس تخرج من N وتدخل في S. الموضع A يقع عند القطب الجنوبي فيكون المجال داخلًا إلى القضيب، فتشير الإبرة نحوه. وعند C (القطب الشمالي) تشير مبتعدة عنه، وعند B وD (فوق المنتصف وتحته) تكون الإبرة موازية للقضيب وتشير نحو اليسار (نحو S).', '["","عند B فوق منتصف القضيب يكون المجال موازيًا للقضيب متجهًا نحو S (اليسار)، لا نحو القضيب.","C عند القطب الشمالي حيث يخرج المجال، فتشير الإبرة مبتعدة عن القضيب.","عند D تحت منتصف القضيب يكون المجال موازيًا للقضيب متجهًا نحو S، لا نحو القضيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-28T06:03:18.318Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الرسم: قضيب طرفاه N وS، وحوله خطوط منحنية مغلقة تخرج من القطب الشمالي وتلتف حول القضيب لتدخل في القطب الجنوبي، والأسهم على الخطوط خارج القضيب تتجه من N إلى S. (a) اتجاه خط المجال هو الاتجاه الذي يشير إليه القطب الشمالي لإبرة البوصلة، والخطوط تخرج من القطب الشمالي وتدخل في القطب الجنوبي. (b) نضع بوصلة صغيرة في مواضع متعددة حول المغناطيس ونرسم في كل موضع سهمًا في الاتجاه الذي يشير إليه قطبها الشمالي. (c) قرب القطبين؛ لأن معظم التدفق المغناطيسي يتركز عندهما فيكون المجال عندهما أكبر ما يمكن.', '["خطوط منحنية حول القضيب من N إلى S خارجه","الأسهم تخرج من N وتدخل في S","القاعدة: اتجاه القطب الشمالي للبوصلة","التحقق بالبوصلة في مواضع متعددة","التقارب عند القطبين لأن المجال أكبر هناك"]'::jsonb, '[]'::jsonb, '[{"element":"الرسم وشكل الخطوط","marks":1},{"element":"اتجاه الأسهم","marks":1},{"element":"القاعدة","marks":1},{"element":"طريقة التحقق","marks":1},{"element":"موضع التقارب مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"رسم صحيح بأسهم صحيحة مع الإجابات الثلاث"},{"level":"3–4 درجات","description":"رسم صحيح مع نقص في إحدى الإجابات"},{"level":"1–2 درجة","description":"رسم بأسهم معكوسة أو إجابة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["رسم الأسهم من S إلى N خارج المغناطيس","رسم خطوط تبدأ من منتصف القضيب","رسم الخطوط متباعدة عند القطبين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.318Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) القطبان المتقابلان في الزوج (a) جنوبيان. خطوط المجال لا تتصل بين القطبين، بل تأتي من الخارج وتدخل في كل قطب جنوبي، وتنحرف الخطوط الداخلة إلى أحد القطبين مبتعدة عن الخطوط الداخلة إلى الآخر؛ واتجاهها نحو كل من القطبين (داخلة فيهما). (b) القطبان المتقابلان في الزوج (b) مختلفان: القطب الشمالي للمغناطيس الأيسر يقابل القطب الجنوبي للمغناطيس الأيمن. تتجه الخطوط مباشرة من القطب الشمالي للأيسر لتتصل بالقطب الجنوبي للأيمن، فيكون اتجاهها في المنطقة بينهما نحو اليمين. (c) عدم اتصال الخطوط بين القطبين المتشابهين في الزوج (a) يرافقه تنافر المغناطيسين، واتصال الخطوط مباشرة بين القطبين المختلفين في الزوج (b) يرافقه تجاذبهما.', '["(a) قطبان جنوبيان: الخطوط لا تتصل وتنحرف مبتعدة","(a) الخطوط داخلة في القطبين","(b) قطبان مختلفان: خطوط مباشرة من N إلى S","(b) الاتجاه نحو اليمين من N إلى S","(c) تنافر في (a) وتجاذب في (b)"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الزوج (a)","marks":1},{"element":"اتجاه الزوج (a)","marks":1},{"element":"وصف الزوج (b)","marks":1},{"element":"اتجاه الزوج (b)","marks":1},{"element":"الإجابة (c)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الوصف والاتجاه في الزوجين ونوع القوة صحيحة"},{"level":"3–4 درجات","description":"أحد الزوجين صحيح كاملًا مع خطأ في الآخر"},{"level":"1–2 درجة","description":"تمييز صحيح لنوع القطبين المتقابلين فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["رسم خطوط متصلة بين القطبين المتشابهين","جعل الخطوط خارجة من القطبين الجنوبيين","جعل الخطوط بين القطبين المختلفين متجهة من S إلى N"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.319Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) يشير الطرف الأحمر (الشمالي) للإبرة نحو القطب الجنوبي للمغناطيس، ويبتعد عن القطب الشمالي؛ لأن خطوط المجال تخرج من القطب الشمالي وتدخل في الجنوبي، والإبرة تشير في اتجاه المجال. (b) لأن الإبرة تشير في اتجاه المجال عند موضعها، وهو اتجاه المماس لخط المجال المنحني، والمجال في كل موضع ناتج عن تأثير القطبين (والمغناطيسين) معًا؛ ففي المواضع البعيدة عن طرفي المغناطيس (كأعلى منتصفه) تكون الإبرة موازية للقضيب لا متجهة نحو أي قطب. (c) يمثل المخطط المجال المغناطيسي حول المغناطيسين؛ فالأسهم المتصلة تكوّن خطوط المجال واتجاهاتها.', '["الطرف الأحمر يشير نحو القطب الجنوبي ويبتعد عن الشمالي","التعليل: المجال يخرج من N ويدخل في S","الإبرة تتبع اتجاه المماس للخط المنحني الناتج عن تأثير القطبين معًا","المخطط يمثل المجال المغناطيسي"]'::jsonb, '[]'::jsonb, '[{"element":"الإجابة (a)","marks":1},{"element":"تعليل (a)","marks":1},{"element":"الإجابة (b)","marks":2},{"element":"الإجابة (c)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الإجابات الثلاث صحيحة مع التعليل"},{"level":"3–4 درجات","description":"(a) و(c) صحيحتان مع تفسير ناقص في (b)"},{"level":"1–2 درجة","description":"إجابة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الطرف الأحمر يشير نحو القطب الشمالي للمغناطيس","الاعتقاد بأن الإبرة تشير دائمًا إلى أقرب قطب","الخلط بين المخطط ومجال الجاذبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.320Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
