('mcq', 1, 'أُنفذ سلك مستقيم رأسيًا خلال لوح كرتون أفقي، ورُشّت برادة حديد على اللوح، ثم مُرّر تيار كهربائي في السلك. ما النمط الذي تشكّله برادة الحديد؟', null, null, '["خطوط مستقيمة تخرج من السلك وتمتد مبتعدة عنه في كل الاتجاهات","دوائر متحدة المركز حول السلك","خطوط مستقيمة متوازية تمتد على اللوح في اتجاه واحد","نمط يشبه مجال قضيب مغناطيسي له قطبان على اللوح"]'::jsonb, 'تذكر', 'ملاحظة تجريبية', 'سهل', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم (الشكل 9-3)'),
('mcq', 2, 'ما الوصف الصحيح لخطوط المجال المغناطيسي حول سلك مستقيم طويل يسري فيه تيار كهربائي؟', null, null, '["خطوط مستقيمة موازية للسلك ومتجهة في اتجاه التيار","حلقات مغلقة تقع في مستويات تحتوي السلك نفسه","دوائر مغلقة مركزها السلك تقع في مستويات عمودية عليه","خطوط تبدأ عند أحد طرفي السلك وتنتهي عند طرفه الآخر"]'::jsonb, 'فهم', 'وصف', 'متوسط', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم'),
('mcq', 3, 'في الشكل الآتي يسري تيار في سلك رأسي يخترق لوحًا أفقيًا، ووُضعت حوله أربع بوصلات صغيرة. كيف تترتب إبر البوصلات؟', null, '[{"src":"qimg/phys32/c3l1-o05-card.svg","alt":"سلك مستقيم رأسي يخترق لوحًا أفقيًا من الكرتون من منتصفه، وبجانب جزئه العلوي سهم نحو الأعلى مكتوب عنده I (التيار يسري إلى أعلى). على اللوح أربع بوصلات صغيرة بلا إبر موزعة حول السلك على أبعاد متساوية تقريبًا منه (يمينه ويساره وأمامه وخلفه). ومكتوب تحت اللوح «لوح كرتون أفقي»."}]'::jsonb, '["تشير كلها نحو السلك على امتداد أنصاف أقطار","تشير كلها مبتعدة عن السلك على امتداد أنصاف أقطار","تشير كلها نحو الشمال الجغرافي كما لو لم يكن هناك تيار","تكون كل إبرة مماسًا لدائرة مركزها السلك"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم (الشكل 10a-3)'),
('mcq', 4, 'ماذا يحدث لنمط المجال المغناطيسي حول سلك مستقيم عند عكس اتجاه التيار المار فيه؟', null, null, '["يبقى دوائر متحدة المركز حول السلك، وينعكس اتجاه المجال","يتحول إلى خطوط مستقيمة تخرج من السلك","يبقى دوائر متحدة المركز حول السلك، ولا يتغير اتجاه المجال","يختفي المجال لأن التيارين المتعاكسين يلغي كل منهما الآخر"]'::jsonb, 'فهم', 'تنبؤ', 'متوسط', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم (الشكل 10a-3)'),
('mcq', 5, 'ما الذي تشترك فيه خطوط المجال المغناطيسي حول سلك مستقيم طويل يسري فيه تيار مع خطوط المجال حول المغناطيس الدائم؟', null, null, '["كلتاهما تخرج من قطب شمالي وتنتهي عند قطب جنوبي","كلتاهما خطوط مستقيمة متباعدة","كلتاهما تشكّل حلقات مغلقة","كلتاهما توجد دون الحاجة إلى تيار كهربائي"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم'),
('mcq', 6, 'يبين الشكل الآتي مقطعًا لسلك مستقيم طويل عمودي على الصفحة يسري فيه تيار، وخطوط المجال حوله، والنقطة P على أحد الخطوط. ما اتجاه المجال المغناطيسي عند P بالنسبة إلى الخط الواصل بين السلك وP؟', null, '[{"src":"qimg/phys32/c3l1-o05-tangent.svg","alt":"مقطع دائري لسلك عمودي على الصفحة في المركز، داخله نقطة (التيار خارج من الصفحة). حول السلك ثلاث دوائر خضراء متحدة المركز بلا أسهم. النقطة P تقع على الدائرة الوسطى في أعلى يمين السلك، وخط متقطع يصل بين مركز السلك والنقطة P."}]'::jsonb, '["عمودي على الخط الواصل بين السلك وP، أي مماس للدائرة عند P","على امتداد الخط الواصل بين السلك وP مبتعدًا عن السلك","على امتداد الخط الواصل بين السلك وP متجهًا نحو السلك","عمودي على الصفحة موازيًا للسلك نفسه"]'::jsonb, 'فهم', 'تحليل شكل', 'صعب', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم (الشكل 9-3)'),
('mcq', 7, 'وُضع سلك مستقيم طويل أفقيًا على طاولة في اتجاه شرق–غرب، ومُرّر فيه تيار كهربائي. ما الوصف الصحيح لخطوط المجال المغناطيسي حوله؟', null, null, '["دوائر أفقية تقع في مستوى سطح الطاولة ومركزها السلك","خطوط مستقيمة أفقية موازية للسلك في اتجاه شرق–غرب","دوائر تقع في مستويات رأسية في اتجاه شمال–جنوب ومركزها السلك","خطوط مستقيمة رأسية تخرج من السلك إلى أعلى"]'::jsonb, 'تحليل', 'تطبيق في وضع جديد', 'صعب', 'الكتاب ص 76 وص 98 (السؤال 63)'),
('essay', 1, 'صف تجربة توضح شكل المجال المغناطيسي حول سلك مستقيم يسري فيه تيار كهربائي، مبيّنًا: (a) الأدوات وطريقة ترتيبها. (b) ما تلاحظه على برادة الحديد. (c) ما تبيّنه بوصلات صغيرة توضع حول السلك. (d) ما يتغير عند عكس اتجاه التيار.', null, null, null, 'فهم', 'وصف تجربة', 'سهل', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم (الشكلان 9-3 و10-3)'),
('essay', 2, 'يبين الشكل الآتي مقطعًا لسلك مستقيم طويل عمودي على الصفحة، والتيار الاصطلاحي فيه خارج من الصفحة. (a) صف خطوط المجال المغناطيسي التي ترسمها حول السلك. (b) حدّد اتجاه دوران هذه الخطوط كما تراها في الصفحة. (c) كيف ترسم المسافات بين الخطوط المتتالية كلما ابتعدت عن السلك، ولماذا؟', null, '[{"src":"qimg/phys32/c3l1-o05-e-out.svg","alt":"مقطع دائري لسلك عمودي على الصفحة، في وسطه نقطة سوداء تدل على أن التيار خارج من الصفحة، ومكتوب تحته «التيار خارج من الصفحة». لا توجد خطوط مجال مرسومة."}]'::jsonb, null, 'تطبيق', 'رسم المجال ووصفه', 'متوسط', 'الكتاب ص 76–77 وص 98 (السؤال 64)'),
