from (values
('mcq', 1, 1, 'عند مرور التيار في السلك تترتب برادة الحديد وتشكّل نمطًا في صورة دوائر متحدة المركز حول السلك.', '["الخطوط حول السلك ليست شعاعية خارجة منه، بل دوائر تلتف حوله.","","البرادة لا تصطف في خطوط متوازية، بل في دوائر مركزها السلك.","لا تظهر حول السلك المستقيم أقطاب شمالية وجنوبية، بل دوائر مغلقة حوله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-28T06:03:18.320Z"}'::jsonb),
('mcq', 2, 2, 'خطوط المجال حول السلك الطويل حلقات مغلقة دائرية مركزها السلك، وتقع في مستويات عمودية على السلك (كلوح الكرتون الأفقي الذي يخترقه السلك الرأسي).', '["المجال لا يكون موازيًا للسلك؛ فهو يلتف حوله في دوائر.","الدوائر تقع في مستويات عمودية على السلك (كاللوح الأفقي حول السلك الرأسي)، لا في مستويات تحتويه.","","خطوط المجال حلقات مغلقة لا بداية لها ولا نهاية، وليس للسلك قطبان عند طرفيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-28T06:03:18.320Z"}'::jsonb),
('mcq', 3, 3, 'المجال حول السلك دوائر متحدة المركز حول السلك، والإبرة تصطف موازية للمجال؛ فتكون كل إبرة مماسًا لدائرة مركزها السلك، وتشكل الإبر معًا حلقة حوله.', '["الإبر لا تتجه نحو السلك؛ لأن المجال حوله دائري لا شعاعي.","الإبر لا تشير مبتعدة عن السلك؛ لأن المجال حوله دائري لا شعاعي.","التيار يولّد حول السلك مجالًا يغيّر اتجاه الإبر القريبة منه، فلا تبقى متجهة نحو الشمال.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.321Z"}'::jsonb),
('mcq', 4, 0, 'شكل المجال يبقى دوائر متحدة المركز حول السلك، لكن اتجاهه ينعكس؛ فإذا عُكس اتجاه التيار تعكس إبرة البوصلة اتجاهها أيضًا.', '["","عكس التيار لا يغيّر شكل الخطوط، فتبقى دائرية حول السلك.","اتجاه المجال مرتبط باتجاه التيار؛ فعكس التيار يعكس اتجاه المجال والإبر.","يسري في السلك تيار واحد عُكس اتجاهه، فلا يوجد تياران يلغي أحدهما الآخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-28T06:03:18.321Z"}'::jsonb),
('mcq', 5, 2, 'تشير الخطوط الدائرية إلى أن خطوط المجال حول السلك الطويل تشكّل حلقات مغلقة، بالطريقة نفسها التي تشكّل بها خطوط المجال حلقات مغلقة حول المغانط الدائمة.', '["السلك المستقيم ليس له قطب شمالي ولا جنوبي، وخطوطه دوائر حوله.","الخطوط حول السلك دوائر، وحول المغناطيس منحنيات مغلقة؛ فليست مستقيمة.","","مجال السلك لا يوجد إلا عند سريان التيار فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-28T06:03:18.321Z"}'::jsonb),
('mcq', 6, 0, 'خط المجال حول السلك دائرة مركزها السلك، واتجاه المجال عند أي نقطة يكون مماسًا لخط المجال المار بها؛ والمماس للدائرة عمودي على نصف القطر الواصل إلى المركز (السلك).', '["","المجال حول السلك ليس شعاعيًا خارجًا منه؛ فالخطوط دوائر لا أنصاف أقطار.","المجال حول السلك ليس شعاعيًا داخلًا إليه؛ فالخطوط دوائر حوله.","الدوائر تقع في مستوى الصفحة العمودي على السلك، فالمجال عند P في مستوى الصفحة لا موازٍ للسلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-28T06:03:18.321Z"}'::jsonb),
('mcq', 7, 2, 'خطوط المجال حول السلك دوائر مركزها السلك وتقع في مستويات عمودية عليه. والسلك أفقي في اتجاه شرق–غرب، فالمستويات العمودية عليه رأسية وتمتد في اتجاه شمال–جنوب.', '["مستوى سطح الطاولة يحتوي السلك، والدوائر تقع في مستويات عمودية على السلك لا تحتويه.","المجال لا يكون موازيًا للسلك، بل يلتف حوله في دوائر.","","الخطوط ليست شعاعية خارجة من السلك، بل دوائر مغلقة تلتف حوله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-28T06:03:18.321Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) نُنفذ سلكًا رأسيًا خلال قطعة كرتون أفقية، ونصل طرفيه بمصدر قدرة، ونرش برادة حديد على الكرتون. (b) عند مرور التيار تترتب البرادة في نمط دوائر متحدة المركز حول السلك. (c) تصطف إبر البوصلات مماسات لدوائر مركزها السلك، فتبيّن أن خطوط المجال حلقات مغلقة حول السلك وتحدد اتجاهها. (d) يبقى الشكل دوائر متحدة المركز، لكن اتجاه المجال ينعكس فتعكس إبر البوصلات اتجاهها.', '["سلك رأسي يخترق كرتونًا أفقيًا عليه برادة حديد ومصدر قدرة","البرادة تشكّل دوائر متحدة المركز حول السلك","البوصلات مماسات للدوائر وتبين اتجاه المجال","عكس التيار يعكس اتجاه المجال دون تغيير الشكل"]'::jsonb, '[]'::jsonb, '[{"element":"الأدوات والترتيب","marks":1},{"element":"ملاحظة البرادة","marks":1},{"element":"دور البوصلات","marks":1},{"element":"أثر عكس التيار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"عنصران أو ثلاثة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["وصف البرادة بأنها خطوط شعاعية خارجة من السلك","القول إن عكس التيار يغيّر شكل المجال","نسيان أن المجال لا يظهر إلا عند مرور التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-28T06:03:18.322Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) دوائر متحدة المركز مركزها السلك، تقع في مستوى الصفحة العمودي على السلك، وهي حلقات مغلقة. (b) بتطبيق القاعدة الأولى لليد اليمنى: نجعل الإبهام في اتجاه التيار (خارجًا من الصفحة نحونا) فتلتف الأصابع عكس اتجاه حركة عقارب الساعة؛ فالخطوط تدور عكس عقارب الساعة كما نراها. (c) تُرسم الخطوط أكثر تباعدًا كلما ابتعدنا عن السلك؛ لأن شدة المجال تقل بزيادة البعد عن السلك، وتقارب الخطوط يدل على شدة المجال.', '["دوائر متحدة المركز حول السلك في مستوى الصفحة","الاتجاه عكس عقارب الساعة","استعمال القاعدة الأولى لليد اليمنى","تتباعد الخطوط بالابتعاد لأن المجال يضعف"]'::jsonb, '[]'::jsonb, '[{"element":"شكل الخطوط","marks":1},{"element":"اتجاه الدوران","marks":1},{"element":"تبرير الاتجاه بالقاعدة","marks":1},{"element":"تباعد الخطوط مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الشكل والاتجاه والتبرير والتباعد صحيحة"},{"level":"2–3 درجات","description":"الشكل صحيح مع خطأ في الاتجاه أو التباعد"},{"level":"1 درجة","description":"شكل الخطوط فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["رسم الدوائر مع عقارب الساعة لتيار خارج من الصفحة","رسم خطوط شعاعية","رسم الدوائر متساوية التباعد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-28T06:03:18.322Z"}'::jsonb),
('essay', 3, null::int, null, null, 'أوجه التشابه: (1) خطوط المجال في الحالتين حلقات مغلقة. (2) المجال في الحالتين كمية متجهة تحدد البوصلة اتجاهها، وتظهره برادة الحديد. أوجه الاختلاف: (1) خطوط مجال السلك دوائر متحدة المركز حول السلك في مستويات عمودية عليه، أما خطوط القضيب فتخرج من قطبه الشمالي وتدخل في قطبه الجنوبي خارجه. (2) السلك المستقيم ليس له قطبان، أما القضيب فله قطب شمالي وقطب جنوبي يتركز عندهما التدفق. (3) مجال السلك لا يوجد إلا عند سريان التيار ويعكس اتجاهه بعكس التيار، أما مجال المغناطيس الدائم فموجود دائمًا.', '["التشابه: حلقات مغلقة","التشابه: كمية متجهة تظهرها البوصلة والبرادة","الاختلاف في الشكل: دوائر حول السلك مقابل خطوط من N إلى S","الاختلاف: لا أقطاب للسلك","الاختلاف: مجال السلك مرتبط بالتيار"]'::jsonb, '[]'::jsonb, '[{"element":"وجه التشابه الأول","marks":1},{"element":"وجه التشابه الثاني","marks":1},{"element":"الاختلاف الأول","marks":1},{"element":"الاختلاف الثاني","marks":1},{"element":"الاختلاف الثالث","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وجها التشابه وأوجه الاختلاف الثلاثة صحيحة"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة أوجه صحيحة"},{"level":"1–2 درجة","description":"وجه أو وجهان صحيحان"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن للسلك قطبين عند طرفيه","وصف خطوط السلك بأنها تبدأ منه وتنتهي بعيدًا عنه","القول إن مجال السلك موجود دون تيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-28T06:03:18.322Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
