insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L1-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما العاملان اللذان تعتمد عليهما شدة المجال المغناطيسي الناشئ عند نقطة قرب سلك مستقيم طويل يسري فيه تيار كهربائي؟', null, null, '["طول السلك ونوع المادة المصنوع منها","مقدار التيار والبعد عن السلك","مساحة مقطع السلك ومقاومته الكهربائية","اتجاه التيار في السلك ولون عازله"]'::jsonb, 'تذكر', 'تذكر عوامل', 'سهل', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم'),
('mcq', 2, 'ما العلاقة بين شدة المجال المغناطيسي حول سلك مستقيم طويل وكل من مقدار التيار المار فيه والبعد عنه؟', null, null, '["تتناسب طرديًا مع التيار، وعكسيًا مع مربع البعد","تتناسب عكسيًا مع التيار، وطرديًا مع البعد","تتناسب طرديًا مع كل من التيار والبعد","تتناسب طرديًا مع التيار، وعكسيًا مع البعد"]'::jsonb, 'تذكر', 'تذكر علاقة', 'سهل', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم'),
('mcq', 3, 'إذا كانت شدة المجال المغناطيسي على بُعد 1 cm من سلك طويل يسري فيه تيار تساوي $\mathrm{B}$، فكم تكون شدة المجال على بُعد 3 cm من السلك نفسه؟', null, null, '["ثلث $\\mathrm{B}$","تُسع $\\mathrm{B}$","ثلاثة أمثال $\\mathrm{B}$","تساوي $\\mathrm{B}$"]'::jsonb, 'فهم', 'استدلال تناسبي', 'متوسط', 'الكتاب ص 78 — مسائل تدريبية (المسألة 6)'),
('mcq', 4, 'ضوعف مقدار التيار المار في سلك مستقيم طويل، وفي الوقت نفسه قُرّبت نقطة القياس إلى نصف بُعدها الأصلي عن السلك. كم مرة تصبح شدة المجال المغناطيسي عند نقطة القياس الجديدة مقارنة بالأصلية؟', null, null, '["تبقى مساوية لقيمتها الأصلية","تصبح مثلَي قيمتها الأصلية","تصبح أربعة أمثال قيمتها الأصلية","تصبح ربع قيمتها الأصلية"]'::jsonb, 'فهم', 'استدلال تناسبي', 'متوسط', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم'),
('mcq', 5, 'يعطى المجال المغناطيسي الناتج عن سلك طويل يسري فيه تيار بالعلاقة $\mathrm{B} = (2\times10^{-7}\ \text{T.m/A})(\mathrm{I}/d)$، حيث $\mathrm{I}$ التيار بوحدة A، و$d$ البعد عن السلك بوحدة m. ما مقدار المجال على بُعد 0.30 m من سلك يسري فيه تيار مقداره 15 A؟', null, null, '["$9.0\\times10^{-7}\\ \\text{T}$","$3.0\\times10^{-6}\\ \\text{T}$","$4.0\\times10^{-9}\\ \\text{T}$","$1.0\\times10^{-5}\\ \\text{T}$"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 101–102 — السؤال 95'),
('mcq', 6, 'يبين الشكل الآتي مقطعًا لسلك مستقيم طويل عمودي على الصفحة يسري فيه تيار، والنقاط P وQ وR على أبعاد r و2r و3r منه على الترتيب. ما الترتيب الصحيح لشدة المجال المغناطيسي عند هذه النقاط؟', null, '[{"src":"qimg/phys32/c3l1-o06-points.svg","alt":"مقطع سلك عمودي على الصفحة على يسار الشكل، داخله علامة × (التيار داخل في الصفحة). على خط أفقي إلى يمين السلك ثلاث نقاط: P ثم Q ثم R. وتحتها ثلاثة أسهم قياس تبدأ من السلك: إلى P مكتوب عنده r، وإلى Q مكتوب عنده 2r، وإلى R مكتوب عنده 3r."}]'::jsonb, '["$\\mathrm{B}_\\mathrm{P} > \\mathrm{B}_\\mathrm{Q} > \\mathrm{B}_\\mathrm{R}$","$\\mathrm{B}_\\mathrm{R} > \\mathrm{B}_\\mathrm{Q} > \\mathrm{B}_\\mathrm{P}$","$\\mathrm{B}_\\mathrm{P} = \\mathrm{B}_\\mathrm{Q} = \\mathrm{B}_\\mathrm{R}$","$\\mathrm{B}_\\mathrm{Q} > \\mathrm{B}_\\mathrm{P} > \\mathrm{B}_\\mathrm{R}$"]'::jsonb, 'فهم', 'ترتيب', 'سهل', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم'),
('mcq', 7, 'أيّ مما يأتي يزيد شدة المجال المغناطيسي عند نقطة قرب سلك مستقيم طويل يسري فيه تيار كهربائي؟', null, null, '["زيادة بُعد النقطة عن السلك مع بقاء التيار ثابتًا","عكس اتجاه التيار في السلك مع بقاء مقداره ثابتًا","زيادة مقدار التيار المار في السلك مع بقاء البعد ثابتًا","استبدال سلك أطول بالسلك مع بقاء التيار والبعد ثابتين"]'::jsonb, 'تذكر', 'تذكر عوامل', 'سهل', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم'),
('essay', 1, '(a) اذكر العاملين المؤثرين في شدة المجال المغناطيسي حول سلك مستقيم طويل يسري فيه تيار، ونوع علاقة كل منهما بشدة المجال. (b) ماذا يحدث لشدة المجال عند نقطة معيّنة إذا زاد التيار إلى ثلاثة أمثاله؟ (c) ماذا يحدث لشدة المجال إذا ابتعدنا عن السلك إلى ثلاثة أمثال البعد مع ثبات التيار؟ (d) ماذا يحدث إذا حدث التغيران معًا؟', null, null, null, 'تذكر', 'تذكر عوامل وتطبيقها', 'متوسط', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم وص 78 (المسألة 6)'),
('essay', 2, 'يعطى المجال المغناطيسي الناتج عن سلك طويل يسري فيه تيار بالعلاقة $\mathrm{B} = (2\times10^{-7}\ \text{T.m/A})(\mathrm{I}/d)$، حيث $d$ البعد عن السلك. (a) نادرًا ما يمر في أسلاك التمديدات المنزلية تيار أكبر من 10 A. احسب المجال على بُعد 0.5 m من سلك يمر فيه هذا التيار، وقارنه بالمجال المغناطيسي الأرضي $\mathrm{B}_{\text{أرض}} = 5.0\times10^{-5}\ \text{T}$. (b) يسري في سلك لنقل القدرة الكهربائية تيار مقداره 200 A، وهو يرتفع 20 m عن سطح الأرض. احسب المجال الناتج عنه عند سطح الأرض، وقارنه بالمجال في الحالة (a).', null, null, null, 'تطبيق', 'حساب ومقارنة', 'متوسط', 'الكتاب ص 101–102 — السؤال 95'),
('essay', 3, 'يبين المنحنى الآتي العلاقة بين المجال المغناطيسي والبعد عن سلك مستقيم طويل يسري فيه تيار ثابت. (a) صف العلاقة التي يبينها المنحنى. (b) استعمل المنحنى لتحقق أن المجال يتناسب عكسيًا مع البعد. (c) استنتج من المنحنى مقدار المجال على بُعد 5.0 cm من السلك. (d) استعمل العلاقة $\mathrm{B} = (2\times10^{-7}\ \text{T.m/A})(\mathrm{I}/d)$ لحساب التيار المار في السلك. (e) إذا ضوعف التيار فكم يصبح المجال على بُعد 2.0 cm؟', null, '[{"src":"qimg/phys32/c3l1-o06-graph.svg","alt":"منحنى بياني: المحور الأفقي «البعد عن السلك (cm)» من 0 إلى 6 بتدريج كل 1، والمحور الرأسي «المجال المغناطيسي (µT)» من 0 إلى 70 بتدريج كل 10. منحنى أخضر متناقص يمر بالنقاط المعلّمة: (1, 60)، (1.5, 40)، (2, 30)، (3, 20)، (4, 15)، (6, 10)؛ ينحدر بشدة عند الأبعاد الصغيرة ثم يقل انحداره."}]'::jsonb, null, 'تحليل', 'تحليل منحنى وحساب', 'صعب', 'الكتاب ص 76 — المجال المغناطيسي لسلك مستقيم وص 101 (السؤال 95)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
