from (values
('mcq', 1, 1, 'تتناسب شدة المجال المغناطيسي المتولد حول سلك مستقيم وطويل طرديًا مع مقدار التيار المار في السلك، وعكسيًا مع البعد عنه.', '["شدة المجال حول السلك الطويل تعتمد على التيار والبعد عنه، لا على طول السلك أو مادته.","","مساحة المقطع والمقاومة لا تظهران في العلاقة؛ فالتيار المار هو المؤثر لا مقاومة السلك.","اتجاه التيار يحدد اتجاه المجال لا شدته، ولون العازل لا أثر له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (62%)"}],"at":"2026-11-28T06:03:18.323Z"}'::jsonb),
('mcq', 2, 3, 'تتناسب شدة المجال المغناطيسي المتولد حول سلك مستقيم وطويل طرديًا مع مقدار التيار المار في السلك، وعكسيًا مع البعد عنه.', '["العلاقة عكسية مع البعد نفسه لا مع مربعه؛ فهذا خلط بقانون التربيع العكسي.","هذا عكس العلاقة؛ فزيادة التيار تقوي المجال، والابتعاد عن السلك يضعفه.","المجال يضعف كلما ابتعدنا عن السلك؛ فالعلاقة مع البعد عكسية لا طردية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-28T06:03:18.323Z"}'::jsonb),
('mcq', 3, 0, 'شدة المجال تتناسب عكسيًا مع البعد عن السلك؛ فعند مضاعفة البعد ثلاث مرات تقل الشدة إلى الثلث.', '["","التُّسع ينتج عن جعل التناسب عكسيًا مع مربع البعد، والعلاقة عكسية مع البعد نفسه.","جعل العلاقة طردية مع البعد خطأ؛ فالمجال يضعف بالابتعاد عن السلك.","المجال يعتمد على البعد عن السلك، فلا يبقى ثابتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-28T06:03:18.324Z"}'::jsonb),
('mcq', 4, 2, 'مضاعفة التيار تضاعف المجال (×2)، وتنصيف البعد يضاعفه مرة أخرى (×2) لأن العلاقة عكسية مع البعد؛ فيصبح المجال 4 أمثال قيمته الأصلية.', '["جعل أثر التيار وأثر البعد يلغي أحدهما الآخر خطأ؛ فكلاهما هنا يزيد المجال.","أخذ أثر التيار وحده (×2) وإهمال أثر تنصيف البعد الذي يضاعف المجال أيضًا.","","عكس العلاقتين معًا؛ فزيادة التيار وتقليل البعد كلاهما يقوي المجال لا يضعفه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.324Z"}'::jsonb),
('mcq', 5, 3, 'بالتعويض: $\mathrm{B} = (2\times10^{-7}\ \text{T.m/A})(15\ \text{A}/0.30\ \text{m}) = 1.0\times10^{-5}\ \text{T}$.', '["ضُرب التيار في البعد بدل القسمة عليه: $(2\\times10^{-7})(15)(0.30)$.","أُهمل البعد فحُسب $(2\\times10^{-7})(15)$ فقط.","قُسم البعد على التيار بدل قسمة التيار على البعد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.325Z"}'::jsonb),
('mcq', 6, 0, 'شدة المجال تتناسب عكسيًا مع البعد عن السلك؛ فأقرب نقطة (P) عندها أكبر مجال، ثم Q، ثم R الأبعد.', '["","هذا ترتيب عكسي؛ فالمجال يضعف بزيادة البعد لا يقوى.","المجال حول السلك ليس منتظمًا؛ فهو يقل كلما ابتعدنا عن السلك.","لا يوجد سبب لأن يكون المجال عند Q أكبر منه عند P الأقرب إلى السلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-28T06:03:18.325Z"}'::jsonb),
('mcq', 7, 2, 'شدة المجال المغناطيسي حول سلك مستقيم طويل تتناسب طرديًا مع مقدار التيار المار فيه وعكسيًا مع البعد عنه؛ فزيادة التيار مع ثبات البعد تزيد شدة المجال.', '["زيادة البعد عن السلك تُضعف المجال لأن العلاقة مع البعد عكسية.","عكس اتجاه التيار يعكس اتجاه المجال، ولا يغيّر شدته ما دام مقدار التيار ثابتًا.","","شدة المجال حول السلك الطويل تعتمد على التيار والبعد عنه، لا على طول السلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (62%)"}],"at":"2026-11-28T06:03:18.325Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) مقدار التيار المار في السلك: العلاقة طردية؛ والبعد عن السلك: العلاقة عكسية. (b) تزداد شدة المجال إلى ثلاثة أمثالها. (c) تقل شدة المجال إلى ثلثها. (d) لا تتغير شدة المجال؛ لأن الزيادة ثلاث مرات بسبب التيار يقابلها نقصان إلى الثلث بسبب البعد.', '["التيار: علاقة طردية","البعد: علاقة عكسية","ثلاثة أمثال التيار ← ثلاثة أمثال المجال","ثلاثة أمثال البعد ← ثلث المجال","التغيران معًا ← لا تغير"]'::jsonb, '[]'::jsonb, '[{"element":"العاملان ونوع العلاقة","marks":2},{"element":"الإجابة (b)","marks":1},{"element":"الإجابة (c)","marks":1},{"element":"الإجابة (d)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"العاملان بعلاقتيهما والحالات الثلاث صحيحة"},{"level":"3–4 درجات","description":"العاملان صحيحان مع خطأ في إحدى الحالات"},{"level":"1–2 درجة","description":"ذكر العاملين دون العلاقات أو حالة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جعل العلاقة مع البعد عكسية مع مربعه","ذكر طول السلك عاملًا مؤثرًا","جمع الأثرين بدل ضربهما في الحالة (d)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.326Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\mathrm{B} = (2\times10^{-7})\left(\frac{10}{0.5}\right) = 4\times10^{-6}\ \text{T}$، وهو يساوي $\frac{4\times10^{-6}}{5.0\times10^{-5}} = 0.08$ من المجال الأرضي، أي أقل منه بنحو 12 مرة. (b) $\mathrm{B} = (2\times10^{-7})\left(\frac{200}{20}\right) = 2\times10^{-6}\ \text{T}$، وهو نصف المجال في الحالة (a)؛ فمع أن التيار أكبر بعشرين مرة فإن البعد أكبر بأربعين مرة.', '["حساب (a) صحيح: $4\\times10^{-6}\\ \\text{T}$","مقارنة (a) بالمجال الأرضي (0.08 منه)","حساب (b) صحيح: $2\\times10^{-6}\\ \\text{T}$","مقارنة (b) بـ (a): النصف مع التعليل"]'::jsonb, '["$\\mathrm{B}_\\mathrm{a} = (2\\times10^{-7})(10)/(0.5) = 4\\times10^{-6}\\ \\text{T}$","$\\mathrm{B}_\\mathrm{a} / \\mathrm{B}_{\\text{أرض}} = 4\\times10^{-6} / 5.0\\times10^{-5} = 0.08$","$\\mathrm{B}_\\mathrm{b} = (2\\times10^{-7})(200)/(20) = 2\\times10^{-6}\\ \\text{T}$","$\\mathrm{B}_\\mathrm{b} / \\mathrm{B}_\\mathrm{a} = 0.5$"]'::jsonb, '[{"element":"حساب (a)","marks":1},{"element":"المقارنة بالمجال الأرضي","marks":1},{"element":"حساب (b)","marks":1},{"element":"المقارنة بين الحالتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان والمقارنتان صحيحة"},{"level":"2–3 درجات","description":"الحسابان صحيحان مع نقص في المقارنة أو العكس"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["ضرب التيار في البعد بدل القسمة","نسيان تحويل المقارنة إلى نسبة","الحكم بأن مجال خط النقل أكبر لأن تياره أكبر دون مراعاة البعد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.327Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) كلما زاد البعد عن السلك قلّ المجال المغناطيسي، والمنحنى ليس خطًا مستقيمًا. (b) عند 1.0 cm يكون المجال 60 µT، وعند 2.0 cm يكون 30 µT، وعند 3.0 cm يكون 20 µT؛ فحاصل ضرب المجال في البعد ثابت (60 µT·cm)، أي أن المجال يتناسب عكسيًا مع البعد. (c) $\mathrm{B} = \frac{60}{5.0} = 12\ \mu\text{T}$. (d) $\mathrm{I} = \frac{\mathrm{B}d}{2\times10^{-7}} = \frac{(60\times10^{-6})(0.010)}{2\times10^{-7}} = 3.0\ \text{A}$. (e) المجال يتناسب طرديًا مع التيار؛ فيتضاعف من 30 µT إلى 60 µT.', '["المجال يقل بزيادة البعد","التحقق: حاصل الضرب ثابت 60 µT·cm","المجال عند 5.0 cm يساوي 12 µT","التيار 3.0 A مع تحويل الوحدات","المجال الجديد 60 µT"]'::jsonb, '["من المنحنى: $(1.0)(60) = (2.0)(30) = (3.0)(20) = 60\\ \\mu\\text{T}\\cdot\\text{cm}$","$\\mathrm{B}(5.0\\ \\text{cm}) = 60/5.0 = 12\\ \\mu\\text{T}$","$\\mathrm{I} = \\mathrm{B}d/(2\\times10^{-7}) = (60\\times10^{-6})(0.010)/(2\\times10^{-7}) = 3.0\\ \\text{A}$","المجال الجديد $= 2 \\times 30 = 60\\ \\mu\\text{T}$"]'::jsonb, '[{"element":"وصف العلاقة","marks":1},{"element":"التحقق من التناسب العكسي","marks":1},{"element":"القيمة عند 5.0 cm","marks":1},{"element":"حساب التيار","marks":1},{"element":"المجال بعد مضاعفة التيار","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الخمسة صحيحة"},{"level":"3–4 درجات","description":"التحقق والحسابات صحيحة مع خطأ واحد"},{"level":"1–2 درجة","description":"وصف العلاقة أو قراءة صحيحة واحدة فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["نسيان تحويل µT إلى T وcm إلى m عند حساب التيار","الحكم بأن العلاقة خطية لأن المجال يقل","استعمال القسمة على مربع البعد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-28T06:03:18.327Z"}'::jsonb)
