('mcq', 4, 'يسري تيار اصطلاحي إلى أعلى في سلك رأسي كما في الشكل الآتي. ما اتجاه خطوط المجال المغناطيسي حول السلك كما يراها شخص ينظر من أعلى؟', null, '[{"src":"qimg/phys32/c3l1-o07-up.svg","alt":"سلك رأسي وبجانبه سهم إلى أعلى مكتوب عنده I (التيار الاصطلاحي إلى أعلى). يحيط بالسلك خط مجال أخضر على شكل حلقة أفقية (قطع ناقص في المنظور) بلا أسهم، ومكتوب بجانبها «خط مجال»."}]'::jsonb, '["عكس اتجاه حركة عقارب الساعة","مع اتجاه حركة عقارب الساعة","إلى أعلى، موازيًا للسلك","مبتعدة عن السلك في كل الاتجاهات"]'::jsonb, 'تطبيق', 'تطبيق قاعدة', 'متوسط', 'الكتاب ص 77 — القاعدة الأولى لليد اليمنى (الشكل 10-3)'),
('mcq', 5, 'شُدّ سلك مستقيم أفقيًا في اتجاه شرق–غرب، ووُضعت بوصلة فوقه مباشرة، ومُرّر فيه تيار اصطلاحي نحو الشرق. بإهمال أثر المجال المغناطيسي الأرضي، إلى أي اتجاه يشير القطب الشمالي لإبرة البوصلة؟', null, null, '["نحو الشمال","نحو الشرق","نحو الغرب","نحو الجنوب"]'::jsonb, 'تطبيق', 'تطبيق قاعدة', 'متوسط', 'الكتاب ص 78 — مسائل تدريبية (المسألة 5)'),
('mcq', 6, 'يبين الشكل الآتي مقطعًا لسلك مستقيم طويل عمودي على الصفحة، والتيار الاصطلاحي فيه داخل في الصفحة، والنقطة Q على يمين السلك. ما اتجاه المجال المغناطيسي عند Q؟', null, '[{"src":"qimg/phys32/c3l1-o07-q.svg","alt":"مقطع دائري لسلك عمودي على الصفحة داخله علامة × (التيار داخل في الصفحة)، ومكتوب تحته «التيار داخل في الصفحة». وعلى يمين السلك على خط أفقي متقطع النقطة Q."}]'::jsonb, '["نحو أعلى الصفحة","نحو أسفل الصفحة","نحو اليمين، مبتعدًا عن السلك","نحو اليسار، متجهًا إلى السلك"]'::jsonb, 'تطبيق', 'تطبيق قاعدة', 'صعب', 'الكتاب ص 77 — القاعدة الأولى لليد اليمنى'),
('mcq', 7, 'يبين الشكل الآتي منظرًا علويًا لأربع بوصلات حول سلك رأسي يخترق لوحًا أفقيًا ويسري فيه تيار، وإبر البوصلات تشكّل حلقة تدور مع اتجاه حركة عقارب الساعة كما نراها. ما اتجاه التيار الاصطلاحي في السلك؟', null, '[{"src":"qimg/phys32/c3l1-o07-card.svg","alt":"منظر علوي: مقطع دائري لسلك في المركز بلا علامة. حوله أربع بوصلات على أبعاد متساوية: البوصلة العلوية إبرتها الحمراء (القطب الشمالي) تشير نحو اليمين، والبوصلة اليمنى إبرتها الحمراء تشير نحو الأسفل، والبوصلة السفلية إبرتها الحمراء تشير نحو اليسار، والبوصلة اليسرى إبرتها الحمراء تشير نحو الأعلى."}]'::jsonb, '["خارج من الصفحة نحو الناظر","داخل في الصفحة مبتعدًا عن الناظر","في مستوى الصفحة نحو اليمين","لا يسري تيار؛ لأن الإبر تصطف في حلقة"]'::jsonb, 'تحليل', 'استنتاج اتجاه التيار', 'صعب', 'الكتاب ص 77 — القاعدة الأولى لليد اليمنى (الشكل 10-3)'),
('essay', 1, 'صف كيفية استخدام القاعدة الأولى لليد اليمنى لتحديد اتجاه المجال المغناطيسي حول سلك مستقيم يسري فيه تيار كهربائي، مبيّنًا: (a) ما يمثله الإبهام. (b) ما تمثله الأصابع. (c) نوع التيار الذي تُطبَّق عليه القاعدة. (d) ما يحدث لاتجاه المجال عند عكس اتجاه التيار.', null, null, null, 'تذكر', 'وصف قاعدة', 'سهل', 'الكتاب ص 77 — القاعدة الأولى لليد اليمنى وص 80 (السؤال 12) وص 96 (السؤال 38)'),
('essay', 2, 'يسري تيار اصطلاحي نحو اليمين في سلك مستقيم طويل في مستوى الصفحة، والنقطة A فوق السلك والنقطة B تحته كما في الشكل الآتي. (a) استعمل القاعدة الأولى لليد اليمنى لتحديد اتجاه المجال المغناطيسي عند كل من A وB، موضحًا خطوات التطبيق. (b) كيف تمثّل المجال عند كل نقطة بالرموز المستعملة للمجال العمودي على الصفحة؟ (c) ماذا يحدث للإجابتين إذا عُكس اتجاه التيار؟', null, '[{"src":"qimg/phys32/c3l1-o07-e-ab.svg","alt":"سلك مستقيم أفقي في مستوى الصفحة، وفوقه سهم نحو اليمين مكتوب عنده I (التيار الاصطلاحي نحو اليمين). النقطة A فوق السلك والنقطة B تحته، كلتاهما قرب منتصف السلك."}]'::jsonb, null, 'تطبيق', 'تطبيق قاعدة', 'متوسط', 'الكتاب ص 77 — القاعدة الأولى لليد اليمنى وص 98 (السؤال 63)'),
('essay', 3, 'يسري تيار اصطلاحي إلى أسفل في سلك رأسي طويل يخترق سطح طاولة أفقية، ووُضعت على الطاولة بوصلتان صغيرتان: K شرق السلك، وM شمال السلك (أهمل المجال المغناطيسي الأرضي). (a) استعمل القاعدة الأولى لليد اليمنى لتحديد اتجاه دوران خطوط المجال حول السلك كما تُرى من أعلى. (b) حدّد الاتجاه الذي يشير إليه القطب الشمالي لإبرة كل من K وM. (c) وُضعت بوصلة ثالثة على الطاولة فأشار قطبها الشمالي نحو الغرب؛ أين موضعها بالنسبة إلى السلك؟ (d) إذا عُكس التيار ليسري إلى أعلى، فإلى أين يشير القطب الشمالي لإبرة K؟ فسّر كل إجابة.', null, null, null, 'تحليل', 'تنبؤ وتفسير', 'صعب', 'الكتاب ص 76–77 — القاعدة الأولى لليد اليمنى (الشكل 10-3)')
