from (values
('mcq', 1, 2, 'تُستخدم القاعدة الأولى لليد اليمنى في تحديد اتجاه المجال المغناطيسي حول سلك مستقيم بالنسبة إلى اتجاه التيار الاصطلاحي.', '["القاعدة الثانية لليد اليمنى تحدد اتجاه مجال المغناطيس الكهربائي (الملف) وقطبيه، لا مجال السلك المستقيم.","القاعدة الثالثة لليد اليمنى تحدد اتجاه القوة المؤثرة في سلك يسري فيه تيار موضوع في مجال مغناطيسي.","","قاعدة التنافر والتجاذب تحدد نوع القوة بين قطبين، لا اتجاه المجال حول سلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.328Z"}'::jsonb),
('mcq', 2, 1, 'تخيل أنك تمسك بيدك اليمنى قطعة من سلك معزول، واجعل إبهامك في اتجاه التيار الاصطلاحي؛ ستشير أصابعك التي تدور حول السلك إلى اتجاه المجال المغناطيسي.', '["هذا تبديل لدوري الإبهام والأصابع؛ فالإبهام للتيار والأصابع للمجال.","","القاعدة تُطبَّق على التيار الاصطلاحي لا على حركة الإلكترونات المعاكسة له.","السلك المستقيم ليس له قطب شمالي؛ ولفّ الأصابع في اتجاه التيار وتحديد القطب بالإبهام هو القاعدة الثانية للملف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-28T06:03:18.328Z"}'::jsonb),
('mcq', 3, 3, 'تُستخدم القاعدة الأولى لليد اليمنى في تحديد اتجاه المجال المغناطيسي حول سلك مستقيم بالنسبة إلى اتجاه التيار الاصطلاحي؛ فهي تعطي اتجاهًا لا مقدارًا.', '["القاعدة تحدد الاتجاه فقط، ولا تعطي مقدار المجال.","تحديد قطبي المغناطيس الكهربائي يتم بالقاعدة الثانية لليد اليمنى.","تحديد اتجاه القوة المؤثرة في سلك داخل مجال يتم بالقاعدة الثالثة لليد اليمنى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-28T06:03:18.329Z"}'::jsonb),
('mcq', 4, 0, 'بالقاعدة الأولى لليد اليمنى: الإبهام إلى أعلى (في اتجاه التيار، أي نحو الناظر من أعلى) فتلتف الأصابع عكس اتجاه حركة عقارب الساعة كما يراها الناظر من أعلى.', '["","اتجاه حركة عقارب الساعة كما يُرى من أعلى يكون لتيار يسري إلى أسفل (مبتعدًا عن الناظر).","المجال لا يكون موازيًا للسلك؛ فهو يدور حوله في دوائر.","خطوط المجال حول السلك دائرية، لا شعاعية تخرج منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-28T06:03:18.329Z"}'::jsonb),
('mcq', 5, 3, 'بالقاعدة الأولى لليد اليمنى: الإبهام نحو الشرق، فتلتف الأصابع حول السلك؛ فتكون فوق السلك متجهة نحو الجنوب، وتحته متجهة نحو الشمال. والبوصلة فوق السلك، فيشير قطب إبرتها الشمالي نحو الجنوب.', '["الشمال هو اتجاه المجال تحت السلك لا فوقه.","المجال حول السلك عمودي على اتجاه التيار، فلا يكون نحو الشرق.","المجال عمودي على السلك (شرق–غرب)، فلا يكون نحو الغرب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-28T06:03:18.329Z"}'::jsonb),
('mcq', 6, 1, 'بالقاعدة الأولى لليد اليمنى: الإبهام داخل في الصفحة، فتلتف الأصابع مع اتجاه حركة عقارب الساعة كما نراها. وعند نقطة على يمين السلك يكون المماس لهذه الدائرة متجهًا نحو أسفل الصفحة.', '["نحو أعلى الصفحة عند Q يكون إذا كان التيار خارجًا من الصفحة (دوران عكس عقارب الساعة).","","المجال حول السلك مماس لدوائر حوله، لا شعاعي مبتعد عنه.","المجال حول السلك مماس لدوائر حوله، لا شعاعي متجه إليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-28T06:03:18.329Z"}'::jsonb),
('mcq', 7, 1, 'القطب الشمالي لكل إبرة يشير في اتجاه المجال، فالمجال يدور مع اتجاه حركة عقارب الساعة. وبالقاعدة الأولى لليد اليمنى: لكي تلتف الأصابع مع اتجاه عقارب الساعة كما نراها يجب أن يشير الإبهام مبتعدًا عن الناظر؛ فالتيار داخل في الصفحة (إلى أسفل).', '["التيار الخارج من الصفحة نحو الناظر يولّد مجالًا يدور عكس اتجاه حركة عقارب الساعة.","","السلك رأسي يخترق اللوح، فالتيار فيه عمودي على الصفحة لا في مستواها.","اصطفاف الإبر في حلقة حول السلك دليل على وجود مجال ناتج عن التيار؛ فبدون تيار تشير الإبر كلها نحو الشمال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-28T06:03:18.330Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نتخيل أننا نمسك السلك المعزول بيدنا اليمنى. (a) نجعل الإبهام في اتجاه التيار الاصطلاحي. (b) تشير الأصابع التي تدور حول السلك إلى اتجاه المجال المغناطيسي (اتجاه خطوط المجال الدائرية). (c) تُطبَّق القاعدة على التيار الاصطلاحي (من الطرف الموجب إلى الطرف السالب)، لا على حركة الإلكترونات. (d) عند عكس اتجاه التيار ينعكس الإبهام فينعكس اتجاه التفاف الأصابع، أي ينعكس اتجاه المجال.', '["الإمساك بالسلك باليد اليمنى","الإبهام في اتجاه التيار الاصطلاحي","الأصابع الملتفة تشير إلى اتجاه المجال","القاعدة للتيار الاصطلاحي","عكس التيار يعكس المجال"]'::jsonb, '[]'::jsonb, '[{"element":"الإمساك باليد اليمنى","marks":1},{"element":"دور الإبهام","marks":1},{"element":"دور الأصابع","marks":1},{"element":"نوع التيار","marks":1},{"element":"أثر عكس التيار","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"العناصر الخمسة صحيحة"},{"level":"3–4 درجات","description":"دورا الإبهام والأصابع صحيحان مع نقص آخر"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تبديل دوري الإبهام والأصابع","استعمال اتجاه حركة الإلكترونات","استعمال اليد اليسرى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.330Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) نمسك السلك باليد اليمنى بحيث يشير الإبهام نحو اليمين (اتجاه التيار)، فتلتف الأصابع حول السلك: تخرج من الصفحة فوق السلك وتدخل فيها تحته. إذن المجال عند A خارج من الصفحة نحو الناظر، وعند B داخل في الصفحة. (b) عند A يُرسم الرمز • (المجال خارج من الصفحة)، وعند B يُرسم الرمز × (المجال داخل في الصفحة). (c) ينعكس الاتجاهان: يصبح المجال عند A داخلًا في الصفحة (×) وعند B خارجًا منها (•).', '["الإبهام نحو اليمين والأصابع ملتفة حول السلك","عند A خارج من الصفحة","عند B داخل في الصفحة","التمثيل بالرمزين • و×","انعكاس الاتجاهين عند عكس التيار"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات التطبيق","marks":1},{"element":"الاتجاه عند A","marks":1},{"element":"الاتجاه عند B","marks":1},{"element":"الرموز","marks":1},{"element":"أثر عكس التيار","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الاتجاهان والرموز والخطوات وأثر العكس صحيحة"},{"level":"3–4 درجات","description":"الاتجاهان صحيحان مع نقص في الخطوات أو الرموز"},{"level":"1–2 درجة","description":"اتجاه واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جعل المجال عند A وB في مستوى الصفحة","تبديل الرمزين • و×","جعل المجال عند A وB في الاتجاه نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.330Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) نمسك السلك باليد اليمنى ونجعل الإبهام إلى أسفل في اتجاه التيار (مبتعدًا عن الناظر من أعلى)، فتلتف الأصابع مع اتجاه حركة عقارب الساعة كما تُرى من أعلى؛ فخطوط المجال دوائر حول السلك تدور مع اتجاه حركة عقارب الساعة. (b) إذا كان الشمال إلى أعلى المنظر العلوي والشرق إلى يمينه، فإن المماس لدائرة تدور مع عقارب الساعة يتجه عند نقطة شرق السلك نحو الجنوب، وعند نقطة شمال السلك نحو الشرق؛ فيشير القطب الشمالي لإبرة K نحو الجنوب، ولإبرة M نحو الشرق. (c) المماس لهذه الدائرة يتجه نحو الغرب عند نقطة جنوب السلك؛ فالبوصلة الثالثة جنوب السلك. (d) عكس التيار يعكس اتجاه المجال، فتدور الخطوط عكس اتجاه حركة عقارب الساعة كما تُرى من أعلى، ويشير القطب الشمالي لإبرة K نحو الشمال.', '["الإبهام إلى أسفل والأصابع تدور مع عقارب الساعة كما تُرى من أعلى","إبرة K نحو الجنوب","إبرة M نحو الشرق","البوصلة الثالثة جنوب السلك","بعد عكس التيار تشير إبرة K نحو الشمال"]'::jsonb, '[]'::jsonb, '[{"element":"تطبيق القاعدة واتجاه الدوران","marks":1},{"element":"اتجاه إبرة K","marks":1},{"element":"اتجاه إبرة M","marks":1},{"element":"موضع البوصلة الثالثة","marks":1},{"element":"أثر عكس التيار","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الأربعة صحيحة مع تفسير بالقاعدة"},{"level":"3–4 درجات","description":"اتجاه الدوران وإبرتا K وM صحيحة مع خطأ في (c) أو (d)"},{"level":"1–2 درجة","description":"اتجاه الدوران أو اتجاه إبرة واحدة صحيح فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جعل الدوران عكس عقارب الساعة لتيار يسري إلى أسفل كما يُرى من أعلى","جعل إبرة البوصلة تشير نحو السلك أو مبتعدة عنه","الخلط بين موضع البوصلة الثالثة شمال السلك وجنوبه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.331Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
