from (values
('mcq', 1, 'مع أيّ مما يأتي تتناسب شدة المجال المغناطيسي الناتج في ملف لولبي (بلا قلب) تناسبًا طرديًا؟', null, null, '["مقدار التيار المار فيه وعدد لفاته","مقاومة سلكه ومساحة مقطعه","طول سلكه المستقيم قبل لفّه ولون عازله","قطر سلكه ونوع مادة عازله"]'::jsonb, 'تذكر', 'تذكر عوامل', 'سهل', 'الكتاب ص 77 — المجال المغناطيسي لملف لولبي'),
('mcq', 2, 'أيّ التغييرات الآتية يزيد قوة مغناطيس كهربائي دون تغيير التيار أو عدد اللفات؟', null, null, '["عكس اتجاه التيار في الملف","وضع قضيب حديدي (قلب) داخل الملف","استبدال قلب زجاجي بالقلب الحديدي","استعمال سلك أكبر مساحة مقطع بالتيار نفسه"]'::jsonb, 'تذكر', 'تذكر عامل', 'سهل', 'الكتاب ص 77 — المجال المغناطيسي لملف لولبي (القلب الحديدي)'),
('mcq', 3, 'لماذا يزيد وضع قلب حديدي داخل ملف يسري فيه تيار من شدة المجال المغناطيسي؟', null, null, '["لأن الحديد يقلل مقاومة الملف فيزداد التيار المار فيه","لأن الحديد يزيد عدد لفات الملف","لأن مجال الملف يولّد مجالًا مغناطيسيًا مؤقتًا في القلب يضاف إلى مجاله","لأن الحديد مغناطيس دائم يضيف مجاله سواء سرى التيار أم لم يسرِ"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 77 — المجال المغناطيسي لملف لولبي (القلب الحديدي)'),
('mcq', 4, 'أيّ العوامل الآتية لا يؤثر في مقدار المجال المغناطيسي لملف لولبي؟', null, null, '["عدد اللفات","مقدار التيار","نوع قلب الملف","مساحة مقطع السلك"]'::jsonb, 'تذكر', 'تمييز عامل', 'متوسط', 'الكتاب ص 103 — اختبار مقنن (السؤال 5)'),
('mcq', 5, 'يبين الشكل الآتي ثلاثة ملفات لولبية A وB وC متساوية الطول وبلا قلب حديدي، مع عدد لفات كل منها والتيار المار فيه. ما الترتيب الصحيح لشدة المجال المغناطيسي داخلها من الأكبر إلى الأصغر؟', null, '[{"src":"qimg/phys32/c3l1-o08-coils.svg","alt":"ثلاثة ملفات لولبية أفقية متساوية الطول مرسومة متجاورة: الملف A وتحته «عدد اللفات: 50» و«التيار: 2 A» ولفاته متباعدة؛ الملف B وتحته «عدد اللفات: 100» و«التيار: 2 A»؛ الملف C وتحته «عدد اللفات: 100» و«التيار: 4 A». وفي الأسفل عبارة «الملفات الثلاثة متساوية الطول وبلا قلب حديدي»."}]'::jsonb, '["A ثم B ثم C","B ثم C ثم A","C ثم A ثم B","C ثم B ثم A"]'::jsonb, 'تطبيق', 'مقارنة وترتيب', 'متوسط', 'الكتاب ص 77 — المجال المغناطيسي لملف لولبي'),
('mcq', 6, 'يعمل مغناطيس كهربائي جيدًا، وأردت أن تجعل قوته قابلة للتعديل والضبط بسهولة في أثناء التشغيل. ما أنسب طريقة؟', null, null, '["وصل مقاومة متغيرة على التوالي مع الملف لتغيير التيار المار فيه","قلب أطراف البطارية بين حين وآخر لعكس اتجاه التيار","تغيير لون عازل السلك الملفوف حول القلب","وصل مقاومة صغيرة جدًّا على التوازي مع البطارية"]'::jsonb, 'تطبيق', 'اختيار طريقة', 'سهل', 'الكتاب ص 78 — مسائل تدريبية (المسألة 9)'),
('mcq', 7, 'في تجربة صنع مغناطيس كهربائي، غيّر طالب عدد لفات الملف حول مسمار مع إبقاء التيار ثابتًا، وعدّ مشابك الورق التي يرفعها المغناطيس، فحصل على الجدول الآتي. ما الاستنتاج الذي تدعمه البيانات؟', '{"headers":["عدد اللفات","عدد مشابك الورق المرفوعة"],"rows":[["10","3"],["20","6"],["30","9"],["40","12"]]}'::jsonb, null, '["قوة المغناطيس تتناسب عكسيًا مع عدد اللفات عند ثبات التيار","قوة المغناطيس لا تعتمد على عدد اللفات عند ثبات التيار","قوة المغناطيس تتناسب طرديًا مع عدد اللفات عند ثبات التيار","قوة المغناطيس تتناسب طرديًا مع التيار عند ثبات عدد اللفات"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 92–93 — مختبر الفيزياء: صنع مغناطيس كهربائي'),
('essay', 1, 'اذكر ثلاث طرائق لزيادة شدة المجال المغناطيسي لمغناطيس كهربائي، ووضّح سبب تأثير كل طريقة.', null, null, null, 'تذكر', 'تذكر عوامل مع التعليل', 'متوسط', 'الكتاب ص 77 — المجال المغناطيسي لملف لولبي'),
('essay', 2, 'صمّم تجربة لاختبار أثر عدد اللفات في قوة مغناطيس كهربائي، باستعمال: مسمار فولاذي، وسلك معزول، وبطارية، ومشابك ورق صغيرة. حدّد: (a) المتغير المستقل والمتغير التابع. (b) متغيرين يجب إبقاؤهما ثابتين. (c) طريقة قياس قوة المغناطيس. (d) النتيجة المتوقعة.', null, null, null, 'تطبيق', 'تصميم تجربة', 'صعب', 'الكتاب ص 92–93 — مختبر الفيزياء: صنع مغناطيس كهربائي'),
('essay', 3, 'أردت الحصول على مغناطيس كهربائي قوي لاستخدامه في حيز صغير داخل جهاز. (a) اقترح ثلاث طرائق لزيادة قوته دون زيادة حجمه كثيرًا، مع التعليل. (b) قيّم اقتراح زميلك: «لنعكس اتجاه التيار في الملف لنحصل على مغناطيس أقوى». (c) أيّ الطرائق أسهل إذا أردت تغيير قوة المغناطيس في أثناء العمل؟ ولماذا؟', null, null, null, 'تقويم', 'اقتراح وتقييم', 'صعب', 'الكتاب ص 77–78 (المسائل 8–9) وص 93 (الفيزياء في الحياة)')
