('mcq', 1, 0, 'تتناسب شدة المجال المغناطيسي الناتج في ملف طرديًا مع مقدار التيار المار فيه ومع عدد لفاته؛ لأن المجالات المغناطيسية للّفات متساوية وفي الاتجاه نفسه فتتجمع.', '["","المقاومة ومساحة المقطع لا تظهران عاملين مباشرين؛ فالعبرة بالتيار المار وعدد اللفات.","طول السلك قبل اللف ولون العازل ليسا من عوامل شدة مجال الملف.","قطر السلك ومادة العازل ليسا من عوامل شدة مجال الملف؛ فالمؤثر هو التيار المار في الملف وعدد لفاته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-28T06:03:18.332Z"}'::jsonb),
('mcq', 2, 1, 'يمكن زيادة قوة المغناطيس الكهربائي بوضع قضيب حديدي (قلب) داخل الملف؛ حيث يدعم هذا القلب المجال المغناطيسي ويقويه.', '["عكس التيار يعكس قطبي المغناطيس الكهربائي ولا يغيّر قوته.","","الزجاج لا يتمغنط، فاستبداله بالحديد يُضعف المغناطيس الكهربائي.","مساحة مقطع السلك لا تؤثر في مقدار المجال المغناطيسي للملف ما دام التيار وعدد اللفات ثابتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.332Z"}'::jsonb),
('mcq', 3, 2, 'يعمل القلب على زيادة المجال المغناطيسي؛ لأن مجال الملف اللولبي يولّد مجالًا مغناطيسيًا مؤقتًا في القلب، تمامًا كما يعمل المغناطيس الدائم عند تقريبه إلى قطعة حديد، فيدعم القلب المجال ويقويه.', '["القلب داخل الملف لا يدخل في مسار التيار، فلا يغيّر مقاومته ولا التيار المار فيه.","عدد اللفات يتحدد بالسلك الملفوف، والقلب لا يغيّره.","","قلب الحديد المطاوع مغناطيس مؤقت يتمغنط بمجال الملف، ويفقد مغناطيسيته عند قطع التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-28T06:03:18.332Z"}'::jsonb),
('mcq', 4, 3, 'مقدار المجال المغناطيسي للملف يعتمد على مقدار التيار وعدد اللفات ونوع القلب داخله، أما مساحة مقطع السلك فلا تؤثر فيه.', '["زيادة عدد اللفات تزيد المجال؛ فالمجال يتناسب طرديًا مع عدد اللفات.","زيادة التيار تزيد المجال؛ فالمجال يتناسب طرديًا مع التيار.","القلب الحديدي يقوي المجال مقارنة بالهواء أو الزجاج؛ فنوع القلب مؤثر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.332Z"}'::jsonb),
('mcq', 5, 3, 'المجال يتناسب طرديًا مع كل من التيار وعدد اللفات. حاصل ضرب عدد اللفات في التيار: A: $50 \times 2 = 100$، B: $100 \times 2 = 200$، C: $100 \times 4 = 400$؛ فالترتيب C ثم B ثم A.', '["هذا عكس الترتيب الصحيح؛ فالملف A أقل لفات وتيار مساوٍ لـ B، فمجاله الأصغر.","C له عدد اللفات نفسه لـ B لكن تياره ضعف تيار B، فمجاله أكبر.","A له نصف لفات B بالتيار نفسه، فمجاله أصغر من مجال B لا أكبر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.332Z"}'::jsonb),
('mcq', 6, 0, 'شدة مجال المغناطيس الكهربائي تتناسب طرديًا مع التيار المار في الملف؛ والمقاومة المتغيرة الموصولة على التوالي تغيّر هذا التيار، فتضبط قوة المغناطيس.', '["","عكس اتجاه التيار يعكس القطبين ولا يغيّر قوة المغناطيس.","لون العازل لا يؤثر في التيار ولا في عدد اللفات.","مقاومة صغيرة جدًّا على التوازي مع البطارية تُحدث دائرة قصر ولا تضبط تيار الملف ضبطًا آمنًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-28T06:03:18.332Z"}'::jsonb),
('mcq', 7, 2, 'عند مضاعفة عدد اللفات من 10 إلى 20 تضاعف عدد المشابك من 3 إلى 6، وعند 30 و40 لفة صار 9 و12؛ فالنسبة بين عدد المشابك وعدد اللفات ثابتة (0.3)، والتناسب طردي عند ثبات التيار.', '["عدد المشابك يزداد بزيادة اللفات، فالعلاقة ليست عكسية.","عدد المشابك تغيّر بتغيّر عدد اللفات، فالقوة تعتمد عليه.","","العبارة صحيحة علميًا لكن البيانات لا تدعمها؛ لأن التيار أُبقي ثابتًا ولم يُغيَّر في التجربة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.333Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) زيادة مقدار التيار المار في الملف؛ لأن شدة المجال تتناسب طرديًا مع التيار. (2) زيادة عدد لفات الملف؛ لأن المجالات المغناطيسية للّفات متساوية وفي الاتجاه نفسه، فيكون المجال داخل الملف مساويًا لمجموع مجالات لفاته، فيتناسب طرديًا مع عددها. (3) وضع قضيب حديدي (قلب) داخل الملف؛ لأن مجال الملف يولّد مجالًا مغناطيسيًا مؤقتًا في القلب يدعم المجال ويقويه.', '["زيادة التيار (تناسب طردي)","زيادة عدد اللفات (مجموع مجالات اللفات)","وضع قلب حديدي (يتمغنط مؤقتًا ويقوي المجال)"]'::jsonb, '[]'::jsonb, '[{"element":"الطريقة الأولى مع السبب","marks":1},{"element":"الطريقة الثانية مع السبب","marks":1},{"element":"الطريقة الثالثة مع السبب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الطرائق الثلاث مع أسبابها"},{"level":"2 درجة","description":"طريقتان مع السبب، أو ثلاث دون أسباب"},{"level":"1 درجة","description":"طريقة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["ذكر زيادة سمك السلك طريقةً لتقوية المجال","القول إن عكس التيار يقوي المغناطيس","تفسير أثر القلب بأنه يزيد التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.333Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) المتغير المستقل: عدد لفات السلك حول المسمار؛ المتغير التابع: قوة المغناطيس مقيسة بعدد مشابك الورق التي يرفعها. (b) من المتغيرات الثابتة: البطارية نفسها (التيار نفسه)، والمسمار نفسه (القلب نفسه)، ونوع المشابك وحجمها، وطريقة الرفع. (c) نقرّب طرف المسمار من كومة المشابك ونعدّ المشابك التي يرفعها في كل مرة، ونكرر القياس ونأخذ المتوسط. (d) يزداد عدد المشابك المرفوعة بزيادة عدد اللفات؛ لأن شدة مجال الملف تتناسب طرديًا مع عدد لفاته.', '["المستقل: عدد اللفات","التابع: عدد المشابك المرفوعة","متغيران ثابتان صحيحان","طريقة القياس بعدّ المشابك","النتيجة: علاقة طردية"]'::jsonb, '[]'::jsonb, '[{"element":"المتغيران المستقل والتابع","marks":1},{"element":"المتغيران الثابتان","marks":1},{"element":"طريقة القياس","marks":1},{"element":"النتيجة المتوقعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التصميم كامل والنتيجة صحيحة"},{"level":"2–3 درجات","description":"تحديد المتغيرات صحيح مع نقص في القياس أو النتيجة"},{"level":"1 درجة","description":"تحديد المتغير المستقل فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تغيير البطارية وعدد اللفات معًا في التجربة نفسها","الخلط بين المتغير المستقل والتابع","توقع نقصان القوة بزيادة اللفات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.333Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) زيادة التيار المار في الملف (المجال يتناسب طرديًا معه)؛ وزيادة عدد اللفات بلفّها متراصة في طبقات حول القلب (المجال يتناسب طرديًا مع عدد اللفات)؛ واستعمال قلب حديدي داخل الملف بدل الهواء (يتمغنط مؤقتًا بمجال الملف فيقويه). (b) الاقتراح غير صحيح؛ لأن عكس اتجاه التيار يعكس قطبي المغناطيس الكهربائي فقط، ولا يغيّر مقدار التيار ولا عدد اللفات، فتبقى قوته كما هي. (c) تغيير التيار (بمقاومة متغيرة موصولة على التوالي مع الملف)؛ لأنه لا يحتاج إلى إعادة لفّ السلك أو تغيير القلب.', '["زيادة التيار مع التعليل","زيادة عدد اللفات مع التعليل","استعمال قلب حديدي مع التعليل","رفض اقتراح عكس التيار لأنه يعكس القطبين فقط","تغيير التيار بمقاومة متغيرة أسهل"]'::jsonb, '[]'::jsonb, '[{"element":"الطرائق الثلاث مع التعليل","marks":3},{"element":"تقييم الاقتراح","marks":1},{"element":"الطريقة الأسهل مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الطرائق الثلاث والتقييم والطريقة الأسهل صحيحة مع التعليل"},{"level":"3–4 درجات","description":"طريقتان أو ثلاث صحيحة مع تقييم صحيح"},{"level":"1–2 درجة","description":"طريقة واحدة أو تقييم صحيح فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["قبول اقتراح عكس التيار","اقتراح استعمال سلك أسمك لتقوية المجال","اقتراح قلب من الألومنيوم أو الزجاج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.333Z"}'::jsonb)
