('mcq', 1, 'ما اسم القاعدة التي تُستخدم في تحديد اتجاه المجال المغناطيسي الناتج عن مغناطيس كهربائي (ملف لولبي) بالنسبة إلى اتجاه سريان التيار الاصطلاحي؟', null, null, '["القاعدة الأولى لليد اليمنى","القاعدة الثالثة لليد اليمنى","قاعدة التنافر والتجاذب","القاعدة الثانية لليد اليمنى"]'::jsonb, 'تذكر', 'تسمية قاعدة', 'سهل', 'الكتاب ص 78 — القاعدة الثانية لليد اليمنى'),
('mcq', 2, 'ما نص القاعدة الثانية لليد اليمنى؟', null, null, '["أمسك الملف بيدك اليمنى واجعل إبهامك في اتجاه التيار؛ فتشير أصابعك إلى القطب الشمالي","أمسك الملف بيدك اليمنى ودوّر أصابعك حول اللفات في اتجاه التيار الاصطلاحي؛ فيشير إبهامك نحو القطب الشمالي","أمسك الملف بيدك اليمنى ودوّر أصابعك حول اللفات في اتجاه التيار الاصطلاحي؛ فيشير إبهامك نحو القطب الجنوبي","أمسك الملف بيدك اليمنى ودوّر أصابعك حول اللفات في اتجاه حركة الإلكترونات؛ فيشير إبهامك نحو القطب الشمالي"]'::jsonb, 'تذكر', 'نص قاعدة', 'سهل', 'الكتاب ص 78 — القاعدة الثانية لليد اليمنى (الشكل 12-3)'),
('mcq', 3, 'يمثل الشكل الآتي تطبيق القاعدة الثانية لليد اليمنى على ملف لولبي، ويبين اتجاه دوران الأصابع واتجاه الإبهام. وفق القاعدة، ماذا يمثل اتجاه دوران الأصابع، وماذا يمثل الطرف X؟', null, '[{"src":"qimg/phys32/c3l1-o09-hand.svg","alt":"ملف لولبي أفقي طرفه الأيمن مكتوب عنده X وطرفه الأيسر مكتوب عنده Y. سهم بنفسجي منحنٍ يلتف حول الملف قرب منتصفه، يتجه على الجزء الأمامي من الملف إلى أسفل، ومكتوب تحته «اتجاه دوران الأصابع». وفوق الملف سهم برتقالي مستقيم يتجه نحو اليمين (نحو X) مكتوب بجانبه «اتجاه الإبهام»."}]'::jsonb, '["الأصابع: اتجاه خطوط المجال خارج الملف؛ وX: القطب الجنوبي","الأصابع: اتجاه حركة الإلكترونات؛ وX: القطب الشمالي","الأصابع: اتجاه التيار الاصطلاحي في اللفات؛ وX: القطب الجنوبي","الأصابع: اتجاه التيار الاصطلاحي في اللفات؛ وX: القطب الشمالي"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 78 — القاعدة الثانية لليد اليمنى (الشكل 12-3)'),
('mcq', 4, 'ما الفرق بين دوري الإبهام والأصابع في القاعدتين الأولى والثانية لليد اليمنى؟', null, null, '["في الأولى يشير الإبهام إلى التيار والأصابع إلى المجال، وفي الثانية تدور الأصابع مع التيار ويشير الإبهام إلى القطب الشمالي","في الأولى تدور الأصابع مع التيار ويشير الإبهام إلى القطب الشمالي، وفي الثانية يشير الإبهام إلى التيار والأصابع إلى المجال","لا فرق بينهما؛ ففي القاعدتين يشير الإبهام إلى التيار وتدور الأصابع مع المجال","في الأولى يشير الإبهام إلى المجال والأصابع إلى التيار، وفي الثانية يشير الإبهام إلى التيار والأصابع إلى القطب الشمالي"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 77–78 — القاعدتان الأولى والثانية لليد اليمنى'),
('mcq', 5, 'عند تطبيق القاعدة الثانية لتحديد قطبي مغناطيس كهربائي، أيّ يد تُستعمل، وأيّ تيار تتبعه الأصابع؟', null, null, '["اليد اليسرى، والتيار الاصطلاحي","اليد اليمنى، والتيار الاصطلاحي","اليد اليمنى، واتجاه حركة الإلكترونات","اليد اليسرى، واتجاه حركة الإلكترونات"]'::jsonb, 'تذكر', 'شروط تطبيق قاعدة', 'سهل', 'الكتاب ص 78 — القاعدة الثانية لليد اليمنى'),
('mcq', 6, 'وفق القاعدة الثانية لليد اليمنى يشير الإبهام نحو القطب الشمالي للمغناطيس الكهربائي. ماذا يدل عليه ذلك بشأن اتجاه المجال المغناطيسي داخل الملف؟', null, null, '["المجال داخل الملف يتجه نحو القطب الجنوبي، أي عكس اتجاه الإبهام","المجال داخل الملف عمودي على محوره ويدور مع الأصابع","المجال داخل الملف يتجه في اتجاه الإبهام نحو القطب الشمالي","لا يوجد مجال داخل الملف؛ لأن مجالات اللفات تلغي بعضها"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 78 — القاعدة الثانية لليد اليمنى وص 74 وص 77'),
('mcq', 7, 'أراد طالب تحديد القطب الشمالي لمغناطيس كهربائي، فدوّر أصابع يده اليمنى حول اللفات في اتجاه حركة الإلكترونات في السلك بدلًا من اتجاه التيار الاصطلاحي. ما نتيجة هذا الخطأ؟', null, null, '["يحدد القطب الشمالي تحديدًا صحيحًا؛ لأن اتجاه التيار لا يؤثر في القطبية","لا يحصل على أي نتيجة؛ لأن الإبهام يصبح موازيًا للفات","يحدد القطبين صحيحين لكن يخطئ في شدة المجال","يعدّ القطب الجنوبي شماليًا؛ لأن حركة الإلكترونات معاكسة لاتجاه التيار الاصطلاحي"]'::jsonb, 'تحليل', 'تحليل خطأ', 'صعب', 'الكتاب ص 78 — القاعدة الثانية لليد اليمنى، وص 12 — التيار الاصطلاحي'),
('essay', 1, 'صف كيفية استخدام القاعدة الثانية لليد اليمنى لتحديد قطبي مغناطيس كهربائي، مبيّنًا: (a) كيف تُمسك الملف. (b) ما تمثله الأصابع. (c) ما يشير إليه الإبهام. (d) كيف تحدد القطب الجنوبي بعد ذلك.', null, null, null, 'تذكر', 'وصف قاعدة', 'متوسط', 'الكتاب ص 78 — القاعدة الثانية لليد اليمنى وص 96 (السؤال 40)'),
('essay', 2, 'قارن بين القاعدة الأولى لليد اليمنى والقاعدة الثانية لليد اليمنى من حيث: (a) الموصل الذي تُطبَّق عليه كل منهما. (b) ما يمثله الإبهام. (c) ما تمثله الأصابع. (d) ما تحدده كل قاعدة.', null, null, null, 'فهم', 'مقارنة', 'صعب', 'الكتاب ص 77–78 ومفردات ص 95'),
('essay', 3, '(a) لماذا يشبه مجال ملف لولبي يسري فيه تيار مجال قضيب مغناطيسي؟ (b) وضّح كيف تربط القاعدة الثانية لليد اليمنى بين اتجاه التيار في اللفات واتجاه خطوط المجال داخل الملف وخارجه. (c) ماذا يحدث لنمط برادة الحديد المرشوشة على لوح زجاجي فوق المغناطيس الكهربائي إذا عُكست قطبية مصدر الجهد؟ فسّر.', null, null, null, 'فهم', 'تفسير وربط', 'صعب', 'الكتاب ص 78 — القاعدة الثانية لليد اليمنى وص 77 وص 80 (السؤال 13)')
