from (values
('mcq', 1, 3, 'تُستخدم القاعدة الثانية لليد اليمنى في تحديد اتجاه المجال المغناطيسي الناتج عن مغناطيس كهربائي بالنسبة إلى اتجاه سريان التيار الاصطلاحي.', '["القاعدة الأولى لليد اليمنى تحدد اتجاه المجال حول سلك مستقيم.","القاعدة الثالثة لليد اليمنى تحدد اتجاه القوة المؤثرة في سلك يسري فيه تيار داخل مجال مغناطيسي.","قاعدة التنافر والتجاذب تحدد نوع القوة بين قطبين، لا اتجاه مجال الملف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.334Z"}'::jsonb),
('mcq', 2, 1, 'تخيل أنك تمسك بيدك اليمنى ملفًا معزولًا؛ فإذا دوّرت أصابعك حول الحلقات في اتجاه سريان التيار الاصطلاحي فسيشير إبهامك نحو القطب الشمالي للمغناطيس الكهربائي.', '["هذا تبديل لدوري الإبهام والأصابع؛ ففي القاعدة الثانية تلتف الأصابع مع التيار ويشير الإبهام إلى القطب الشمالي.","","الإبهام يشير نحو القطب الشمالي لا الجنوبي.","القاعدة تُطبَّق على التيار الاصطلاحي لا على حركة الإلكترونات المعاكسة له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.334Z"}'::jsonb),
('mcq', 3, 3, 'في القاعدة الثانية لليد اليمنى تدور الأصابع حول اللفات في اتجاه سريان التيار الاصطلاحي، ويشير الإبهام نحو القطب الشمالي؛ والإبهام في الشكل يشير نحو X فهو القطب الشمالي.', '["الأصابع في القاعدة الثانية تمثل التيار لا المجال، والإبهام يشير إلى القطب الشمالي لا الجنوبي.","القاعدة تُطبَّق على التيار الاصطلاحي لا على حركة الإلكترونات.","الإبهام يشير نحو القطب الشمالي؛ فالطرف X الذي يشير إليه الإبهام شمالي لا جنوبي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.335Z"}'::jsonb),
('mcq', 4, 0, 'في القاعدة الأولى (سلك مستقيم) يكون الإبهام في اتجاه التيار الاصطلاحي وتشير الأصابع الملتفة إلى اتجاه المجال. وفي القاعدة الثانية (ملف) تدور الأصابع حول اللفات في اتجاه التيار ويشير الإبهام نحو القطب الشمالي.', '["","هذا تبديل للقاعدتين؛ فالسلك المستقيم (الأولى) ليس له قطب شمالي.","دورا الإبهام والأصابع متبادلان بين القاعدتين؛ ففي الثانية تمثل الأصابع التيار لا المجال.","في الأولى يمثل الإبهام التيار لا المجال، والأصابع لا تشير إلى قطب في أي من القاعدتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.335Z"}'::jsonb),
('mcq', 5, 1, 'القاعدة الثانية لليد اليمنى تُطبَّق باليد اليمنى، وتدور الأصابع حول الحلقات في اتجاه سريان التيار الاصطلاحي.', '["القاعدة لليد اليمنى؛ واستعمال اليسرى يعطي القطب المعاكس.","","الأصابع تتبع التيار الاصطلاحي، واتجاه حركة الإلكترونات معاكس له.","في هذا البديل خطآن: اليد اليسرى وحركة الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.335Z"}'::jsonb),
('mcq', 6, 2, 'خطوط المجال تخرج من القطب الشمالي خارج المغناطيس وتكمل دورتها داخله من القطب الجنوبي إلى الشمالي؛ فداخل الملف يتجه المجال في اتجاه الإبهام نحو القطب الشمالي.', '["المجال يتجه من S إلى N داخل المغناطيس، أي في اتجاه الإبهام لا عكسه.","مجالات اللفات داخل الملف تتجمع في اتجاه محوره، والأصابع تمثل التيار لا المجال.","","مجالات اللفات متساوية وفي الاتجاه نفسه فتتجمع؛ فالمجال داخل الملف قوي لا منعدم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.335Z"}'::jsonb),
('mcq', 7, 3, 'حركة الإلكترونات معاكسة لاتجاه التيار الاصطلاحي؛ فتدوير الأصابع معها يجعل الإبهام يشير في الاتجاه المعاكس، أي نحو القطب الجنوبي، فيظنه الطالب شماليًا.', '["قطبية المغناطيس الكهربائي تعتمد على اتجاه التيار؛ فعكس الاتجاه المتّبع يعكس النتيجة.","الإبهام يبقى على امتداد محور الملف، لكنه يشير إلى الطرف المعاكس.","القاعدة تحدد الاتجاه لا الشدة؛ والخطأ هنا يعكس القطبين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.335Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) نتخيل أننا نمسك الملف المعزول بيدنا اليمنى. (b) ندوّر الأصابع حول الحلقات (اللفات) في اتجاه سريان التيار الاصطلاحي فيها. (c) يشير الإبهام نحو القطب الشمالي للمغناطيس الكهربائي. (d) القطب الجنوبي هو الطرف الآخر للملف المقابل للطرف الذي يشير إليه الإبهام.', '["الإمساك باليد اليمنى","الأصابع تدور مع التيار الاصطلاحي في اللفات","الإبهام يشير إلى القطب الشمالي","الطرف المقابل هو القطب الجنوبي"]'::jsonb, '[]'::jsonb, '[{"element":"طريقة الإمساك","marks":1},{"element":"دور الأصابع","marks":1},{"element":"دور الإبهام","marks":1},{"element":"تحديد القطب الجنوبي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"دورا الأصابع والإبهام صحيحان مع نقص آخر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جعل الإبهام في اتجاه التيار","استعمال اتجاه حركة الإلكترونات","القول إن الإبهام يشير إلى القطب الجنوبي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.336Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الأولى تُطبَّق على سلك مستقيم يسري فيه تيار، والثانية على ملف (مغناطيس كهربائي). (b) في الأولى يكون الإبهام في اتجاه التيار الاصطلاحي، وفي الثانية يشير الإبهام نحو القطب الشمالي للمغناطيس الكهربائي. (c) في الأولى تشير الأصابع الملتفة حول السلك إلى اتجاه المجال المغناطيسي، وفي الثانية تدور الأصابع حول اللفات في اتجاه التيار الاصطلاحي. (d) الأولى تحدد اتجاه المجال المغناطيسي حول السلك، والثانية تحدد اتجاه المجال الناتج عن المغناطيس الكهربائي وقطبيه.', '["الموصل: سلك مستقيم / ملف","الإبهام: التيار / القطب الشمالي","الأصابع: المجال / التيار","ما تحدده: اتجاه المجال حول السلك / قطبا المغناطيس الكهربائي"]'::jsonb, '[]'::jsonb, '[{"element":"الموصل","marks":1},{"element":"الإبهام","marks":1},{"element":"الأصابع","marks":1},{"element":"ما تحدده كل قاعدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المقارنة صحيحة في البنود الأربعة"},{"level":"2–3 درجات","description":"بندان أو ثلاثة صحيحة"},{"level":"1 درجة","description":"بند واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تبديل دوري الإبهام والأصابع بين القاعدتين","نسبة تحديد القطب الشمالي إلى القاعدة الأولى","الخلط مع القاعدة الثالثة الخاصة بالقوة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.336Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) لأن مجالات اللفات متساوية وفي الاتجاه نفسه فتتجمع، فيصبح للملف قطبان شمالي وجنوبي، ويشبه مجاله مجال المغناطيس الدائم. (b) بتدوير أصابع اليد اليمنى مع التيار الاصطلاحي في اللفات يشير الإبهام نحو القطب الشمالي؛ فخطوط المجال داخل الملف تتجه في اتجاه الإبهام (من الطرف الجنوبي إلى الطرف الشمالي)، وخارجه تخرج من القطب الشمالي وتلتف لتدخل في القطب الجنوبي، مكوّنة حلقات مغلقة. (c) يبقى نمط البرادة كما هو؛ لأن البرادة تبيّن شكل خطوط المجال لا اتجاهها، أما اتجاه المجال فينعكس وينعكس القطبان (وهذا تُظهره بوصلة لا البرادة).', '["تجمع مجالات اللفات فيصبح للملف قطبان","الإبهام في اتجاه المجال داخل الملف نحو القطب الشمالي","خارج الملف من N إلى S في حلقات مغلقة","النمط لا يتغير لأن البرادة لا تبين الاتجاه","ينعكس الاتجاه والقطبان"]'::jsonb, '[]'::jsonb, '[{"element":"الإجابة (a)","marks":1},{"element":"المجال داخل الملف","marks":1},{"element":"المجال خارج الملف","marks":1},{"element":"النمط لا يتغير مع التعليل","marks":1},{"element":"انعكاس الاتجاه والقطبين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الثلاثة صحيحة كاملة مع التفسير"},{"level":"3–4 درجات","description":"جزءان صحيحان مع نقص في الثالث"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن المجال داخل الملف يتجه نحو القطب الجنوبي","القول إن نمط البرادة ينقلب أو يختفي عند عكس المصدر","نسيان أن الخطوط حلقات مغلقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.336Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C3-L1-O09') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L1-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثل الشكل الآتي ملفًا لولبيًّا يسري فيه تيار كهربائي، وتبيّن الأسهم على اللفات الأمامية اتجاه التيار الاصطلاحي. أيّ العبارات الآتية تصف قطبي الملف؟', null, '[{"src":"qimg/phys32/c3l1-o10-coil.svg","alt":"ملف لولبي أفقي من سلك نحاسي له سبع لفات. اللفات الأمامية مرسومة بخط متصل مائل من أعلى إلى أسفل، والأجزاء الخلفية بخط متقطع باهت. على كل لفة أمامية سهم يتجه من أعلى إلى أسفل يبين اتجاه التيار الاصطلاحي. يدخل التيار I من سلك رأسي عند أعلى الطرف الأيسر (سهم نحو الأسفل)، ويخرج من سلك رأسي عند أسفل الطرف الأيمن (سهم نحو الأسفل). الطرف الأيسر للملف معلّم بالحرف X، والطرف الأيمن بالحرف Y."}]'::jsonb, '["القطب الشمالي X، والجنوبي Y","الطرفان X وY قطبان شماليان","لا قطبين للملف دون قلب حديدي","القطب الشمالي Y، والجنوبي X"]'::jsonb, 'تطبيق', 'تحديد قطبي مغناطيس كهربائي', 'متوسط', 'الكتاب ص 77–78 — المجال المغناطيسي لملف لولبي والقاعدة الثانية لليد اليمنى (الشكل 12-3)'),
('mcq', 2, 'صنع طالب مغناطيسًا كهربائيًّا بلفّ سلك حول مسمار، ثم وصل طرفي السلك ببطارية كما في الشكل الآتي (الخطوط المتصلة هي الأجزاء الأمامية من اللفات، والمتقطعة أجزاؤها الخلفية خلف المسمار). أيّ طرفي المسمار يصبح قطبًا شماليًّا؟', null, '[{"src":"qimg/phys32/c3l1-o10-nail.svg","alt":"مسمار حديدي أفقي، طرفه المسطح (الرأس) على اليسار، وطرفه المدبب على اليمين. لُفّ حوله سلك نحاسي سبع لفات: الجزء الأمامي من كل لفة خط متصل مائل يصل من أعلى المسمار عند موضع ما إلى أسفله عند موضع أبعد قليلًا إلى اليمين، والجزء الخلفي (خلف المسمار) خط متقطع باهت يصل أسفل كل لفة أمامية بأعلى اللفة الأمامية التي تليها إلى اليمين. الطرف الأيسر للسلك يخرج من أعلى اللفة اليسرى ويلتف إلى اليسار ثم ينزل إلى أسفل الشكل ويتصل بالقطب السالب (اللوح القصير) لبطارية. الطرف الأيمن للسلك يخرج من أسفل اللفة اليمنى، ويمتد إلى اليمين ثم ينزل ويتصل بالقطب الموجب (اللوح الطويل، المعلّم بالإشارة +) للبطارية."}]'::jsonb, '["الطرف المسطح (الرأس)","الطرف المدبب","الطرفان المسطح والمدبب معًا","منتصف المسمار حيث تتركز اللفات"]'::jsonb, 'تطبيق', 'تحديد قطبي مغناطيس كهربائي', 'صعب', 'الكتاب ص 78 — مسألة تدريبية 7 (الشكل 13-3)'),
('mcq', 3, 'ينظر طالب إلى أحد طرفي ملف لولبي يسري فيه تيار، فيرى التيار يدور في اللفات كما في الشكل الآتي. ما نوع القطب عند طرف الملف المقابل للطالب؟', null, '[{"src":"qimg/phys32/c3l1-o10-end.svg","alt":"دائرة نحاسية تمثل طرف ملف لولبي كما يراه شخص يقف مقابله، وحولها سهمان منحنيان يبينان اتجاه التيار I في اللفات: السهم الأيمن يصعد من أسفل إلى أعلى، والسهم الأيسر ينزل من أعلى إلى أسفل، أي أن التيار يدور عكس اتجاه حركة عقارب الساعة كما يراه الناظر. أسفل الشكل عبارة: طرف الملف المقابل للناظر."}]'::jsonb, '["قطب جنوبي؛ لأن التيار يدور عكس عقارب الساعة","قطب شمالي فقط إذا كان داخل الملف قلب حديدي","قطب شمالي؛ لأن المجال داخل الملف يتجه نحو الطالب","لا قطب عنده؛ لأن القطبين يقعان على جانبي الملف"]'::jsonb, 'تطبيق', 'تحديد قطبي مغناطيس كهربائي', 'متوسط', 'الكتاب ص 98 — السؤال 65 (الشكل 31-3)'),
('mcq', 4, 'ملف لولبي يسري فيه تيار، قطبه الشمالي عند طرفه A وقطبه الجنوبي عند طرفه B. إذا عُكس اتجاه التيار في الملف دون تغيير طريقة لفّه، فماذا يحدث؟', null, null, '["يبقى A قطبًا شماليًّا؛ لأن اتجاه لفّ السلك لم يتغير","يصبح A قطبًا جنوبيًّا وB قطبًا شماليًّا","يفقد الملف قطبيه ويبقى مجاله داخله فقط","يصبح الطرفان A وB قطبين جنوبيين"]'::jsonb, 'فهم', 'تحديد قطبي مغناطيس كهربائي', 'سهل', 'الكتاب ص 77 — الملف الذي يسري فيه تيار مغناطيس له قطبان'),
('mcq', 5, 'وُضعت بوصلة صغيرة على امتداد محور الملف الموضح في الشكل الآتي، خارج الملف وقريبًا من طرفه Y. إلى أين يشير القطب الشمالي لإبرة البوصلة؟', null, '[{"src":"qimg/phys32/c3l1-o10-coil.svg","alt":"ملف لولبي أفقي من سلك نحاسي له سبع لفات. اللفات الأمامية مرسومة بخط متصل مائل من أعلى إلى أسفل، والأجزاء الخلفية بخط متقطع باهت. على كل لفة أمامية سهم يتجه من أعلى إلى أسفل يبين اتجاه التيار الاصطلاحي. يدخل التيار I من سلك رأسي عند أعلى الطرف الأيسر (سهم نحو الأسفل)، ويخرج من سلك رأسي عند أسفل الطرف الأيمن (سهم نحو الأسفل). الطرف الأيسر للملف معلّم بالحرف X، والطرف الأيمن بالحرف Y."}]'::jsonb, '["بعيدًا عن الملف على امتداد محوره","نحو الطرف Y على امتداد محور الملف","عموديًّا على محور الملف","لا تنحرف؛ لأن المجال خارج الملف معدوم"]'::jsonb, 'تحليل', 'تحديد قطبي مغناطيس كهربائي', 'متوسط', 'الكتاب ص 77–78 — المجال المغناطيسي لملف لولبي والقاعدة الثانية لليد اليمنى (الشكل 12-3)'),
('mcq', 6, 'يبين الشكل الآتي ملفين لولبيين متماثلين على محور واحد، وتبين الأسهم على لفاتهما الأمامية اتجاه التيار الاصطلاحي. ماذا يحدث للملفين؟', null, '[{"src":"qimg/phys32/c3l1-o10-pair.svg","alt":"ملفان لولبيان أفقيان متماثلان على محور واحد، لكل منهما خمس لفات، الملف 1 على اليسار والملف 2 على اليمين، وبينهما مسافة. اللفات الأمامية بخط متصل مائل والأجزاء الخلفية بخط متقطع. في الملف 1 الأسهم على اللفات الأمامية تتجه من أعلى إلى أسفل، وفي الملف 2 الأسهم على اللفات الأمامية تتجه من أسفل إلى أعلى، وتبين الأسهم اتجاه التيار الاصطلاحي."}]'::jsonb, '["يتجاذبان؛ لأن الطرفين المتقابلين قطبان مختلفان","يتنافران؛ لأن الطرفين المتقابلين قطبان جنوبيان","لا يؤثر أحدهما في الآخر لعدم وجود قلب حديدي","يتنافران؛ لأن الطرفين المتقابلين قطبان شماليان"]'::jsonb, 'تحليل', 'تحديد قطبي مغناطيس كهربائي', 'صعب', 'الكتاب ص 77–78 — المجال المغناطيسي لملف لولبي والقاعدة الثانية لليد اليمنى (الشكل 12-3)'),
('mcq', 7, 'عُلّق الملف الموضح في الشكل الآتي أفقيًّا بخيط بحيث يدور بحرية، بعيدًا عن المغانط الأخرى، والتيار يسري فيه. عندما يستقر، أيّ طرفيه يتجه نحو الشمال الجغرافي؟', null, '[{"src":"qimg/phys32/c3l1-o10-coil.svg","alt":"ملف لولبي أفقي من سلك نحاسي له سبع لفات. اللفات الأمامية مرسومة بخط متصل مائل من أعلى إلى أسفل، والأجزاء الخلفية بخط متقطع باهت. على كل لفة أمامية سهم يتجه من أعلى إلى أسفل يبين اتجاه التيار الاصطلاحي. يدخل التيار I من سلك رأسي عند أعلى الطرف الأيسر (سهم نحو الأسفل)، ويخرج من سلك رأسي عند أسفل الطرف الأيمن (سهم نحو الأسفل). الطرف الأيسر للملف معلّم بالحرف X، والطرف الأيمن بالحرف Y."}]'::jsonb, '["أيّ طرف منهما بحسب وضعه لحظة تعليقه","الطرف X؛ لأن القطب الجنوبي يتجه نحو الشمال","الطرف Y؛ لأنه القطب الشمالي للملف","لا يستقر في اتجاه محدد لأنه ليس مغناطيسًا دائمًا"]'::jsonb, 'تطبيق', 'تحديد قطبي مغناطيس كهربائي', 'سهل', 'الكتاب ص 77–78 — المجال المغناطيسي لملف لولبي والقاعدة الثانية لليد اليمنى (الشكل 12-3)'),
('essay', 1, 'يمثل الشكل الآتي طرف ملف لولبي يسري فيه تيار كما يراه شخص يقف مقابله. (a) ما اتجاه المجال المغناطيسي داخل اللفات؟ (b) ما اتجاه المجال المغناطيسي خارج اللفات حول الملف؟ (c) حدّد نوع القطب عند هذا الطرف، ووضّح كيف استخدمت القاعدة الثانية لليد اليمنى.', null, '[{"src":"qimg/phys32/c3l1-o10-end-cw.svg","alt":"دائرة نحاسية تمثل طرف ملف لولبي كما يراه شخص يقف مقابله، وحولها سهمان منحنيان يبينان اتجاه التيار I في اللفات: السهم الأيمن ينزل من أعلى إلى أسفل، والسهم الأيسر يصعد من أسفل إلى أعلى، أي أن التيار يدور مع اتجاه حركة عقارب الساعة كما يراه الناظر. أسفل الشكل عبارة: طرف الملف المقابل للناظر."}]'::jsonb, null, 'تطبيق', 'تحديد قطبي مغناطيس كهربائي', 'متوسط', 'الكتاب ص 98 — السؤال 65 (الشكل 31-3)'),
('essay', 2, 'صنع طالب مغناطيسًا كهربائيًّا بلفّ سلك معزول حول قضيب حديدي ووصله ببطارية، فصار يجذب مشابك الورق. (a) صف خطوات استخدام القاعدة الثانية لليد اليمنى لتحديد القطب الشمالي للمغناطيس الكهربائي. (b) إذا عكس الطالب قطبي البطارية، فماذا يحدث لقطبي المغناطيس الكهربائي؟ (c) هل يستمر المغناطيس الكهربائي في جذب المشابك بعد عكس البطارية؟ فسّر إجابتك.', null, null, null, 'تطبيق', 'تحديد قطبي مغناطيس كهربائي', 'سهل', 'الكتاب ص 78 والسؤال 40 ص 96 والسؤال 13 ص 80'),
('essay', 3, 'عُلّق مغناطيس دائم بخيط بحيث يواجه قطبه الجنوبي الطرف A لملف لولبي موضوع على الطاولة، ثم أُغلقت الدائرة فانجذب المغناطيس نحو الملف، مع أن الطالب كان يريد أن يتنافرا. (a) ما نوع القطب الذي تكوّن عند الطرف A، وما نوع القطب المطلوب عنده لتحقيق التنافر؟ (b) إذا أمسك الطالب الملف بيده اليمنى وإبهامه يشير نحو الطرف A، فهل كان اتجاه التيار في اللفات يطابق اتجاه أصابعه أم يعاكسه؟ وضّح. (c) اقترح طريقتين مختلفتين لتحقيق التنافر دون تغيير المغناطيس المعلّق.', null, null, null, 'تحليل', 'تحديد قطبي مغناطيس كهربائي', 'صعب', 'الكتاب ص 77–78 — المجال المغناطيسي لملف لولبي والقاعدة الثانية لليد اليمنى (الشكل 12-3)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C3-L1-O10') and x.type = v.type and x.number = v.number);
