from (values
('mcq', 1, 3, 'نطبق القاعدة الثانية لليد اليمنى: نُدوّر أصابع اليد اليمنى حول اللفات في اتجاه التيار الاصطلاحي فيشير الإبهام نحو القطب الشمالي. التيار في الجزء الأمامي من كل لفة يتجه من أعلى إلى أسفل، فإذا دُوّرت أصابع اليد اليمنى في هذا الاتجاه حول الملف أشار الإبهام نحو اليمين، أي نحو Y؛ فالطرف Y قطب شمالي والطرف X قطب جنوبي.', '["عكس القطبين؛ وهذا يحدث عند تدوير الأصابع عكس اتجاه التيار أو استعمال اليد اليسرى.","للمغناطيس الكهربائي قطبان مختلفان دائمًا، شمالي عند طرف وجنوبي عند الطرف الآخر.","الملف الذي يسري فيه تيار مغناطيس له قطبان حتى دون قلب؛ والقلب الحديدي يقوّي المجال فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.337Z"}'::jsonb),
('mcq', 2, 0, 'يسري التيار الاصطلاحي خارجًا من القطب الموجب للبطارية (اللوح الطويل على اليمين)، فيدخل الملف من أسفل اللفة اليمنى، ثم يصعد في الجزء الأمامي من كل لفة من أسفل إلى أعلى، ويلتف خلف المسمار إلى اللفة التي على يسارها، حتى يخرج من أعلى اللفة اليسرى عائدًا إلى القطب السالب. بتدوير أصابع اليد اليمنى في اتجاه هذا التيار (صاعدًا في الجزء الأمامي) يشير الإبهام إلى اليسار، فالطرف المسطح (الرأس) قطب شمالي، والطرف المدبب قطب جنوبي.', '["","هذا القطب الجنوبي؛ وينتج عن افتراض أن التيار يخرج من القطب السالب، أو عن تدوير الأصابع في عكس اتجاه التيار.","للمغناطيس الكهربائي قطبان مختلفان: إذا كان أحد طرفيه شماليًّا كان الآخر جنوبيًّا.","القطبان يتكونان عند طرفي الملف لا عند منتصفه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.337Z"}'::jsonb),
('mcq', 3, 2, 'التيار يدور عكس اتجاه حركة عقارب الساعة كما يراه الطالب. بتدوير أصابع اليد اليمنى في هذا الاتجاه يشير الإبهام نحو الطالب، فالمجال المغناطيسي داخل الملف يتجه نحو الطالب ويخرج من هذا الطرف؛ لذا فهو قطب شمالي.', '["ربط دوران التيار عكس عقارب الساعة بالقطب الجنوبي، وهذا عكس ما تعطيه القاعدة الثانية لليد اليمنى.","القطبان يتكونان في الملف الذي يسري فيه تيار حتى دون قلب؛ والقلب يقوّي المجال ولا يحدد نوع القطب.","","قطبا الملف اللولبي عند طرفيه (وجهيه)، لا على جانبيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-28T06:03:18.338Z"}'::jsonb),
('mcq', 4, 1, 'بحسب القاعدة الثانية لليد اليمنى يحدد اتجاه التيار في اللفات اتجاه الإبهام، أي موضع القطب الشمالي. عكس التيار يعكس اتجاه دوران الأصابع فيشير الإبهام نحو B؛ فيصبح B قطبًا شماليًّا وA قطبًا جنوبيًّا.', '["القطبية تتبع اتجاه التيار في اللفات؛ فعكس التيار مع بقاء طريقة اللف يعكس القطبين.","","يبقى الملف مغناطيسًا له قطبان ما دام التيار يسري فيه، وإنما يتبادل القطبان موضعيهما.","لا يكون للمغناطيس قطبان متشابهان عند طرفيه؛ فأحدهما شمالي والآخر جنوبي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.338Z"}'::jsonb),
('mcq', 5, 0, 'بالقاعدة الثانية لليد اليمنى: التيار في الجزء الأمامي من اللفات يتجه من أعلى إلى أسفل، فيشير الإبهام نحو Y، أي أن Y قطب شمالي. خطوط المجال تخرج من القطب الشمالي، والقطب الشمالي لإبرة البوصلة يشير في اتجاه المجال؛ لذا يشير بعيدًا عن الملف على امتداد محوره.', '["","هذا صحيح لو كان Y قطبًا جنوبيًّا؛ لكن Y هنا قطب شمالي فيتنافر مع القطب الشمالي للإبرة.","على امتداد المحور خارج الطرف يكون المجال موازيًا للمحور لا عموديًّا عليه.","للملف الذي يسري فيه تيار مجال خارجه يشبه مجال المغناطيس الدائم، وأقوى ما يكون قرب طرفيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.338Z"}'::jsonb),
('mcq', 6, 3, 'في الملف 1 يتجه التيار في اللفات الأمامية من أعلى إلى أسفل، فيشير الإبهام (القاعدة الثانية لليد اليمنى) نحو اليمين: قطبه الشمالي هو طرفه الأيمن. وفي الملف 2 يتجه التيار في اللفات الأمامية من أسفل إلى أعلى، فيشير الإبهام نحو اليسار: قطبه الشمالي هو طرفه الأيسر. لذا يتنافر الملفان؛ لأن الطرفين المتقابلين قطبان شماليان، والأقطاب المتشابهة تتنافر.', '["اتجاها التيار في الملفين متعاكسان، فيكون الطرفان المتقابلان قطبين متشابهين لا مختلفين.","النتيجة (تنافر) صحيحة لكن تحديد نوع القطبين معكوس؛ فالقاعدة الثانية تعطي قطبين شماليين متقابلين.","كل ملف يسري فيه تيار مغناطيس حتى دون قلب حديدي، فيؤثر كل منهما في الآخر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.339Z"}'::jsonb),
('mcq', 7, 2, 'بالقاعدة الثانية لليد اليمنى يكون الطرف Y هو القطب الشمالي للملف (الإبهام يشير نحو Y عند تدوير الأصابع في اتجاه التيار في اللفات). الملف الذي يسري فيه تيار يسلك سلوك المغناطيس، فإذا عُلّق حرًّا استقر في اتجاه شمال–جنوب وقطبه الشمالي Y نحو الشمال الجغرافي، كإبرة البوصلة.', '["المغناطيس المعلّق حرًّا يتخذ اتجاهًا معينًا (شمال–جنوب) أيًّا كان وضعه الأول.","القطب الشمالي لا الجنوبي هو الذي يتجه نحو الشمال الجغرافي، وX هنا قطب جنوبي.","","الملف الذي يسري فيه تيار مغناطيس له قطبان ما دام التيار يسري، فيستقر كما يستقر المغناطيس الدائم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.339Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) التيار يدور مع اتجاه حركة عقارب الساعة كما يراه الناظر؛ فإذا دُوّرت أصابع اليد اليمنى في هذا الاتجاه أشار الإبهام بعيدًا عن الناظر، فالمجال داخل اللفات يتجه بعيدًا عن الناظر (داخلًا إلى الصفحة). (b) خطوط المجال حلقات مغلقة، فخارج اللفات حول الملف يكون المجال في الاتجاه المعاكس، أي نحو الناظر (خارجًا من الصفحة). (c) خطوط المجال تدخل الملف من هذا الطرف، فهو قطب جنوبي، والقطب الشمالي عند الطرف البعيد الذي يشير إليه الإبهام.', '["المجال داخل اللفات بعيدًا عن الناظر (داخل إلى الصفحة)","المجال خارج اللفات نحو الناظر (خارج من الصفحة)","الطرف المقابل قطب جنوبي","وصف القاعدة: الأصابع مع التيار والإبهام نحو القطب الشمالي"]'::jsonb, '[]'::jsonb, '[{"element":"اتجاه المجال داخل اللفات","marks":1},{"element":"اتجاه المجال خارج اللفات","marks":1},{"element":"نوع القطب","marks":1},{"element":"وصف استخدام القاعدة الثانية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الاتجاهان ونوع القطب صحيحة مع وصف صحيح للقاعدة"},{"level":"2–3 درجات","description":"نوع القطب صحيح مع خطأ في أحد الاتجاهين أو في وصف القاعدة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["ربط الدوران مع عقارب الساعة بالقطب الشمالي","جعل المجال خارج اللفات في اتجاه المجال داخلها نفسه","استعمال اليد اليسرى أو جعل الإبهام في اتجاه التيار كما في القاعدة الأولى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-28T06:03:18.339Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) أمسك الملف بيدك اليمنى بحيث تلتف أصابعك حول اللفات في اتجاه سريان التيار الاصطلاحي (الخارج من القطب الموجب للبطارية)؛ فيشير إبهامك نحو القطب الشمالي للمغناطيس الكهربائي، ويكون الطرف الآخر قطبًا جنوبيًّا. (b) عكس البطارية يعكس اتجاه التيار في اللفات، فيشير الإبهام إلى الطرف الآخر: يتبادل القطبان موضعيهما. (c) نعم يستمر في جذبها؛ لأن المشابك الحديدية تتمغنط بالحث مغنطة مؤقتة يكون فيها طرفها القريب قطبًا مخالفًا لقطب المغناطيس الكهربائي أيًّا كان نوعه، فتنجذب إلى أيّ من القطبين.', '["الأصابع حول اللفات في اتجاه التيار الاصطلاحي","الإبهام يشير إلى القطب الشمالي","عكس البطارية يعكس التيار فيتبادل القطبان","يستمر الجذب لأن المشابك تتمغنط بالحث بقطب مخالف"]'::jsonb, '[]'::jsonb, '[{"element":"وصف وضع الأصابع والتيار","marks":1},{"element":"الإبهام نحو القطب الشمالي","marks":1},{"element":"تبادل القطبين عند عكس البطارية","marks":1},{"element":"استمرار الجذب مع التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"وصف القاعدة صحيح مع نقص في (b) أو (c)"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["جعل الإبهام في اتجاه التيار والأصابع نحو القطب","الاعتقاد أن عكس البطارية يجعل المغناطيس يطرد المشابك","الاعتقاد أن عكس البطارية يلغي المغناطيسية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-28T06:03:18.340Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) انجذاب القطب الجنوبي للمغناطيس يعني أن A قطب شمالي (الأقطاب المختلفة تتجاذب). والمطلوب للتنافر أن يكون A قطبًا جنوبيًّا مثل القطب المواجه له. (b) بما أن A قطب شمالي، فإن الإبهام يشير نحو A عندما تدور الأصابع في اتجاه التيار؛ أي أن اتجاه التيار في اللفات كان يطابق اتجاه الأصابع. (c) عكس قطبي البطارية لعكس اتجاه التيار في اللفات فيصبح A قطبًا جنوبيًّا، أو قلب الملف بحيث يواجه طرفه الآخر (الجنوبي) المغناطيس، أو إعادة لفّ السلك في الاتجاه المعاكس مع بقاء التوصيل.', '["A قطب شمالي لأنه جذب القطب الجنوبي","المطلوب أن يكون A قطبًا جنوبيًّا","التيار كان مطابقًا لاتجاه الأصابع لأن الإبهام يشير إلى القطب الشمالي A","طريقتان: عكس البطارية، قلب الملف، أو عكس اتجاه اللف"]'::jsonb, '[]'::jsonb, '[{"element":"نوع القطب المتكوّن عند A","marks":1},{"element":"القطب المطلوب للتنافر","marks":1},{"element":"تحليل اتجاه التيار بالقاعدة الثانية","marks":1},{"element":"طريقتان صحيحتان","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"التحليل كامل مع طريقتين صحيحتين"},{"level":"3–4 درجات","description":"تحديد القطبين صحيح مع نقص في (b) أو طريقة واحدة"},{"level":"1–2 درجة","description":"تحديد صحيح لنوع القطب عند A فقط"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["الاعتقاد أن الملف يجذب المغناطيس لأنه يجذب الحديد دائمًا مهما كان القطب","الخلط بين القاعدة الأولى (الإبهام مع التيار) والقاعدة الثانية","اقتراح زيادة التيار لتحقيق التنافر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.340Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
