from (values
('mcq', 1, 'ما اسم مجموعة الذرات المتجاورة التي تترتب المجالات المغناطيسية الخاصة بإلكتروناتها في الاتجاه نفسه؟', null, null, '["المجال المغناطيسي","المنطقة المغناطيسية","التدفق المغناطيسي","المغناطيس المستقطب"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 95 — المفردات: المنطقة المغناطيسية'),
('mcq', 2, 'يمثل الشكل الآتي قطعتين من الحديد مقسّمتين إلى مناطق مغناطيسية. ماذا يمثل كل سهم أخضر في الشكل؟', null, '[{"src":"qimg/phys32/c3l1-o11-domains.svg","alt":"مربعان أصفران يمثلان قطعتين من الحديد مقسّمتين إلى مناطق صغيرة، في كل منطقة سهم أخضر. في المربع (a) الأسهم الثلاثون تتجه في اتجاهات عشوائية مختلفة. في المربع (b) الأسهم الثلاثون كلها تتجه نحو اليمين في اتجاه واحد."}]'::jsonb, '["اتجاه حركة الإلكترونات الحرة في الحديد","اتجاه التيار الكهربائي المار في القطعة","اتجاه مجال إلكترون منفرد في ذرة واحدة","اتجاه مجال منطقة مغناطيسية واحدة"]'::jsonb, 'فهم', 'تفسير رسم', 'سهل', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('mcq', 3, 'قد تحتوي المنطقة المغناطيسية الواحدة على عدد كبير جدًّا من الذرات يصل إلى نحو', null, null, '["$10^{20}$ ذرة","$10^{6}$ ذرة","1000 ذرة","ذرة واحدة فقط"]'::jsonb, 'تذكر', 'حقائق', 'متوسط', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('mcq', 4, 'ما المدى الذي تقع فيه غالبًا أبعاد المنطقة المغناطيسية؟', null, null, '["من 10 إلى 1000 مليمتر","من 1 إلى 10 سنتيمترات","من 10 إلى 1000 ميكرون","بحجم ذرة واحدة تقريبًا"]'::jsonb, 'تذكر', 'حقائق', 'متوسط', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('mcq', 5, 'بُني مفهوم المناطق المغناطيسية على فكرة أساسية صائبة اقترحها أمبير. ما هذه الفكرة؟', null, null, '["لكل ذرة قطب مغناطيسي مفرد يبقى ثابتًا داخل المادة","نواة الذرة وحدها هي مصدر مغناطيسية المادة كلها","تنشأ المغناطيسية من احتكاك الذرات المتجاورة بعضها ببعض","كل إلكترون في الذرة يشبه مغناطيسًا كهربائيًّا صغيرًا"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('mcq', 6, 'لماذا تحتوي عينة صغيرة من الحديد على عدد هائل من المناطق المغناطيسية؟', null, null, '["لأن المنطقة صغيرة جدًّا، غالبًا من 10 إلى 1000 ميكرون","لأن كل ذرة حديد منفردة تمثل منطقة مغناطيسية مستقلة","لأن المناطق تتكون فقط عند وضع العينة في مجال مغناطيسي","لأن كل منطقة مغناطيسية تحتوي على إلكترون واحد فقط"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('mcq', 7, 'ممّ تتكون المنطقة المغناطيسية؟', null, null, '["من إلكترون واحد يدور حول نواة ذرة حديد منفردة","من ذرات متجاورة مجالات إلكتروناتها في اتجاه واحد","من قطعة حديد كاملة رُتّبت جميع مناطقها في اتجاه واحد","من ذرات متباعدة مجالات إلكتروناتها في اتجاهات عشوائية"]'::jsonb, 'فهم', 'تعريف مصطلح', 'صعب', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('essay', 1, '(a) عرّف المنطقة المغناطيسية. (b) اذكر العدد التقريبي للذرات الذي قد تحتويه منطقة مغناطيسية واحدة. (c) اذكر المدى الذي تقع فيه أبعادها غالبًا.', null, null, null, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('essay', 2, 'وضّح كيف بُني مفهوم المنطقة المغناطيسية على فكرة أمبير، ثم صف ماذا يمثل كل سهم في الشكل الآتي، وما الفرق بين ترتيب الأسهم في (a) وترتيبها في (b).', null, '[{"src":"qimg/phys32/c3l1-o11-domains.svg","alt":"مربعان أصفران يمثلان قطعتين من الحديد مقسّمتين إلى مناطق صغيرة، في كل منطقة سهم أخضر. في المربع (a) الأسهم الثلاثون تتجه في اتجاهات عشوائية مختلفة. في المربع (b) الأسهم الثلاثون كلها تتجه نحو اليمين في اتجاه واحد."}]'::jsonb, null, 'فهم', 'تفسير رسم', 'متوسط', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('essay', 3, 'عينة من الحديد على شكل مكعب طول ضلعه 1.0 cm. افترض أن كل منطقة مغناطيسية مكعب طول ضلعه 100 ميكرون (ضمن المدى المعتاد لأبعاد المناطق، و$1\ \mu\text{m} = 10^{-6}\ \text{m}$)، وأن المناطق متماثلة وتملأ العينة كلها دون فراغات. (a) كم منطقة مغناطيسية تقع على طول ضلع واحد للعينة؟ (b) ما العدد الكلي للمناطق المغناطيسية في العينة؟ (c) ماذا تستنتج عن حجم المنطقة المغناطيسية مقارنة بحجم العينة؟', null, null, null, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C3-L1-O11') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'عندما تترتب مجموعة المجالات المغناطيسية الخاصة بإلكترونات الذرات المتجاورة في الاتجاه نفسه تسمى هذه المجموعة المنطقة المغناطيسية.', '["المجال المغناطيسي هو المنطقة التي تؤثر فيها القوة المغناطيسية حول المغناطيس، لا مجموعة ذرات داخل المادة.","","التدفق المغناطيسي هو عدد خطوط المجال المغناطيسي التي تخترق السطح.","المستقطب وصف للمغناطيس الذي له قطبان متعاكسان، لا لمجموعة ذرات مرتبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-28T06:03:18.341Z"}'::jsonb),
('mcq', 2, 3, 'كل سهم يمثل منطقة مغناطيسية واحدة، أي مجموعة كبيرة من الذرات المتجاورة رُتّبت مجالات إلكتروناتها في الاتجاه نفسه؛ فيشير السهم إلى اتجاه مجال منطقة مغناطيسية واحدة.', '["الأسهم لا تمثل حركة شحنات، بل اتجاه المجال المغناطيسي لكل منطقة.","لا يسري تيار كهربائي في قطعة الحديد هنا؛ الأسهم تمثل مجالات المناطق.","المنطقة الواحدة تضم عددًا هائلًا من الذرات، فالسهم يمثل مجال المنطقة كلها لا مجال إلكترون واحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-28T06:03:18.341Z"}'::jsonb),
('mcq', 3, 0, 'المنطقة المغناطيسية مجموعة من الذرات المتجاورة قد تحتوي على $10^{20}$ ذرة مفردة، ومع ذلك تبقى صغيرة جدًّا.', '["","عدد أقل كثيرًا مما قد تحتويه المنطقة الواحدة ($10^{20}$ ذرة).","خلط بين عدد الذرات والحد الأعلى لأبعاد المنطقة (1000 ميكرون).","المنطقة مجموعة من الذرات المتجاورة لا ذرة مفردة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.341Z"}'::jsonb),
('mcq', 4, 2, 'على الرغم من أن المنطقة المغناطيسية قد تحتوي على $10^{20}$ ذرة، فإنها تبقى صغيرة جدًّا ومحدودة، غالبًا من 10 إلى 1000 ميكرون.', '["الأرقام صحيحة لكن الوحدة خاطئة؛ فالمليمتر أكبر من الميكرون ألف مرة.","هذه أبعاد قطعة حديد صغيرة كاملة، وهي تحتوي على عدد هائل من المناطق.","","المنطقة مجموعة كبيرة جدًّا من الذرات، فهي أكبر كثيرًا من ذرة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-28T06:03:18.341Z"}'::jsonb),
('mcq', 5, 3, 'على الرغم من أن التفصيلات التي اقترحها أمبير كانت غير صحيحة، فإن فكرته الأساسية صائبة: كل إلكترون في الذرة يشبه مغناطيسًا كهربائيًّا صغيرًا، وعندما تترتب مجالات إلكترونات الذرات المتجاورة في اتجاه واحد تتكون المنطقة المغناطيسية.', '["لا توجد أقطاب مغناطيسية مفردة؛ فلكل مغناطيس مهما صغر قطبان.","منشأ مغناطيسية المادة إلكترونات الذرة التي يشبه كل منها مغناطيسًا كهربائيًّا صغيرًا.","المغناطيسية لا تنشأ عن الاحتكاك؛ بل عن إلكترونات الذرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.341Z"}'::jsonb),
('mcq', 6, 0, 'المنطقة المغناطيسية صغيرة جدًّا ومحدودة (غالبًا من 10 إلى 1000 ميكرون)؛ لذا تحتوي عينة صغيرة من الحديد على عدد هائل من المناطق المغناطيسية.', '["","المنطقة الواحدة تضم عددًا كبيرًا جدًّا من الذرات (قد يصل إلى $10^{20}$ ذرة)، لا ذرة واحدة.","المناطق موجودة في الحديد دائمًا، لكنها تكون في اتجاهات عشوائية خارج المجال المغناطيسي.","المنطقة مجموعة من ذرات كثيرة لكل منها إلكترونات عديدة، لا إلكترون واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.341Z"}'::jsonb),
('mcq', 7, 1, 'المنطقة المغناطيسية مجموعة من الذرات المتجاورة رُتّبت المجالات المغناطيسية الخاصة بإلكتروناتها في الاتجاه نفسه.', '["الإلكترون الواحد يشبه مغناطيسًا كهربائيًّا صغيرًا، لكن المنطقة مجموعة كبيرة من الذرات.","","قطعة الحديد الكاملة تحتوي على عدد هائل من المناطق؛ فالمنطقة جزء صغير جدًّا منها.","المنطقة تتميز بأن ذراتها متجاورة ومجالات إلكتروناتها مرتبة في اتجاه واحد لا عشوائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-28T06:03:18.341Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) المنطقة المغناطيسية مجموعة من الذرات المتجاورة تترتب المجالات المغناطيسية الخاصة بإلكتروناتها في الاتجاه نفسه. (b) قد تحتوي على نحو $10^{20}$ ذرة مفردة. (c) تبقى صغيرة جدًّا ومحدودة، غالبًا من 10 إلى 1000 ميكرون.', '["مجموعة من الذرات المتجاورة","مجالات إلكتروناتها مرتبة في الاتجاه نفسه","نحو $10^{20}$ ذرة","من 10 إلى 1000 ميكرون"]'::jsonb, '[]'::jsonb, '[{"element":"ذرات متجاورة","marks":1},{"element":"مجالات الإلكترونات في اتجاه واحد","marks":1},{"element":"عدد الذرات","marks":1},{"element":"مدى الأبعاد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريف كامل مع العدد والمدى صحيحين"},{"level":"2–3 درجات","description":"التعريف صحيح مع نقص في العدد أو المدى"},{"level":"1 درجة","description":"جزء من التعريف فقط"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["تعريف المنطقة بأنها المنطقة المحيطة بالمغناطيس التي تظهر فيها القوة (وهذا المجال المغناطيسي)","إهمال شرط ترتّب المجالات في الاتجاه نفسه","كتابة الوحدة مليمترًا بدل ميكرون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-28T06:03:18.342Z"}'::jsonb),
('essay', 2, null::int, null, null, 'فكرة أمبير الأساسية الصائبة أن كل إلكترون في الذرة يشبه مغناطيسًا كهربائيًّا صغيرًا. وعندما تترتب المجالات المغناطيسية لإلكترونات مجموعة من الذرات المتجاورة في الاتجاه نفسه تتكون منطقة مغناطيسية لها مجال في اتجاه واحد. في الشكل يمثل كل سهم اتجاه المجال المغناطيسي لمنطقة مغناطيسية واحدة. في (a) تتجه مجالات المناطق في اتجاهات عشوائية مختلفة، وفي (b) تتجه مجالات المناطق كلها في اتجاه واحد.', '["كل إلكترون يشبه مغناطيسًا كهربائيًّا صغيرًا","ترتّب مجالات إلكترونات ذرات متجاورة في اتجاه واحد يكوّن المنطقة","السهم يمثل اتجاه مجال منطقة واحدة","في (a) عشوائية وفي (b) في اتجاه واحد"]'::jsonb, '[]'::jsonb, '[{"element":"فكرة أمبير","marks":1},{"element":"تكوّن المنطقة من ترتّب المجالات","marks":1},{"element":"معنى السهم","marks":1},{"element":"الفرق بين (a) و(b)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"عنصران أو ثلاثة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["جعل السهم يمثل إلكترونًا واحدًا أو ذرة واحدة","نسبة المغناطيسية إلى النواة","وصف الأسهم بأنها اتجاه التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-28T06:03:18.342Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) طول الضلع $1.0\ \text{cm} = 1.0\times10^{-2}\ \text{m} = 1.0\times10^{4}\ \mu\text{m}$، وعدد المناطق على طوله $\frac{1.0\times10^{4}}{100} = 100$ منطقة. (b) العدد الكلي $100\times100\times100 = 1.0\times10^{6}$ منطقة. (c) المنطقة المغناطيسية صغيرة جدًّا مقارنة بالعينة؛ لذا تحتوي عينة صغيرة من الحديد على عدد هائل من المناطق المغناطيسية.', '["تحويل 1.0 cm إلى $1.0\\times10^{4}\\ \\mu\\text{m}$","100 منطقة على طول الضلع","العدد الكلي $1.0\\times10^{6}$ منطقة","الاستنتاج: المنطقة صغيرة جدًّا والعينة تحتوي على عدد هائل منها"]'::jsonb, '["$1.0\\ \\text{cm} = 1.0\\times10^{-2}\\ \\text{m} = 1.0\\times10^{4}\\ \\mu\\text{m}$","عدد المناطق على الضلع $= \\frac{1.0\\times10^{4}\\ \\mu\\text{m}}{100\\ \\mu\\text{m}} = 100$","العدد الكلي $= 100^3 = 1.0\\times10^{6}$ منطقة"]'::jsonb, '[{"element":"تحويل الوحدات","marks":1},{"element":"عدد المناطق على الضلع","marks":1},{"element":"العدد الكلي (تكعيب)","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات والاستنتاج صحيحة"},{"level":"2–3 درجات","description":"التحويل والعدد على الضلع صحيحان مع خطأ في التكعيب أو الاستنتاج"},{"level":"1 درجة","description":"تحويل الوحدات فقط"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["قسمة 1.0 على 100 دون تحويل الوحدات","الاكتفاء بعدد المناطق على الضلع (100) دون تكعيب","تربيع العدد بدل تكعيبه ($10^{4}$)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.342Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
