insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L1-O12'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'بأيّ مما يأتي يتشابه المغناطيس الدائم والمغناطيس المؤقت؟', null, null, '["يحتفظ كلاهما بمغناطيسيته بعد إبعاد المجال الخارجي","يُصنع كلاهما من الحديد المطاوع القليل الكربون","يتمغنط كلاهما بالحث بترتب مناطقه في اتجاه المجال","لا يحتوي أيٌّ منهما على مناطق مغناطيسية قبل تمغنطه"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 73 و79 — المغناطيس الدائم، والمناطق المغناطيسية'),
('mcq', 2, 'من أيّ المواد يُصنع كثير من المغانط الدائمة؟', null, null, '["الحديد المطاوع الذي يحتوي على القليل من الكربون","سبيكة حديد مع الألومنيوم والنيكل والكوبالت","النحاس والألومنيوم النقيان دون خلطهما بالحديد","الزجاج المغطى بطبقة رقيقة من برادة الحديد"]'::jsonb, 'تذكر', 'حقائق', 'سهل', 'الكتاب ص 73 — كيف تؤثر المغانط في المواد الأخرى، والمغناطيس الدائم'),
('mcq', 3, 'قُرِّب مغناطيس قوي من عينتين فتمغنطتا، ثم أُبعد عنهما. يمثل الشكل الآتي ترتيب المناطق المغناطيسية في كل عينة بعد إبعاده. أيّ استنتاج صحيح؟', null, '[{"src":"qimg/phys32/c3l1-o12-after.svg","alt":"عنوان: بعد إبعاد المغناطيس عن العينتين. مربعان أصفران يمثلان عينتين مقسّمتين إلى مناطق مغناطيسية، في كل منطقة سهم أخضر يمثل اتجاه مجالها. في العينة 1 (يسار) الأسهم في اتجاهات عشوائية مختلفة. في العينة 2 (يمين) الأسهم كلها نحو اليمين في اتجاه واحد."}]'::jsonb, '["المغناطيس الدائم هو العينة 1","العينتان دائمتان؛ لأنهما تمغنطتا بالمغناطيس نفسه","العينتان مؤقتتان؛ لأن المغنطة بالحث مؤقتة دائمًا","المغناطيس الدائم هو العينة 2"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 79 — المناطق المغناطيسية والمغناطيس الدائم'),
('mcq', 4, 'اختبر طالب ثلاث عينات فلزية (A وB وC) بجعل كل منها ملامسة لمغناطيس دائم قوي ثم إبعاده عنها، وسجّل عدد مشابك الورق التي تحملها كل عينة كما في الجدول الآتي. أيّ العينات حديد مطاوع على الأرجح؟', '{"headers":["العينة","عدد المشابك المجذوبة والمغناطيس ملامس لها","عدد المشابك بعد إبعاد المغناطيس مباشرة","عدد المشابك بعد ساعة"],"rows":[["A","6","0","0"],["B","7","3","1"],["C","5","5","5"]]}'::jsonb, null, '["A؛ لأنها فقدت قدرتها على الجذب فور إبعاد المغناطيس","B؛ لأنها احتفظت ببعض مغناطيسيتها مدة قصيرة ثم فقدتها","C؛ لأنها احتفظت بالمشابك كلها بعد إبعاد المغناطيس","C؛ لأنها جذبت أقل عدد من المشابك قبل الإبعاد"]'::jsonb, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 73 — كيف تؤثر المغانط في المواد الأخرى، والمغناطيس الدائم'),
('mcq', 5, 'بماذا يُفسَّر احتفاظ المغناطيس الدائم بمغناطيسيته بعد إزالة المجال المغناطيسي الخارجي؟', null, null, '["تحتوي سبيكته على أقطاب مغناطيسية مفردة ثابتة","تبقى مناطق سبيكته مرتبة بعد إزالة المجال","يسري فيه تيار كهربائي دائم من مصدر داخل المغناطيس","تخلو مادته تمامًا من المناطق المغناطيسية"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 79 — المناطق المغناطيسية والمغناطيس الدائم'),
('mcq', 6, 'تُستعمل في رافعة نقل الخردة الحديدية مغناطيس كهربائي قلبه من الحديد المطاوع، لا من سبيكة مغناطيس دائم. ما سبب هذا الاختيار؟', null, null, '["الحديد المطاوع مغناطيس دائم أقوى من سبائك المغانط","السبائك المغناطيسية لا تتمغنط بالحث مطلقًا","الحديد المطاوع يتمغنط دون الحاجة إلى تيار في الملف","يفقد القلب مغناطيسيته عند قطع التيار فيُفلت الحمل"]'::jsonb, 'تحليل', 'تطبيق في الحياة', 'صعب', 'الكتاب ص 73 و77 — الحديد المطاوع مغناطيس مؤقت، وتطبيق الفيزياء: الكهرومغناطيسية'),
('mcq', 7, 'في لعبة قضيبان فلزيان أفقيان متوازيان أحدهما فوق الآخر، والعلوي حر الحركة إلى أعلى وإلى أسفل. كان القضيب العلوي يطفو فوق السفلي، فلما عُكس اتجاهه سقط نحو السفلي. ما الاستنتاج الصحيح؟', null, null, '["العلوي حديد مطاوع غير ممغنط والسفلي مغناطيس دائم","القضيبان من الحديد المطاوع وقد تمغنطا بالحث","القضيبان مغناطيسان دائمان تقابل قطباهما المتشابهان","السفلي غير ممغنط والعلوي مغناطيس دائم قوي"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 80 — مراجعة 3-1 السؤال 14'),
('essay', 1, 'قارن بين المغناطيس الدائم والمغناطيس المؤقت من حيث: (a) مثال على مادة يُصنع منها كل منهما. (b) سلوكه بعد إبعاد المجال المغناطيسي الخارجي. (c) ترتيب مناطقه المغناطيسية بعد إبعاد المجال.', null, null, null, 'تحليل', 'مقارنة', 'سهل', 'الكتاب ص 96 — السؤالان 33 و47'),
('essay', 2, 'انجذبت قطعة فلزية إلى أحد قطبي مغناطيس كبير. صف تجربة تعرف بها ما إذا كانت القطعة مغناطيسًا مؤقتًا أم مغناطيسًا دائمًا، مبيّنًا النتيجة المتوقعة في كل حالة وتفسيرها.', null, null, null, 'تحليل', 'تصميم تجربة', 'متوسط', 'الكتاب ص 96 — السؤالان 33 و47'),
('essay', 3, 'في لعبة قضيبان فلزيان أفقيان متوازيان أحدهما فوق الآخر، والعلوي حر الحركة رأسيًّا. السفلي مغناطيس دائم. فُقد القضيب العلوي واستُبدل به قضيب آخر، فصار يسقط نحو السفلي مهما كان اتجاهه. (a) ما نوع القضيب الجديد: مغناطيس دائم أم مغناطيس مؤقت (حديد غير ممغنط)؟ (b) فسّر سقوطه في الاتجاهين بدلالة المغنطة بالحث. (c) لماذا لم يكن ممكنًا أن يطفو؟', null, null, null, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 80 — مراجعة 3-1 السؤال 14')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
