from (values
('mcq', 1, 2, 'تتولد مغناطيسية المغناطيس الدائم بطريقة مشابهة للتي تتولد بها مغناطيسية المسمار أو الحديد المطاوع: عند وضع المادة في مجال مغناطيسي تترتب مناطقها المغناطيسية في اتجاه المجال الخارجي فتتمغنط بالحث. ويختلفان بعد إبعاد المجال: تعود مناطق المغناطيس المؤقت إلى عشوائيتها، وتبقى مناطق سبيكة المغناطيس الدائم مرتبة.', '["هذه صفة المغناطيس الدائم وحده؛ فالمؤقت يفقد مغناطيسيته عند إبعاد المجال.","الحديد المطاوع مادة المغناطيس المؤقت، أما الدائم فيُصنع من سبائك مثل سبيكة الحديد مع الألومنيوم والنيكل والكوبالت.","","المناطق المغناطيسية موجودة في المادة قبل تمغنطها، لكنها تكون في اتجاهات عشوائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.343Z"}'::jsonb),
('mcq', 2, 1, 'يُصنع العديد من المغانط الدائمة من سبيكة حديد تحتوي على خليط من الألومنيوم والنيكل والكوبالت، كما تُنتج عناصر ترابية نادرة مثل النيوديميوم والجادولينيوم مغانط دائمة قوية جدًّا مقارنة بأحجامها.', '["الحديد المطاوع مغناطيس مؤقت يفقد مغناطيسيته مباشرة عند إبعاد المجال.","","النحاس والألومنيوم النقيان لا ينجذبان إلى المغناطيس ولا يصنع منهما مغناطيس دائم.","الزجاج مادة غير مغناطيسية، ووضع البرادة عليه لا يجعله مغناطيسًا دائمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-28T06:03:18.343Z"}'::jsonb),
('mcq', 3, 3, 'في المغناطيس المؤقت تعود المناطق المغناطيسية إلى عشوائيتها بعد إزالة المجال الخارجي (العينة 1)، أما سبائك المغناطيس الدائم فتحافظ على المناطق مرتبة بعد إزالة المجال (العينة 2)؛ لذا المغناطيس الدائم هو العينة 2، والعينة 1 مغناطيس مؤقت.', '["عكس العينتين؛ فالمناطق العشوائية بعد إزالة المجال تدل على مغناطيس مؤقت.","التمغنط بالمغناطيس نفسه لا يجعل المغنطة دائمة؛ فالعينة 1 فقدت ترتيب مناطقها.","المغناطيسية المستحثة تصبح دائمة في بعض المواد بسبب تركيبها المجهري، كالعينة 2.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.343Z"}'::jsonb),
('mcq', 4, 0, 'الحديد المطاوع مغناطيس مؤقت يفقد كل جاذبيته للأجسام الفلزية مباشرة عند إبعاد المغناطيس، وهذا سلوك A التي فقدت قدرتها على الجذب فور إبعاد المغناطيس (من 6 مشابك إلى صفر). أما B فتشبه المسمار الذي يحتفظ ببعض مغناطيسيته ولا يطول جذبه، وC تسلك سلوك المغناطيس الدائم.', '["","هذا سلوك المسمار الذي يحتوي على معادن أخرى تتيح له الاحتفاظ ببعض مغناطيسيته.","الاحتفاظ بالمشابك بعد إبعاد المغناطيس صفة المغناطيس الدائم لا الحديد المطاوع.","عدد المشابك قبل الإبعاد لا يميز المغناطيس المؤقت من الدائم؛ المهم سلوك العينة بعد الإبعاد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.344Z"}'::jsonb),
('mcq', 5, 1, 'للحصول على مغناطيس دائم يُخلط الحديد مع مواد أخرى لإنتاج سبائك تحافظ على المناطق المغناطيسية مرتبة بعد إزالة تأثير المجال المغناطيسي الخارجي، أي تبقى مناطق سبيكته مرتبة بعد إزالة المجال، بخلاف المغناطيس المؤقت الذي تعود مناطقه إلى عشوائيتها.', '["لا توجد أقطاب مغناطيسية مفردة؛ فلكل مغناطيس قطبان.","","المغناطيس الدائم لا يحتاج إلى تيار؛ وهذا ما يميزه من المغناطيس الكهربائي.","مغناطيسيته ناتجة عن مناطقه المغناطيسية المرتبة، فهو لا يخلو منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.344Z"}'::jsonb),
('mcq', 6, 3, 'الحديد المطاوع مغناطيس مؤقت: يتمغنط بقوة ما دام التيار يسري في الملف، ويفقد القلب مغناطيسيته مباشرة عند قطع التيار فيُفلت الحمل (الخردة). أما قلب من سبيكة مغناطيس دائم فيبقى ممغنطًا بعد قطع التيار فلا يُفلت الحمل.', '["الحديد المطاوع مغناطيس مؤقت لا دائم.","السبائك تتمغنط بالحث أيضًا، لكن مغنطتها تبقى بعد إزالة المجال، وهذا غير مرغوب في الرافعة.","القلب يتمغنط بمجال الملف الذي يسري فيه التيار؛ فدون تيار لا يتمغنط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-28T06:03:18.344Z"}'::jsonb),
('mcq', 7, 2, 'الطفو يعني تنافرًا، والتنافر لا يحدث إلا بين قطبين متشابهين لمغناطيسين؛ لذا القضيبان مغناطيسان دائمان تقابل قطباهما المتشابهان قبل العكس. وعند عكس العلوي تتقابل أقطاب مختلفة فيتجاذبان ويسقط.', '["الحديد المطاوع غير الممغنط ينجذب إلى المغناطيس أيًّا كان اتجاهه، فلا يطفو فوقه.","المغنطة بالحث تجعل الطرف القريب قطبًا مخالفًا فيحدث تجاذب دائمًا لا تنافر.","","المغناطيس يجذب الحديد غير الممغنط بالحث، فلا يحدث طفو في أيّ اتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.344Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) المغناطيس الدائم: سبيكة حديد تحتوي على خليط من الألومنيوم والنيكل والكوبالت، أو عناصر ترابية نادرة مثل النيوديميوم والجادولينيوم. المغناطيس المؤقت: الحديد المطاوع (حديد يحتوي على القليل من الكربون). (b) الدائم يحتفظ بمغناطيسيته بعد إبعاد المجال الخارجي، أما المؤقت فيفقد كل جاذبيته للأجسام الفلزية مباشرة عند إبعاد المجال. (c) في الدائم تحافظ السبيكة على المناطق المغناطيسية مرتبة بعد إزالة المجال، وفي المؤقت تعود المناطق إلى عشوائيتها.', '["مادة الدائم: سبيكة (ألومنيوم ونيكل وكوبالت) أو عناصر ترابية نادرة","مادة المؤقت: الحديد المطاوع","الدائم يحتفظ بمغناطيسيته والمؤقت يفقدها مباشرة","المناطق تبقى مرتبة في الدائم وتعود عشوائية في المؤقت"]'::jsonb, '[]'::jsonb, '[{"element":"مادة المغناطيس الدائم","marks":1},{"element":"مادة المغناطيس المؤقت","marks":1},{"element":"المقارنة في السلوك بعد الإبعاد","marks":1},{"element":"المقارنة في ترتيب المناطق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أوجه المقارنة كلها صحيحة"},{"level":"2–3 درجات","description":"وجهان من أوجه المقارنة صحيحان"},{"level":"1 درجة","description":"وجه واحد صحيح"},{"level":"صفر","description":"لا وجه صحيح"}]'::jsonb, '["عدّ الحديد المطاوع مادة للمغانط الدائمة","القول إن المغناطيس الدائم لا يحتوي على مناطق مغناطيسية","الخلط بين المغناطيس المؤقت والمغناطيس الكهربائي من حيث الحاجة إلى تيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.345Z"}'::jsonb),
('essay', 2, null::int, null, null, 'أبعد القطعة عن المغناطيس الكبير، ثم: (1) قرّبها من مشابك ورق؛ فإن لم تجذبها (أو سقطت المشابك مباشرة) فهي مغناطيس مؤقت فقد مغناطيسيته بإبعاد المجال، وإن جذبتها مدة طويلة فهي مغناطيس دائم. (2) قرّب كل طرف من طرفيها من القطب الشمالي لإبرة بوصلة (أو مغناطيس معلّق)؛ فإن تنافر أحد الطرفين مع القطب فهي مغناطيس دائم لها قطبان، وإن انجذب الطرفان كلاهما فهي ليست مغناطيسًا بعد الإبعاد، أي كانت مغناطيسًا مؤقتًا. التنافر هو الدليل الأكيد على المغناطيس؛ لأن الجذب يحدث بين المغناطيس وأي قطعة حديد غير ممغنطة.', '["إبعاد القطعة عن المغناطيس قبل الاختبار","اختبار الجذب بعد الإبعاد (مشابك) وتفسيره","اختبار التنافر مع قطب معلوم","التنافر دليل المغناطيس الدائم، والجذب وحده لا يكفي"]'::jsonb, '[]'::jsonb, '[{"element":"إبعاد القطعة أولًا","marks":1},{"element":"اختبار المشابك مع النتيجتين","marks":1},{"element":"اختبار التنافر مع قطب معلوم","marks":1},{"element":"تفسير أن التنافر هو الدليل الأكيد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تجربة كاملة بنتائجها وتفسيرها"},{"level":"2–3 درجات","description":"اختبار واحد صحيح بنتيجتيه مع نقص في التفسير"},{"level":"1 درجة","description":"وصف ناقص دون نتائج"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["إجراء الاختبار والقطعة ما زالت ملامسة للمغناطيس الكبير","الاعتماد على الجذب وحده دليلًا على أن القطعة مغناطيس دائم","عدم ذكر النتيجة المتوقعة لكل حالة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-28T06:03:18.345Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) القضيب الجديد ليس مغناطيسًا دائمًا؛ إنه قطعة حديد غير ممغنطة (مغناطيس مؤقت). (b) عند تقريبه من المغناطيس الدائم يتمغنط بالحث، فيصبح طرفه القريب من أي قطب قطبًا مخالفًا له، فيحدث تجاذب أيًّا كان اتجاه القضيب. (c) الطفو يحتاج إلى تنافر بين قطبين متشابهين، والمغناطيس المؤقت المتمغنط بالحث يتكون فيه دائمًا قطب مخالف للقطب المقابل، فلا يحدث تنافر.', '["القضيب الجديد مغناطيس مؤقت (غير ممغنط)","يتمغنط بالحث فيتكون قطب مخالف للقطب المقابل","الجذب يحدث في الاتجاهين","لا تنافر لأن القطب المستحث مخالف دائمًا"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد نوع القضيب","marks":1},{"element":"المغنطة بالحث بقطب مخالف","marks":2},{"element":"تفسير عدم الطفو","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التحديد والتفسيران صحيحة"},{"level":"2–3 درجات","description":"التحديد صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"تحديد النوع فقط"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["القول إن القضيب الجديد مغناطيس دائم ضعيف","عدم ذكر المغنطة بالحث","الاعتقاد أن الحديد المتمغنط بالحث قد يتنافر مع المغناطيس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.345Z"}'::jsonb)
