from (values
('mcq', 1, 0, 'بتطبيق القاعدة الأولى لليد اليمنى على أي جزء من الحلقة (الإبهام في اتجاه التيار) تلتف الأصابع فتخرج من الصفحة داخل الحلقة. فالتيار الذي يدور عكس عقارب الساعة يولّد داخل الحلقة مجالًا خارجًا من الصفحة، ويكون اتجاه المجال داخل الحلقة دائمًا في الاتجاه نفسه.', '["","هذا اتجاه المجال داخل الحلقة لو كان التيار يدور مع عقارب الساعة.","المجال داخل حلقة في مستوى الصفحة عمودي على مستواها، لا موازٍ له.","المجال داخل الحلقة عمودي على مستوى الصفحة، لا في اتجاه أي جزء من السلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-28T06:03:18.346Z"}'::jsonb),
('mcq', 2, 2, 'بالقاعدة الأولى لليد اليمنى على الجزء الأيمن من الحلقة (التيار فيه إلى أعلى): تلتف الأصابع فتخرج من الصفحة على يسار السلك (داخل الحلقة) وتدخلها على يمينه (خارج الحلقة). فالمجال خارج الحلقة عند Q داخل إلى الصفحة، عكس اتجاهه عند P داخلها.', '["المجال خارج الحلقة يعاكس اتجاهه داخلها؛ فخطوط المجال حلقات مغلقة تعود من الخارج.","للحلقة مجال حول جميع أجزائها، داخلها وخارجها.","","المجال حول السلك يلتف حوله عموديًّا على اتجاه التيار لا موازيًا له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-28T06:03:18.346Z"}'::jsonb),
('mcq', 3, 1, 'المجال داخل الحلقة خارج من الصفحة. بتطبيق القاعدة الأولى لليد اليمنى: إذا كان التيار في الجزء الأيمن من الحلقة إلى أعلى فإن الأصابع تخرج من الصفحة داخل الحلقة وتدخلها خارجها، وهذا يطابق الشكل؛ أي أن التيار يدور عكس اتجاه حركة عقارب الساعة.', '["التيار مع عقارب الساعة يجعل المجال داخل الحلقة داخلًا إلى الصفحة، وهذا عكس الشكل.","","التيار يدور في الحلقة في اتجاه واحد؛ لذلك يكون المجال داخلها كله في الاتجاه نفسه.","اتجاه المجال يحدد اتجاه التيار تمامًا بالقاعدة الأولى لليد اليمنى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-28T06:03:18.347Z"}'::jsonb),
('mcq', 4, 3, 'كل جزء من الحلقة يولد مجالًا حوله، وبتطبيق القاعدة الأولى لليد اليمنى على أي جزء نجد أن مجالات جميع أجزاء الحلقة تكون داخلها في الاتجاه نفسه فتتجمع، وتتقارب خطوط المجال داخل الحلقة فيكون المجال أكبر. أما خارج الحلقة فيعاكس مجالُ الأجزاء البعيدة مجالَ الجزء القريب، وتعود الخطوط في حيّز أوسع فتتباعد ويكون المجال أضعف.', '["التيار يسري في السلك نفسه، والمجال ينشأ داخل الحلقة وخارجها.","خطوط المجال المغناطيسي حلقات مغلقة لا تبدأ من نقطة ولا تنتهي عند أخرى.","للحلقة مجال خارجها أيضًا، لكنه أضعف ومعاكس لاتجاه المجال داخلها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-28T06:03:18.347Z"}'::jsonb),
('mcq', 5, 2, 'بالقاعدة الأولى لليد اليمنى: حول الجزء العلوي (التيار خارج من الصفحة) تدور خطوط المجال عكس عقارب الساعة، فيكون المجال أسفله عند P نحو اليمين. وحول الجزء السفلي (التيار داخل إلى الصفحة) تدور الخطوط مع عقارب الساعة، فيكون المجال فوقه عند P نحو اليمين أيضًا. المجالان في الاتجاه نفسه فيتجه المجال عند P نحو اليمين على امتداد محور الحلقة.', '["هذا اتجاه المجال خارج الحلقة (عند R مثلًا)، أو ناتج عن عكس القاعدة الأولى لليد اليمنى.","المجال عند مركز الحلقة عمودي على مستواها، أي على امتداد محورها الأفقي هنا.","","التيار في الجزأين متعاكس، لكن مجاليهما داخل الحلقة في الاتجاه نفسه فيتجمعان لا يتلاشيان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-28T06:03:18.347Z"}'::jsonb),
('mcq', 6, 0, 'مجال كل لفة داخلها في اتجاه واحد، وعند لف السلك لفات متجاورة يكون اتجاه المجال حول جميع اللفات في الاتجاه نفسه؛ لذا يضاف مجال كل لفة إلى مجالات اللفات الأخرى، فيساوي المجال داخل الملف مجموع المجالات الناتجة عن لفاته.', '["","مجالات اللفات تتجمع فيكون المجال أكبر من مجال لفة واحدة.","اللفات ملفوفة في الاتجاه نفسه فمجالاتها داخل الملف في الاتجاه نفسه ولا تتعاكس.","التيار يدور في جميع اللفات في الاتجاه نفسه، فاتجاه المجال داخلها واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.348Z"}'::jsonb),
('mcq', 7, 3, 'قبل العكس كان التيار يدور عكس عقارب الساعة، فالمجال داخل الحلقة (عند P) خارج من الصفحة وخارجها (عند Q) داخل إليها. عكس التيار يعكس المجال في كل مكان: يصبح عند P داخلًا إلى الصفحة، وعند Q خارجًا منها.', '["هذا اتجاه المجال قبل عكس التيار.","المجال خارج الحلقة يعاكس اتجاهه داخلها دائمًا، فلا يتفقان.","المجالان داخل الحلقة وخارجها متعاكسان دائمًا، وقد عُكس كلاهما أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-28T06:03:18.348Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) نمسك أي جزء من الحلقة باليد اليمنى بحيث يشير الإبهام في اتجاه التيار، فتلتف الأصابع حول السلك. في الجزء الأيمن مثلًا التيار إلى أعلى، فتخرج الأصابع من الصفحة على يسار السلك أي داخل الحلقة؛ فالمجال عند P خارج من الصفحة، ويكون داخل الحلقة كلها في الاتجاه نفسه. (b) وتدخل الأصابع الصفحة على يمين السلك؛ فالمجال خارج الحلقة عند Q داخل إلى الصفحة. (c) نرسم نقاطًا (•) داخل الحلقة للمجال الخارج من الصفحة، وعلامات (×) حولها خارجها للمجال الداخل إلى الصفحة.', '["الإبهام في اتجاه التيار والأصابع تلتف حول السلك","المجال داخل الحلقة خارج من الصفحة","المجال خارج الحلقة داخل إلى الصفحة","التمثيل: • داخل الحلقة و× خارجها"]'::jsonb, '[]'::jsonb, '[{"element":"وصف استخدام القاعدة الأولى","marks":1},{"element":"الاتجاه عند P","marks":1},{"element":"الاتجاه عند Q","marks":1},{"element":"التمثيل بالرمزين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"الاتجاهان صحيحان مع نقص في وصف القاعدة أو التمثيل"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["جعل الأصابع في اتجاه التيار والإبهام نحو المجال عند تطبيق القاعدة على جزء من السلك","جعل المجال خارج الحلقة في اتجاه المجال داخلها","الخلط بين • و×"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-28T06:03:18.348Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) كل جزء من الحلقة يولد حوله مجالًا مغناطيسيًّا، وبتطبيق القاعدة الأولى لليد اليمنى على أي جزء نجد أن المجال داخل الحلقة يكون دائمًا في الاتجاه نفسه؛ فتتجمع مجالات جميع الأجزاء داخلها وتتقارب خطوطها فيكبر المجال، أما خارجها فتتوزع الخطوط في حيّز أوسع ويكون المجال أضعف. (b) يزداد المجال؛ لأن اتجاه المجال حول جميع اللفات يكون في الاتجاه نفسه، فيضاف مجال كل لفة إلى مجالات اللفات الأخرى، ويكون المجال داخل الملف مساويًا لمجموع المجالات الناتجة عن لفاته.', '["مجالات أجزاء الحلقة داخلها في الاتجاه نفسه","تجمّع الخطوط داخل الحلقة يعني مجالًا أكبر","في الملف يزداد المجال","المجال داخل الملف مجموع مجالات اللفات"]'::jsonb, '[]'::jsonb, '[{"element":"المجالات داخل الحلقة في اتجاه واحد","marks":1},{"element":"ربط تقارب الخطوط بشدة المجال","marks":1},{"element":"زيادة المجال في الملف","marks":1},{"element":"التفسير بجمع مجالات اللفات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التفسيران كاملان"},{"level":"2–3 درجات","description":"أحد التفسيرين كامل والآخر ناقص"},{"level":"1 درجة","description":"إجابة دون تفسير"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["القول إن التيار يسري داخل الحلقة","القول إن المجال خارج الحلقة منعدم","القول إن مجالات اللفات المتجاورة يلغي بعضها بعضًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.348Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) الجزء العلوي: التيار خارج من الصفحة، فبالقاعدة الأولى لليد اليمنى تدور خطوط المجال حوله عكس عقارب الساعة، فيكون المجال أسفله (عند P) نحو اليمين. الجزء السفلي: التيار داخل إلى الصفحة، فتدور الخطوط حوله مع عقارب الساعة، فيكون المجال فوقه (عند P) نحو اليمين. المجال الكلي عند P نحو اليمين وهو مجموع المجالين. (b) عند R فوق الجزء العلوي يكون مجاله نحو اليسار (خطوط عكس عقارب الساعة)، والجزء السفلي أبعد كثيرًا عن R فمجاله عندها أضعف، فيغلب مجال الجزء العلوي ويكون المجال عند R نحو اليسار. (c) المجال داخل الحلقة يتجه نحو اليمين ويعود خارجها نحو اليسار؛ فخطوط المجال تخترق الحلقة في اتجاه واحد ثم تلتف حولها عائدة، فهي حلقات مغلقة.', '["مجال الجزء العلوي عند P نحو اليمين","مجال الجزء السفلي عند P نحو اليمين، والكلي نحو اليمين","المجال عند R نحو اليسار","الخطوط تخترق الحلقة في اتجاه وتعود خارجها في الاتجاه المعاكس (حلقات مغلقة)"]'::jsonb, '["الجزء العلوي (تيار خارج): خطوط عكس عقارب الساعة، فالمجال أسفله نحو اليمين","الجزء السفلي (تيار داخل): خطوط مع عقارب الساعة، فالمجال فوقه نحو اليمين","المجال الكلي عند P نحو اليمين","فوق الجزء العلوي: المجال نحو اليسار"]'::jsonb, '[{"element":"مجالا الجزأين عند P","marks":2},{"element":"المجال الكلي عند P","marks":1},{"element":"المجال عند R","marks":1},{"element":"الاستنتاج عن الخطوط المغلقة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الاتجاهات والاستنتاج صحيحة"},{"level":"3–4 درجات","description":"الاتجاه عند P صحيح مع خطأ عند R أو نقص في الاستنتاج"},{"level":"1–2 درجة","description":"اتجاه مجال جزء واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["استنتاج أن المجالين عند P يلغي أحدهما الآخر لأن التيارين متعاكسان","استعمال اليد اليسرى أو عكس اتجاه الدوران","جعل المجال عند R في اتجاه المجال عند P"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-28T06:03:18.349Z"}'::jsonb)
