from (values
('mcq', 1, 'من العالم الذي أجرى عام 1820م تجارب بيّنت أن التيار الكهربائي المار في سلك يؤثر في إبرة البوصلة؟', null, null, '["أندريه ماري أمبير","هانز كريستيان أورستد","جورج سيمون أوم","مايكل فاراداي"]'::jsonb, 'تذكر', 'حقائق', 'سهل', 'الكتاب ص 76 — المجالات المغناطيسية حول التيارات الكهربائية: تجربة أورستد (الشكل 8-3)'),
('mcq', 2, 'يمثل الشكل الآتي تجربة أورستد: سلك فوق محور بوصلة قبل مرور التيار (a) وبعد مروره (b). ما الذي لاحظه أورستد عند مرور التيار؟', null, '[{"src":"qimg/phys32/c3l1-o14-oersted.svg","alt":"شكلان (a) و(b) لتجربة أورستد كما تُرى من أعلى. في كل منهما بوصلة عليها الاتجاهات N أعلى وE يمين وS أسفل وW يسار، وسلك رأسي يمر فوق محور البوصلة على امتداد الاتجاه N–S، ويتصل طرفاه بمصدر قدرة له مفتاح. في (a) المفتاح على OFF، والقطب الشمالي للإبرة (الطرف الأحمر) يشير نحو N موازيًا للسلك. في (b) المفتاح على ON، والقطب الشمالي للإبرة يشير نحو E، أي أن الإبرة عمودية على السلك. عبارة أعلى الشكل: السلك فوق البوصلة."}]'::jsonb, '["أشارت الإبرة إلى اتجاه سريان التيار في السلك","بقيت الإبرة موازية للسلك دون أي تغير","اهتزت الإبرة ثم استقرت مشيرة نحو مصدر القدرة","دارت الإبرة لتصبح عمودية على السلك"]'::jsonb, 'فهم', 'وصف تجربة', 'سهل', 'الكتاب ص 76 — المجالات المغناطيسية حول التيارات الكهربائية: تجربة أورستد (الشكل 8-3)'),
('mcq', 3, 'ماذا كان أورستد يتوقع أن يحدث لإبرة البوصلة عند مرور التيار في السلك الموضوع فوقها؟', null, null, '["أن تشير إلى اتجاه السلك أو اتجاه سريان التيار","أن تدور الإبرة لتصبح عمودية على السلك","أن تنجذب الإبرة نحو السلك وتلتصق به مباشرة","أن تفقد الإبرة مغناطيسيتها بسبب حرارة السلك"]'::jsonb, 'تذكر', 'وصف تجربة', 'متوسط', 'الكتاب ص 76 — المجالات المغناطيسية حول التيارات الكهربائية: تجربة أورستد (الشكل 8-3)'),
('mcq', 4, 'ما الاستنتاج الأساسي الذي بيّنته تجربة أورستد عن العلاقة بين الكهرباء والمغناطيسية؟', null, null, '["المغناطيس الساكن يولّد تيارًا كهربائيًّا في السلك","سلك النحاس مادة مغناطيسية مثل الحديد","التيار الكهربائي يولّد مجالًا مغناطيسيًّا حوله","الإبرة تتأثر بالمجال الكهربائي لمصدر القدرة"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 76 — المجالات المغناطيسية حول التيارات الكهربائية: تجربة أورستد (الشكل 8-3)'),
('mcq', 5, 'في تجربة أورستد، ماذا يحدث لإبرة البوصلة بعد قطع التيار عن السلك؟', null, null, '["تبقى عمودية على السلك لأنها تمغنطت بالتيار","تدور دورانًا مستمرًّا حول محورها","تشير إلى عكس اتجاهها قبل مرور التيار","تعود إلى اتجاهها الأصلي موازية للسلك"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 76 — المجالات المغناطيسية حول التيارات الكهربائية: تجربة أورستد (الشكل 8-3)'),
('mcq', 6, 'في التجربة الموضحة في الشكل الآتي، إذا عُكس اتجاه التيار في السلك بعد الحالة (b)، فإلى أين يشير القطب الشمالي لإبرة البوصلة؟', null, '[{"src":"qimg/phys32/c3l1-o14-oersted.svg","alt":"شكلان (a) و(b) لتجربة أورستد كما تُرى من أعلى. في كل منهما بوصلة عليها الاتجاهات N أعلى وE يمين وS أسفل وW يسار، وسلك رأسي يمر فوق محور البوصلة على امتداد الاتجاه N–S، ويتصل طرفاه بمصدر قدرة له مفتاح. في (a) المفتاح على OFF، والقطب الشمالي للإبرة (الطرف الأحمر) يشير نحو N موازيًا للسلك. في (b) المفتاح على ON، والقطب الشمالي للإبرة يشير نحو E، أي أن الإبرة عمودية على السلك. عبارة أعلى الشكل: السلك فوق البوصلة."}]'::jsonb, '["نحو E، كما كان في الحالة (b) تمامًا","نحو W، عكس اتجاهه في الحالة (b)","نحو N، موازيًا للسلك كما في (a)","نحو S، موازيًا للسلك وعكس (a)"]'::jsonb, 'تطبيق', 'تنبؤ', 'صعب', 'الكتاب ص 76 — المجالات المغناطيسية حول التيارات الكهربائية: تجربة أورستد (الشكل 8-3)'),
('mcq', 7, 'في الحالة (b) من التجربة الموضحة في الشكل الآتي يمر السلك فوق البوصلة على امتداد الاتجاه N–S، ويشير القطب الشمالي للإبرة نحو E. ما اتجاه التيار الاصطلاحي في جزء السلك الذي فوق البوصلة؟ (افترض أن مجال السلك عند البوصلة أكبر كثيرًا من المجال المغناطيسي الأرضي.)', null, '[{"src":"qimg/phys32/c3l1-o14-oersted.svg","alt":"شكلان (a) و(b) لتجربة أورستد كما تُرى من أعلى. في كل منهما بوصلة عليها الاتجاهات N أعلى وE يمين وS أسفل وW يسار، وسلك رأسي يمر فوق محور البوصلة على امتداد الاتجاه N–S، ويتصل طرفاه بمصدر قدرة له مفتاح. في (a) المفتاح على OFF، والقطب الشمالي للإبرة (الطرف الأحمر) يشير نحو N موازيًا للسلك. في (b) المفتاح على ON، والقطب الشمالي للإبرة يشير نحو E، أي أن الإبرة عمودية على السلك. عبارة أعلى الشكل: السلك فوق البوصلة."}]'::jsonb, '["نحو الجنوب (S)","نحو الشمال (N)","نحو الشرق (E)","نحو الغرب (W)"]'::jsonb, 'تطبيق', 'تنبؤ', 'صعب', 'الكتاب ص 76–77 — تجربة أورستد (الشكل 8-3)، والقاعدة الأولى لليد اليمنى'),
('essay', 1, 'صف تجربة أورستد التي بيّنت العلاقة بين الكهرباء والمغناطيسية من حيث: (a) الأدوات وطريقة ترتيبها. (b) ما كان يتوقعه. (c) ما لاحظه فعلًا. (d) الاستنتاج.', null, null, null, 'فهم', 'وصف تجربة', 'سهل', 'الكتاب ص 76 — المجالات المغناطيسية حول التيارات الكهربائية: تجربة أورستد (الشكل 8-3)'),
('essay', 2, 'في تجربة أورستد الموضحة في الشكل الآتي: (a) ماذا يحدث لإبرة البوصلة إذا قُطع التيار بعد الحالة (b)؟ فسّر ذلك. (b) ماذا يحدث للإبرة إذا عُكس اتجاه التيار؟ (c) ماذا تبين هاتان الملاحظتان عن مصدر المجال المغناطيسي حول السلك واتجاهه؟', null, '[{"src":"qimg/phys32/c3l1-o14-oersted.svg","alt":"شكلان (a) و(b) لتجربة أورستد كما تُرى من أعلى. في كل منهما بوصلة عليها الاتجاهات N أعلى وE يمين وS أسفل وW يسار، وسلك رأسي يمر فوق محور البوصلة على امتداد الاتجاه N–S، ويتصل طرفاه بمصدر قدرة له مفتاح. في (a) المفتاح على OFF، والقطب الشمالي للإبرة (الطرف الأحمر) يشير نحو N موازيًا للسلك. في (b) المفتاح على ON، والقطب الشمالي للإبرة يشير نحو E، أي أن الإبرة عمودية على السلك. عبارة أعلى الشكل: السلك فوق البوصلة."}]'::jsonb, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 76 — المجالات المغناطيسية حول التيارات الكهربائية: تجربة أورستد (الشكل 8-3)'),
('essay', 3, 'يسري تيار نحو الشمال في سلك أفقي مثبت فوق بوصلة كما في الشكل الآتي (افترض أن مجال السلك عند البوصلة أكبر كثيرًا من المجال المغناطيسي الأرضي). (a) استخدم القاعدة الأولى لليد اليمنى لتحديد اتجاه القطب الشمالي لإبرة البوصلة، ووضّح خطواتك. (b) كان أورستد يتوقع أن تشير الإبرة إلى اتجاه السلك. فسّر، بدلالة شكل خطوط المجال المغناطيسي حول السلك، لماذا تستقر الإبرة عمودية على السلك. (c) لماذا يجب أن تكون الدائرة الكهربائية مغلقة لتنحرف الإبرة؟', null, '[{"src":"qimg/phys32/c3l1-o14-predict.svg","alt":"بوصلة كما تُرى من أعلى عليها الاتجاهات N أعلى وE يمين وS أسفل وW يسار، دون إبرة ظاهرة. سلك مستقيم يمر فوق محور البوصلة على امتداد الاتجاه N–S، وبجانبه سهم إلى أعلى (نحو N) معلّم بالرمز I يبين اتجاه التيار. أسفل الشكل عبارة: السلك فوق البوصلة، والتيار نحو الشمال."}]'::jsonb, null, 'تطبيق', 'تنبؤ', 'صعب', 'الكتاب ص 76–78 — تجربة أورستد، والقاعدة الأولى لليد اليمنى، ومسألة تدريبية 5')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
