insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'أجرى الفيزيائي الدنماركي هانز كريستيان أورستد عام 1820م تجارب على التيارات الكهربائية المارة في الأسلاك، فوضع سلكًا فوق محور بوصلة صغيرة ولاحظ انحراف إبرتها عند مرور التيار.', '["أمبير اقترح فكرة أن كل إلكترون يشبه مغناطيسًا كهربائيًّا صغيرًا، ولم يُجرِ تجربة البوصلة عام 1820م.","","أوم ارتبط اسمه بالعلاقة بين الجهد والتيار والمقاومة، لا بتجربة البوصلة.","فاراداي ارتبط اسمه بالحث الكهرومغناطيسي، وليس هو من أجرى تجربة البوصلة والسلك عام 1820م."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.349Z"}'::jsonb),
('mcq', 2, 3, 'لاحظ أورستد أن إبرة البوصلة تدور عند مرور التيار لتصبح في اتجاه عمودي على السلك، أي أن القوى المؤثرة في قطبي مغناطيس البوصلة كانت متعامدة مع اتجاه التيار داخل السلك.', '["هذا ما كان متوقعًا قبل التجربة، لكن الإبرة صارت عمودية على السلك لا موازية لاتجاه التيار.","الإبرة تكون موازية للسلك قبل مرور التيار فقط (a)، أما مع التيار فتدور.","الإبرة لا تتجه نحو مصدر القدرة؛ إنها تتأثر بالمجال المغناطيسي حول السلك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.350Z"}'::jsonb),
('mcq', 3, 0, 'كان أورستد يتوقع أن تشير البوصلة إلى اتجاه السلك أو اتجاه سريان التيار، لكنه تعجب لرؤية الإبرة تدور لتصبح في اتجاه عمودي على السلك.', '["","هذا ما لاحظه فعلًا وأثار تعجبه، لا ما كان يتوقعه.","الإبرة محمولة على محور ولا تنجذب نحو السلك؛ وهذا لم يكن توقع أورستد.","لم يكن التوقع فقدان الإبرة مغناطيسيتها؛ فالتجربة تتعلق باتجاه الإبرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-28T06:03:18.350Z"}'::jsonb),
('mcq', 4, 2, 'انحراف إبرة البوصلة قرب السلك الذي يحمل تيارًا يعني وجود مجال مغناطيسي ولّده التيار الكهربائي، ولو لم يكن هناك تيار في السلك لما كان هناك قوى مغناطيسية؛ فالتيار الكهربائي يولد مجالًا مغناطيسيًّا حوله.', '["التجربة بيّنت أن التيار يولد مجالًا مغناطيسيًّا، لا أن المغناطيس الساكن يولد تيارًا.","النحاس لا ينجذب إلى المغناطيس، والإبرة لم تتأثر بالسلك إلا عند مرور التيار.","","التأثير اختفى عند قطع التيار، فهو ناتج عن المجال المغناطيسي للتيار لا عن مصدر القدرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.350Z"}'::jsonb),
('mcq', 5, 3, 'وجد أورستد أنه لو لم يكن هناك تيار في السلك لما كان هناك قوى مغناطيسية؛ فعند قطع التيار يزول المجال المغناطيسي للسلك وتعود الإبرة إلى اتجاهها الأصلي (شمال–جنوب) موازية للسلك.', '["الإبرة مغناطيس أصلًا، وانحرافها ناتج عن مجال التيار الذي يزول بقطع التيار.","لا يوجد ما يديم دوران الإبرة؛ فهي تستقر في اتجاه المجال المؤثر فيها.","عكس الاتجاه يحدث عند عكس اتجاه التيار، لا عند قطعه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-28T06:03:18.350Z"}'::jsonb),
('mcq', 6, 1, 'المجال المغناطيسي حول السلك ينشأ عن التيار، واتجاهه يتبع اتجاه التيار؛ فإذا عُكس اتجاه التيار انعكس اتجاه المجال، فتعكس إبرة البوصلة اتجاهها أيضًا وتبقى عمودية على السلك: يشير قطبها الشمالي نحو W، عكس اتجاهه في الحالة (b).', '["عكس التيار يعكس المجال المغناطيسي، فلا تبقى الإبرة على اتجاهها.","","الإبرة تكون موازية للسلك عند انعدام التيار فقط؛ أما مع التيار فتبقى عمودية عليه.","ما دام التيار يسري فالإبرة عمودية على السلك لا موازية له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-28T06:03:18.351Z"}'::jsonb),
('mcq', 7, 0, 'الإبرة أسفل السلك، ويشير قطبها الشمالي في اتجاه المجال عندها، أي نحو الشرق. بالقاعدة الأولى لليد اليمنى: إذا جعلنا الإبهام نحو الجنوب التفّت الأصابع حول السلك فاتجهت أسفله نحو الشرق وفوقه نحو الغرب؛ وهذا يطابق الشكل، فالتيار في السلك نحو الجنوب (S).', '["","التيار نحو الشمال يجعل المجال أسفل السلك نحو الغرب لا الشرق؛ وهذا الاختيار ينتج عن عكس القاعدة الأولى لليد اليمنى أو عن تطبيقها كأن البوصلة فوق السلك.","السلك ممتد في اتجاه N–S فلا يسري فيه تيار نحو الشرق؛ والإبرة تشير في اتجاه المجال لا في اتجاه التيار.","السلك ممتد في اتجاه N–S، والتيار يسري على امتداده، فلا يكون نحو الغرب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-28T06:03:18.351Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) وضع أورستد سلكًا فوق محور بوصلة صغيرة (موازيًا لإبرتها)، وأوصل نهايتي السلك بدائرة كهربائية مغلقة (مصدر قدرة). (b) كان يتوقع أن تشير البوصلة إلى اتجاه السلك أو اتجاه سريان التيار. (c) لاحظ أن إبرة البوصلة تدور عند مرور التيار لتصبح في اتجاه عمودي على السلك. (d) التيار الكهربائي المار في السلك يولد مجالًا مغناطيسيًّا حوله، والقوى المؤثرة في قطبي البوصلة متعامدة مع اتجاه التيار، ولو لم يكن هناك تيار لما كان هناك قوى مغناطيسية.', '["سلك فوق محور بوصلة موصول بدائرة مغلقة","التوقع: تشير البوصلة إلى اتجاه السلك أو التيار","الملاحظة: دارت الإبرة لتصبح عمودية على السلك","الاستنتاج: التيار يولد مجالًا مغناطيسيًّا"]'::jsonb, '[]'::jsonb, '[{"element":"الأدوات وترتيبها","marks":1},{"element":"التوقع","marks":1},{"element":"الملاحظة","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الأربعة صحيحة"},{"level":"2–3 درجات","description":"الملاحظة والاستنتاج صحيحان مع نقص في غيرهما"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["الخلط بين ما توقعه أورستد وما لاحظه","القول إن الإبرة أشارت إلى اتجاه التيار","الاستنتاج أن المغناطيس يولد تيارًا كهربائيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.351Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) تعود الإبرة إلى اتجاهها الأصلي (شمال–جنوب) موازية للسلك؛ لأنه لو لم يكن هناك تيار في السلك لما كان هناك قوى مغناطيسية، فلا يبقى إلا المجال المغناطيسي الأرضي. (b) تعكس الإبرة اتجاهها فيشير قطبها الشمالي نحو W بدل E، وتبقى عمودية على السلك. (c) تبينان أن المجال المغناطيسي حول السلك ناتج عن التيار الكهربائي (يوجد بوجوده ويزول بزواله)، وأن اتجاه المجال يعتمد على اتجاه التيار، فإذا عُكس التيار انعكس المجال.', '["تعود الإبرة إلى اتجاهها الأصلي عند قطع التيار","التفسير: لا قوى مغناطيسية دون تيار","عكس التيار يعكس اتجاه الإبرة (نحو W)","المجال مصدره التيار واتجاهه يتبع اتجاه التيار"]'::jsonb, '[]'::jsonb, '[{"element":"ما يحدث عند قطع التيار مع التفسير","marks":2},{"element":"ما يحدث عند عكس التيار","marks":1},{"element":"الاستنتاج عن مصدر المجال واتجاهه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابات الثلاث صحيحة مع التفسير"},{"level":"2–3 درجات","description":"إجابتان صحيحتان"},{"level":"1 درجة","description":"إجابة واحدة صحيحة"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["القول إن الإبرة تبقى منحرفة لأنها تمغنطت","القول إن عكس التيار لا يغير اتجاه الإبرة","نسبة انحراف الإبرة إلى مصدر القدرة لا إلى التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-28T06:03:18.351Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) نمسك السلك باليد اليمنى بحيث يشير الإبهام في اتجاه التيار (نحو الشمال)، فتلتف الأصابع حول السلك: تتجه فوقه نحو الشرق وأسفله نحو الغرب. البوصلة أسفل السلك، فالمجال عندها نحو الغرب، ويشير القطب الشمالي للإبرة نحو الغرب (W). (b) خطوط المجال المغناطيسي حول سلك مستقيم يحمل تيارًا دوائر متحدة المركز حول السلك، تقع في مستويات عمودية عليه؛ فالمجال عند البوصلة مماس لهذه الدوائر، أي عمودي على السلك، والإبرة تترتب في اتجاه المجال فتستقر عمودية على السلك لا موازية له. (c) لأن التيار لا يسري إلا في دائرة مغلقة، والمجال المغناطيسي حول السلك ينشأ عن التيار؛ فدون تيار لا توجد قوى مغناطيسية تحرف الإبرة.', '["الإبهام في اتجاه التيار والأصابع تلتف حول السلك","أسفل السلك: الإبرة نحو الغرب","خطوط المجال دوائر متحدة المركز حول السلك فالمجال عند البوصلة عمودي عليه","الدائرة المغلقة لازمة لسريان التيار الذي يولد المجال"]'::jsonb, '["الإبهام نحو الشمال (اتجاه التيار)","الأصابع فوق السلك نحو الشرق وأسفله نحو الغرب","البوصلة أسفل السلك فالإبرة نحو الغرب"]'::jsonb, '[{"element":"تطبيق القاعدة الأولى","marks":1},{"element":"الاتجاه أسفل السلك","marks":1},{"element":"تفسير تعامد الإبرة بشكل خطوط المجال","marks":1},{"element":"تفسير ضرورة الدائرة المغلقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"اتجاه الإبرة صحيح مع تطبيق صحيح للقاعدة ونقص في أحد التفسيرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["استعمال القاعدة الثانية (للملف) بدل الأولى","جعل الإبرة تشير في اتجاه التيار","القول إن خطوط المجال حول السلك موازية له"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.352Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C3-L1-O14') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L1-O15'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا يشير القطب الشمالي لإبرة البوصلة نحو الشمال الجغرافي؟', null, null, '["لأن الجاذبية الأرضية أكبر ما يمكن عند القطب الشمالي الجغرافي","لأن قطب الأرض المغناطيسي هناك جنوبي، والقطبان المختلفان يتجاذبان","لأن قطب الأرض المغناطيسي هناك شمالي، والقطبان المتشابهان يتجاذبان","لأن المجال المغناطيسي الأرضي يخرج من قرب القطب الشمالي الجغرافي"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 72 — الأرض مغناطيس عملاق'),
('mcq', 2, 'يبين الشكل الآتي خطوط المجال المغناطيسي الأرضي، ومغناطيسًا تخيليًّا داخل الأرض طرفاه 1 و2. ما نوع القطب المغناطيسي عند الطرف 1؟', null, '[{"src":"qimg/phys32/c3l1-o15-earth-q.svg","alt":"الكرة الأرضية دائرة زرقاء، وفي داخلها مغناطيس تخيلي رأسي رمادي اللون: طرفه العلوي (قرب القطب الشمالي الجغرافي) معلّم بالرقم 1، وطرفه السفلي (قرب القطب الجنوبي الجغرافي) معلّم بالرقم 2. أعلى الشكل عبارة القطب الشمالي الجغرافي، وأسفله القطب الجنوبي الجغرافي. حول الأرض ثلاثة خطوط مجال خضراء على كل جانب تلتف من نصف الأرض الجنوبي إلى نصفها الشمالي، وعليها أسهم عند مستوى خط الاستواء تتجه إلى أعلى (نحو الشمال الجغرافي)، وخطوط أخرى أبعد تخرج من قرب القطب الجنوبي الجغرافي وتدخل قرب القطب الشمالي الجغرافي ممتدة خارج حدود الشكل."}]'::jsonb, '["قطب جنوبي؛ لأن خطوط المجال خارج الأرض تتجه نحوه","قطب شمالي؛ لأنه قريب من القطب الشمالي الجغرافي","قطب شمالي؛ لأن خطوط المجال خارج الأرض تخرج منه","لا يُحدَّد؛ لأن للأرض قطبًا مغناطيسيًّا واحدًا"]'::jsonb, 'تطبيق', 'تفسير رسم', 'متوسط', 'الكتاب ص 97 — السؤال 57 (الشكل 24-3)'),
('mcq', 3, 'عند أيّ النقطتين A وB الموضحتين في الشكل الآتي يكون المجال المغناطيسي الأرضي أكبر، ولماذا؟', null, '[{"src":"qimg/phys32/c3l1-o15-earth.svg","alt":"الكرة الأرضية دائرة زرقاء، وفي داخلها مغناطيس تخيلي رأسي: نصفه العلوي (قرب القطب الشمالي الجغرافي) معلّم بالحرف S، ونصفه السفلي (قرب القطب الجنوبي الجغرافي) معلّم بالحرف N. أعلى الشكل عبارة القطب الشمالي الجغرافي، وأسفله القطب الجنوبي الجغرافي. حول الأرض ثلاثة خطوط مجال خضراء على كل جانب، تخرج من نصف الأرض الجنوبي وتلتف لتدخل نصفها الشمالي، وعليها أسهم عند مستوى خط الاستواء تتجه إلى أعلى (نحو الشمال الجغرافي). وخطوط أخرى أبعد تخرج من قرب القطب الجنوبي الجغرافي وتدخل قرب القطب الشمالي الجغرافي ممتدة خارج حدود الشكل؛ فالخطوط متقاربة قرب القطبين ومتباعدة عند خط الاستواء. النقطة A على سطح الأرض قرب القطب الشمالي الجغرافي، والنقطة B على سطح الأرض عند خط الاستواء."}]'::jsonb, '["عند B؛ لأن خطوط المجال عند خط الاستواء موازية لسطح الأرض","عند B؛ لأن خط الاستواء أقرب إلى مركز الأرض من القطبين","يتساوى عندهما؛ لأن المجال المغناطيسي الأرضي منتظم","عند A؛ لأن خطوط المجال تتقارب وتتركز قرب القطبين"]'::jsonb, 'فهم', 'تفسير رسم', 'متوسط', 'الكتاب ص 97 — السؤال 57 (الشكل 24-3)'),
('mcq', 4, 'عُلّق قضيب مغناطيسي بخيط من منتصفه وتُرك يدور بحرية بعيدًا عن المغانط الأخرى. باعتبار الأرض مغناطيسًا عملاقًا، إلى أين يتجه القطب الجنوبي للقضيب عندما يستقر، ولماذا؟', null, null, '["نحو الشمال الجغرافي؛ لأن قطب الأرض المغناطيسي هناك جنوبي","نحو الجنوب الجغرافي؛ لأن قطب الأرض المغناطيسي هناك شمالي","نحو الجنوب الجغرافي؛ لأن قطب الأرض المغناطيسي هناك جنوبي","لا يتجه اتجاهًا محددًا؛ لأن المجال الأرضي أضعف من أن يوجّهه"]'::jsonb, 'فهم', 'تنبؤ', 'متوسط', 'الكتاب ص 72 — الأرض مغناطيس عملاق'),
('mcq', 5, 'كيف تقارن القوة المغناطيسية التي تؤثر بها الأرض في إبرة البوصلة بالقوة التي تؤثر بها إبرة البوصلة في الأرض؟', null, null, '["قوة الأرض أكبر؛ لأن الأرض مغناطيس أكبر كثيرًا","قوة الإبرة أكبر؛ لأنها أقرب إلى سطح الأرض","متساويتان مقدارًا ومتعاكستان اتجاهًا","الإبرة لا تؤثر في الأرض بأي قوة"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 96 — السؤال 48'),
('mcq', 6, 'وُجد أن اتجاه المغنطة في صخور قاع البحر يختلف بين الصخور القريبة من الشقوق والصخور الأبعد عنها (الأقدم). ماذا استنتج العلماء من ذلك؟', null, null, '["الصخور القديمة لا تحتوي على الحديد فلا تتمغنط","تتمغنط الصخور بعد أن تبرد في اتجاهات عشوائية","المجال المغناطيسي الأرضي لم يتغير اتجاهه عبر العصور","القطبان المغناطيسيان للأرض تبادلا موقعيهما عدة مرات"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 80 — التاريخ المغناطيسي للأرض'),
('mcq', 7, 'إذا انعكس اتجاه المجال المغناطيسي الأرضي كما حدث في عصور سابقة، فإلى أين سيشير القطب الشمالي لإبرة البوصلة؟', null, null, '["نحو الجنوب الجغرافي","نحو الشمال الجغرافي كما هو الآن","نحو الشرق الجغرافي","لن يشير إلى اتجاه محدد"]'::jsonb, 'تطبيق', 'تنبؤ', 'صعب', 'الكتاب ص 80 — التاريخ المغناطيسي للأرض'),
('essay', 1, 'فسّر اتجاه إبرة البوصلة باعتبار الأرض مغناطيسًا عملاقًا، مبيّنًا: (a) نوع القطب المغناطيسي للأرض القريب من القطب الشمالي الجغرافي، وسبب ذلك. (b) اتجاه خطوط المجال المغناطيسي الأرضي خارج الأرض.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 72 — الأرض مغناطيس عملاق'),
('essay', 2, 'انظر خطوط المجال المغناطيسي الأرضي في الشكل الآتي. (a) عند أيّ النقطتين يكون المجال المغناطيسي أكبر: A قرب القطب أم B عند خط الاستواء؟ وضّح إجابتك. (b) ما اتجاه المجال المغناطيسي الأرضي عند B؟ (c) إلى أين يشير القطب الشمالي لبوصلة موضوعة عند B؟', null, '[{"src":"qimg/phys32/c3l1-o15-earth.svg","alt":"الكرة الأرضية دائرة زرقاء، وفي داخلها مغناطيس تخيلي رأسي: نصفه العلوي (قرب القطب الشمالي الجغرافي) معلّم بالحرف S، ونصفه السفلي (قرب القطب الجنوبي الجغرافي) معلّم بالحرف N. أعلى الشكل عبارة القطب الشمالي الجغرافي، وأسفله القطب الجنوبي الجغرافي. حول الأرض ثلاثة خطوط مجال خضراء على كل جانب، تخرج من نصف الأرض الجنوبي وتلتف لتدخل نصفها الشمالي، وعليها أسهم عند مستوى خط الاستواء تتجه إلى أعلى (نحو الشمال الجغرافي). وخطوط أخرى أبعد تخرج من قرب القطب الجنوبي الجغرافي وتدخل قرب القطب الشمالي الجغرافي ممتدة خارج حدود الشكل؛ فالخطوط متقاربة قرب القطبين ومتباعدة عند خط الاستواء. النقطة A على سطح الأرض قرب القطب الشمالي الجغرافي، والنقطة B على سطح الأرض عند خط الاستواء."}]'::jsonb, null, 'فهم', 'تفسير رسم', 'متوسط', 'الكتاب ص 97 — السؤال 57 (الشكل 24-3)'),
('essay', 3, 'تسجّل الصخور التي تحتوي على الحديد تاريخ اتجاهات المجال المغناطيسي الأرضي. (a) فسّر كيف تتمغنط صخور قاع البحر في اتجاه المجال الأرضي. (b) لماذا تُعدّ الصخور الأبعد عن الشقوق أقدم من القريبة منها؟ (c) ماذا يعني وجود صخور متجاورة مغنطتها متعاكسة؟ (d) لو استُعملت بوصلة في عصر كان فيه المجال معكوسًا، فإلى أين كان سيشير قطبها الشمالي؟', null, null, null, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 80 — التاريخ المغناطيسي للأرض')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C3-L1-O15') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الأرض نفسها مغناطيس عملاق. ولأن الأقطاب المغناطيسية المختلفة تتجاذب، والقطب الشمالي لإبرة البوصلة يشير نحو الشمال، فلا بد أن يكون قطب الأرض المغناطيسي هناك (قرب الشمال الجغرافي) جنوبيًّا، والقطبان المختلفان يتجاذبان.', '["اتجاه البوصلة ظاهرة مغناطيسية لا علاقة لها بالجاذبية الأرضية.","","الأقطاب المتشابهة تتنافر لا تتجاذب، والقطب القريب من الشمال الجغرافي جنوبي.","خطوط المجال تخرج من القطب الشمالي للمغناطيس، وهو للأرض قرب الجنوب الجغرافي؛ وتدخل قرب الشمال الجغرافي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.353Z"}'::jsonb),
('mcq', 2, 0, 'الأسهم على خطوط المجال خارج الأرض تتجه نحو الشمال الجغرافي، أي أن الخطوط تدخل الأرض عند الطرف 1. وخطوط المجال تخرج من القطب الشمالي للمغناطيس وتدخل في قطبه الجنوبي؛ فالطرف 1 قطب جنوبي لأن خطوط المجال خارج الأرض تتجه نحوه.', '["","قرب الطرف من الشمال الجغرافي لا يجعله قطبًا شماليًّا؛ فهو يجذب القطب الشمالي للبوصلة فهو جنوبي.","الأسهم تبين أن الخطوط تدخل عند الطرف 1 لا تخرج منه.","للأرض قطبان مغناطيسيان كأي مغناطيس، ولا توجد أقطاب مفردة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.353Z"}'::jsonb),
('mcq', 3, 3, 'معظم التدفق المغناطيسي مركّز عند القطبين، حيث تتقارب خطوط المجال، فيكون المجال المغناطيسي أكبر ما يمكن عندهما؛ لذا المجال عند A أكبر منه عند B؛ لأن خطوط المجال تتقارب وتتركز قرب القطبين.', '["اتجاه الخطوط لا يحدد شدة المجال؛ الشدة تُعرف من تقارب الخطوط، وهي متباعدة عند B.","النقطتان على سطح الأرض فبُعدهما عن المركز متساوٍ تقريبًا، والخطوط أقرب بعضها إلى بعض عند A.","تقارب خطوط المجال يختلف من مكان إلى آخر، فالمجال غير منتظم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.353Z"}'::jsonb),
('mcq', 4, 1, 'الأرض مغناطيس عملاق: قطبها المغناطيسي الجنوبي قرب الشمال الجغرافي، وقطبها المغناطيسي الشمالي قرب الجنوب الجغرافي. ولأن الأقطاب المختلفة تتجاذب، يستقر القضيب في اتجاه شمال–جنوب فيتجه قطبه الشمالي نحو الشمال الجغرافي، وقطبه الجنوبي نحو الجنوب الجغرافي حيث القطب المغناطيسي الشمالي للأرض.', '["القطب الجنوبي للقضيب يتنافر مع القطب المغناطيسي الجنوبي للأرض القريب من الشمال الجغرافي، فلا يتجه نحوه.","","الاتجاه صحيح لكن التعليل خاطئ؛ فالقطبان المتشابهان يتنافران، والقطب المغناطيسي للأرض قرب الجنوب الجغرافي شمالي.","المجال الأرضي يكفي لتوجيه المغناطيس الحر، وهذا مبدأ عمل البوصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.354Z"}'::jsonb),
('mcq', 5, 2, 'القوتان متبادلتان بين جسمين (الأرض والإبرة)، فهما زوج من القوى؛ بحسب القانون الثالث لنيوتن تكونان متساويتين مقدارًا ومتعاكستين اتجاهًا. تتحرك الإبرة ولا تتحرك الأرض لأن كتلة الأرض هائلة.', '["كبر المغناطيس لا يجعل قوة التأثير المتبادل غير متساوية؛ فالقوتان زوج تأثير متبادل.","القرب يؤثر في مقدار القوتين معًا بالقدر نفسه، فلا تكون إحداهما أكبر.","","كل مغناطيس يؤثر في الآخر؛ فالإبرة تؤثر في الأرض بقوة مساوية، لكن أثرها لا يُلاحظ لكبر كتلة الأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-28T06:03:18.354Z"}'::jsonb),
('mcq', 6, 3, 'صخور قاع البحر تنتج عن صخور منصهرة تندفع من الشقوق، وعندما تبرد تتمغنط في اتجاه المجال المغناطيسي الأرضي في ذلك الزمن. اختلاف اتجاه المغنطة بين صخور أعمارها مختلفة يعني أن القطبين المغناطيسيين للأرض تبادلا موقعيهما عدة مرات على مر العصور.', '["الصخور التي تحتوي على الحديد تسجل اتجاه المجال، والاختلاف في الاتجاه لا في وجود المغنطة.","الصخور تتمغنط في اتجاه المجال الأرضي السائد عند تبريدها، لا عشوائيًّا.","لو لم يتغير اتجاه المجال لتمغنطت الصخور كلها في الاتجاه نفسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-28T06:03:18.354Z"}'::jsonb),
('mcq', 7, 0, 'عند انعكاس المجال يصبح القطب المغناطيسي للأرض القريب من الجنوب الجغرافي قطبًا جنوبيًّا، فيجذب القطب الشمالي للإبرة؛ لذا تشير الإبرة نحو الجنوب الجغرافي.', '["","اتجاه الإبرة يتبع اتجاه المجال الأرضي؛ فإذا انعكس المجال انعكس اتجاهها.","المجال المنعكس يبقى في اتجاه شمال–جنوب، فلا تتجه الإبرة شرقًا.","المجال المنعكس موجود ومنتظم الاتجاه، فتستقر الإبرة في اتجاه محدد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.354Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) الأرض مغناطيس عملاق، والمغانط الحرة (ومنها إبرة البوصلة) تنتظم في اتجاه شمال–جنوب ويشير قطبها الشمالي نحو الشمال الجغرافي. ولأن الأقطاب المغناطيسية المختلفة تتجاذب، يجب أن يكون القطب المغناطيسي للأرض القريب من الشمال الجغرافي قطبًا جنوبيًّا. (b) خطوط المجال تخرج من القطب الشمالي للمغناطيس وتدخل في قطبه الجنوبي؛ فهي تخرج من قرب القطب الجنوبي الجغرافي وتتجه خارج الأرض نحو الشمال الجغرافي فتدخل قربه.', '["الأرض مغناطيس عملاق والبوصلة تنتظم شمال–جنوب","القطب المغناطيسي قرب الشمال الجغرافي جنوبي","السبب: الأقطاب المختلفة تتجاذب","الخطوط خارج الأرض من الجنوب الجغرافي نحو الشمال الجغرافي"]'::jsonb, '[]'::jsonb, '[{"element":"الأرض مغناطيس والبوصلة تنتظم معه","marks":1},{"element":"نوع القطب قرب الشمال الجغرافي","marks":1},{"element":"التعليل بالتجاذب","marks":1},{"element":"اتجاه الخطوط خارج الأرض","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"نوع القطب صحيح مع نقص في التعليل أو اتجاه الخطوط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["القول إن القطب المغناطيسي قرب الشمال الجغرافي شمالي","جعل خطوط المجال خارج الأرض تتجه نحو الجنوب الجغرافي","تعليل اتجاه البوصلة بالجاذبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.354Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) عند A؛ لأن خطوط المجال تتقارب قرب القطبين حيث يتركز معظم التدفق المغناطيسي، فيكون المجال أكبر ما يمكن هناك، أما عند خط الاستواء فتكون الخطوط متباعدة. (b) عند B يكون المجال موازيًا لسطح الأرض ويتجه نحو الشمال الجغرافي (الأسهم على الخطوط إلى أعلى). (c) يشير القطب الشمالي للبوصلة في اتجاه المجال، أي نحو الشمال الجغرافي.', '["المجال أكبر عند A","التعليل بتقارب الخطوط وتركّز التدفق عند القطبين","المجال عند B نحو الشمال الجغرافي موازيًا للسطح","البوصلة عند B تشير نحو الشمال الجغرافي"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد النقطة","marks":1},{"element":"التعليل","marks":1},{"element":"اتجاه المجال عند B","marks":1},{"element":"اتجاه البوصلة عند B","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابات والتعليل صحيحة"},{"level":"2–3 درجات","description":"الإجابة (a) صحيحة مع خطأ في الاتجاه"},{"level":"1 درجة","description":"تحديد النقطة دون تعليل"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["القول إن المجال أكبر عند خط الاستواء لأنه أقرب إلى المغناطيس التخيلي","جعل المجال عند B نحو الجنوب الجغرافي","الخلط بين اتجاه الخطوط وشدتها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.355Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) صخور قاع البحر ناتجة عن اندفاع صخور منصهرة من شقوق في قاع المحيط، وعندما تبرد تتمغنط في اتجاه المجال المغناطيسي الأرضي في ذلك الزمن وتحتفظ به. (b) بسبب توسع قاع البحر تبتعد الصخور القديمة عن الشقوق وتحل محلها صخور جديدة؛ فالأبعد أقدم. (c) يعني أن اتجاه المجال الأرضي كان مختلفًا عند تكوّن كل منها، أي أن القطبين المغناطيسيين للأرض تبادلا موقعيهما عدة مرات على مر العصور. (d) نحو الجنوب الجغرافي؛ لأن القطب المغناطيسي الجنوبي للأرض كان قرب الجنوب الجغرافي.', '["تتمغنط عند تبريدها في اتجاه المجال السائد آنذاك","توسّع قاع البحر يجعل الأبعد أقدم","المغنطة المتعاكسة تعني تبادل القطبين موقعيهما","البوصلة كانت ستشير نحو الجنوب الجغرافي"]'::jsonb, '[]'::jsonb, '[{"element":"آلية المغنطة عند التبريد","marks":1},{"element":"تفسير قِدم الصخور الأبعد","marks":1},{"element":"دلالة المغنطة المتعاكسة","marks":1},{"element":"اتجاه البوصلة في المجال المعكوس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابات الأربع صحيحة"},{"level":"2–3 درجات","description":"إجابتان أو ثلاث صحيحة"},{"level":"1 درجة","description":"إجابة واحدة صحيحة"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["القول إن الصخور تتمغنط عشوائيًّا","القول إن المجال الأرضي ثابت الاتجاه منذ نشأة الأرض","القول إن البوصلة كانت ستشير نحو الشمال الجغرافي أيضًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-28T06:03:18.355Z"}'::jsonb)
