from (values
('mcq', 1, 'يمثل الشكل الآتي ترتيب المناطق المغناطيسية في ثلاث قطع حديد متماثلة. أيّها تمثل المغناطيس الأقوى؟', null, '[{"src":"qimg/phys32/c3l1-o16-three.svg","alt":"ثلاثة مربعات صفراء مرقّمة 1 و2 و3 تمثل ثلاث قطع حديد متماثلة مقسّمة إلى مناطق مغناطيسية، في كل منطقة سهم أخضر يمثل اتجاه مجالها. في القطعة 1 الأسهم في اتجاهات عشوائية. في القطعة 2 يتجه معظم الأسهم تقريبًا نحو اليمين وبعضها في اتجاهات أخرى. في القطعة 3 تتجه الأسهم كلها نحو اليمين."}]'::jsonb, '["القطعة 1؛ لأن مناطقها تتجه في اتجاهات كثيرة مختلفة","القطعة 2؛ لأن بعض مناطقها فقط مرتب في اتجاه واحد","القطع الثلاث متساوية؛ لأن عدد المناطق فيها متساوٍ","القطعة 3؛ لأن جميع مناطقها مرتبة في اتجاه واحد"]'::jsonb, 'فهم', 'تفسير رسم', 'سهل', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('mcq', 2, 'أيّ المجموعات الآتية كلها عناصر لها خاصية الفرومغناطيسية؟', null, null, '["الحديد والنحاس والألومنيوم","الحديد والنيكل والكوبالت","النيكل والنحاس والذهب","الألومنيوم والكوبالت والفضة"]'::jsonb, 'تذكر', 'حقائق', 'سهل', 'الكتاب ص 96 — الأسئلة 34 و41 و42'),
('mcq', 3, 'كل إلكترون في قطعة حديد يشبه مغناطيسًا صغيرًا جدًّا، ومع ذلك قد لا تكون القطعة مغناطيسًا. ما التفسير؟', null, null, '["مناطقها عشوائية الاتجاه فتلغي مجالاتها بعضها بعضًا","إلكتروناتها لا تكتسب مغناطيسية إلا عند مرور تيار كهربائي فيها","تحتوي القطعة على أقطاب مغناطيسية مفردة متعاكسة تلغي بعضها","الحديد غير الممغنط يخلو تمامًا من المناطق المغناطيسية"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 96 — الأسئلة 34 و41 و42'),
('mcq', 4, 'وُضعت قطعة حديد في مجال مغناطيسي خارجي منتظم، فترتبت مناطقها كما في الشكل الآتي. أيّ طرفيها يصبح قطبًا شماليًّا؟', null, '[{"src":"qimg/phys32/c3l1-o16-field.svg","alt":"سهمان أخضران أفقيان طويلان أعلى الشكل وأسفله يتجهان نحو اليمين، يمثلان مجالًا مغناطيسيًّا خارجيًّا منتظمًا B (عبارة: المجال المغناطيسي الخارجي). بينهما قطعة حديد مستطيلة صفراء مقسّمة إلى أربعة صفوف من المناطق المغناطيسية، وفي كل منطقة سهم أخضر يتجه نحو اليمين. الطرف الأيسر للقطعة معلّم بالحرف P والأيمن بالحرف Q."}]'::jsonb, '["الطرف P؛ لأن المجال الخارجي يدخل القطعة منه","الطرفان P وQ معًا؛ لأن المناطق كلها مرتبة","الطرف Q؛ لأن مجالات المناطق تتجه نحوه","لا يتكون قطب؛ لأن الحديد لا يتمغنط بالحث"]'::jsonb, 'تطبيق', 'تفسير رسم', 'متوسط', 'الكتاب ص 75 — القوى المؤثرة في الأجسام الموضوعة في مجالات مغناطيسية'),
('mcq', 5, 'ماذا يحدث للمناطق المغناطيسية في قطعة حديد مطاوع بعد إبعادها عن المجال المغناطيسي الخارجي؟', null, null, '["تبقى مرتبة في اتجاه المجال الخارجي الذي أُزيل","تعود إلى عشوائيتها فتفقد القطعة مغناطيسيتها","تنعكس جميعها فتتبادل القطعة قطبيها","تندمج كلها في منطقة واحدة كبيرة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('mcq', 6, 'لماذا يضعف المغناطيس عند طرقه بشدة أو تسخينه؟', null, null, '["لأن الطرق يُخرج الإلكترونات من ذرات المغناطيس","لأن الطرق يفصل القطبين فيتكون قطبان مفردان","لأن التسخين يحوّل الحديد إلى عنصر غير مغناطيسي آخر","لأن الطرق أو التسخين يبعثر ترتيب مناطقه"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 96 — الأسئلة 34 و41 و42'),
('mcq', 7, 'في التسجيل الصوتي على شريط مغناطيسي، كيف تُخزَّن الإشارة على الشريط؟', null, null, '["يرتّب مجال رأس التسجيل مناطق جسيمات الشريط بحسب التيار","يشحن رأس التسجيل جسيمات الشريط بشحنات كهربائية ساكنة","ينقل رأس التسجيل برادة حديد إلى الشريط بأنماط مختلفة","يزيل رأس التسجيل المناطق المغناطيسية من أجزاء الشريط"]'::jsonb, 'تطبيق', 'تطبيق في الحياة', 'صعب', 'الكتاب ص 79–80 — التسجيل في الوسائط'),
('essay', 1, 'يمثل الشكل الآتي قطعتين من الحديد مقسّمتين إلى مناطق مغناطيسية. (a) أيّ القطعتين تسلك سلوك المغناطيس؟ فسّر إجابتك. (b) صف ما يحدث للمناطق المغناطيسية عند وضع القطعة (a) في مجال مغناطيسي خارجي. (c) ماذا يحدث لمناطقها إذا كانت من الحديد المطاوع ثم أُزيل المجال؟', null, '[{"src":"qimg/phys32/c3l1-o11-domains.svg","alt":"مربعان أصفران يمثلان قطعتين من الحديد مقسّمتين إلى مناطق مغناطيسية، في كل منطقة سهم أخضر يمثل اتجاه مجالها. في المربع (a) الأسهم في اتجاهات عشوائية مختلفة. في المربع (b) الأسهم كلها تتجه نحو اليمين في اتجاه واحد."}]'::jsonb, null, 'فهم', 'تفسير رسم', 'سهل', 'الكتاب ص 79 — المناطق المغناطيسية (الشكل 14-3)'),
('essay', 2, '(a) فسّر لماذا يضعف المغناطيس عند طرقه أو تسخينه، بدلالة المناطق المغناطيسية. (b) كيف يُصنع مغناطيس دائم يحتفظ بمغناطيسيته؟ (c) سمِّ العناصر الثلاثة الأكثر شيوعًا التي لها خاصية الفرومغناطيسية.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 96 — الأسئلة 34 و41 و42'),
('essay', 3, 'وُضعت عينة من النيكل قرب القطب الشمالي لمغناطيس دائم فانجذبت إليه، بينما لم تنجذب عينة من النحاس. (a) صف العمليات المجهرية التي تجعل عينة النيكل تتمغنط وتنجذب. (b) حدّد نوع القطب المتكوّن عند طرف عينة النيكل القريب من القطب الشمالي للمغناطيس، وعلّل. (c) لماذا لم تنجذب عينة النحاس؟', null, null, null, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 75 — القوى المؤثرة في الأجسام الموضوعة في مجالات مغناطيسية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
