from (values
('mcq', 1, 3, 'تصبح قطعة الحديد مغناطيسًا عندما تترتب مناطقها المغناطيسية في اتجاه واحد فتتجمع مجالاتها؛ وكلما زاد عدد المناطق المرتبة في الاتجاه نفسه كان المغناطيس أقوى. فالقطعة 3 الأقوى؛ لأن جميع مناطقها مرتبة في اتجاه واحد.', '["المناطق العشوائية تلغي مجالاتها بعضها بعضًا، فالقطعة 1 غير ممغنطة.","القطعة 2 ممغنطة جزئيًّا، لكنها أضعف من قطعة رُتّبت جميع مناطقها.","العبرة بترتيب المناطق لا بعددها؛ فالقطع متساوية في العدد ومختلفة في الترتيب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-28T06:03:18.356Z"}'::jsonb),
('mcq', 2, 1, 'تسلك العناصر الثلاثة الحديد والنيكل والكوبالت سلوك مغانط كهربائية بطرائق عديدة؛ إذ لها خاصية تسمى الفرومغناطيسية.', '["النحاس والألومنيوم لا ينجذبان إلى المغناطيس، فليسا فرومغناطيسيين.","","النيكل فرومغناطيسي، لكن النحاس والذهب ليسا كذلك.","الكوبالت فرومغناطيسي، لكن الألومنيوم والفضة ليسا كذلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-28T06:03:18.356Z"}'::jsonb),
('mcq', 3, 0, 'مجالات إلكترونات الذرات المتجاورة تترتب في مناطق مغناطيسية، لكن عندما لا تكون قطعة الحديد داخل مجال مغناطيسي تكون مناطقها في اتجاهات عشوائية، أي أن مناطقها عشوائية الاتجاه فتلغي مجالاتها بعضها بعضًا، ولا تسلك القطعة سلوك المغناطيس.', '["","كل إلكترون في الذرة يشبه مغناطيسًا كهربائيًّا صغيرًا دون تيار خارجي؛ والسبب عشوائية المناطق.","لا توجد أقطاب مغناطيسية مفردة.","المناطق موجودة في الحديد غير الممغنط، لكنها عشوائية الاتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-28T06:03:18.356Z"}'::jsonb),
('mcq', 4, 2, 'تترتب المناطق بفعل المجال الخارجي لتصبح متفقة معه في الاتجاه (نحو اليمين)، فتمر خطوط المجال خلال القطعة وتخرج من طرفها الأيمن. وخطوط المجال تخرج من القطب الشمالي؛ لذا الطرف Q قطب شمالي لأن مجالات المناطق تتجه نحوه، والطرف P قطب جنوبي.', '["الطرف الذي تدخل منه خطوط المجال قطب جنوبي، لا شمالي.","القطعة الممغنطة مغناطيس له قطبان مختلفان، لا قطبان شماليان.","","الحديد يتمغنط بالحث داخل المجال؛ إذ تترتب مناطقه في اتجاه المجال الخارجي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-28T06:03:18.356Z"}'::jsonb),
('mcq', 5, 1, 'في حالة المغناطيس المؤقت (كالحديد المطاوع) تعود المناطق إلى عشوائيتها بعد إزالة المجال المغناطيسي الخارجي، فتلغي مجالاتها بعضها بعضًا وتفقد القطعة مغناطيسيتها.', '["بقاء المناطق مرتبة صفة سبائك المغناطيس الدائم لا الحديد المطاوع.","","إزالة المجال لا تعكس المناطق، بل تعيدها إلى اتجاهات عشوائية.","المناطق تبقى صغيرة ومحدودة الحجم، ولا تندمج في منطقة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.357Z"}'::jsonb),
('mcq', 6, 3, 'مغناطيسية القطعة ناتجة عن ترتيب مناطقها المغناطيسية في اتجاه واحد. الطرق أو التسخين يبعثر ترتيب مناطقه المغناطيسية لتصبح أكثر عشوائية، فتلغي مجالاتها بعضها بعضًا جزئيًّا ويضعف المغناطيس.', '["الإلكترونات تبقى في الذرات؛ ما يتغير هو اتجاه المناطق.","لا يمكن الحصول على قطب مفرد بأي طريقة.","التسخين لا يحوّل عنصرًا إلى عنصر آخر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.357Z"}'::jsonb),
('mcq', 7, 0, 'رأس التسجيل مغناطيس كهربائي يولّد مجالات مغناطيسية تمثل الصوت. عندما يمر الشريط فوقه تترتب المناطق المغناطيسية لجسيماته، وتعتمد اتجاهات ترتيبها على اتجاه التيار المار برأس التسجيل؛ فيرتّب مجال رأس التسجيل مناطق جسيمات الشريط بحسب التيار، وتحافظ المادة على هذا الترتيب.', '["","التسجيل مغناطيسي يعتمد على ترتيب المناطق، لا على شحنات كهربائية ساكنة.","الشريط يحتوي أصلًا على جسيمات مغناطيسية؛ ورأس التسجيل يرتب مناطقها لا ينقل إليها برادة.","المناطق لا تزول؛ بل يتغير اتجاه ترتيبها بحسب الإشارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-28T06:03:18.357Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) القطعة (b)؛ لأن مناطقها المغناطيسية مرتبة في اتجاه واحد فتتجمع مجالاتها، أما (a) فمناطقها في اتجاهات عشوائية فتلغي مجالاتها بعضها بعضًا. (b) تترتب المناطق بفعل المجال الخارجي لتصبح متفقة معه في الاتجاه، فتتمغنط القطعة بالحث. (c) تعود المناطق إلى عشوائيتها بعد إزالة المجال الخارجي، فتفقد القطعة مغناطيسيتها (مغناطيس مؤقت).', '["القطعة (b) مغناطيس لأن مناطقها مرتبة في اتجاه واحد","مناطق (a) العشوائية تلغي مجالاتها","في المجال الخارجي تترتب المناطق في اتجاهه","بعد إزالة المجال تعود مناطق الحديد المطاوع عشوائية"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد القطعة الممغنطة مع التفسير","marks":2},{"element":"ترتب المناطق في المجال الخارجي","marks":1},{"element":"عودة المناطق إلى العشوائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابات الثلاث صحيحة مع التفسير"},{"level":"2–3 درجات","description":"إجابتان صحيحتان"},{"level":"1 درجة","description":"إجابة واحدة صحيحة"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["القول إن الحديد غير الممغنط لا يحتوي على مناطق مغناطيسية","القول إن المناطق تتكون فقط داخل المجال","القول إن مناطق الحديد المطاوع تبقى مرتبة بعد إزالة المجال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.357Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) مغناطيسية القطعة ناتجة عن ترتيب مناطقها المغناطيسية في اتجاه واحد؛ والطرق أو التسخين يبعثر هذا الترتيب فتصبح المناطق أكثر عشوائية وتلغي مجالاتها بعضها بعضًا جزئيًّا، فيضعف المغناطيس. (b) يُخلط الحديد مع مواد أخرى لإنتاج سبائك تحافظ على المناطق المغناطيسية مرتبة بعد إزالة تأثير المجال المغناطيسي الخارجي (مثل سبيكة الحديد مع الألومنيوم والنيكل والكوبالت). (c) الحديد والنيكل والكوبالت.', '["الطرق أو التسخين يبعثر ترتيب المناطق","المناطق العشوائية تلغي مجالاتها فيضعف المغناطيس","السبائك تحافظ على ترتيب المناطق بعد إزالة المجال","الحديد والنيكل والكوبالت"]'::jsonb, '[]'::jsonb, '[{"element":"تبعثر ترتيب المناطق","marks":1},{"element":"ربط العشوائية بضعف المغناطيس","marks":1},{"element":"صنع المغناطيس الدائم بالسبائك","marks":1},{"element":"العناصر الثلاثة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"عنصران أو ثلاثة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["القول إن الطرق يُخرج الإلكترونات أو يفصل القطبين","ذكر النحاس أو الألومنيوم عنصرًا فرومغناطيسيًّا","عدم ربط الضعف بترتيب المناطق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.357Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) النيكل عنصر فرومغناطيسي، وتكون مناطقه المغناطيسية في اتجاهات عشوائية خارج المجال. عند وضعه في مجال المغناطيس تترتب مناطقه بفعل المجال الخارجي لتصبح متفقة معه في الاتجاه، وتصبح خطوط المجال مركزة أكثر خلال العينة فتتمغنط بالحث. (b) تخرج خطوط المجال من القطب الشمالي للمغناطيس وتدخل العينة من طرفها القريب ثم تخرج من طرفها الآخر؛ فيكون طرفها القريب قطبًا جنوبيًّا، ولأن القطبين المختلفين يتجاذبان تنجذب العينة. (c) العناصر الثلاثة التي لها خاصية الفرومغناطيسية هي الحديد والنيكل والكوبالت، والنحاس ليس منها؛ فلا توجد فيه مناطق مغناطيسية تترتب في اتجاه المجال، فلا يتمغنط بالحث ولا ينجذب.', '["النيكل فرومغناطيسي ومناطقه عشوائية خارج المجال","تترتب المناطق في اتجاه المجال فتتمغنط العينة بالحث","الطرف القريب من القطب الشمالي قطب جنوبي لأن الخطوط تدخل منه","النحاس ليس من العناصر الفرومغناطيسية (الحديد والنيكل والكوبالت) فلا يتمغنط"]'::jsonb, '[]'::jsonb, '[{"element":"وصف ترتب المناطق والمغنطة بالحث","marks":2},{"element":"نوع القطب مع التعليل","marks":1},{"element":"تفسير عدم انجذاب النحاس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التفسيرات الثلاثة صحيحة"},{"level":"2–3 درجات","description":"المغنطة بالحث صحيحة مع خطأ في نوع القطب أو النحاس"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["القول إن الطرف القريب من القطب الشمالي يصبح شماليًّا","القول إن النيكل مغناطيس دائم أصلًا","تفسير عدم انجذاب النحاس بأنه موصل كهربائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-28T06:03:18.358Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C3-L1-O16') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L1-O17'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين الشكل الآتي خطوط المجال المغناطيسي حول قضيب مغناطيسي. ما اتجاه المجال المغناطيسي عند النقطة P داخل المغناطيس؟', null, '[{"src":"qimg/phys32/c3l1-o17-bar.svg","alt":"قضيب مغناطيسي أفقي رمادي، قطبه الشمالي N على اليسار وقطبه الجنوبي S على اليمين. حوله ثلاثة خطوط مجال خضراء فوقه وثلاثة تحته، كل منها يخرج من طرف N ويلتف ليدخل طرف S، وعلى كل منها سهم في منتصفه يتجه نحو اليمين (من N إلى S خارج المغناطيس). خط أفقي على امتداد المحور: على يسار المغناطيس سهمه يتجه نحو اليسار مبتعدًا عن N، وعلى يمينه سهمه يتجه نحو اليسار داخلًا إلى S. داخل المغناطيس يكمل الخط المحوري مساره خطًّا متقطعًا دون سهم، وعليه النقطة P في منتصف المغناطيس."}]'::jsonb, '["من القطب الشمالي نحو الجنوبي","من القطب الجنوبي نحو الشمالي","صفر؛ لأن الخطوط لا تمر داخل المغناطيس","عمودي على المحور نحو أعلى الصفحة"]'::jsonb, 'فهم', 'تفسير رسم', 'متوسط', 'الكتاب ص 74 — خطوط المجال المغناطيسي حلقات مقفلة (الشكل 5-3)'),
('mcq', 2, 'كُسر قضيب مغناطيسي إلى نصفين كما في الشكل الآتي. ما نوع القطبين عند الطرفين 2 و3؟', null, '[{"src":"qimg/phys32/c3l1-o17-broken.svg","alt":"في الأعلى (قبل الكسر) قضيب مغناطيسي نصفه الأيسر أحمر معلّم بالحرف N ونصفه الأيمن أزرق معلّم بالحرف S. في الأسفل (بعد الكسر) قطعتان رماديتان منفصلتان: القطعة اليسرى طرفاها 1 (يسار، مكان N الأصلي) و2 (يمين، موضع الكسر)، والقطعة اليمنى طرفاها 3 (يسار، موضع الكسر) و4 (يمين، مكان S الأصلي)."}]'::jsonb, '["الطرف 2 شمالي، والطرف 3 جنوبي","الطرفان 2 و3 بلا أي قطبين","الطرف 2 جنوبي، والطرف 3 شمالي","الطرفان 2 و3 جنوبيان"]'::jsonb, 'تطبيق', 'تفسير رسم', 'سهل', 'الكتاب ص 72 — الخصائص العامة للمغانط: لا يوجد قطب مفرد'),
('mcq', 3, 'لماذا تشكّل خطوط المجال المغناطيسي حلقات مقفلة؟', null, null, '["لعدم وجود أقطاب مفردة تبدأ منها الخطوط أو تنتهي فيها","لأن الخطوط تبدأ من القطب الشمالي وتنتهي عند الجنوبي","لأن الخطوط حقيقية ويمكن رؤيتها بوضوح ببرادة الحديد","لأن المجال المغناطيسي منعدم داخل المغناطيس"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 74 — خطوط المجال المغناطيسي حلقات مقفلة (الشكل 5-3)'),
('mcq', 4, 'أيّ العبارات الآتية صحيحة بشأن الأقطاب المغناطيسية المفردة؟', null, null, '["يمكن الحصول عليها بكسر المغناطيس من منتصفه","توجد في باطن الأرض قرب القطبين الجغرافيين","تنتج عن تسخين المغناطيس حتى يفقد أحد قطبيه","لم يحصل عليها أحد حتى على المستوى المجهري"]'::jsonb, 'تذكر', 'حقائق', 'متوسط', 'الكتاب ص 103 — اختبار مقنن السؤال 6'),
('mcq', 5, 'بماذا تختلف خطوط المجال المغناطيسي عن خطوط المجال الكهربائي؟', null, null, '["خطوط المجال المغناطيسي حقيقية، أما الكهربائية فوهمية","خطوط المجال المغناطيسي تبدأ من القطب الجنوبي وتنتهي عند الشمالي","الكهربائية تبدأ وتنتهي عند الشحنات، والمغناطيسية مقفلة","خطوط المجال الكهربائي مقفلة، والمغناطيسية تبدأ وتنتهي عند القطبين"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 74 — خطوط المجال المغناطيسي حلقات مقفلة (الشكل 5-3)'),
('mcq', 6, 'قُطِّع قضيب مغناطيسي إلى أربع قطع متساوية. ما العدد الكلي للأقطاب المغناطيسية في القطع الأربع؟', null, null, '["قطبان فقط","8 أقطاب","4 أقطاب","6 أقطاب"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 72 — الخصائص العامة للمغانط: لا يوجد قطب مفرد'),
('mcq', 7, 'تتبّع طالب أحد خطوط المجال المغناطيسي لقضيب مغناطيسي بدءًا من نقطة P قرب القطب الشمالي خارج المغناطيس، متحركًا دائمًا في اتجاه المجال. أين ينتهي مساره؟', null, null, '["عند القطب الجنوبي للمغناطيس حيث تدخل الخطوط","في اللانهاية بعيدًا عن المغناطيس دون أن يعود","عند القطب الشمالي بعد أن يلتف حول المغناطيس","يعود إلى P نفسها بعد مروره داخل المغناطيس"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 74 — خطوط المجال المغناطيسي حلقات مقفلة (الشكل 5-3)'),
('essay', 1, 'إذا كسرت مغناطيسًا جزأين، فهل تحصل على قطبين منفصلين شمالي وجنوبي؟ وضّح إجابتك، وبيّن نوع القطب عند طرفي موضع الكسر إذا كان القطب الشمالي للمغناطيس الأصلي على اليسار.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 72 والسؤال 37 ص 96'),
('essay', 2, 'اعتمادًا على الشكل الآتي: (a) صف المسار الكامل لخط المجال المحوري خارج المغناطيس وداخله، وحدّد اتجاه المجال عند النقطة P. (b) فسّر لماذا تشكّل خطوط المجال المغناطيسي حلقات مقفلة. (c) قارن ذلك بخطوط المجال الكهربائي.', null, '[{"src":"qimg/phys32/c3l1-o17-bar.svg","alt":"قضيب مغناطيسي أفقي رمادي، قطبه الشمالي N على اليسار وقطبه الجنوبي S على اليمين. حوله ثلاثة خطوط مجال خضراء فوقه وثلاثة تحته، كل منها يخرج من طرف N ويلتف ليدخل طرف S، وعلى كل منها سهم في منتصفه يتجه نحو اليمين (من N إلى S خارج المغناطيس). خط أفقي على امتداد المحور: على يسار المغناطيس سهمه يتجه نحو اليسار مبتعدًا عن N، وعلى يمينه سهمه يتجه نحو اليسار داخلًا إلى S. داخل المغناطيس يكمل الخط المحوري مساره خطًّا متقطعًا دون سهم، وعليه النقطة P في منتصف المغناطيس."}]'::jsonb, null, 'فهم', 'تفسير رسم', 'متوسط', 'الكتاب ص 74 — خطوط المجال المغناطيسي حلقات مقفلة (الشكل 5-3)'),
('essay', 3, 'ادّعى طالب أنه حصل على قطب شمالي مفرد بقطع جزء صغير جدًّا من الطرف الشمالي لقضيب مغناطيسي. (a) قيّم هذا الادعاء مستندًا إلى خصائص المغانط. (b) صف تجربة باستخدام بوصلة تثبت أن للقطعة الصغيرة قطبين، مبيّنًا النتيجة المتوقعة. (c) ماذا يحدث لخطوط المجال حول القطعة الصغيرة؟', null, null, null, 'تقويم', 'تقييم ادعاء', 'صعب', 'الكتاب ص 72 — الخصائص العامة للمغانط: لا يوجد قطب مفرد')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C3-L1-O17') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'خطوط المجال تخرج من القطب الشمالي وتدخل إلى القطب الجنوبي خارج المغناطيس، ولا توجد أقطاب مفردة تنتهي عندها؛ لذا تكمل دورتها داخل المغناطيس من القطب الجنوبي نحو الشمالي لتشكل حلقات مقفلة. فالمجال عند P من القطب الجنوبي نحو الشمالي (نحو اليسار).', '["هذا اتجاه المجال خارج المغناطيس؛ أما داخله فيكمل الخط دورته في الاتجاه المعاكس.","","خطوط المجال تكمل دورتها داخل المغناطيس، ولو انقطعت عند القطبين لكانا قطبين مفردين.","الخط المحوري يمر داخل المغناطيس على امتداد محوره لا عموديًّا عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-28T06:03:18.358Z"}'::jsonb),
('mcq', 2, 2, 'إذا قُسم المغناطيس نصفين نتج مغناطيسان جديدان، لكل منهما قطبان. القطعة اليسرى طرفها 1 شمالي، فطرفها الآخر 2 جنوبي؛ والقطعة اليمنى طرفها 4 جنوبي، فطرفها الآخر 3 شمالي. أي أن الطرف 2 جنوبي، والطرف 3 شمالي.', '["عكس القطبين؛ فلو كان 2 شماليًّا لكان للقطعة اليسرى قطبان شماليان (1 و2).","كل قطعة مغناطيس كامل له قطبان، فيتكون قطبان جديدان عند موضع الكسر.","","كل قطعة لها قطب شمالي وآخر جنوبي، فلا يكون 3 جنوبيًّا مع 4 الجنوبي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.359Z"}'::jsonb),
('mcq', 3, 0, 'لا توجد أقطاب مفردة تنتهي فيها أو تبدأ منها خطوط المجال المغناطيسي؛ لذا فهي تكمل دورتها داخل المغناطيس من القطب الجنوبي إلى القطب الشمالي لتشكل حلقات مقفلة.', '["","الخطوط لا تنتهي عند القطب الجنوبي، بل تكمل دورتها داخل المغناطيس.","خطوط المجال وهمية تساعدنا على تصور المجال، وبرادة الحديد تظهر نمطها فقط.","المجال موجود داخل المغناطيس، وفيه تكمل الخطوط دورتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-28T06:03:18.359Z"}'::jsonb),
('mcq', 4, 3, 'حاول العلماء كسر المغناطيس ليفصلوا القطبين أحدهما عن الآخر للحصول على قطب مغناطيسي منفرد، إلا أن أحدًا لم ينجح في ذلك، أي لم يحصل عليها أحد حتى على المستوى المجهري؛ فكل مغناطيس له قطبان.', '["كسر المغناطيس ينتج مغناطيسين جديدين لكل منهما قطبان.","الأرض مغناطيس عملاق له قطبان مغناطيسيان، لا قطبان مفردان.","التسخين يضعف المغناطيس بتبعثر مناطقه، ولا يفصل أحد قطبيه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-28T06:03:18.359Z"}'::jsonb),
('mcq', 5, 2, 'تتشابه الخطوط في أنها وهمية تساعد على تصور المجال. لكن خطوط المجال الكهربائي تبدأ من الشحنات الموجبة وتنتهي عند السالبة، أما خطوط المجال المغناطيسي فلا توجد أقطاب مفردة تبدأ منها أو تنتهي فيها، فهي مقفلة؛ أي أن الكهربائية تبدأ وتنتهي عند الشحنات، والمغناطيسية مقفلة.', '["النوعان كلاهما خطوط وهمية تستخدم لتصور المجال.","خطوط المجال المغناطيسي لا تبدأ ولا تنتهي عند أي قطب؛ فهي مقفلة.","","عكس الحقيقة؛ فالمغناطيسية هي المقفلة، والكهربائية تبدأ وتنتهي عند الشحنات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-28T06:03:18.359Z"}'::jsonb),
('mcq', 6, 1, 'كل قطعة تنتج عن تقسيم المغناطيس مغناطيس جديد له قطبان (شمالي وجنوبي)، ولا يمكن الحصول على قطب مفرد. فللقطع الأربع $4 \times 2 = 8$ أقطاب.', '["هذا عدد أقطاب المغناطيس قبل التقطيع؛ لكن كل قطعة تصبح مغناطيسًا له قطبان.","","عدّ قطبًا واحدًا لكل قطعة، كأنه يمكن الحصول على قطب مفرد.","أضاف إلى القطبين الأصليين قطبين عند موضعي قطع فقط ($2 + 2 + 2$)، مع أن مواضع القطع ثلاثة وكل منها يُنتج قطبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-28T06:03:18.359Z"}'::jsonb),
('mcq', 7, 3, 'يخرج الخط من القطب الشمالي ويلتف خارج المغناطيس حتى يدخل القطب الجنوبي، لكنه لا ينتهي هناك؛ إذ لا توجد أقطاب مفردة تنتهي فيها الخطوط، فيكمل دورته داخل المغناطيس من القطب الجنوبي إلى الشمالي ويخرج من جديد؛ أي يعود إلى P نفسها بعد مروره داخل المغناطيس لأن الخط حلقة مقفلة.', '["الخط لا ينتهي عند القطب الجنوبي؛ بل يكمل دورته داخل المغناطيس، فلا أقطاب مفردة تنتهي فيها الخطوط.","خطوط مجال المغناطيس حلقات مقفلة تعود إليه، لا تمتد إلى اللانهاية.","الخط يدخل المغناطيس عند القطب الجنوبي لا الشمالي، ولا ينتهي عند أي قطب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-28T06:03:18.359Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لا. إذا قُسم المغناطيس نصفين نتج مغناطيسان جديدان، لكل منهما قطبان شمالي وجنوبي، ولم ينجح أحد في الحصول على قطب مفرد حتى على المستوى المجهري. القطعة اليسرى طرفها الأيسر شمالي فيكون طرفها عند موضع الكسر جنوبيًّا، والقطعة اليمنى طرفها الأيمن جنوبي فيكون طرفها عند موضع الكسر شماليًّا؛ فالطرفان المتقابلان عند الكسر قطبان مختلفان يتجاذبان.', '["لا يمكن الحصول على قطبين منفصلين","كل جزء مغناطيس جديد له قطبان","طرف القطعة اليسرى عند الكسر جنوبي","طرف القطعة اليمنى عند الكسر شمالي"]'::jsonb, '[]'::jsonb, '[{"element":"الإجابة بالنفي","marks":1},{"element":"التعليل: كل جزء مغناطيس له قطبان","marks":1},{"element":"نوع القطبين عند الكسر","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة والتعليل ونوعا القطبين صحيحة"},{"level":"2–3 درجات","description":"الإجابة والتعليل صحيحان مع خطأ في نوع القطبين"},{"level":"1 درجة","description":"الإجابة دون تعليل"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["القول إن كل نصف يحمل قطبًا واحدًا","جعل الطرفين عند الكسر قطبين متشابهين","القول إن المغناطيس يفقد مغناطيسيته بالكسر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-28T06:03:18.360Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) يخرج الخط من القطب الشمالي N متجهًا نحو اليسار، ويلتف خارج المغناطيس ليعود فيدخل القطب الجنوبي S من اليمين، ثم يكمل دورته داخل المغناطيس من S نحو N؛ فالمجال عند P يتجه من القطب الجنوبي نحو الشمالي (نحو اليسار). (b) لأنه لا توجد أقطاب مفردة تبدأ منها خطوط المجال أو تنتهي فيها، فتكمل الخطوط دورتها داخل المغناطيس دائمًا. (c) الخطوط في الحالتين وهمية تساعد على تصور المجال، لكن خطوط المجال الكهربائي تبدأ من الشحنات الموجبة وتنتهي عند السالبة، أما خطوط المجال المغناطيسي فمقفلة لا بداية لها ولا نهاية.', '["الخط خارج المغناطيس من N إلى S","داخل المغناطيس من S إلى N، والمجال عند P نحو N","لا أقطاب مفردة تبدأ منها الخطوط أو تنتهي فيها","الكهربائية تبدأ وتنتهي عند الشحنات والمغناطيسية مقفلة"]'::jsonb, '[]'::jsonb, '[{"element":"المسار خارج المغناطيس","marks":1},{"element":"المسار داخله والاتجاه عند P","marks":1},{"element":"التفسير بعدم وجود أقطاب مفردة","marks":1},{"element":"المقارنة بالمجال الكهربائي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"المسار والتفسير صحيحان مع نقص في المقارنة أو الاتجاه داخل المغناطيس"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["جعل المجال داخل المغناطيس من N إلى S","القول إن الخطوط تنتهي عند القطب الجنوبي","القول إن خطوط المجال المغناطيسي حقيقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-28T06:03:18.360Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) الادعاء غير صحيح؛ فإذا قُسم المغناطيس نتج مغناطيسان جديدان لكل منهما قطبان، ولم ينجح أحد في الحصول على قطب مغناطيسي منفرد حتى على المستوى المجهري. للقطعة الصغيرة قطب شمالي (طرفها الخارجي) وقطب جنوبي (عند موضع القطع). (b) نقرّب كل طرف من طرفي القطعة من القطب الشمالي لإبرة البوصلة: أحد الطرفين يتنافر معه (قطب شمالي)، والطرف الآخر (موضع القطع) يجذبه وينفر القطب الجنوبي للإبرة (قطب جنوبي)؛ فالتنافر مع قطبي الإبرة كلٍّ في جهة يثبت وجود قطبين. (c) تخرج خطوط المجال من قطبها الشمالي وتدخل قطبها الجنوبي، وتكمل دورتها داخل القطعة لتشكل حلقات مقفلة كأي مغناطيس.', '["الادعاء غير صحيح","كل قطعة مغناطيس له قطبان ولا قطب مفرد حتى مجهريًّا","تجربة البوصلة: كل طرف يتنافر مع قطب مختلف من الإبرة","خطوط المجال حول القطعة حلقات مقفلة من N إلى S"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على الادعاء","marks":1},{"element":"التعليل بخصائص المغانط","marks":1},{"element":"تجربة البوصلة ونتيجتها","marks":2},{"element":"وصف خطوط المجال","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التقييم والتعليل والتجربة والخطوط صحيحة"},{"level":"3–4 درجات","description":"التقييم والتعليل صحيحان مع نقص في التجربة أو الخطوط"},{"level":"1–2 درجة","description":"الحكم صحيح دون تعليل كافٍ"},{"level":"صفر","description":"لا عنصر صحيح"}]'::jsonb, '["قبول الادعاء لأن القطعة مأخوذة من الطرف الشمالي","الاعتماد على الجذب وحده في تجربة البوصلة","القول إن خطوط المجال تخرج من القطعة ولا تعود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-28T06:03:18.361Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
