('mcq', 1, 'عند إغلاق دائرة كهربائية يتحرك سلك مستقيم موضوع عموديًّا بين قطبي مغناطيس. ما سبب حركة السلك؟', null, null, '["يؤثر المجال المغناطيسي بقوة في الشحنات المتحركة في السلك، فتتولد قوة مغناطيسية تؤثر في السلك","يسخن السلك بمرور التيار الكهربائي فيه فيتمدد ويتحرك بين القطبين","يتمغنط السلك النحاسي بمرور التيار فيجذبه أقرب القطبين إليه","تؤثر البطارية في السلك بقوة كهربائية تدفعه في اتجاه التيار"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'سهل', 'الكتاب ص 81 — القوى المؤثرة في التيارات الكهربائية المارة في مجالات مغناطيسية'),
('mcq', 2, 'سلك نحاسي مستقيم موضوع عموديًّا في مجال مغناطيسي منتظم، وطرفاه موصولان ببطارية عبر مفتاح مفتوح. ماذا يحدث للسلك؟', null, null, '["يتحرك نحو القطب الشمالي؛ لأن المجال المغناطيسي يجذب النحاس","يتحرك في اتجاه خطوط المجال من القطب الشمالي إلى الجنوبي","يبقى ساكنًا؛ لأنه لا يسري فيه تيار فلا تؤثر فيه قوة مغناطيسية","يهتز ببطء؛ لأن البطارية الموصولة به تولد فيه قوة رغم فتح المفتاح"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'سهل', 'الكتاب ص 81 — القوى المؤثرة في التيارات الكهربائية المارة في مجالات مغناطيسية'),
('mcq', 3, 'يبين الشكل الآتي سلكًا مستقيمًا في مجال مغناطيسي منتظم داخل في الورقة. في الحالة (1) يتأثر السلك بقوة مغناطيسية إلى أعلى الصفحة. إذا عُكس اتجاه التيار كما في الحالة (2) مع بقاء المجال كما هو، فما القوة المؤثرة في السلك؟', null, '[{"src":"qimg/phys32/c3l2-o01-reverse.svg","alt":"شكلان متجاوران لسلك مستقيم أفقي في مجال مغناطيسي منتظم داخل في الورقة تمثله رموز (×) خضراء، ويرمز للمجال بالحرف B. في الحالة (1) سهم التيار I فوق السلك يتجه إلى اليمين، وسهم أزرق للقوة F يبدأ من السلك ويتجه إلى أعلى الصفحة. في الحالة (2) سهم التيار I يتجه إلى اليسار، ومكان سهم القوة علامة استفهام."}]'::jsonb, '["يتضاعف مقدارها ويبقى اتجاهها إلى أعلى الصفحة","لها المقدار نفسه واتجاهها إلى أعلى الصفحة","تنعدم؛ لأن التيار أصبح معاكسًا للمجال","لها المقدار نفسه واتجاهها إلى أسفل الصفحة"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 81 — الشكل 15-3 (اتجاه القوة يعتمد على اتجاه التيار)'),
('mcq', 4, 'ما العلاقة بين اتجاه القوة المغناطيسية المؤثرة في سلك يسري فيه تيار واتجاهي التيار والمجال المغناطيسي؟', null, null, '["في اتجاه المجال المغناطيسي دائمًا","عمودية على اتجاه كل من التيار والمجال المغناطيسي","في اتجاه التيار الكهربائي دائمًا","عكس اتجاه المجال المغناطيسي دائمًا"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 81 — القوى المؤثرة في التيارات الكهربائية المارة في مجالات مغناطيسية'),
('mcq', 5, 'لماذا افترض أمبير أن سلكًا يسري فيه تيار كهربائي يتأثر بقوة عند وضعه في مجال مغناطيسي؟', null, null, '["لأن السلك الذي يسري فيه تيار يكتسب شحنة موجبة كبيرة فيجذبه قطبا المغناطيس","لأن التيار يولد مجالًا مغناطيسيًّا يشبه مجال المغناطيس الدائم الذي يتأثر بقوة في المجال","لأن المغناطيس الدائم يولد تيارًا كهربائيًّا إضافيًّا في أي سلك قريب منه","لأن النحاس مادة مغناطيسية تتمغنط بسهولة عند وضعها في مجال"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 81 — مقدمة الدرس (فرضية أمبير)'),
('mcq', 6, 'اكتشف فاراداي أن القوة المغناطيسية المؤثرة في سلك يسري فيه تيار موضوع في مجال مغناطيسي تكون عمودية على اتجاه كل من التيار والمجال، لكن هذا الوصف لم يكن كافيًا لتحديد اتجاه حركة السلك. لماذا؟', null, null, '["لأن القوة تكون أحيانًا موازية للمجال المغناطيسي، فلا تبقى عمودية عليه دائمًا","لأن اتجاه القوة يعتمد على نوع مادة السلك، فيختلف من سلك إلى آخر","لأن السلك لا يتحرك إلا إذا كان موازيًا للمجال، فلا معنى لاتجاه عمودي","لأن هناك اتجاهين متعاكسين عموديين على التيار والمجال معًا، فقد تكون القوة إلى أعلى أو إلى أسفل"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 81 — تحديد اتجاه القوة (الشكل 15-3)'),
('mcq', 7, 'النحاس ليس مادة مغناطيسية، ومع ذلك يتحرك سلك نحاسي يسري فيه تيار عند وضعه عموديًّا في مجال مغناطيسي. ما تفسير ذلك؟', null, null, '["النحاس يتمغنط بمرور التيار فيه فيجذبه أحد القطبين","المجال المغناطيسي يجذب أي فلز موصل سواء سرى فيه تيار أم لا","القوة تؤثر في الشحنات المتحركة (التيار) لا في نوع المادة، فتنتقل إلى السلك نفسه","القوة ناتجة عن المجال الكهربائي للبطارية لا عن المجال المغناطيسي"]'::jsonb, 'تحليل', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 81 — القوى المؤثرة في التيارات الكهربائية المارة في مجالات مغناطيسية'),
('essay', 1, 'يبين الشكل الآتي سلكًا مستقيمًا أفقيًّا بين قطبي مغناطيس، موصولًا ببطارية ومفتاح مفتوح. (a) ماذا يحدث للسلك عند إغلاق المفتاح؟ فسّر. (b) ما العلاقة بين اتجاه القوة المؤثرة في السلك واتجاهي التيار والمجال المغناطيسي؟ (c) ماذا يحدث للسلك إذا عُكس قطبا البطارية؟', null, '[{"src":"qimg/phys32/c3l2-o01-e1.svg","alt":"قطب مغناطيسي شمالي N في الأعلى وقطب جنوبي S في الأسفل، وبينهما خطوط مجال مغناطيسي خضراء رأسية تتجه من N إلى S (إلى أسفل الصفحة) ويرمز لها B. يمر بين القطبين سلك نحاسي مستقيم أفقي عمودي على خطوط المجال، وطرفاه موصولان بأسلاك توصيل إلى بطارية ومفتاح مفتوح في أسفل الشكل."}]'::jsonb, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 81 — الشكل 15-3، وص 95 المفاهيم الرئيسة'),
('essay', 2, 'قال طالب: «يتحرك السلك الذي يسري فيه تيار بين قطبي مغناطيس لأنه ينجذب نحو القطب الشمالي أو القطب الجنوبي». قوّم هذه العبارة، ثم اكتب التفسير الصحيح لحركة السلك، مستدلًّا بدليلين على خطأ العبارة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 81–82 — القوى المؤثرة في التيارات الكهربائية في المجالات المغناطيسية'),
('essay', 3, 'لكي يتحرك سلك مستقيم بين قطبي مغناطيس يلزم: مصدر جهد (بطارية)، ومغناطيس، وسلك موضوع عموديًّا على المجال. (a) وضّح دور كل عنصر منها. (b) ماذا يحدث للسلك إذا أُزيل المغناطيس مع بقاء التيار؟ (c) ماذا يحدث إذا أُزيلت البطارية مع بقاء المغناطيس؟ (d) ماذا يحدث إذا دُوِّر السلك ليصبح موازيًا للمجال؟', null, null, null, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 81 و83 — القوى المؤثرة في التيارات، والعلاقة F = ILB (sin θ)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
