insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'عندما يسري تيار كهربائي في سلك موضوع في مجال مغناطيسي تتولد قوة مغناطيسية تؤثر فيه؛ لأن المجال المغناطيسي يؤثر بقوة في الشحنات المتحركة، وهذه القوة عمودية على اتجاهي التيار والمجال فتحرّك السلك.', '["","التسخين لا يسبب حركة السلك؛ فالحركة ناتجة عن القوة المغناطيسية، وتنعكس بعكس التيار.","النحاس لا يتمغنط ولا ينجذب إلى أحد القطبين؛ والقوة عمودية على المجال لا في اتجاه القطب.","القوة المؤثرة في السلك مغناطيسية مصدرها المجال، وهي عمودية على اتجاه التيار لا في اتجاهه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-28T06:03:18.361Z"}'::jsonb),
('mcq', 2, 2, 'المفتاح المفتوح يقطع الدائرة فلا يسري تيار في السلك، والقوة المغناطيسية لا تتولد إلا عند سريان تيار في السلك؛ لذا يبقى السلك ساكنًا.', '["النحاس لا ينجذب إلى المغناطيس، والقوة المغناطيسية تحتاج إلى تيار يسري في السلك.","لا تؤثر قوة في السلك دون تيار، وحتى مع التيار تكون القوة عمودية على خطوط المجال لا في اتجاهها.","","الدائرة المفتوحة لا يسري فيها تيار، فلا تؤثر البطارية في السلك بأي قوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-28T06:03:18.362Z"}'::jsonb),
('mcq', 3, 3, 'يعتمد اتجاه القوة المغناطيسية المؤثرة في السلك على اتجاه التيار المار فيه؛ فعند عكس التيار مع بقاء المجال ينعكس اتجاه القوة؛ فللقوة المقدار نفسه (لأن مقادير التيار وطول السلك والمجال لم تتغير) واتجاهها إلى أسفل الصفحة.', '["مقدار التيار لم يتغير فلا يتغير مقدار القوة، واتجاهها ينعكس بعكس التيار.","اتجاه القوة يعتمد على اتجاه التيار، فلا يبقى كما هو عند عكس التيار.","التيار ما زال عموديًّا على المجال (الداخل في الورقة)، فالقوة لا تنعدم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.362Z"}'::jsonb),
('mcq', 4, 1, 'اكتشف فاراداي أن القوة المغناطيسية المؤثرة في السلك تكون عمودية على اتجاه كل من التيار الكهربائي والمجال المغناطيسي.', '["القوة عمودية على المجال، لا في اتجاهه.","","القوة عمودية على التيار، لا في اتجاهه.","القوة لا تكون موازية للمجال لا في اتجاهه ولا عكسه؛ بل عمودية عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-28T06:03:18.362Z"}'::jsonb),
('mcq', 5, 1, 'لاحظ أمبير أن التيار الكهربائي يولد مجالًا مغناطيسيًّا مشابهًا لمجال المغناطيس الدائم، ولأن المجال المغناطيسي يؤثر بقوة في المغانط افترض أنه توجد قوة تؤثر في السلك الذي يسري فيه تيار عند وضعه في المجال.', '["السلك الذي يسري فيه تيار متعادل كهربائيًّا، والقوة مغناطيسية لا كهربائية.","","المغناطيس الساكن لا يولد تيارًا في سلك ساكن، والتيار في هذه الحالة مصدره البطارية.","النحاس ليس مادة مغناطيسية، والقوة تنشأ عن التيار لا عن تمغنط السلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-28T06:03:18.362Z"}'::jsonb),
('mcq', 6, 3, 'الاتجاه العمودي على كل من التيار والمجال ليس اتجاهًا واحدًا، بل اتجاهان متعاكسان (إلى أعلى أو إلى أسفل مثلًا)، ويتحدد أحدهما باتجاه التيار المار في السلك؛ لذا لم يكن وصف فاراداي كافيًا، واحتيج إلى قاعدة تحدد أيّ الاتجاهين هو اتجاه القوة.', '["القوة المغناطيسية المؤثرة في السلك عمودية دائمًا على كل من التيار والمجال، ولا تكون موازية للمجال.","اتجاه القوة يعتمد على اتجاهي التيار والمجال، لا على نوع مادة السلك.","عندما يوازي السلك المجال تنعدم القوة فلا يتحرك؛ ويتحرك السلك عندما يكون عموديًّا على المجال.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-28T06:03:18.363Z"}'::jsonb),
('mcq', 7, 2, 'القوة المغناطيسية تؤثر في الشحنات المتحركة؛ فالتيار شحنات تتحرك داخل السلك، والمجال يؤثر فيها بقوة عمودية على اتجاه حركتها، ولأنها محصورة داخل السلك تنتقل القوة إلى السلك فيتحرك، مهما كانت مادته مغناطيسية أم لا.', '["النحاس لا يتمغنط، والقوة لا تتجه نحو أحد القطبين بل عمودية على المجال.","السلك النحاسي الذي لا يسري فيه تيار لا يتأثر بقوة في المجال المغناطيسي.","","لو كانت القوة من البطارية لتحرك السلك دون مغناطيس؛ والقوة هنا مغناطيسية تعتمد على وجود المجال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-28T06:03:18.363Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) يتحرك السلك؛ لأن إغلاق المفتاح يجعل تيارًا كهربائيًّا يسري فيه، والسلك عمودي على المجال المغناطيسي بين القطبين، فتتولد قوة مغناطيسية تؤثر فيه. (b) القوة عمودية على كل من اتجاه التيار (الأفقي) واتجاه المجال (الرأسي من N إلى S)؛ فيتحرك السلك إلى داخل الورقة أو إلى خارجها وفق اتجاه التيار. (c) ينعكس اتجاه التيار فينعكس اتجاه القوة، فيتحرك السلك في الاتجاه المعاكس، ويبقى مقدار القوة كما هو إذا لم يتغير مقدار التيار.', '["يتحرك السلك عند إغلاق المفتاح","سبب الحركة: قوة مغناطيسية تؤثر في سلك يسري فيه تيار في مجال","القوة عمودية على التيار والمجال","عكس التيار يعكس اتجاه القوة"]'::jsonb, '[]'::jsonb, '[{"element":"حركة السلك عند الإغلاق","marks":1},{"element":"تفسير الحركة","marks":1},{"element":"العلاقة بين الاتجاهات","marks":1},{"element":"أثر عكس البطارية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"يذكر الحركة وسببها مع نقص في (b) أو (c)"},{"level":"1 درجة","description":"يذكر أن السلك يتحرك دون تفسير صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السلك ينجذب نحو القطب الشمالي أو الجنوبي","القول إن عكس البطارية لا يغير اتجاه الحركة","القول إن السلك يتحرك والمفتاح مفتوح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.363Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العبارة غير صحيحة. التفسير الصحيح: عندما يسري تيار في سلك موضوع في مجال مغناطيسي يؤثر المجال بقوة مغناطيسية في الشحنات المتحركة في السلك، وتكون هذه القوة عمودية على كل من اتجاه التيار واتجاه المجال. الدليل الأول: القوة عمودية على خطوط المجال الممتدة من N إلى S، فلا يتحرك السلك نحو أيّ من القطبين بل في اتجاه عمودي على الخط الواصل بينهما. الدليل الثاني: عند عكس اتجاه التيار ينعكس اتجاه الحركة مع بقاء القطبين في مكانيهما، ولو كان الأمر تجاذبًا مع قطب لما تغير الاتجاه. (ويصلح دليلًا أيضًا أن السلك لا يتحرك إذا لم يسرِ فيه تيار، وأن النحاس لا ينجذب إلى المغناطيس.)', '["الحكم بأن العبارة غير صحيحة","التفسير: قوة مغناطيسية على التيار في المجال","القوة عمودية على المجال فلا تتجه نحو القطبين","دليل ثانٍ: انعكاس الحركة بعكس التيار أو عدم الحركة دون تيار"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التفسير الصحيح","marks":1},{"element":"الدليل الأول","marks":1},{"element":"الدليل الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"حكم صحيح مع تفسير صحيح ودليل واحد"},{"level":"1 درجة","description":"حكم صحيح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن المغناطيس يجذب الفلزات","الاكتفاء بالحكم دون ذكر أن القوة عمودية على المجال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.364Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) البطارية تولد تيارًا كهربائيًّا (شحنات متحركة) في السلك، والمغناطيس يوفر مجالًا مغناطيسيًّا يؤثر بقوة في الشحنات المتحركة، ووضع السلك عموديًّا على المجال يجعل القوة أكبر ما يمكن ($F = \mathrm{ILB}$). (b) لا يتحرك؛ لعدم وجود مجال مغناطيسي خارجي يؤثر في التيار. (c) لا يتحرك؛ لعدم وجود تيار في السلك. (d) لا يتحرك؛ لأن $\theta = 0^\circ$ فتنعدم القوة.', '["دور البطارية: توليد التيار","دور المغناطيس: توفير المجال المؤثر في التيار","لا حركة دون مجال أو دون تيار","لا حركة عند توازي السلك والمجال"]'::jsonb, '[]'::jsonb, '[{"element":"دور العناصر الثلاثة","marks":2},{"element":"حالة إزالة المغناطيس","marks":1},{"element":"حالة إزالة البطارية","marks":1},{"element":"حالة التوازي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"3–4 درجات","description":"أدوار العناصر صحيحة مع خطأ في إحدى الحالات"},{"level":"1–2 درجة","description":"يوضح دور عنصر أو عنصرين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السلك يتحرك بفعل المغناطيس وحده","القول إن القوة تكون أكبر عندما يوازي السلك المجال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-28T06:03:18.364Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
