insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L2-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تتناسب القوة المغناطيسية المؤثرة في سلك مستقيم يسري فيه تيار موضوع عموديًّا في مجال مغناطيسي طرديًّا مع:', null, null, '["مقدار التيار، ومقاومة السلك، وكتلة السلك","طول السلك، ومساحة مقطعه، وبعده عن القطب الشمالي","مقدار التيار، وطول السلك داخل المجال، ومقدار المجال المغناطيسي","مقدار المجال، ونوع مادة السلك، ودرجة حرارته"]'::jsonb, 'تذكر', 'استرجاع قانون', 'سهل', 'الكتاب ص 83 — القوة المغناطيسية المؤثرة في سلك يسري فيه تيار'),
('mcq', 2, 'أيّ العلاقات الآتية تعطي مقدار القوة المغناطيسية المؤثرة في سلك يسري فيه تيار ويصنع زاوية $\theta$ مع المجال المغناطيسي؟', null, null, '["$F = \\mathrm{ILB}\\,(\\sin\\theta)$","$F = \\mathrm{ILB}\\,(\\cos\\theta)$","$F = \\frac{\\mathrm{IL}}{\\mathrm{B}}\\,(\\sin\\theta)$","$F = qv\\mathrm{B}\\,(\\sin\\theta)$"]'::jsonb, 'تذكر', 'استرجاع قانون', 'سهل', 'الكتاب ص 83 — القوة المغناطيسية المؤثرة في سلك يسري فيه تيار'),
('mcq', 3, 'ما وحدة قياس مقدار المجال المغناطيسي $\mathrm{B}$، وبمَ تكافئ؟', null, null, '["النيوتن N، ويكافئ 1 T.A.m","الأمبير A، ويكافئ 1 C/s","التسلا T، وتكافئ 1 N.A/m","التسلا T، وتكافئ 1 N/A.m"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 83 — القوة المغناطيسية المؤثرة في سلك يسري فيه تيار'),
('mcq', 4, 'سلك يسري فيه تيار موضوع عموديًّا في مجال مغناطيسي منتظم ويتأثر بقوة مقدارها $F$. إذا ضوعف التيار المار فيه مع بقاء طوله داخل المجال ومقدار المجال ثابتين، فكم يصبح مقدار القوة؟', null, null, '["تقل إلى النصف فتصبح $\\frac{F}{2}$","تتضاعف فتصبح $2F$","تصبح أربعة أمثالها $4F$","تبقى كما هي $F$"]'::jsonb, 'فهم', 'علاقة تناسب', 'متوسط', 'الكتاب ص 83 — القوة المغناطيسية المؤثرة في سلك يسري فيه تيار'),
('mcq', 5, 'سلك يسري فيه تيار ثابت موضوع في مجال مغناطيسي منتظم. متى يكون مقدار القوة المغناطيسية المؤثرة فيه أكبر ما يمكن؟', null, null, '["عندما يكون السلك موازيًا للمجال ($\\theta = 0^\\circ$)","عندما يصنع السلك زاوية $45^\\circ$ مع المجال","مقدار القوة واحد في جميع الأوضاع ما دام التيار ثابتًا","عندما يكون السلك عموديًّا على المجال ($\\theta = 90^\\circ$)"]'::jsonb, 'فهم', 'علاقة تناسب', 'متوسط', 'الكتاب ص 83 — القوة المغناطيسية المؤثرة في سلك يسري فيه تيار (أثر الزاوية θ)'),
('mcq', 6, 'يبين الشكل الآتي سلكًا مستقيمًا طوله 1.20 m يسري فيه تيار، ولا يقع منه داخل المجال المغناطيسي المنتظم إلا جزء طوله 0.30 m عمودي على المجال. ما قيمة $\mathrm{L}$ التي تُستخدم لحساب القوة المغناطيسية المؤثرة في السلك؟', null, '[{"src":"qimg/phys32/c3l2-o02-inside.svg","alt":"سلك نحاسي مستقيم أفقي يسري فيه تيار I إلى اليمين، طوله الكلي 1.20 m كما يبين خط قياس أسفل الشكل. يمر السلك عبر منطقة مستطيلة خضراء مكتوب فوقها «منطقة المجال» وفيها رموز (×) تمثل مجالًا مغناطيسيًّا منتظمًا B داخلًا في الورقة، وطول جزء السلك الواقع داخل هذه المنطقة 0.30 m كما يبين خط قياس آخر. خارج المنطقة لا يوجد مجال."}]'::jsonb, '["0.30 m، وهو طول جزء السلك الواقع داخل المجال","1.20 m، وهو الطول الكلي للسلك","1.50 m، وهو مجموع الطولين المبينين","0.90 m، وهو طول جزء السلك الواقع خارج المجال"]'::jsonb, 'فهم', 'تحديد متغير', 'صعب', 'الكتاب ص 83 — القوة المغناطيسية المؤثرة في سلك يسري فيه تيار (L طول السلك داخل المجال)'),
('mcq', 7, 'يبين الجدول الآتي أربعة أسلاك موضوعة عموديًّا على مجالات مغناطيسية منتظمة. أيّ الأسلاك يتأثر بأكبر قوة مغناطيسية؟', '{"headers":["السلك","$\\mathrm{I}$ (A)","$\\mathrm{L}$ (m)","$\\mathrm{B}$ (T)"],"rows":[["1","2.0","0.50","0.40"],["2","4.0","0.20","0.30"],["3","1.0","1.00","0.50"],["4","3.0","0.40","0.30"]]}'::jsonb, null, '["السلك 1","السلك 2","السلك 3","السلك 4"]'::jsonb, 'تطبيق', 'مقارنة كمية', 'صعب', 'الكتاب ص 83 — F = ILB، وص 99 الأسئلة 71–73'),
('essay', 1, 'اذكر العوامل التي يعتمد عليها مقدار القوة المغناطيسية المؤثرة في سلك مستقيم يسري فيه تيار موضوع في مجال مغناطيسي، واكتب العلاقة الرياضية التي تربطها، موضحًا مدلول كل رمز ووحدة قياسه.', null, null, null, 'تذكر', 'استرجاع قانون', 'متوسط', 'الكتاب ص 83، وص 95 المفاهيم الرئيسة'),
('essay', 2, 'سلك يسري فيه تيار موضوع عموديًّا في مجال مغناطيسي منتظم ويتأثر بقوة مقدارها 0.60 N. احسب مقدار القوة الجديدة إذا أصبح التيار ثلاثة أمثال قيمته، وقلّ طول السلك داخل المجال إلى النصف، وضوعف مقدار المجال المغناطيسي، موضحًا أثر كل عامل.', null, null, null, 'تطبيق', 'علاقة تناسب', 'متوسط', 'الكتاب ص 83 — القوة المغناطيسية المؤثرة في سلك يسري فيه تيار'),
('essay', 3, 'يبين الشكل الآتي ثلاثة أسلاك متماثلة في مجال مغناطيسي منتظم، يسري في كل منها التيار نفسه، ولكل منها الطول نفسه داخل المجال: السلك 1 عمودي على المجال، والسلك 2 يصنع زاوية $30^\circ$ مع المجال، والسلك 3 موازٍ له. (a) رتّب الأسلاك تنازليًّا حسب مقدار القوة المغناطيسية المؤثرة فيها، وفسّر. (b) إذا كانت القوة المؤثرة في السلك 1 تساوي 0.40 N، فما مقدار القوة المؤثرة في كل من السلكين 2 و3؟', null, '[{"src":"qimg/phys32/c3l2-o02-angles.svg","alt":"أربعة خطوط مجال مغناطيسي خضراء أفقية متوازية تتجه إلى اليمين ويرمز لها B. فيها ثلاثة أسلاك مرقمة: السلك 1 رأسي عمودي على خطوط المجال، والسلك 2 مائل يصنع زاوية 30° مع خطوط المجال (الزاوية مؤشر عليها بقوس وخط متقطع أفقي)، والسلك 3 أفقي موازٍ لخطوط المجال."}]'::jsonb, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 83 — أثر الزاوية θ، وص 101 السؤال 92')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
