from (values
('mcq', 1, 2, 'مقدار القوة المغناطيسية المؤثرة في السلك $F$ يتناسب طرديًّا مع كل من مقدار المجال المغناطيسي $\mathrm{B}$، ومقدار التيار $\mathrm{I}$، وطول السلك $\mathrm{L}$ الموضوع داخل المجال: $F = \mathrm{ILB}$.', '["المقاومة والكتلة لا تظهران في علاقة القوة؛ فالعوامل هي التيار وطول السلك والمجال.","مساحة المقطع والبعد عن القطب ليسا من عوامل القوة في العلاقة.","","نوع المادة ودرجة الحرارة ليسا من عوامل القوة عند ثبات التيار؛ والعوامل هي التيار والطول والمجال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-28T06:03:18.364Z"}'::jsonb),
('mcq', 2, 0, 'القوة المؤثرة في سلك يسري فيه تيار موضوع في مجال مغناطيسي: $F = \mathrm{ILB}\,(\sin\theta)$، وتؤول إلى $F = \mathrm{ILB}$ عندما $\theta = 90^\circ$ وإلى الصفر عندما $\theta = 0^\circ$.', '["","مع جيب التمام تكون القوة أكبر ما يمكن عند توازي السلك والمجال، وهذا عكس الصحيح.","القوة تتناسب طرديًّا مع المجال $\\mathrm{B}$ لا عكسيًّا.","هذه علاقة القوة المؤثرة في جسيم مشحون متحرك، لا في سلك يسري فيه تيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.365Z"}'::jsonb),
('mcq', 3, 3, 'يُقاس مقدار المجال المغناطيسي بوحدة التسلا T، وهي تساوي 1 N/A.m، كما يتبين من $\mathrm{B} = \frac{F}{\mathrm{IL}}$.', '["النيوتن وحدة القوة لا وحدة المجال المغناطيسي.","الأمبير وحدة التيار الكهربائي لا المجال المغناطيسي.","من $\\mathrm{B} = \\frac{F}{\\mathrm{IL}}$ يقسم النيوتن على حاصل ضرب الأمبير في المتر، لا يُضرب في الأمبير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.365Z"}'::jsonb),
('mcq', 4, 1, 'القوة تتناسب طرديًّا مع التيار ($F = \mathrm{ILB}$)، فإذا ضوعف التيار مع ثبات $\mathrm{L}$ و$\mathrm{B}$ تتضاعف القوة لتصبح $2F$.', '["العلاقة طردية لا عكسية، فلا تقل القوة بزيادة التيار.","","التيار في العلاقة من الدرجة الأولى، فلا يُربَّع.","القوة تعتمد على مقدار التيار، فلا تبقى ثابتة عند تغيّره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-28T06:03:18.365Z"}'::jsonb),
('mcq', 5, 3, 'من $F = \mathrm{ILB}\,(\sin\theta)$ تكون القوة أكبر ما يمكن عندما $\sin\theta = 1$ أي $\theta = 90^\circ$ (السلك عمودي على المجال)، وتنعدم عند التوازي ($\theta = 0^\circ$).', '["عند التوازي $\\sin 0^\\circ = 0$ فتنعدم القوة، لا تكون أكبر ما يمكن.","عند $45^\\circ$ تكون القوة نحو 0.71 من قيمتها العظمى فقط.","القوة تعتمد على الزاوية بين السلك والمجال، فتتغير بتغير وضع السلك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-28T06:03:18.365Z"}'::jsonb),
('mcq', 6, 0, 'الطول $\mathrm{L}$ في العلاقة $F = \mathrm{ILB}$ هو طول السلك الموضوع داخل المجال المغناطيسي؛ لأن الأجزاء الواقعة خارج المجال لا تتأثر بقوة مغناطيسية. لذا $\mathrm{L} = 0.30\ \text{m}$.', '["","أجزاء السلك خارج المجال لا تتأثر بقوة، فلا يُستخدم الطول الكلي.","الطول 0.30 m جزء من الطول 1.20 m، فجمعهما لا معنى له.","الجزء الواقع خارج المجال لا تؤثر فيه قوة مغناطيسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-28T06:03:18.366Z"}'::jsonb),
('mcq', 7, 2, 'بحساب $F = \mathrm{ILB}$ لكل سلك: السلك 1: 0.40 N، السلك 2: 0.24 N، السلك 3: 0.50 N، السلك 4: 0.36 N؛ فأكبر قوة تؤثر في السلك 3 رغم أن تياره أصغر التيارات، لأن القوة تعتمد على حاصل ضرب العوامل الثلاثة معًا.', '["قوته 0.40 N، وهي أقل من قوة السلك 3 (0.50 N).","تياره أكبر التيارات لكن طوله صغير، فقوته 0.24 N فقط.","","قوته 0.36 N، وهي أقل من 0.50 N."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-28T06:03:18.366Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العوامل: مقدار التيار المار في السلك، وطول السلك الموضوع داخل المجال، ومقدار المجال المغناطيسي، والزاوية بين السلك والمجال. العلاقة: $F = \mathrm{ILB}\,(\sin\theta)$، حيث $F$ القوة المغناطيسية بوحدة N، و$\mathrm{I}$ التيار بوحدة A، و$\mathrm{L}$ طول السلك داخل المجال بوحدة m، و$\mathrm{B}$ مقدار المجال المغناطيسي بوحدة التسلا T (تساوي 1 N/A.m)، و$\theta$ الزاوية بين السلك والمجال. وعندما يكون السلك عموديًّا على المجال تصبح $F = \mathrm{ILB}$.', '["التيار","طول السلك داخل المجال","مقدار المجال المغناطيسي","الزاوية بين السلك والمجال","العلاقة مع مدلول الرموز ووحداتها"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر العوامل الأربعة","marks":2},{"element":"كتابة العلاقة","marks":1},{"element":"مدلول الرموز ووحداتها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"يذكر ثلاثة عوامل والعلاقة مع نقص في الوحدات"},{"level":"1 درجة","description":"يذكر عاملين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر مقاومة السلك أو كتلته عاملًا","كتابة العلاقة بجيب التمام","عدّ الطول الكلي للسلك بدل طوله داخل المجال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-28T06:03:18.366Z"}'::jsonb),
('essay', 2, null::int, null, null, 'القوة تتناسب طرديًّا مع كل من $\mathrm{I}$ و$\mathrm{L}$ و$\mathrm{B}$. زيادة التيار ثلاثة أمثال تضرب القوة في 3، وتنصيف الطول يضربها في $\frac{1}{2}$، ومضاعفة المجال تضربها في 2. القوة الجديدة $= 0.60 \times 3 \times \frac{1}{2} \times 2 = 1.8\ \text{N}$.', '["أثر التيار: ×3","أثر الطول: ×½","أثر المجال: ×2","النتيجة 1.8 N"]'::jsonb, '["$F'' = (3\\mathrm{I})(\\frac{1}{2}\\mathrm{L})(2\\mathrm{B}) = 3\\,\\mathrm{ILB}$ حيث $F''$ القوة الجديدة","$F'' = 3 \\times 0.60\\ \\text{N} = 1.8\\ \\text{N}$"]'::jsonb, '[{"element":"أثر كل عامل من العوامل الثلاثة","marks":3},{"element":"القوة الجديدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"أثر عاملين صحيح أو خطأ حسابي في النتيجة"},{"level":"1 درجة","description":"أثر عامل واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل العلاقة مع الطول عكسية","جمع المعاملات بدل ضربها","تربيع أحد المعاملات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-28T06:03:18.367Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) الترتيب: السلك 1 ثم السلك 2 ثم السلك 3. التفسير: $F = \mathrm{ILB}\,(\sin\theta)$، و$\mathrm{I}$ و$\mathrm{L}$ و$\mathrm{B}$ متساوية، فالقوة تتناسب مع $\sin\theta$: $\sin 90^\circ = 1$ للسلك 1، و$\sin 30^\circ = 0.5$ للسلك 2، و$\sin 0^\circ = 0$ للسلك 3. (b) $\mathrm{ILB} = 0.40\ \text{N}$، فالقوة على السلك 2 $= 0.40 \times 0.5 = 0.20\ \text{N}$، والقوة على السلك 3 تساوي صفرًا.', '["الترتيب 1 ثم 2 ثم 3","التفسير بالاعتماد على $\\sin\\theta$","القوة على السلك 2 = 0.20 N","القوة على السلك 3 = صفر"]'::jsonb, '["$F_1 = \\mathrm{ILB} = 0.40\\ \\text{N}$","$F_2 = \\mathrm{ILB}\\,(\\sin 30^\\circ) = 0.40 \\times 0.5 = 0.20\\ \\text{N}$","$F_3 = \\mathrm{ILB}\\,(\\sin 0^\\circ) = 0$"]'::jsonb, '[{"element":"الترتيب","marks":1},{"element":"التفسير","marks":1},{"element":"القوة على السلك 2","marks":1},{"element":"القوة على السلك 3","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"ترتيب صحيح مع خطأ في إحدى القيمتين"},{"level":"1 درجة","description":"ترتيب صحيح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $\\cos$ بدل $\\sin$ فتصبح قوة السلك 3 أكبر القوى","عدّ القوة على السلك المائل مساوية لقوة السلك العمودي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.367Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
