insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L2-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما اسم القاعدة التي تُستخدم لتحديد اتجاه القوة المغناطيسية المؤثرة في سلك يسري فيه تيار موضوع في مجال مغناطيسي؟', null, null, '["القاعدة الأولى لليد اليمنى","القاعدة الثانية لليد اليمنى","القاعدة الثالثة لليد اليمنى","قاعدة التنافر والتجاذب المغناطيسي"]'::jsonb, 'تذكر', 'استرجاع قاعدة', 'سهل', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى'),
('mcq', 2, 'عند استخدام القاعدة الثالثة لليد اليمنى، إلى أيّ اتجاه تشير أصابع اليد اليمنى؟', null, null, '["اتجاه المجال المغناطيسي","اتجاه التيار الاصطلاحي","اتجاه القوة المغناطيسية","اتجاه حركة الإلكترونات في السلك"]'::jsonb, 'تذكر', 'استرجاع قاعدة', 'سهل', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى'),
('mcq', 3, 'في القاعدة الثالثة لليد اليمنى، يشير الإبهام إلى اتجاه:', null, null, '["حركة الإلكترونات في السلك","خطوط المجال المغناطيسي من القطب الشمالي إلى الجنوبي","القوة المغناطيسية المؤثرة في السلك","التيار الاصطلاحي في السلك"]'::jsonb, 'فهم', 'تطبيق قاعدة', 'متوسط', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى'),
('mcq', 4, 'بعد وضع الأصابع والإبهام في القاعدة الثالثة لليد اليمنى، كيف يُحدَّد اتجاه القوة المغناطيسية المؤثرة في السلك؟', null, null, '["هو اتجاه الأصابع الممدودة نفسها","هو الاتجاه العمودي على باطن الكف نحو الخارج","هو الاتجاه الذي يشير إليه الإبهام نفسه","هو الاتجاه الذي تلتف فيه الأصابع حول السلك"]'::jsonb, 'فهم', 'تطبيق قاعدة', 'متوسط', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى'),
('mcq', 5, 'ما الذي يجب معرفته لاستخدام القاعدة الثالثة لليد اليمنى في تحديد اتجاه القوة المؤثرة في سلك يسري فيه تيار؟', null, null, '["مقدار التيار ومقدار المجال المغناطيسي","طول السلك ومقدار القوة المؤثرة فيه","اتجاه التيار الاصطلاحي في السلك واتجاه المجال المغناطيسي","اتجاه القوة واتجاه حركة الإلكترونات"]'::jsonb, 'فهم', 'تطبيق قاعدة', 'متوسط', 'الكتاب ص 84 — مسائل تدريبية السؤال 15'),
('mcq', 6, 'بماذا تختلف القاعدة الثالثة لليد اليمنى عن القاعدة الأولى لليد اليمنى؟', null, null, '["الأولى تحدد اتجاه القوة المؤثرة في السلك، والثالثة تحدد اتجاه المجال حوله","الأولى تحدد قطبي المغناطيس الكهربائي، والثالثة تحدد اتجاه التيار في الملف","لا تختلفان؛ فكلتاهما تحدد اتجاه القوة لكن الأولى للتيارات الكبيرة","الأولى تحدد اتجاه المجال حول سلك يسري فيه تيار، والثالثة تحدد اتجاه القوة على سلك في مجال"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 82 — القاعدة الأولى والثالثة لليد اليمنى'),
('mcq', 7, 'في الحالة (1) من الشكل الآتي يتأثر السلك بقوة مغناطيسية إلى أسفل الصفحة. في الحالة (2) عُكس اتجاه التيار واتجاه المجال المغناطيسي معًا. ما اتجاه القوة المؤثرة في السلك في الحالة (2)؟', null, '[{"src":"qimg/phys32/c3l2-o03-reverse.svg","alt":"شكلان متجاوران لسلك مستقيم أفقي. في الحالة (1) المجال المغناطيسي B خارج من الورقة تمثله نقاط خضراء، وسهم التيار I يتجه إلى اليمين، وسهم أزرق للقوة F يبدأ من السلك ويتجه إلى أسفل الصفحة. في الحالة (2) المجال داخل في الورقة تمثله رموز (×) خضراء، وسهم التيار I يتجه إلى اليسار، ومكان القوة علامة استفهام."}]'::jsonb, '["إلى أعلى الصفحة","إلى أسفل الصفحة","إلى داخل الورقة","تنعدم القوة"]'::jsonb, 'تحليل', 'تطبيق قاعدة', 'صعب', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى'),
('essay', 1, 'صف كيف تستخدم القاعدة الثالثة لليد اليمنى لتحديد اتجاه القوة المغناطيسية المؤثرة في سلك يسري فيه تيار موضوع في مجال مغناطيسي، ثم بيّن كيف يُرمز في الرسم إلى مجال داخل في الورقة ومجال خارج منها.', null, null, null, 'فهم', 'وصف قاعدة', 'سهل', 'الكتاب ص 82، وص 96 السؤال 43'),
('essay', 2, 'قارن بين القاعدة الأولى لليد اليمنى والقاعدة الثالثة لليد اليمنى من حيث: (a) الكمية التي تحددها كل منهما. (b) ما يشير إليه الإبهام في كل منهما. (c) ما تمثله الأصابع في كل منهما. ثم وضّح كيف تُستخدم القاعدتان معًا لتحديد القوة بين سلكين متجاورين يسري فيهما تياران.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 82 — القاعدة الأولى والثالثة لليد اليمنى (الشكل 17-3)'),
('essay', 3, 'يبين الشكل الآتي سلكًا يسري فيه تيار إلى اليمين في مجال مغناطيسي داخل في الورقة. استخدم طالب يده اليمنى فجعل إبهامه في اتجاه المجال المغناطيسي وأصابعه في اتجاه التيار، ثم أخذ الاتجاه العمودي على باطن الكف. (a) قوّم طريقة الطالب. (b) حدّد الاتجاه الصحيح للقوة باستخدام القاعدة الثالثة لليد اليمنى. (c) ما الاتجاه الذي سيحصل عليه الطالب بطريقته؟ ولماذا يختلف؟', null, '[{"src":"qimg/phys32/c3l2-o03-case.svg","alt":"سلك مستقيم أفقي في مجال مغناطيسي منتظم B داخل في الورقة تمثله رموز (×) خضراء، وفوق السلك سهم التيار I يتجه إلى اليمين. لا يظهر في الشكل اتجاه القوة."}]'::jsonb, null, 'تقويم', 'تقويم طريقة', 'صعب', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى')
