from (values
('mcq', 1, 2, 'يُحدَّد اتجاه القوة المغناطيسية المؤثرة في سلك يسري فيه تيار وموضوع في مجال مغناطيسي باستخدام القاعدة الثالثة لليد اليمنى.', '["القاعدة الأولى تحدد اتجاه المجال المغناطيسي حول سلك يسري فيه تيار.","القاعدة الثانية تحدد قطبي المغناطيس الكهربائي (الملف اللولبي).","","هذه القاعدة تصف تنافر الأقطاب المتشابهة وتجاذب المختلفة، ولا تحدد اتجاه القوة على سلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-28T06:03:18.367Z"}'::jsonb),
('mcq', 2, 0, 'في القاعدة الثالثة لليد اليمنى تُجعل الأصابع في اتجاه المجال المغناطيسي، والإبهام في اتجاه التيار الاصطلاحي، فيكون اتجاه القوة عموديًّا على باطن الكف نحو الخارج.', '["","الإبهام هو الذي يشير إلى التيار الاصطلاحي لا الأصابع.","القوة تُعرف من الاتجاه العمودي على باطن الكف، لا من الأصابع.","القاعدة تستخدم التيار الاصطلاحي (بالإبهام)، والأصابع للمجال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-28T06:03:18.368Z"}'::jsonb),
('mcq', 3, 3, 'يشير الإبهام في القاعدة الثالثة لليد اليمنى إلى اتجاه التيار الاصطلاحي في السلك، والأصابع إلى اتجاه المجال.', '["الإلكترونات تتحرك عكس التيار الاصطلاحي، والقاعدة تستخدم التيار الاصطلاحي.","المجال المغناطيسي تمثله الأصابع لا الإبهام.","القوة تُعرف من باطن الكف، لا من الإبهام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-28T06:03:18.368Z"}'::jsonb),
('mcq', 4, 1, 'اتجاه القوة المغناطيسية المؤثرة في السلك هو الاتجاه العمودي على باطن الكف نحو الخارج، وهو عمودي على كل من الأصابع (المجال) والإبهام (التيار).', '["الأصابع تمثل المجال، والقوة عمودية عليه.","","الإبهام يمثل التيار، والقوة عمودية عليه.","التفاف الأصابع حول السلك يخص القاعدة الأولى لتحديد المجال حول السلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-28T06:03:18.368Z"}'::jsonb),
('mcq', 5, 2, 'تحتاج القاعدة إلى معرفة اتجاهين: اتجاه التيار الاصطلاحي (للإبهام) واتجاه المجال المغناطيسي (للأصابع)، فتعطي اتجاه القوة.', '["المقادير تلزم لحساب مقدار القوة لا لتحديد اتجاهها.","الطول والمقدار لا يحددان الاتجاه، ومقدار القوة ليس معطى لازمًا.","","اتجاه القوة هو المطلوب، والقاعدة تستخدم التيار الاصطلاحي لا حركة الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.368Z"}'::jsonb),
('mcq', 6, 3, 'القاعدة الأولى لليد اليمنى تحدد اتجاه المجال المغناطيسي حول سلك يسري فيه تيار (الإبهام مع التيار والأصابع تلتف مع المجال)، أما الثالثة فتحدد اتجاه القوة المؤثرة في سلك يسري فيه تيار موضوع في مجال مغناطيسي.', '["هذا تبديل لوظيفتي القاعدتين.","تحديد قطبي المغناطيس الكهربائي وظيفة القاعدة الثانية لليد اليمنى.","القاعدتان مختلفتان في الوظيفة، ولا علاقة لهما بمقدار التيار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.368Z"}'::jsonb),
('mcq', 7, 1, 'بالقاعدة الثالثة لليد اليمنى: عكس التيار وحده يعكس اتجاه الإبهام فتنعكس القوة، وعكس المجال وحده يعكس اتجاه الأصابع فتنعكس القوة؛ وعند عكسهما معًا تنعكس القوة مرتين فتعود إلى اتجاهها الأصلي: إلى أسفل الصفحة.', '["هذا الاتجاه يصح لو عُكس أحدهما فقط، أما عكسهما معًا فيعيد القوة إلى اتجاهها.","","القوة عمودية على التيار والمجال، والمجال هنا داخل في الورقة، فلا تكون القوة إلى داخلها.","التيار ما زال عموديًّا على المجال، فلا تنعدم القوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.369Z"}'::jsonb),
('essay', 1, null::int, null, null, 'اجعل أصابع يدك اليمنى في اتجاه المجال المغناطيسي، واجعل إبهامك يشير إلى اتجاه التيار الاصطلاحي في السلك، فيكون اتجاه القوة المغناطيسية المؤثرة في السلك في الاتجاه العمودي على باطن الكف نحو الخارج. ويُستخدم الرمز (×) للإشارة إلى أن المجال داخل في الورقة، والرمز (•) للإشارة إلى أنه خارج من الورقة.', '["الأصابع في اتجاه المجال","الإبهام في اتجاه التيار الاصطلاحي","القوة عمودية على باطن الكف نحو الخارج","(×) داخل و(•) خارج"]'::jsonb, '[]'::jsonb, '[{"element":"الأصابع","marks":1},{"element":"الإبهام","marks":1},{"element":"باطن الكف","marks":1},{"element":"رمزا الداخل والخارج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"خطوات القاعدة صحيحة مع نقص في الرموز أو في عنصر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الإبهام في اتجاه المجال","استخدام اتجاه حركة الإلكترونات بدل التيار الاصطلاحي","عكس معنى الرمزين (×) و(•)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-28T06:03:18.369Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) القاعدة الأولى تحدد اتجاه المجال المغناطيسي حول سلك يسري فيه تيار، والثالثة تحدد اتجاه القوة المغناطيسية المؤثرة في سلك يسري فيه تيار موضوع في مجال. (b) الإبهام في كلتيهما يشير إلى اتجاه التيار الاصطلاحي. (c) في الأولى تلتف الأصابع حول السلك فتشير إلى اتجاه المجال الناتج عنه، وفي الثالثة تُمدّ الأصابع في اتجاه المجال الخارجي المؤثر، ويكون اتجاه القوة عموديًّا على باطن الكف. ولتحديد القوة بين سلكين: تُستخدم الأولى لتحديد اتجاه المجال الناتج عن أحد السلكين عند موقع الآخر، ثم الثالثة لتحديد اتجاه القوة المؤثرة في السلك الآخر.', '["ما تحدده كل قاعدة","الإبهام: التيار الاصطلاحي في الاثنتين","الأصابع: التفاف حول السلك في الأولى، واتجاه المجال الخارجي في الثالثة","استخدام القاعدتين معًا"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"الاستخدام معًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"مقارنة صحيحة في جانبين أو ثلاثة"},{"level":"1 درجة","description":"يذكر ما تحدده إحدى القاعدتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الأولى والثانية","القول إن الإبهام في الثالثة يشير إلى القوة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.369Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) طريقته خاطئة؛ لأنه بدّل دوري الإبهام والأصابع: في القاعدة الثالثة تكون الأصابع في اتجاه المجال والإبهام في اتجاه التيار الاصطلاحي. (b) الأصابع إلى داخل الورقة والإبهام إلى اليمين، فيكون الاتجاه العمودي على باطن الكف إلى أعلى الصفحة؛ أي القوة إلى أعلى الصفحة. (c) سيحصل على اتجاه إلى أسفل الصفحة، أي عكس الاتجاه الصحيح؛ لأن تبديل دوري الإبهام والأصابع يقلب اليد فيصبح باطن الكف متجهًا إلى الجهة المعاكسة.', '["الحكم بخطأ الطريقة مع بيان التبديل","القوة الصحيحة إلى أعلى الصفحة","نتيجة الطالب إلى أسفل الصفحة","تعليل الاختلاف"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c) الاتجاه","marks":1},{"element":"(c) التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"التقويم والاتجاه الصحيح صحيحان مع نقص في (c)"},{"level":"1 درجة","description":"يحدد الاتجاه الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن تبديل الإصبع والإبهام لا يغير النتيجة","تحديد القوة إلى داخل الورقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.370Z"}'::jsonb)
