('mcq', 1, 'سلك طوله 0.40 m يسري فيه تيار 6.0 A، وُضع عموديًّا في مجال مغناطيسي منتظم مقداره 0.25 T. ما مقدار القوة المغناطيسية المؤثرة فيه؟', null, null, '["9.6 N","0.60 N","3.8 N","0.017 N"]'::jsonb, 'تطبيق', 'حساب مباشر', 'سهل', 'الكتاب ص 83–84 — المثال 1 ومسائل تدريبية 16–19'),
('mcq', 2, 'سلك يسري فيه تيار 4.0 A، وطول الجزء الموضوع منه عموديًّا في مجال مغناطيسي منتظم 30 cm، ويتأثر بقوة مقدارها 0.36 N. ما مقدار المجال المغناطيسي؟', null, null, '["0.0030 T","0.43 T","0.090 T","0.30 T"]'::jsonb, 'تطبيق', 'حساب كمية مجهولة', 'متوسط', 'الكتاب ص 83–84 — المثال 1 ومسائل تدريبية 16–19'),
('mcq', 3, 'ما مقدار التيار الذي يجب أن يسري في سلك طوله 0.75 m موضوع عموديًّا في مجال مغناطيسي منتظم مقداره 0.60 T ليتأثر بقوة مقدارها 0.90 N؟', null, null, '["2.0 A","0.41 A","1.5 A","0.50 A"]'::jsonb, 'تطبيق', 'حساب كمية مجهولة', 'متوسط', 'الكتاب ص 83–84 — المثال 1 ومسائل تدريبية 16–19 (السؤال 19)'),
('mcq', 4, 'يسري تيار 5.0 A في سلك طوله 0.50 m موضوع في مجال مغناطيسي منتظم مقداره 0.40 T، ويصنع زاوية $30^\circ$ مع المجال كما في الشكل الآتي. ما مقدار القوة المغناطيسية المؤثرة في السلك؟', null, '[{"src":"qimg/phys32/c3l2-o04-angle.svg","alt":"أربعة خطوط مجال مغناطيسي خضراء أفقية متوازية تتجه إلى اليمين ويرمز لها B. يقطعها سلك مستقيم مائل، وبجانبه سهم التيار I يتجه على طول السلك إلى أعلى اليمين. الزاوية بين السلك وخطوط المجال مؤشر عليها بقوس وخط متقطع أفقي، وقيمتها 30°."}]'::jsonb, '["0.87 N","1.0 N","0.50 N","0 N"]'::jsonb, 'تطبيق', 'حساب مع زاوية', 'متوسط', 'الكتاب ص 83 — F = ILB (sin θ)، وص 101 السؤال 92'),
('mcq', 5, 'سلك طوله 40 cm يسري فيه تيار 3.0 A، وُضع موازيًا لخطوط مجال مغناطيسي منتظم مقداره 0.50 T. ما مقدار القوة المغناطيسية المؤثرة فيه؟', null, null, '["0 N","0.60 N","60 N","2.4 N"]'::jsonb, 'تطبيق', 'حساب مباشر', 'سهل', 'الكتاب ص 83، وص 99 السؤال 74'),
('mcq', 6, 'سلك نحاسي أفقي طوله 50.0 cm ووزنه 0.24 N يسري فيه تيار 4.0 A، وهو موضوع عموديًّا في مجال مغناطيسي منتظم أفقي كما في الشكل الآتي. ما مقدار المجال المغناطيسي الذي يجعل القوة المغناطيسية توازن وزن السلك؟', null, '[{"src":"qimg/phys32/c3l2-o04-balance.svg","alt":"سلك أفقي في مجال مغناطيسي منتظم B داخل في الورقة تمثله رموز (×) خضراء، وأسفل السلك سهم التيار I يتجه إلى اليمين. من نقطة على السلك سهمان أزرقان: سهم القوة المغناطيسية F إلى أعلى الصفحة، وسهم الوزن F_g إلى أسفل الصفحة، ولهما الطول نفسه."}]'::jsonb, '["0.0012 T","0.48 T","8.3 T","0.12 T"]'::jsonb, 'تحليل', 'حساب في حالة اتزان', 'صعب', 'الكتاب ص 84 — مسائل تدريبية السؤال 18'),
('mcq', 7, 'سلك يسري فيه تيار 3.0 A موضوع عموديًّا في مجال مغناطيسي منتظم مقداره 0.12 T، ويتأثر بقوة مقدارها 18 mN. ما طول جزء السلك الموجود داخل المجال؟', null, null, '["50 m","0.050 m","0.0065 m","20 m"]'::jsonb, 'تطبيق', 'حساب كمية مجهولة', 'متوسط', 'الكتاب ص 99 السؤال 77، وص 103 اختبار مقنن س1'),
('essay', 1, 'يسري تيار 12 A في سلك طوله 20 cm موضوع في مجال مغناطيسي منتظم مقداره 0.50 T. احسب مقدار القوة المغناطيسية المؤثرة في السلك عندما يصنع مع المجال الزوايا الآتية: (a) $90^\circ$ (b) $45^\circ$ (c) $0^\circ$.', null, null, null, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 83، وص 101 السؤال 92'),
('essay', 2, 'في الدائرة المبينة في الشكل الآتي يمر جزء من سلك طوله 8.0 cm داخل مجال مغناطيسي منتظم مقداره 1.5 T داخل في الورقة، والسلك عمودي على المجال. البطارية 12 V والمقاومة 6.0 Ω (أهمل مقاومة السلك والبطارية). أوجد مقدار القوة المؤثرة في السلك واتجاهها في كل من الحالات الآتية: (a) المفتاح مفتوح. (b) المفتاح مغلق. (c) المفتاح مغلق وعُكست البطارية.', null, '[{"src":"qimg/phys32/c3l2-o04-e2.svg","alt":"دائرة كهربائية: في أعلاها جزء من سلك نحاسي أفقي يمر داخل منطقة مستطيلة خضراء فيها رموز (×) تمثل مجالًا مغناطيسيًّا منتظمًا داخلًا في الورقة مكتوب فوقها B = 1.5 T، وطول جزء السلك داخل المنطقة 8.0 cm كما يبين خط قياس. في الضلع الأيسر للدائرة بطارية 12 V قطبها الموجب (+) إلى أعلى، وفي الضلع السفلي مفتاح مفتوح ومقاومة 6.0 Ω، والضلع الأيمن سلك توصيل يعود إلى طرف السلك العلوي."}]'::jsonb, null, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 100 السؤال 86'),
('essay', 3, 'وُصل سلك ببطارية فرق جهدها 6.0 V في دائرة مقاومتها الكلية 12 Ω، وكان 20 cm من السلك داخل مجال مغناطيسي منتظم مقداره 0.80 T. فإذا كان مقدار القوة المؤثرة في السلك 40 mN، فما مقدار الزاوية بين السلك والمجال المغناطيسي؟ استخدم $F = \mathrm{ILB}\,(\sin\theta)$.', null, null, null, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 103 — اختبار مقنن الأسئلة الممتدة س8')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
