('mcq', 4, 2, '$F = \mathrm{ILB}\,(\sin\theta) = (5.0\ \text{A})(0.50\ \text{m})(0.40\ \text{T})(\sin 30^\circ) = 1.0 \times 0.50 = 0.50\ \text{N}$.', '["استعمال $\\cos 30^\\circ$ بدل $\\sin 30^\\circ$.","إهمال الزاوية وعدّ السلك عموديًّا على المجال.","","السلك ليس موازيًا للمجال، فالقوة لا تنعدم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (51%)"}],"at":"2026-11-28T06:03:18.371Z"}'::jsonb),
('mcq', 5, 0, 'السلك موازٍ للمجال فالزاوية $\theta = 0^\circ$ و$\sin 0^\circ = 0$، لذا $F = \mathrm{ILB}\,(\sin 0^\circ) = 0$.', '["","هذه القوة لو كان السلك عموديًّا على المجال.","عدم تحويل الطول من cm إلى m مع إهمال أن السلك موازٍ للمجال.","قسمة $\\mathrm{IL}$ على $\\mathrm{B}$ مع إهمال أن السلك موازٍ للمجال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (71%)"}],"at":"2026-11-28T06:03:18.371Z"}'::jsonb),
